		'__wp_mysql_timestamp_2'        => 'timestamp(2)',
		'__wp_mysql_timestamp_3'        => 'timestamp(3)',
		'__wp_mysql_timestamp_4'        => 'timestamp(4)',
		'__wp_mysql_timestamp_5'        => 'timestamp(5)',
		'__wp_mysql_timestamp_6'        => 'timestamp(6)',
