			'table_privileges'                      => 'GRANTEE TABLE_CATALOG TABLE_SCHEMA TABLE_NAME PRIVILEGE_TYPE IS_GRANTABLE',
			'column_privileges'                     => 'GRANTEE TABLE_CATALOG TABLE_SCHEMA TABLE_NAME COLUMN_NAME PRIVILEGE_TYPE IS_GRANTABLE',
			'resource_groups'                       => 'RESOURCE_GROUP_NAME RESOURCE_GROUP_TYPE RESOURCE_GROUP_ENABLED VCPU_IDS THREAD_PRIORITY',
			'applicable_roles'                      => 'USER HOST GRANTEE GRANTEE_HOST ROLE_NAME ROLE_HOST IS_GRANTABLE IS_DEFAULT IS_MANDATORY',
			'administrable_role_authorizations'     => 'USER HOST GRANTEE GRANTEE_HOST ROLE_NAME ROLE_HOST IS_GRANTABLE IS_DEFAULT IS_MANDATORY',
			'enabled_roles'                         => 'ROLE_NAME ROLE_HOST IS_DEFAULT IS_MANDATORY',
			'role_table_grants'                     => 'GRANTOR GRANTOR_HOST GRANTEE GRANTEE_HOST TABLE_CATALOG TABLE_SCHEMA TABLE_NAME PRIVILEGE_TYPE IS_GRANTABLE',
			'role_column_grants'                    => 'GRANTOR GRANTOR_HOST GRANTEE GRANTEE_HOST TABLE_CATALOG TABLE_SCHEMA TABLE_NAME COLUMN_NAME PRIVILEGE_TYPE IS_GRANTABLE',
			'role_routine_grants'                   => 'GRANTOR GRANTOR_HOST GRANTEE GRANTEE_HOST SPECIFIC_CATALOG SPECIFIC_SCHEMA SPECIFIC_NAME ROUTINE_CATALOG ROUTINE_SCHEMA ROUTINE_NAME PRIVILEGE_TYPE IS_GRANTABLE',
			'views'                                 => 'TABLE_CATALOG TABLE_SCHEMA TABLE_NAME VIEW_DEFINITION CHECK_OPTION IS_UPDATABLE DEFINER SECURITY_TYPE CHARACTER_SET_CLIENT COLLATION_CONNECTION',
			'schemata_extensions'                   => 'CATALOG_NAME SCHEMA_NAME OPTIONS',
			'view_table_usage'                      => 'VIEW_CATALOG VIEW_SCHEMA VIEW_NAME TABLE_CATALOG TABLE_SCHEMA TABLE_NAME',
			'view_routine_usage'                    => 'TABLE_CATALOG TABLE_SCHEMA TABLE_NAME SPECIFIC_CATALOG SPECIFIC_SCHEMA SPECIFIC_NAME',
			'triggers'                              => 'TRIGGER_CATALOG TRIGGER_SCHEMA TRIGGER_NAME EVENT_MANIPULATION EVENT_OBJECT_CATALOG EVENT_OBJECT_SCHEMA EVENT_OBJECT_TABLE ACTION_ORDER ACTION_CONDITION ACTION_STATEMENT ACTION_ORIENTATION ACTION_TIMING ACTION_REFERENCE_OLD_TABLE ACTION_REFERENCE_NEW_TABLE ACTION_REFERENCE_OLD_ROW ACTION_REFERENCE_NEW_ROW CREATED SQL_MODE DEFINER CHARACTER_SET_CLIENT COLLATION_CONNECTION DATABASE_COLLATION',
			'st_geometry_columns'                   => 'TABLE_CATALOG TABLE_SCHEMA TABLE_NAME COLUMN_NAME SRS_NAME SRS_ID GEOMETRY_TYPE_NAME',
			'routines'                              => 'SPECIFIC_NAME ROUTINE_CATALOG ROUTINE_SCHEMA ROUTINE_NAME ROUTINE_TYPE DATA_TYPE CHARACTER_MAXIMUM_LENGTH CHARACTER_OCTET_LENGTH NUMERIC_PRECISION NUMERIC_SCALE DATETIME_PRECISION CHARACTER_SET_NAME COLLATION_NAME DTD_IDENTIFIER ROUTINE_BODY ROUTINE_DEFINITION EXTERNAL_NAME EXTERNAL_LANGUAGE PARAMETER_STYLE IS_DETERMINISTIC SQL_DATA_ACCESS SQL_PATH SECURITY_TYPE CREATED LAST_ALTERED SQL_MODE ROUTINE_COMMENT DEFINER CHARACTER_SET_CLIENT COLLATION_CONNECTION DATABASE_COLLATION',
			'parameters'                            => 'SPECIFIC_CATALOG SPECIFIC_SCHEMA SPECIFIC_NAME ORDINAL_POSITION PARAMETER_MODE PARAMETER_NAME DATA_TYPE CHARACTER_MAXIMUM_LENGTH CHARACTER_OCTET_LENGTH NUMERIC_PRECISION NUMERIC_SCALE DATETIME_PRECISION CHARACTER_SET_NAME COLLATION_NAME DTD_IDENTIFIER ROUTINE_TYPE',
		);

		$view = strtolower( $view );
		return isset( $columns[ $view ] ) ? explode( ' ', $columns[ $view ] ) : null;
	}
	/**
	 * Get a MySQL column definition type for an information_schema output column.
	 *
	 * @param string $column Uppercase information_schema column name.
	 * @return string MySQL column definition fragment.
	 */
	private function get_direct_information_schema_create_column_type( string $column ): string {
		static $type_by_column = null;

		if ( null === $type_by_column ) {
			$type_by_column = array();
			foreach (
				array(
					'bigint DEFAULT NULL'        => 'VERSION TABLE_ID INDEX_ID FLAG N_COLS SPACE ZIP_PAGE_SIZE INSTANT_COLS TOTAL_ROW_VERSIONS PAGE_SIZE FS_BLOCK_SIZE FILE_SIZE ALLOCATED_SIZE SPACE_VERSION TYPE N_FIELDS PAGE_NO MERGE_THRESHOLD QUERY_ID SEQ MISSING_BYTES_BEYOND_MAX_MEM_SIZE CONTEXT_VOLUNTARY CONTEXT_INVOLUNTARY RESERVED RESOURCE_GROUP_ENABLED THREAD_PRIORITY BLOCK_OPS_IN BLOCK_OPS_OUT MESSAGES_SENT MESSAGES_RECEIVED PAGE_FAULTS_MAJOR PAGE_FAULTS_MINOR SWAPS SOURCE_LINE NODEGROUP NODEGROUP_ID POS MTYPE PRTYPE LEN HAS_DEFAULT TABLE_ROWS AVG_ROW_LENGTH DATA_LENGTH MAX_DATA_LENGTH INDEX_LENGTH DATA_FREE AUTO_INCREMENT ORDINAL_POSITION CHARACTER_MAXIMUM_LENGTH CHARACTER_OCTET_LENGTH NUMERIC_PRECISION NUMERIC_SCALE DATETIME_PRECISION SRS_ID NON_UNIQUE SEQ_IN_INDEX CARDINALITY SUB_PART POSITION_IN_UNIQUE_CONSTRAINT MAXLEN ID SORTLEN TIME ACTION_ORDER FILE_ID LOGFILE_GROUP_NUMBER FULLTEXT_KEYS DELETED_ROWS UPDATE_COUNT FREE_EXTENTS TOTAL_EXTENTS EXTENT_SIZE INITIAL_SIZE MAXIMUM_SIZE AUTOEXTEND_SIZE TRANSACTION_COUNTER ORIGINATOR PARTITION_ORDINAL_POSITION SUBPARTITION_ORDINAL_POSITION',
					'decimal(20,6) DEFAULT NULL' => 'DURATION CPU_USER CPU_SYSTEM',
					'longtext DEFAULT NULL'      => 'COLUMN_DEFAULT CHECK_CLAUSE GENERATION_EXPRESSION EXPRESSION VIEW_DEFINITION ACTION_CONDITION ACTION_STATEMENT ROUTINE_DEFINITION FILE_NAME EXTRA PARTITION_EXPRESSION SUBPARTITION_EXPRESSION PARTITION_DESCRIPTION ENGINE_ATTRIBUTE SECONDARY_ENGINE_ATTRIBUTE OPTIONS ATTRIBUTE VCPU_IDS SRS_NAME PATH DEFAULT_VALUE HISTOGRAM QUERY TRACE TABLESPACE_COMMENT',
					'datetime DEFAULT NULL'      => 'CREATE_TIME UPDATE_TIME CHECK_TIME CREATED EXECUTE_AT STARTS ENDS LAST_ALTERED LAST_EXECUTED CREATION_TIME LAST_UPDATE_TIME LAST_ACCESS_TIME RECOVER_TIME',
				) as $type => $columns
			) {
				foreach ( explode( ' ', $columns ) as $typed_column ) {
					$type_by_column[ $typed_column ] = $type;
				}
			}
		}

		return $type_by_column[ $column ] ?? 'varchar(512) DEFAULT NULL';
	}

	/**
	 * Get relation SQL for a supported direct information_schema view.
	 *
	 * @param string $view    Information schema view name.
	 * @param array  $options Relation options.
	 * @return string|null Relation SQL, or null.
	 */
	private function get_direct_information_schema_relation_sql( string $view, array $options = array() ): ?string {
		$view = strtolower( $view );
		if ( null === $this->get_direct_information_schema_relation_columns( $view ) ) {
			return null;
		}

		if ( 'global_variables' === $view || 'session_variables' === $view ) {
			$rows      = array();
			$variables = 'global_variables' === $view ? $this->get_mysql_global_variables() : $this->get_mysql_session_variables();
			foreach ( $variables as $name => $value ) {
				$rows[] = array(
					'VARIABLE_NAME'  => $name,
					'VARIABLE_VALUE' => $value,
				);
			}

			return $this->get_direct_information_schema_literal_relation_sql(
				$this->get_direct_information_schema_relation_columns( 'session_variables' ),
				$rows
			);
		}

		if ( in_array( $view, array( 'global_status', 'session_status', 'server_status' ), true ) ) {
			$rows = array();
			foreach ( $this->get_mysql_status_variables() as $name => $value ) {
				$rows[] = array(
					'VARIABLE_NAME'  => $name,
					'VARIABLE_VALUE' => $value,
				);
			}

			return $this->get_direct_information_schema_literal_relation_sql(
				$this->get_direct_information_schema_relation_columns( 'session_status' ),
				$rows
			);
		}

		if ( 'character_sets' === $view || 'collations' === $view ) {
			$rows = 'character_sets' === $view
				? $this->get_mysql_static_character_set_rows()
				: $this->get_mysql_static_collation_rows();

			return $this->get_direct_information_schema_literal_relation_sql(
				$this->get_direct_information_schema_relation_columns( $view ),
				$rows
			);
		}

		if ( 'engines' === $view ) {
			$rows = array();
			foreach ( $this->get_mysql_static_show_engine_rows() as $row ) {
				$rows[] = array(
					'ENGINE'       => $row['Engine'],
					'SUPPORT'      => $row['Support'],
					'COMMENT'      => $row['Comment'],
					'TRANSACTIONS' => $row['Transactions'],
					'XA'           => $row['XA'],
					'SAVEPOINTS'   => $row['Savepoints'],
				);
			}

			return $this->get_direct_information_schema_literal_relation_sql(
				$this->get_direct_information_schema_relation_columns( 'engines' ),
				$rows
			);
		}

		if ( 'collation_character_set_applicability' === $view ) {
			$rows = array();
			foreach ( $this->get_mysql_static_collation_rows() as $row ) {
				$rows[] = array(
					'COLLATION_NAME'     => $row['COLLATION_NAME'],
					'CHARACTER_SET_NAME' => $row['CHARACTER_SET_NAME'],
				);
			}

			return $this->get_direct_information_schema_literal_relation_sql(
				$this->get_direct_information_schema_relation_columns( 'collation_character_set_applicability' ),
				$rows
			);
		}

		if ( 'schemata' === $view ) {
			if ( $this->should_use_postgresql_catalog_metadata() ) {
				return $this->get_direct_information_schema_simple_native_relation_sql( 'schemata' );
			}

			return $this->get_direct_information_schema_literal_relation_sql(
				$this->get_direct_information_schema_relation_columns( 'schemata' ),
				array(
					array(
						'CATALOG_NAME'               => 'def',
						'SCHEMA_NAME'                => 'information_schema',
						'DEFAULT_CHARACTER_SET_NAME' => self::DEFAULT_MYSQL_CHARSET,
						'DEFAULT_COLLATION_NAME'     => self::DEFAULT_MYSQL_COLLATION,
						'SQL_PATH'                   => null,
						'DEFAULT_ENCRYPTION'         => 'NO',
					),
					array(
						'CATALOG_NAME'               => 'def',
						'SCHEMA_NAME'                => $this->main_db_name,
						'DEFAULT_CHARACTER_SET_NAME' => self::DEFAULT_MYSQL_CHARSET,
						'DEFAULT_COLLATION_NAME'     => self::DEFAULT_MYSQL_COLLATION,
						'SQL_PATH'                   => null,
						'DEFAULT_ENCRYPTION'         => 'NO',
					),
				)
			);
		}

		if ( 'columns' === $view ) {
			if ( $this->should_use_postgresql_catalog_metadata() ) {
				$comment_sql     = 'pg_catalog.col_description(pc.oid, pa.attnum)';
				$type_expression = $this->get_direct_information_schema_catalog_data_type_expression( 'c', true, $comment_sql );
				$column_type     = $this->get_direct_information_schema_catalog_column_type_expression(
					'c',
					$this->get_postgresql_identity_sequence_comment_sql( 'c' ),
					$comment_sql
				);
				$charset         = $this->get_direct_information_schema_character_set_expression(
					$column_type,
					'NULL',
					$comment_sql,
					$this->connection->quote( self::DEFAULT_MYSQL_CHARSET )
				);
				$collation       = $this->get_direct_information_schema_collation_expression(
					$column_type,
					'c.collation_name',
					$comment_sql,
					$this->connection->quote( self::DEFAULT_MYSQL_COLLATION )
				);
				$column_key      = sprintf(
					'(SELECT CASE
		WHEN BOOL_OR(s."INDEX_NAME" = \'PRIMARY\') THEN \'PRI\'
		WHEN BOOL_OR(s."NON_UNIQUE" = 0) THEN \'UNI\'
		WHEN COUNT(*) > 0 THEN \'MUL\'
		ELSE \'\'
	END
	FROM (%1$s) s
	WHERE s."TABLE_SCHEMA" = %2$s
		AND s."TABLE_NAME" = c.table_name
		AND s."COLUMN_NAME" = c.column_name)',
					$this->get_direct_information_schema_relation_sql( 'statistics' ),
					$this->get_direct_information_schema_display_schema_sql( 'c.table_schema' )
				);
				$column_comment  = $comment_sql;
				for ( $i = 0; $i < 4; ++$i ) {
					$marker_conditions = array();
					foreach ( self::POSTGRESQL_CATALOG_COLUMN_COMMENT_MARKER_PREFIXES as $prefix ) {
						$prefix_sql          = $this->connection->quote( $prefix );
						$marker_conditions[] = sprintf(
							'LEFT(COALESCE(%1$s, \'\'), LENGTH(%2$s)) = %2$s',
							$column_comment,
							$prefix_sql
						);
					}

					$column_comment = sprintf(
						'CASE
		WHEN %2$s THEN
			CASE
				WHEN POSITION(CHR(10) IN COALESCE(%1$s, \'\')) > 0 THEN SUBSTRING(COALESCE(%1$s, \'\') FROM POSITION(CHR(10) IN COALESCE(%1$s, \'\')) + 1)
				ELSE \'\'
		END
		ELSE COALESCE(%1$s, \'\')
	END',
						$column_comment,
						implode(
							'
			OR ',
							$marker_conditions
						)
					);
				}

				return sprintf(
					'SELECT
	\'def\' AS "TABLE_CATALOG",
	%1$s AS "TABLE_SCHEMA",
	c.table_name AS "TABLE_NAME",
	c.column_name AS "COLUMN_NAME",
	c.ordinal_position AS "ORDINAL_POSITION",
	%8$s AS "COLUMN_DEFAULT",
	c.is_nullable AS "IS_NULLABLE",
	%2$s AS "DATA_TYPE",
	c.character_maximum_length AS "CHARACTER_MAXIMUM_LENGTH",
	CASE WHEN c.character_maximum_length IS NULL THEN NULL ELSE c.character_maximum_length * 4 END AS "CHARACTER_OCTET_LENGTH",
	c.numeric_precision AS "NUMERIC_PRECISION",
	c.numeric_scale AS "NUMERIC_SCALE",
	c.datetime_precision AS "DATETIME_PRECISION",
	%3$s AS "CHARACTER_SET_NAME",
	%4$s AS "COLLATION_NAME",
	%5$s AS "COLUMN_TYPE",
	%6$s AS "COLUMN_KEY",
	%7$s AS "EXTRA",
	\'select,insert,update,references\' AS "PRIVILEGES",
	%9$s AS "COLUMN_COMMENT",
	\'\' AS "GENERATION_EXPRESSION",
	NULL AS "SRS_ID"
FROM information_schema.columns c
LEFT JOIN pg_catalog.pg_namespace pn
	ON pn.nspname = c.table_schema
LEFT JOIN pg_catalog.pg_class pc
	ON pc.relnamespace = pn.oid
	AND pc.relname = c.table_name
	AND pc.relkind IN (\'r\', \'p\', \'v\', \'m\')
LEFT JOIN pg_catalog.pg_attribute pa
	ON pa.attrelid = pc.oid
	AND pa.attname = c.column_name
	AND pa.attnum > 0
WHERE c.table_schema !~ \'^(pg_|information_schema$|pg_catalog$)\'
',
					$this->get_direct_information_schema_display_schema_sql( 'c.table_schema' ),
					$type_expression,
					$charset,
					$collation,
					$column_type,
					$column_key,
					$this->get_direct_information_schema_column_extra_expression( 'c', true, $comment_sql ),
					$this->get_direct_information_schema_column_default_expression( 'c', $comment_sql ),
					$column_comment
				);
			}

			return $this->get_direct_information_schema_literal_relation_sql(
				$this->get_direct_information_schema_relation_columns( 'columns' ),
				array()
			);
		}

		if ( 'tables' === $view ) {
			if ( ! $this->should_use_postgresql_catalog_metadata() ) {
				return $this->get_direct_information_schema_literal_relation_sql(
					$this->get_direct_information_schema_relation_columns( 'tables' ),
					array()
				);
			}

				$postgresql_table_comment_sql       = "pg_catalog.obj_description(pc.oid, 'pg_class')";
				$table_comment_prefix_sql           = $this->connection->quote( self::MYSQL_TABLE_COMMENT_COLLATION_PREFIX );
				$table_comment_value_sql            = sprintf( 'COALESCE(%s, \'\')', $postgresql_table_comment_sql );
				$table_comment_sql                  = sprintf(
					'CASE
		WHEN LEFT(%1$s, LENGTH(%2$s)) = %2$s THEN
			CASE
				WHEN POSITION(CHR(10) IN %1$s) > 0 THEN SUBSTRING(%1$s FROM POSITION(CHR(10) IN %1$s) + 1)
				ELSE \'\'
			END
		ELSE %1$s
	END',
					$table_comment_value_sql,
					$table_comment_prefix_sql
				);
				$table_collation_comment_sql        = sprintf(
					'CASE
		WHEN LEFT(%1$s, LENGTH(%2$s)) = %2$s THEN %3$s
		ELSE NULL
	END',
					$table_comment_value_sql,
					$table_comment_prefix_sql,
					$this->get_postgresql_catalog_column_comment_marker_decode_sql( $table_comment_value_sql, $table_comment_prefix_sql )
				);
				$table_collation_column_comment_sql = 'pg_catalog.col_description(table_collation_pc.oid, table_collation_pa.attnum)';
				$table_collation_column_type_sql    = $this->get_direct_information_schema_catalog_column_type_expression( 'table_collation_columns', null, $table_collation_column_comment_sql );
				$table_collation_column_sql         = $this->get_direct_information_schema_collation_expression(
					$table_collation_column_type_sql,
					'table_collation_columns.collation_name',
					$table_collation_column_comment_sql,
					$this->connection->quote( self::DEFAULT_MYSQL_COLLATION )
				);
				$table_collation_sql                = sprintf(
					'COALESCE(%3$s, (
		SELECT %1$s
		FROM information_schema.columns table_collation_columns
		LEFT JOIN pg_catalog.pg_namespace table_collation_pn
			ON table_collation_pn.nspname = table_collation_columns.table_schema
		LEFT JOIN pg_catalog.pg_class table_collation_pc
			ON table_collation_pc.relnamespace = table_collation_pn.oid
			AND table_collation_pc.relname = table_collation_columns.table_name
			AND table_collation_pc.relkind IN (\'r\', \'p\', \'v\', \'m\')
		LEFT JOIN pg_catalog.pg_attribute table_collation_pa
			ON table_collation_pa.attrelid = table_collation_pc.oid
			AND table_collation_pa.attname = table_collation_columns.column_name
			AND table_collation_pa.attnum > 0
		WHERE table_collation_columns.table_schema = t.table_schema
			AND table_collation_columns.table_name = t.table_name
			AND %1$s IS NOT NULL
		ORDER BY table_collation_columns.ordinal_position
		LIMIT 1
	), %2$s)',
					$table_collation_column_sql,
					$this->connection->quote( self::DEFAULT_MYSQL_COLLATION ),
					$table_collation_comment_sql
				);
				return sprintf(
					'SELECT
		\'def\' AS "TABLE_CATALOG",
	%1$s AS "TABLE_SCHEMA",
	t.table_name AS "TABLE_NAME",
	CASE WHEN t.table_type = \'VIEW\' THEN \'VIEW\' ELSE \'BASE TABLE\' END AS "TABLE_TYPE",
	\'InnoDB\' AS "ENGINE",
	10 AS "VERSION",
	\'Dynamic\' AS "ROW_FORMAT",
	GREATEST(CAST(COALESCE(pc.reltuples, 0) AS bigint), 0) AS "TABLE_ROWS",
	0 AS "AVG_ROW_LENGTH",
	0 AS "DATA_LENGTH",
	0 AS "MAX_DATA_LENGTH",
	0 AS "INDEX_LENGTH",
	0 AS "DATA_FREE",
	CASE
		WHEN identity_column.column_name IS NULL THEN NULL
		ELSE CAST(COALESCE(ps.last_value + ps.increment_by, ps.start_value, 1) AS bigint)
	END AS "AUTO_INCREMENT",
	TO_CHAR(CURRENT_TIMESTAMP, \'YYYY-MM-DD HH24:MI:SS\') AS "CREATE_TIME",
	NULL AS "UPDATE_TIME",
	NULL AS "CHECK_TIME",
	%2$s AS "TABLE_COLLATION",
	NULL AS "CHECKSUM",
	\'\' AS "CREATE_OPTIONS",
	%3$s AS "TABLE_COMMENT"
FROM information_schema.tables t
LEFT JOIN pg_catalog.pg_namespace pn
	ON pn.nspname = t.table_schema
LEFT JOIN pg_catalog.pg_class pc
	ON pc.relnamespace = pn.oid
	AND pc.relname = t.table_name
	AND pc.relkind IN (\'r\', \'p\', \'v\', \'m\')
LEFT JOIN LATERAL (
	SELECT
		c.column_name,
		pg_catalog.pg_get_serial_sequence(
			pg_catalog.format(\'%%I.%%I\', t.table_schema, t.table_name),
			c.column_name
		)::regclass AS sequence_oid
	FROM information_schema.columns c
	WHERE c.table_schema = t.table_schema
		AND c.table_name = t.table_name
		AND (
			c.is_identity = \'YES\'
			OR LOWER(COALESCE(c.column_default, \'\')) LIKE \'nextval(%%\'
		)
	ORDER BY c.ordinal_position
	LIMIT 1
) identity_column
	ON TRUE
LEFT JOIN pg_catalog.pg_class seq
	ON seq.oid = identity_column.sequence_oid
LEFT JOIN pg_catalog.pg_namespace seq_ns
	ON seq_ns.oid = seq.relnamespace
LEFT JOIN pg_catalog.pg_sequences ps
	ON ps.schemaname = seq_ns.nspname
	AND ps.sequencename = seq.relname
WHERE t.table_schema !~ \'^(pg_|information_schema$|pg_catalog$)\'
		AND t.table_type IN (\'BASE TABLE\', \'VIEW\')',
					$this->get_direct_information_schema_display_schema_sql( 't.table_schema' ),
					$table_collation_sql,
					$table_comment_sql
				);
		}

		if ( in_array( $view, explode( ' ', 'events optimizer_trace profiling resource_groups user_attributes' ), true ) ) {
			return $this->get_direct_information_schema_literal_relation_sql(
				$this->get_direct_information_schema_relation_columns( $view ),
				array()
			);
		}

		if (
			! $this->should_use_postgresql_catalog_metadata()
			&& ! in_array( $view, explode( ' ', 'processlist keywords' ), true )
		) {
			return $this->get_direct_information_schema_literal_relation_sql(
				$this->get_direct_information_schema_relation_columns( $view ),
				array()
			);
		}

		$native_relation_sql = $this->get_direct_information_schema_simple_native_relation_sql( $view );
		if ( null !== $native_relation_sql ) {
			return $native_relation_sql;
		}

		if ( 'processlist' === $view ) {
			if ( $this->should_use_postgresql_catalog_metadata() ) {
				return 'SELECT
	a.pid AS "ID",
	COALESCE(a.usename, CURRENT_USER) AS "USER",
	CASE
		WHEN a.client_addr IS NULL THEN \'localhost\'
		WHEN a.client_port IS NULL THEN CAST(a.client_addr AS text)
		ELSE CAST(a.client_addr AS text) || \':\' || CAST(a.client_port AS text)
	END AS "HOST",
	COALESCE(a.datname, \'\') AS "DB",
	CASE WHEN a.state = \'idle\' THEN \'Sleep\' ELSE \'Query\' END AS "COMMAND",
	GREATEST(CAST(FLOOR(EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - COALESCE(a.query_start, a.state_change, a.backend_start, CURRENT_TIMESTAMP)))) AS bigint), 0) AS "TIME",
	COALESCE(
		a.wait_event_type || CASE WHEN a.wait_event IS NULL THEN \'\' ELSE \':\' || a.wait_event END,
		a.state,
		\'\'
	) AS "STATE",
	COALESCE(a.query, \'\') AS "INFO"
FROM pg_catalog.pg_stat_activity a
WHERE a.datname IS NULL OR a.datname = current_database()';
			}

			return $this->get_direct_information_schema_literal_relation_sql(
				$this->get_direct_information_schema_relation_columns( 'processlist' ),
				array(
					array(
						'ID'      => '1',
						'USER'    => 'root',
						'HOST'    => 'localhost',
						'DB'      => $this->db_name,
						'COMMAND' => 'Query',
						'TIME'    => '0',
						'STATE'   => '',
						'INFO'    => (string) $this->last_mysql_query,
					),
				)
			);
		}

		if ( 'keywords' === $view ) {
			if ( $this->should_use_postgresql_catalog_metadata() ) {
				return 'SELECT
	UPPER(k.word) AS "WORD",
	CASE WHEN k.catcode = \'R\' THEN 1 ELSE 0 END AS "RESERVED"
FROM pg_catalog.pg_get_keywords() k';
			}

			return $this->get_direct_information_schema_literal_relation_sql(
				$this->get_direct_information_schema_relation_columns( 'keywords' ),
				array(
					array(
						'WORD'     => 'SELECT',
						'RESERVED' => 1,
					),
					array(
						'WORD'     => 'FROM',
						'RESERVED' => 1,
					),
					array(
						'WORD'     => 'WHERE',
						'RESERVED' => 1,
					),
					array(
						'WORD'     => 'VALUE',
						'RESERVED' => 0,
					),
				)
			);
		}

		if ( 'innodb_lock_waits' === $view ) {
			return 'SELECT
	CAST(waiting.pid AS text) AS "REQUESTING_TRX_ID",
	pg_catalog.concat_ws(
		\':\',
		waiting.locktype,
		waiting.mode,
		CAST(waiting.database AS text),
		CAST(waiting.relation AS text),
		CAST(waiting.page AS text),
		CAST(waiting.tuple AS text),
		CAST(waiting.virtualxid AS text),
		CAST(waiting.transactionid AS text),
		CAST(waiting.classid AS text),
		CAST(waiting.objid AS text),
		CAST(waiting.objsubid AS text)
	) AS "REQUESTED_LOCK_ID",
	CAST(blocking.pid AS text) AS "BLOCKING_TRX_ID",
	pg_catalog.concat_ws(
		\':\',
		blocking.locktype,
		blocking.mode,
		CAST(blocking.database AS text),
		CAST(blocking.relation AS text),
		CAST(blocking.page AS text),
		CAST(blocking.tuple AS text),
		CAST(blocking.virtualxid AS text),
		CAST(blocking.transactionid AS text),
		CAST(blocking.classid AS text),
		CAST(blocking.objid AS text),
		CAST(blocking.objsubid AS text)
	) AS "BLOCKING_LOCK_ID"
FROM pg_catalog.pg_locks waiting
JOIN pg_catalog.pg_locks blocking
	ON blocking.pid = ANY(pg_catalog.pg_blocking_pids(waiting.pid))
	AND blocking.granted
	AND waiting.locktype = blocking.locktype
	AND waiting.database IS NOT DISTINCT FROM blocking.database
	AND waiting.relation IS NOT DISTINCT FROM blocking.relation
	AND waiting.page IS NOT DISTINCT FROM blocking.page
	AND waiting.tuple IS NOT DISTINCT FROM blocking.tuple
	AND waiting.virtualxid IS NOT DISTINCT FROM blocking.virtualxid
	AND waiting.transactionid IS NOT DISTINCT FROM blocking.transactionid
	AND waiting.classid IS NOT DISTINCT FROM blocking.classid
	AND waiting.objid IS NOT DISTINCT FROM blocking.objid
	AND waiting.objsubid IS NOT DISTINCT FROM blocking.objsubid
WHERE NOT waiting.granted';
		}

		if ( 'innodb_tables' === $view ) {
			return sprintf(
				'SELECT
	CAST(c.oid AS bigint) AS "TABLE_ID",
	%1$s || \'/\' || c.relname AS "NAME",
	0 AS "FLAG",
	CAST(COALESCE(column_counts.n_cols, 0) + 3 AS bigint) AS "N_COLS",
	CAST(COALESCE(NULLIF(c.reltablespace, 0::oid), db.dattablespace, 0::oid) AS bigint) AS "SPACE",
	\'Dynamic\' AS "ROW_FORMAT",
	0 AS "ZIP_PAGE_SIZE",
	\'Single\' AS "SPACE_TYPE",
	NULL AS "INSTANT_COLS",
	0 AS "TOTAL_ROW_VERSIONS"
FROM pg_catalog.pg_class c
JOIN pg_catalog.pg_namespace n
	ON n.oid = c.relnamespace
LEFT JOIN pg_catalog.pg_database db
	ON db.datname = current_database()
LEFT JOIN LATERAL (
	SELECT COUNT(*) AS n_cols
	FROM pg_catalog.pg_attribute a
	WHERE a.attrelid = c.oid
		AND a.attnum > 0
		AND NOT a.attisdropped
) column_counts
	ON TRUE
WHERE c.relkind IN (\'r\', \'p\')
	AND n.nspname !~ \'^(pg_|information_schema$|pg_catalog$)\'',
				$this->get_direct_information_schema_display_schema_sql( 'n.nspname' )
			);
		}

		if ( 'partitions' === $view ) {
			return sprintf(
				'SELECT
		\'def\' AS "TABLE_CATALOG",
		%1$s AS "TABLE_SCHEMA",
		parent_class.relname AS "TABLE_NAME",
		child_class.relname AS "PARTITION_NAME",
		NULL AS "SUBPARTITION_NAME",
		CAST(ROW_NUMBER() OVER (PARTITION BY parent_class.oid ORDER BY child_class.relname) AS bigint) AS "PARTITION_ORDINAL_POSITION",
		NULL AS "SUBPARTITION_ORDINAL_POSITION",
		CASE
			WHEN partkey.definition LIKE \'RANGE%%\' THEN \'RANGE\'
			WHEN partkey.definition LIKE \'LIST%%\' THEN \'LIST\'
			WHEN partkey.definition LIKE \'HASH%%\' THEN \'HASH\'
			ELSE NULL
		END AS "PARTITION_METHOD",
		NULL AS "SUBPARTITION_METHOD",
		CASE
			WHEN partkey.definition IS NULL THEN NULL
			ELSE pg_catalog.regexp_replace(partkey.definition, \'^[^(]*\((.*)\)$\', \'\1\')
		END AS "PARTITION_EXPRESSION",
		NULL AS "SUBPARTITION_EXPRESSION",
		pg_catalog.pg_get_expr(child_class.relpartbound, child_class.oid) AS "PARTITION_DESCRIPTION",
		GREATEST(CAST(COALESCE(child_class.reltuples, 0) AS bigint), 0) AS "TABLE_ROWS",
		0 AS "AVG_ROW_LENGTH",
		0 AS "DATA_LENGTH",
		0 AS "MAX_DATA_LENGTH",
		0 AS "INDEX_LENGTH",
		0 AS "DATA_FREE",
		NULL AS "CREATE_TIME",
		NULL AS "UPDATE_TIME",
		NULL AS "CHECK_TIME",
		NULL AS "CHECKSUM",
		\'\' AS "PARTITION_COMMENT",
		\'default\' AS "NODEGROUP",
		\'DEFAULT\' AS "TABLESPACE_NAME"
	FROM pg_catalog.pg_inherits inh
	JOIN pg_catalog.pg_class child_class
		ON child_class.oid = inh.inhrelid
	JOIN pg_catalog.pg_class parent_class
		ON parent_class.oid = inh.inhparent
	JOIN pg_catalog.pg_namespace parent_ns
		ON parent_ns.oid = parent_class.relnamespace
	LEFT JOIN LATERAL (
		SELECT pg_catalog.pg_get_partkeydef(parent_class.oid) AS definition
	) partkey
		ON TRUE
	WHERE parent_ns.nspname !~ \'^(pg_|information_schema$|pg_catalog$)\'
	UNION ALL
	SELECT
		\'def\' AS "TABLE_CATALOG",
		%2$s AS "TABLE_SCHEMA",
		t.table_name AS "TABLE_NAME",
		NULL AS "PARTITION_NAME",
		NULL AS "SUBPARTITION_NAME",
		NULL AS "PARTITION_ORDINAL_POSITION",
		NULL AS "SUBPARTITION_ORDINAL_POSITION",
		NULL AS "PARTITION_METHOD",
		NULL AS "SUBPARTITION_METHOD",
		NULL AS "PARTITION_EXPRESSION",
		NULL AS "SUBPARTITION_EXPRESSION",
		NULL AS "PARTITION_DESCRIPTION",
		GREATEST(CAST(COALESCE(pc.reltuples, 0) AS bigint), 0) AS "TABLE_ROWS",
		0 AS "AVG_ROW_LENGTH",
		0 AS "DATA_LENGTH",
		0 AS "MAX_DATA_LENGTH",
		0 AS "INDEX_LENGTH",
		0 AS "DATA_FREE",
		NULL AS "CREATE_TIME",
		NULL AS "UPDATE_TIME",
		NULL AS "CHECK_TIME",
		NULL AS "CHECKSUM",
		\'\' AS "PARTITION_COMMENT",
		\'\' AS "NODEGROUP",
		\'DEFAULT\' AS "TABLESPACE_NAME"
	FROM information_schema.tables t
	LEFT JOIN pg_catalog.pg_namespace pn
		ON pn.nspname = t.table_schema
	LEFT JOIN pg_catalog.pg_class pc
		ON pc.relnamespace = pn.oid
		AND pc.relname = t.table_name
		AND pc.relkind IN (\'r\', \'p\')
	WHERE t.table_schema !~ \'^(pg_|information_schema$|pg_catalog$)\'
		AND t.table_type = \'BASE TABLE\'
		AND (
			pc.oid IS NULL
			OR NOT EXISTS (
				SELECT 1
				FROM pg_catalog.pg_inherits table_partition
				WHERE table_partition.inhrelid = pc.oid
					OR table_partition.inhparent = pc.oid
			)
		)',
				$this->get_direct_information_schema_display_schema_sql( 'parent_ns.nspname' ),
				$this->get_direct_information_schema_display_schema_sql( 't.table_schema' )
			);
		}

		if ( 'innodb_indexes' === $view ) {
			return 'SELECT
	CAST(idx_class.oid AS bigint) AS "INDEX_ID",
	CASE WHEN idx.indisprimary THEN \'PRIMARY\' ELSE idx_class.relname END AS "NAME",
	CAST(table_class.oid AS bigint) AS "TABLE_ID",
	CASE
		WHEN idx.indisprimary THEN 3
		WHEN idx.indisunique THEN 2
		ELSE 0
	END AS "TYPE",
	CAST(idx.indnkeyatts AS bigint) AS "N_FIELDS",
	0 AS "PAGE_NO",
	CAST(COALESCE(NULLIF(table_class.reltablespace, 0::oid), db.dattablespace, 0::oid) AS bigint) AS "SPACE",
	50 AS "MERGE_THRESHOLD"
FROM pg_catalog.pg_index idx
JOIN pg_catalog.pg_class idx_class
	ON idx_class.oid = idx.indexrelid
JOIN pg_catalog.pg_class table_class
	ON table_class.oid = idx.indrelid
JOIN pg_catalog.pg_namespace table_ns
	ON table_ns.oid = table_class.relnamespace
LEFT JOIN pg_catalog.pg_database db
	ON db.datname = current_database()
WHERE table_class.relkind IN (\'r\', \'p\')
	AND table_ns.nspname !~ \'^(pg_|information_schema$|pg_catalog$)\'';
		}

		if ( 'innodb_fields' === $view ) {
			return 'SELECT
	CAST(idx_class.oid AS bigint) AS "INDEX_ID",
	att.attname AS "NAME",
	CAST(key_positions.position AS bigint) AS "POS"
FROM pg_catalog.pg_index idx
JOIN pg_catalog.pg_class idx_class
	ON idx_class.oid = idx.indexrelid
JOIN pg_catalog.pg_class table_class
	ON table_class.oid = idx.indrelid
JOIN pg_catalog.pg_namespace table_ns
	ON table_ns.oid = table_class.relnamespace
JOIN pg_catalog.generate_series(0, idx.indnkeyatts - 1) AS key_positions(position)
	ON TRUE
JOIN pg_catalog.pg_attribute att
	ON att.attrelid = table_class.oid
	AND att.attnum = idx.indkey[key_positions.position]
WHERE table_class.relkind IN (\'r\', \'p\')
	AND table_ns.nspname !~ \'^(pg_|information_schema$|pg_catalog$)\'';
		}

		if ( 'innodb_columns' === $view ) {
			return 'SELECT
	CAST(c.oid AS bigint) AS "TABLE_ID",
	a.attname AS "NAME",
	CAST(a.attnum - 1 AS bigint) AS "POS",
	CASE
		WHEN typ.typcategory = \'N\' THEN 6
		WHEN typ.typcategory = \'S\' THEN 1
		WHEN typ.typcategory = \'B\' THEN 6
		WHEN typ.typcategory = \'U\' THEN 14
		ELSE 12
	END AS "MTYPE",
	0 AS "PRTYPE",
	CAST(
		CASE
			WHEN a.atttypmod > 0 THEN GREATEST(a.atttypmod - 4, 0)
			WHEN typ.typlen > 0 THEN typ.typlen
			ELSE 0
		END
	AS bigint) AS "LEN",
	CASE WHEN def.adbin IS NULL THEN 0 ELSE 1 END AS "HAS_DEFAULT",
	CASE WHEN def.adbin IS NULL THEN NULL ELSE pg_catalog.pg_get_expr(def.adbin, def.adrelid) END AS "DEFAULT_VALUE"
FROM pg_catalog.pg_class c
JOIN pg_catalog.pg_namespace n
	ON n.oid = c.relnamespace
JOIN pg_catalog.pg_attribute a
	ON a.attrelid = c.oid
JOIN pg_catalog.pg_type typ
	ON typ.oid = a.atttypid
LEFT JOIN pg_catalog.pg_attrdef def
	ON def.adrelid = a.attrelid
	AND def.adnum = a.attnum
WHERE c.relkind IN (\'r\', \'p\')
	AND a.attnum > 0
	AND NOT a.attisdropped
	AND n.nspname !~ \'^(pg_|information_schema$|pg_catalog$)\'';
		}

		if ( 'st_geometry_columns' === $view ) {
			$geometry_types     = array( 'geometry', 'point', 'linestring', 'polygon', 'multipoint', 'multilinestring', 'multipolygon', 'geomcollection', 'geometrycollection' );
			$geometry_domains   = array();
			$geometry_type_case = array();
			foreach ( self::MYSQL_TEXT_DOMAIN_TYPES as $domain_name => $mysql_type ) {
				if ( in_array( $mysql_type, $geometry_types, true ) ) {
					$geometry_domains[]   = $domain_name;
					$geometry_type_case[] = sprintf(
						'WHEN c.domain_name = %s THEN %s',
						$this->connection->quote( $domain_name ),
						$this->connection->quote( strtoupper( $mysql_type ) )
					);
				}
			}
			foreach ( $geometry_types as $geometry_type ) {
				$geometry_type_case[] = sprintf(
					'WHEN LOWER(COALESCE(c.udt_name, c.data_type)) = %s THEN %s',
					$this->connection->quote( $geometry_type ),
					$this->connection->quote( strtoupper( $geometry_type ) )
				);
			}

			$geometry_type_values = array_merge( $geometry_domains, $geometry_types );
			$geometry_type_list   = implode(
				', ',
				array_map(
					array( $this->connection, 'quote' ),
					$geometry_type_values
				)
			);

			return sprintf(
				'SELECT
	\'def\' AS "TABLE_CATALOG",
	%1$s AS "TABLE_SCHEMA",
	c.table_name AS "TABLE_NAME",
	c.column_name AS "COLUMN_NAME",
	NULL AS "SRS_NAME",
	NULL AS "SRS_ID",
	CASE
		%2$s
		ELSE UPPER(COALESCE(c.domain_name, c.udt_name, c.data_type))
	END AS "GEOMETRY_TYPE_NAME"
FROM information_schema.columns c
WHERE c.table_schema !~ \'^(pg_|information_schema$|pg_catalog$)\'
	AND LOWER(COALESCE(c.domain_name, c.udt_name, c.data_type)) IN (%3$s)',
				$this->get_direct_information_schema_display_schema_sql( 'c.table_schema' ),
				implode( "\n\t\t", $geometry_type_case ),
				$geometry_type_list
			);
		}

		if ( 'statistics' === $view ) {
			$include_internal_sort_column = ! empty( $options['include_internal_sort_column'] );
			$column_name_sql              = $this->get_postgresql_prefix_index_expression_column_name_sql( 'expression' );
			$index_type_sql               = sprintf(
				'COALESCE(%s, UPPER(access_method))',
				$this->get_postgresql_catalog_index_type_comment_sql( 'index_comment' )
			);
			$sub_part_sql                 = $this->get_postgresql_catalog_display_index_sub_part_sql( 'expression', 'index_comment', 'seq_in_index' );
			$internal_sort_column_sql     = $include_internal_sort_column ? ',
	postgresql_index_oid AS "POSTGRESQL_INDEX_OID"' : '';

			return sprintf(
				'%7$s
SELECT
	\'def\' AS "TABLE_CATALOG",
	%1$s AS "TABLE_SCHEMA",
	table_name AS "TABLE_NAME",
	CASE WHEN indisunique THEN 0 ELSE 1 END AS "NON_UNIQUE",
	%1$s AS "INDEX_SCHEMA",
	CASE
		WHEN indisprimary THEN \'PRIMARY\'
		WHEN postgresql_index_name LIKE table_name || \'__%%\' THEN SUBSTRING(postgresql_index_name FROM CHAR_LENGTH(table_name || \'__\') + 1)
		ELSE postgresql_index_name
	END AS "INDEX_NAME",
	CAST(seq_in_index AS integer) AS "SEQ_IN_INDEX",
	COALESCE(column_name, %2$s) AS "COLUMN_NAME",
	CASE WHEN %3$s = \'FULLTEXT\' THEN NULL ELSE CASE WHEN is_desc THEN \'D\' ELSE \'A\' END END AS "COLLATION",
	0 AS "CARDINALITY",
	CASE WHEN %3$s = \'FULLTEXT\' THEN NULL ELSE %4$s END AS "SUB_PART",
	NULL AS "PACKED",
	CASE
		WHEN 0 = attnum OR attnotnull THEN \'\'
		ELSE \'YES\'
	END AS "NULLABLE",
	%3$s AS "INDEX_TYPE",
	\'\' AS "COMMENT",
	%5$s AS "INDEX_COMMENT",
	\'YES\' AS "IS_VISIBLE",
	%6$s AS "EXPRESSION"%8$s
FROM index_columns',
				$this->get_direct_information_schema_display_schema_sql( 'table_schema' ),
				$column_name_sql,
				$index_type_sql,
				$sub_part_sql,
				$this->get_postgresql_catalog_index_comment_sql( 'index_comment' ),
				$this->get_postgresql_non_prefix_index_expression_sql( 'expression' ),
				$this->get_postgresql_catalog_index_columns_cte_sql(
					'n.nspname AS table_schema',
					'',
					array(
						'n.nspname !~ \'^(pg_|information_schema$|pg_catalog$)\'',
						't.relkind IN (\'r\', \'p\')',
					)
				),
				$internal_sort_column_sql
			);
		}

		if ( 'column_statistics' === $view ) {
			return sprintf(
				'SELECT
	%1$s AS "SCHEMA_NAME",
	stats.tablename AS "TABLE_NAME",
	stats.attname AS "COLUMN_NAME",
	CAST(pg_catalog.json_build_object(
		\'buckets\', COALESCE(pg_catalog.to_json(stats.histogram_bounds), \'[]\'::json),
		\'null-values\', stats.null_frac,
		\'last-updated\', NULL
	) AS text) AS "HISTOGRAM"
FROM pg_catalog.pg_stats stats
WHERE stats.schemaname !~ \'^(pg_|information_schema$|pg_catalog$)\'',
				$this->get_direct_information_schema_display_schema_sql( 'stats.schemaname' )
			);
		}

		return null;
	}

	/**
	 * Get SQL for a simple native PostgreSQL information_schema relation.
	 *
	 * These relations only need an ordered MySQL-shaped projection over a native
	 * information_schema source. More complex catalog relations stay explicit.
	 *
	 * @param string $view Information schema view name.
	 * @return string|null Relation SQL, or null when the relation is not simple-native.
	 */
	private function get_direct_information_schema_simple_native_relation_sql( string $view ): ?string {
		$def_sql             = $this->connection->quote( 'def' );
		$empty_sql           = $this->connection->quote( '' );
		$function_sql        = $this->connection->quote( 'FUNCTION' );
		$information_schema  = $this->connection->quote( 'information_schema' );
		$none_sql            = $this->connection->quote( 'NONE' );
		$no_sql              = $this->connection->quote( 'NO' );
		$percent_sql         = $this->connection->quote( '%' );
		$user_host_sql       = $this->connection->quote( '@\'%\'' );
		$datetime_format_sql = $this->connection->quote( 'YYYY-MM-DD HH24:MI:SS' );
		$schema_filter       = '!~ ' . $this->connection->quote( '^(pg_|information_schema$|pg_catalog$)' );
		$pg_schema_filter    = '!~ ' . $this->connection->quote( '^pg_' );
		$charset_sql         = $this->connection->quote( self::DEFAULT_MYSQL_CHARSET );
		$collation_sql       = $this->connection->quote( self::DEFAULT_MYSQL_COLLATION );
		$sql_mode_sql        = $this->connection->quote( $this->get_sql_mode() );
		$check_comment_sql   = 'pg_catalog.obj_description(con.oid, \'pg_constraint\')';
		$check_clause_sql    = $this->get_postgresql_mysql_check_clause_comment_sql( $check_comment_sql, 'cc.check_clause' );
		$check_enforced_sql  = $this->get_postgresql_mysql_check_enforced_comment_sql( $check_comment_sql );
		$acl_grantee_sql     = 'pg_catalog.quote_literal(CASE WHEN acl.grantee = 0 THEN \'PUBLIC\' ELSE grantee_role.rolname END) || ' . $user_host_sql;
		$tablespace_path_sql = 'NULLIF(pg_catalog.pg_tablespace_location(ts.oid), \'\')';
		$tablespace_relation = array(
			'alias'   => 'ts',
			'from'    => 'pg_catalog.pg_tablespace ts',
			'default' => 'NULL',
		);

		$definitions = array(
			'files'                        => $tablespace_relation + array(
				'expressions' => array(
					'FILE_ID'         => 'CAST(ts.oid AS bigint)',
					'FILE_NAME'       => $tablespace_path_sql,
					'FILE_TYPE'       => $this->connection->quote( 'TABLESPACE' ),
					'TABLESPACE_NAME' => 'ts.spcname',
					'TABLE_CATALOG'   => $empty_sql,
					'ENGINE'          => $this->connection->quote( 'InnoDB' ),
					'STATUS'          => $this->connection->quote( 'NORMAL' ),
				),
			),
			'plugins'                      => array(
				'alias'       => 'ae',
				'from'        => 'pg_catalog.pg_available_extensions ae',
				'default'     => 'NULL',
				'expressions' => array(
					'PLUGIN_NAME'         => 'ae.name',
					'PLUGIN_VERSION'      => 'COALESCE(ae.installed_version, ae.default_version, \'\')',
					'PLUGIN_STATUS'       => 'CASE WHEN ae.installed_version IS NULL THEN \'DISABLED\' ELSE \'ACTIVE\' END',
					'PLUGIN_TYPE'         => $this->connection->quote( 'EXTENSION' ),
					'PLUGIN_TYPE_VERSION' => 'COALESCE(ae.default_version, \'\')',
					'PLUGIN_AUTHOR'       => $empty_sql,
					'PLUGIN_DESCRIPTION'  => 'COALESCE(ae.comment, \'\')',
					'PLUGIN_LICENSE'      => $empty_sql,
					'LOAD_OPTION'         => 'CASE WHEN ae.installed_version IS NULL THEN \'OFF\' ELSE \'ON\' END',
				),
			),
			'schemata'                     => array(
				'alias'       => 's',
				'from'        => 'information_schema.schemata s',
				'where'       => 's.schema_name = ' . $information_schema . ' OR s.schema_name ' . $pg_schema_filter,
				'expressions' => array(
					'CATALOG_NAME'               => $def_sql,
					'SCHEMA_NAME'                => $this->get_direct_information_schema_display_schema_sql( 's.schema_name' ),
					'DEFAULT_CHARACTER_SET_NAME' => $charset_sql,
					'DEFAULT_COLLATION_NAME'     => $collation_sql,
					'SQL_PATH'                   => 'NULL',
					'DEFAULT_ENCRYPTION'         => $no_sql,
				),
			),
			'table_constraints'            => array(
				'alias'       => 'tc',
				'from'        => 'information_schema.table_constraints tc',
				'join'        => 'LEFT JOIN pg_catalog.pg_namespace table_ns
	ON table_ns.nspname = tc.table_schema
LEFT JOIN pg_catalog.pg_class table_class
	ON table_class.relnamespace = table_ns.oid
	AND table_class.relname = tc.table_name
	AND table_class.relkind IN (\'r\', \'p\')
LEFT JOIN pg_catalog.pg_constraint con
	ON con.conrelid = table_class.oid
	AND con.conname = tc.constraint_name
	AND con.contype = \'c\'',
				'where'       => 'tc.table_schema ' . $schema_filter,
				'expressions' => array(
					'CONSTRAINT_CATALOG' => $def_sql,
					'CONSTRAINT_SCHEMA'  => $this->get_direct_information_schema_display_schema_sql( 'tc.constraint_schema' ),
					'CONSTRAINT_NAME'    => 'CASE WHEN tc.constraint_type = \'PRIMARY KEY\' THEN \'PRIMARY\' ELSE tc.constraint_name END',
					'TABLE_SCHEMA'       => $this->get_direct_information_schema_display_schema_sql( 'tc.table_schema' ),
					'ENFORCED'           => 'CASE WHEN tc.constraint_type = \'CHECK\' THEN ' . $check_enforced_sql . ' ELSE \'YES\' END',
				),
			),
			'table_constraints_extensions' => array(
				'alias'       => 'tc',
				'from'        => 'information_schema.table_constraints tc',
				'where'       => 'tc.table_schema ' . $schema_filter,
				'expressions' => array(
					'CONSTRAINT_CATALOG'         => $def_sql,
					'CONSTRAINT_SCHEMA'          => $this->get_direct_information_schema_display_schema_sql( 'tc.constraint_schema' ),
					'CONSTRAINT_NAME'            => 'CASE WHEN tc.constraint_type = \'PRIMARY KEY\' THEN \'PRIMARY\' ELSE tc.constraint_name END',
					'TABLE_SCHEMA'               => $this->get_direct_information_schema_display_schema_sql( 'tc.table_schema' ),
					'ENGINE_ATTRIBUTE'           => 'NULL',
					'SECONDARY_ENGINE_ATTRIBUTE' => 'NULL',
				),
			),
			'key_column_usage'             => array(
				'alias'       => 'kcu',
				'from'        => 'information_schema.key_column_usage kcu',
				'join'        => 'LEFT JOIN information_schema.table_constraints tc
	ON tc.constraint_schema = kcu.constraint_schema
	AND tc.constraint_name = kcu.constraint_name
	AND tc.table_schema = kcu.table_schema
	AND tc.table_name = kcu.table_name
LEFT JOIN information_schema.referential_constraints rc
	ON rc.constraint_schema = kcu.constraint_schema
	AND rc.constraint_name = kcu.constraint_name
LEFT JOIN information_schema.key_column_usage ref_kcu
	ON ref_kcu.constraint_schema = rc.unique_constraint_schema
	AND ref_kcu.constraint_name = rc.unique_constraint_name
	AND ref_kcu.ordinal_position = kcu.position_in_unique_constraint',
				'where'       => 'kcu.table_schema ' . $schema_filter,
				'expressions' => array(
					'CONSTRAINT_CATALOG'      => $def_sql,
					'CONSTRAINT_SCHEMA'       => $this->get_direct_information_schema_display_schema_sql( 'kcu.constraint_schema' ),
					'CONSTRAINT_NAME'         => 'CASE WHEN tc.constraint_type = \'PRIMARY KEY\' THEN \'PRIMARY\' ELSE kcu.constraint_name END',
					'TABLE_CATALOG'           => $def_sql,
					'TABLE_SCHEMA'            => $this->get_direct_information_schema_display_schema_sql( 'kcu.table_schema' ),
					'REFERENCED_TABLE_SCHEMA' => $this->get_direct_information_schema_display_schema_sql( 'ref_kcu.table_schema' ),
					'REFERENCED_TABLE_NAME'   => 'ref_kcu.table_name',
					'REFERENCED_COLUMN_NAME'  => 'ref_kcu.column_name',
				),
			),
			'referential_constraints'      => array(
				'alias'       => 'rc',
				'from'        => 'information_schema.referential_constraints rc',
				'join'        => 'JOIN information_schema.table_constraints tc
	ON tc.constraint_schema = rc.constraint_schema
	AND tc.constraint_name = rc.constraint_name
LEFT JOIN information_schema.table_constraints ref_tc
	ON ref_tc.constraint_schema = rc.unique_constraint_schema
	AND ref_tc.constraint_name = rc.unique_constraint_name',
				'where'       => 'tc.table_schema ' . $schema_filter,
				'expressions' => array(
					'CONSTRAINT_CATALOG'        => $def_sql,
					'CONSTRAINT_SCHEMA'         => $this->get_direct_information_schema_display_schema_sql( 'rc.constraint_schema' ),
					'UNIQUE_CONSTRAINT_CATALOG' => $def_sql,
					'UNIQUE_CONSTRAINT_SCHEMA'  => $this->get_direct_information_schema_display_schema_sql( 'rc.unique_constraint_schema' ),
					'UNIQUE_CONSTRAINT_NAME'    => 'CASE WHEN ref_tc.constraint_type = \'PRIMARY KEY\' THEN \'PRIMARY\' ELSE rc.unique_constraint_name END',
					'TABLE_NAME'                => 'tc.table_name',
					'REFERENCED_TABLE_NAME'     => 'ref_tc.table_name',
				),
			),
			'check_constraints'            => array(
				'alias'       => 'cc',
				'from'        => 'information_schema.check_constraints cc',
				'join'        => 'JOIN information_schema.table_constraints tc
	ON tc.constraint_schema = cc.constraint_schema
	AND tc.constraint_name = cc.constraint_name
	AND tc.constraint_type = \'CHECK\'
LEFT JOIN pg_catalog.pg_namespace table_ns
	ON table_ns.nspname = tc.table_schema
LEFT JOIN pg_catalog.pg_class table_class
	ON table_class.relnamespace = table_ns.oid
	AND table_class.relname = tc.table_name
	AND table_class.relkind IN (\'r\', \'p\')
LEFT JOIN pg_catalog.pg_constraint con
	ON con.conrelid = table_class.oid
	AND con.conname = tc.constraint_name
	AND con.contype = \'c\'',
				'where'       => 'tc.table_schema ' . $schema_filter,
				'expressions' => array(
					'CONSTRAINT_CATALOG' => $def_sql,
					'CONSTRAINT_SCHEMA'  => $this->get_direct_information_schema_display_schema_sql( 'cc.constraint_schema' ),
					'CHECK_CLAUSE'       => $check_clause_sql,
				),
			),
			'columns_extensions'           => array(
				'alias'       => 'c',
				'from'        => 'information_schema.columns c',
				'where'       => 'c.table_schema ' . $schema_filter,
				'expressions' => array(
					'TABLE_CATALOG'              => $def_sql,
					'TABLE_SCHEMA'               => $this->get_direct_information_schema_display_schema_sql( 'c.table_schema' ),
					'ENGINE_ATTRIBUTE'           => 'NULL',
					'SECONDARY_ENGINE_ATTRIBUTE' => 'NULL',
				),
			),
			'tablespaces_extensions'       => $tablespace_relation + array(
				'expressions' => array(
					'TABLESPACE_NAME' => 'ts.spcname',
				),
			),
			'tablespaces'                  => $tablespace_relation + array(
				'expressions' => array(
					'TABLESPACE_NAME'    => 'ts.spcname',
					'ENGINE'             => $this->connection->quote( 'InnoDB' ),
					'TABLESPACE_TYPE'    => $this->connection->quote( 'General' ),
					'TABLESPACE_COMMENT' => 'COALESCE(pg_catalog.obj_description(ts.oid, \'pg_tablespace\'), \'\')',
				),
			),
			'innodb_tablespaces'           => $tablespace_relation + array(
				'expressions' => array(
					'SPACE'           => 'CAST(ts.oid AS bigint)',
					'NAME'            => 'ts.spcname',
					'FLAG'            => '0',
					'ROW_FORMAT'      => $this->connection->quote( 'Dynamic' ),
					'PAGE_SIZE'       => '16384',
					'ZIP_PAGE_SIZE'   => '0',
					'SPACE_TYPE'      => $this->connection->quote( 'Single' ),
					'AUTOEXTEND_SIZE' => '0',
					'SPACE_VERSION'   => '1',
					'ENCRYPTION'      => $this->connection->quote( 'N' ),
					'STATE'           => $this->connection->quote( 'normal' ),
				),
			),
			'innodb_tablespaces_brief'     => $tablespace_relation + array(
				'expressions' => array(
					'SPACE'      => 'CAST(ts.oid AS bigint)',
					'NAME'       => 'ts.spcname',
					'PATH'       => $tablespace_path_sql,
					'FLAG'       => '0',
					'SPACE_TYPE' => $this->connection->quote( 'Single' ),
				),
			),
			'innodb_datafiles'             => $tablespace_relation + array(
				'expressions' => array(
					'SPACE' => 'CAST(ts.oid AS bigint)',
					'PATH'  => $tablespace_path_sql,
				),
			),
			'user_privileges'              => array(
				'alias'       => 'acl',
				'from'        => 'pg_catalog.pg_database d
CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(d.datacl, pg_catalog.acldefault(\'d\', d.datdba))) acl',
				'join'        => 'LEFT JOIN pg_catalog.pg_roles grantee_role
	ON grantee_role.oid = acl.grantee',
				'where'       => 'd.datname = current_database()',
				'expressions' => array(
					'GRANTEE'       => $acl_grantee_sql,
					'TABLE_CATALOG' => $def_sql,
					'IS_GRANTABLE'  => 'CASE WHEN acl.is_grantable THEN \'YES\' ELSE \'NO\' END',
				),
			),
			'schema_privileges'            => array(
				'alias'       => 'acl',
				'from'        => 'pg_catalog.pg_namespace n
CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(n.nspacl, pg_catalog.acldefault(\'n\', n.nspowner))) acl',
				'join'        => 'LEFT JOIN pg_catalog.pg_roles grantee_role
	ON grantee_role.oid = acl.grantee',
				'where'       => 'n.nspname ' . $schema_filter,
				'expressions' => array(
					'GRANTEE'       => $acl_grantee_sql,
					'TABLE_CATALOG' => $def_sql,
					'TABLE_SCHEMA'  => $this->get_direct_information_schema_display_schema_sql( 'n.nspname' ),
					'IS_GRANTABLE'  => 'CASE WHEN acl.is_grantable THEN \'YES\' ELSE \'NO\' END',
				),
			),
			'table_privileges'             => array(
				'alias'       => 'tp',
				'from'        => 'information_schema.table_privileges tp',
				'where'       => 'tp.table_schema ' . $schema_filter,
				'expressions' => array(
					'GRANTEE'       => 'pg_catalog.quote_literal(tp.grantee) || ' . $user_host_sql,
					'TABLE_CATALOG' => $def_sql,
					'TABLE_SCHEMA'  => $this->get_direct_information_schema_display_schema_sql( 'tp.table_schema' ),
				),
			),
			'role_table_grants'            => array(
				'alias'       => 'rtg',
				'from'        => 'information_schema.role_table_grants rtg',
				'where'       => 'rtg.table_schema ' . $schema_filter,
				'expressions' => array(
					'GRANTOR_HOST'  => $percent_sql,
					'GRANTEE_HOST'  => $percent_sql,
					'TABLE_CATALOG' => $def_sql,
					'TABLE_SCHEMA'  => $this->get_direct_information_schema_display_schema_sql( 'rtg.table_schema' ),
				),
			),
			'role_routine_grants'          => array(
				'alias'       => 'rrg',
				'from'        => 'information_schema.role_routine_grants rrg',
				'where'       => 'rrg.specific_schema ' . $schema_filter,
				'expressions' => array(
					'GRANTOR_HOST'     => $percent_sql,
					'GRANTEE_HOST'     => $percent_sql,
					'SPECIFIC_CATALOG' => $def_sql,
					'SPECIFIC_SCHEMA'  => $this->get_direct_information_schema_display_schema_sql( 'rrg.specific_schema' ),
					'ROUTINE_CATALOG'  => $def_sql,
					'ROUTINE_SCHEMA'   => $this->get_direct_information_schema_display_schema_sql( 'rrg.routine_schema' ),
				),
			),
			'applicable_roles'             => array(
				'alias'       => 'ar',
				'from'        => 'information_schema.applicable_roles ar',
				'expressions' => array(
					'USER'         => 'ar.grantee',
					'HOST'         => $percent_sql,
					'GRANTEE'      => 'ar.grantee',
					'GRANTEE_HOST' => $percent_sql,
					'ROLE_HOST'    => $percent_sql,
					'IS_DEFAULT'   => $no_sql,
					'IS_MANDATORY' => $no_sql,
				),
			),
			'enabled_roles'                => array(
				'alias'       => 'er',
				'from'        => 'information_schema.enabled_roles er',
				'expressions' => array(
					'ROLE_HOST'    => $percent_sql,
					'IS_DEFAULT'   => $no_sql,
					'IS_MANDATORY' => $no_sql,
				),
			),
			'schemata_extensions'          => array(
				'alias'       => 's',
				'from'        => 'information_schema.schemata s',
				'where'       => 's.schema_name = ' . $information_schema . ' OR s.schema_name ' . $pg_schema_filter,
				'expressions' => array(
					'CATALOG_NAME' => $def_sql,
					'SCHEMA_NAME'  => $this->get_direct_information_schema_display_schema_sql( 's.schema_name' ),
					'OPTIONS'      => 'NULL',
				),
			),
			'view_table_usage'             => array(
				'alias'       => 'vtu',
				'from'        => 'information_schema.view_table_usage vtu',
				'where'       => 'vtu.view_schema ' . $schema_filter . "\n\tAND vtu.table_schema " . $schema_filter,
				'expressions' => array(
					'VIEW_CATALOG'  => $def_sql,
					'VIEW_SCHEMA'   => $this->get_direct_information_schema_display_schema_sql( 'vtu.view_schema' ),
					'TABLE_CATALOG' => $def_sql,
					'TABLE_SCHEMA'  => $this->get_direct_information_schema_display_schema_sql( 'vtu.table_schema' ),
				),
			),
			'view_routine_usage'           => array(
				'alias'       => 'vru',
				'from'        => 'information_schema.view_routine_usage vru',
				'where'       => 'vru.table_schema ' . $schema_filter . "\n\tAND vru.specific_schema " . $schema_filter,
				'expressions' => array(
					'TABLE_CATALOG'    => $def_sql,
					'TABLE_SCHEMA'     => $this->get_direct_information_schema_display_schema_sql( 'vru.table_schema' ),
					'SPECIFIC_CATALOG' => $def_sql,
					'SPECIFIC_SCHEMA'  => $this->get_direct_information_schema_display_schema_sql( 'vru.specific_schema' ),
				),
			),
			'views'                        => array(
				'alias'       => 'v',
				'from'        => 'information_schema.views v',
				'where'       => 'v.table_schema ' . $schema_filter,
				'expressions' => array(
					'TABLE_CATALOG'        => $def_sql,
					'TABLE_SCHEMA'         => $this->get_direct_information_schema_display_schema_sql( 'v.table_schema' ),
					'CHECK_OPTION'         => 'COALESCE(v.check_option, ' . $none_sql . ')',
					'IS_UPDATABLE'         => 'COALESCE(v.is_updatable, ' . $no_sql . ')',
					'DEFINER'              => $empty_sql,
					'SECURITY_TYPE'        => $this->connection->quote( 'DEFINER' ),
					'CHARACTER_SET_CLIENT' => $charset_sql,
					'COLLATION_CONNECTION' => $collation_sql,
				),
			),
			'triggers'                     => array(
				'alias'       => 't',
				'from'        => 'information_schema.triggers t',
				'where'       => 't.trigger_schema ' . $schema_filter,
				'expressions' => array(
					'TRIGGER_CATALOG'      => $def_sql,
					'TRIGGER_SCHEMA'       => $this->get_direct_information_schema_display_schema_sql( 't.trigger_schema' ),
					'EVENT_OBJECT_CATALOG' => $def_sql,
					'EVENT_OBJECT_SCHEMA'  => $this->get_direct_information_schema_display_schema_sql( 't.event_object_schema' ),
					'CREATED'              => 'TO_CHAR(t.created, ' . $datetime_format_sql . ')',
					'SQL_MODE'             => $sql_mode_sql,
					'DEFINER'              => $empty_sql,
					'CHARACTER_SET_CLIENT' => $charset_sql,
					'COLLATION_CONNECTION' => $collation_sql,
					'DATABASE_COLLATION'   => $collation_sql,
				),
			),
			'routines'                     => array(
				'alias'       => 'r',
				'from'        => 'information_schema.routines r',
				'where'       => 'r.routine_schema ' . $schema_filter,
				'expressions' => array(
					'ROUTINE_CATALOG'      => $def_sql,
					'ROUTINE_SCHEMA'       => $this->get_direct_information_schema_display_schema_sql( 'r.routine_schema' ),
					'CREATED'              => 'TO_CHAR(r.created, ' . $datetime_format_sql . ')',
					'LAST_ALTERED'         => 'TO_CHAR(r.last_altered, ' . $datetime_format_sql . ')',
					'SQL_MODE'             => $sql_mode_sql,
					'ROUTINE_COMMENT'      => $empty_sql,
					'DEFINER'              => $empty_sql,
					'CHARACTER_SET_CLIENT' => $charset_sql,
					'COLLATION_CONNECTION' => $collation_sql,
					'DATABASE_COLLATION'   => $collation_sql,
				),
			),
			'parameters'                   => array(
				'alias'       => 'p',
				'from'        => 'information_schema.parameters p',
				'join'        => 'LEFT JOIN information_schema.routines r
	ON r.specific_catalog = p.specific_catalog
	AND r.specific_schema = p.specific_schema
	AND r.specific_name = p.specific_name',
				'where'       => 'p.specific_schema ' . $schema_filter,
				'expressions' => array(
					'SPECIFIC_CATALOG' => $def_sql,
					'SPECIFIC_SCHEMA'  => $this->get_direct_information_schema_display_schema_sql( 'p.specific_schema' ),
					'ROUTINE_TYPE'     => 'COALESCE(r.routine_type, ' . $function_sql . ')',
				),
			),
		);

		foreach (
			array(
				'column_privileges'                 => array(
					'base'       => 'table_privileges',
					'base_alias' => 'tp',
					'alias'      => 'cp',
					'from'       => 'information_schema.column_privileges cp',
				),
				'role_column_grants'                => array(
					'base'       => 'role_table_grants',
					'base_alias' => 'rtg',
					'alias'      => 'rcg',
					'from'       => 'information_schema.role_column_grants rcg',
				),
				'administrable_role_authorizations' => array(
					'base'       => 'applicable_roles',
					'base_alias' => 'ar',
					'alias'      => 'ara',
					'from'       => 'information_schema.administrable_role_authorizations ara',
				),
			) as $relation => $variant
		) {
			$definition          = $definitions[ $variant['base'] ];
			$definition['alias'] = $variant['alias'];
			$definition['from']  = $variant['from'];
			if ( isset( $definition['where'] ) ) {
				$definition['where'] = str_replace( $variant['base_alias'] . '.', $variant['alias'] . '.', $definition['where'] );
			}
			foreach ( $definition['expressions'] as $column => $expression ) {
				$definition['expressions'][ $column ] = str_replace( $variant['base_alias'] . '.', $variant['alias'] . '.', $expression );
			}
			$definitions[ $relation ] = $definition;
		}

		if ( ! isset( $definitions[ $view ] ) ) {
			return null;
		}

		$definition = $definitions[ $view ];
		$sql        = 'SELECT
		' . $this->get_direct_information_schema_ordered_native_projection_sql( $view, $definition ) . '
FROM ' . $definition['from'];

		if ( ! empty( $definition['join'] ) ) {
			$sql .= "\n" . $definition['join'];
		}

		if ( ! empty( $definition['where'] ) ) {
			$sql .= "\nWHERE " . $definition['where'];
		}

		return $sql;
	}

	/**
	 * Build a MySQL-ordered SELECT list for a native information_schema source.
	 *
	 * @param string $view       Information schema view name.
	 * @param array  $definition Native relation definition.
	 * @return string Ordered projection SQL.
	 */
	private function get_direct_information_schema_ordered_native_projection_sql( string $view, array $definition ): string {
		$columns = $this->get_direct_information_schema_relation_columns( $view );
		if ( null === $columns ) {
			throw new LogicException( 'Unsupported direct information_schema relation projection.' );
		}

		$alias       = $definition['alias'];
		$expressions = $definition['expressions'] ?? array();
		$default     = $definition['default'] ?? null;
		$projection  = array();
		foreach ( $columns as $column ) {
			$expression = array_key_exists( $column, $expressions )
				? $expressions[ $column ]
				: ( $default ?? $alias . '.' . strtolower( $column ) );

			$projection[] = $expression . ' AS ' . $this->connection->quote_identifier( $column );
		}

		return implode( ",\n\t\t", $projection );
	}

	/**
	 * Check whether a projection expression is unaliased COUNT(*).
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First expression token.
	 * @param int              $end    Final expression token, exclusive.
	 * @return bool Whether this is COUNT(*).
	 */
	private function is_direct_information_schema_count_star_projection( array $tokens, int $start, int $end ): bool {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		return $start + 4 === $end
			&& isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ], $tokens[ $start + 3 ] )
			&& $this->is_mysql_token_value( $tokens[ $start ], 'count' )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $start + 1 ]->id
			&& '*' === $tokens[ $start + 2 ]->get_bytes()
			&& WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $start + 3 ]->id;
	}

	/**
	 * Get DATABASE()/SCHEMA() replacements for a direct information_schema range.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int              $start            First token.
	 * @param int              $end              Final token, exclusive.
	 * @param array[]          $protected_ranges Ranges already handled by larger replacements.
	 * @return array[]|null Replacement ranges, or null when a current-database function has unsupported arguments.
	 */
	private function get_direct_information_schema_current_database_function_replacements( array $tokens, int $start, int $end, array $protected_ranges = array() ): ?array {
		$replacements = array();
		for ( $position = $start; $position < $end; $position++ ) {
			$protected_end = $this->get_covering_mysql_replacement_range_end( $position, $protected_ranges );
			if ( null !== $protected_end ) {
				$position = $protected_end - 1;
				continue;
			}

			$bounds = $this->get_mysql_common_function_bounds( $tokens, $position, $end );
			if ( null === $bounds || ! in_array( $bounds['function'], array( 'database', 'schema' ), true ) ) {
				continue;
			}

			$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
			if ( null === $arguments || array() !== $arguments ) {
				return null;
			}

			$replacements[] = array(
				'start' => $position,
				'end'   => $bounds['close'] + 1,
				'sql'   => $this->connection->quote( $this->db_name ),
			);
			$position       = $bounds['close'];
		}

		return $replacements;
	}

	/**
	 * Get column-reference replacements for a direct information_schema range.
	 *
	 * @param WP_MySQL_Token[] $tokens  MySQL lexer token stream.
	 * @param int              $start   First token.
	 * @param int              $end     Final token, exclusive.
	 * @param array            $context Direct information_schema SELECT context.
	 * @return array[]|null Replacement ranges, or null when a source-qualified reference is unsupported.
	 */
	private function get_direct_information_schema_column_replacements( array $tokens, int $start, int $end, array $context, array $protected_ranges = array() ): ?array {
		$replacements = array();
		for ( $position = $start; $position < $end; $position++ ) {
			$protected_end = $this->get_covering_mysql_replacement_range_end( $position, $protected_ranges );
			if ( null !== $protected_end ) {
				$position = $protected_end - 1;
				continue;
			}

			if (
				isset( $tokens[ $position + 1 ], $tokens[ $position + 2 ], $tokens[ $position + 3 ], $tokens[ $position + 4 ] )
				&& $position + 4 < $end
				&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position + 1 ]->id
				&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position + 3 ]->id
			) {
				$schema = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] );
				if ( null !== $schema && 0 === strcasecmp( $schema, 'information_schema' ) ) {
					$qualifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position + 2 ] );
					$source    = null === $qualifier ? null : $this->get_direct_information_schema_source_for_qualifier( $qualifier, $context );
					$column    = null === $source ? null : $this->get_direct_information_schema_column_name_for_token( $tokens[ $position + 4 ], $source['column_map'] );
					if ( null === $source || null === $column ) {
						return null;
					}

					$replacements[] = array(
						'start' => $position,
						'end'   => $position + 5,
						'sql'   => $this->get_direct_information_schema_qualified_column_sql( $source, $column ),
					);
					$position      += 4;
					continue;
				}
			}

			if (
				isset( $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
				&& $position + 2 < $end
				&& ( ! isset( $tokens[ $position - 1 ] ) || WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $position - 1 ]->id )
				&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				$qualifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] );
				$source    = null === $qualifier ? null : $this->get_direct_information_schema_source_for_qualifier( $qualifier, $context );
				if ( null !== $source ) {
					$column = $this->get_direct_information_schema_column_name_for_token( $tokens[ $position + 2 ], $source['column_map'] );
					if ( null === $column ) {
						return null;
					}

					$replacements[] = array(
						'start' => $position,
						'end'   => $position + 3,
						'sql'   => $this->get_direct_information_schema_qualified_column_sql( $source, $column ),
					);
					$position      += 2;
					continue;
				}
			}

			if (
				( isset( $tokens[ $position - 1 ] ) && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position - 1 ]->id )
				|| ( isset( $tokens[ $position + 1 ] ) && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position + 1 ]->id )
			) {
				continue;
			}

			$column_sql = $this->get_direct_information_schema_unqualified_column_sql( $tokens[ $position ], $context );
			if ( false === $column_sql ) {
				return null;
			}
			if ( null === $column_sql ) {
				continue;
			}

			$replacements[] = array(
				'start' => $position,
				'end'   => $position + 1,
				'sql'   => $column_sql,
			);
		}

		return $replacements;
	}

	/**
	 * Get safe unary BINARY operator replacements for direct information_schema ranges.
	 *
	 * PostgreSQL text comparisons are already byte-sensitive in these rewritten
	 * catalog relations. Strip only the standalone MySQL unary operator while
	 * leaving CAST(... AS BINARY) and CONVERT(..., BINARY) intact for their
	 * dedicated translators.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int              $start            First token.
	 * @param int              $end              Final token, exclusive.
	 * @param array[]          $protected_ranges Ranges already handled by larger replacements.
	 * @return array[] Replacement ranges.
	 */
	private function get_direct_information_schema_binary_operator_replacements( array $tokens, int $start, int $end, array $protected_ranges = array() ): array {
		$invalid_next_token_ids     = array(
			WP_MySQL_Lexer::CLOSE_PAR_SYMBOL,
			WP_MySQL_Lexer::COMMA_SYMBOL,
			WP_MySQL_Lexer::EOF,
			WP_MySQL_Lexer::SEMICOLON_SYMBOL,
		);
		$invalid_previous_token_ids = array(
			WP_MySQL_Lexer::AS_SYMBOL,
			WP_MySQL_Lexer::COMMA_SYMBOL,
			WP_MySQL_Lexer::OPEN_PAR_SYMBOL,
			WP_MySQL_Lexer::USING_SYMBOL,
		);
		$valid_previous_token_ids   = array(
			WP_MySQL_Lexer::AND_SYMBOL,
			WP_MySQL_Lexer::BETWEEN_SYMBOL,
			WP_MySQL_Lexer::BY_SYMBOL,
			WP_MySQL_Lexer::EQUAL_OPERATOR,
			WP_MySQL_Lexer::GREATER_OR_EQUAL_OPERATOR,
			WP_MySQL_Lexer::GREATER_THAN_OPERATOR,
			WP_MySQL_Lexer::HAVING_SYMBOL,
			WP_MySQL_Lexer::LESS_OR_EQUAL_OPERATOR,
			WP_MySQL_Lexer::LESS_THAN_OPERATOR,
			WP_MySQL_Lexer::LIKE_SYMBOL,
			WP_MySQL_Lexer::NOT_SYMBOL,
			WP_MySQL_Lexer::NOT_EQUAL_OPERATOR,
			WP_MySQL_Lexer::OR_SYMBOL,
			WP_MySQL_Lexer::REGEXP_SYMBOL,
			WP_MySQL_Lexer::WHERE_SYMBOL,
			WP_MySQL_Lexer::XOR_SYMBOL,
		);
		$replacements               = array();

		for ( $position = $start; $position < $end; $position++ ) {
			$protected_end = $this->get_covering_mysql_replacement_range_end( $position, $protected_ranges );
			if ( null !== $protected_end ) {
				$position = $protected_end - 1;
				continue;
			}

			if (
				! isset( $tokens[ $position ] )
				|| WP_MySQL_Lexer::BINARY_SYMBOL !== $tokens[ $position ]->id
				|| $position + 1 >= $end
				|| ! isset( $tokens[ $position + 1 ] )
				|| in_array( $tokens[ $position + 1 ]->id, $invalid_next_token_ids, true )
			) {
				continue;
			}

			if ( $position > $start && isset( $tokens[ $position - 1 ] ) ) {
				$previous_token_id = $tokens[ $position - 1 ]->id;
				if (
					in_array( $previous_token_id, $invalid_previous_token_ids, true )
					|| ! in_array( $previous_token_id, $valid_previous_token_ids, true )
				) {
					continue;
				}
			}

			$replacements[] = array(
				'start' => $position,
				'end'   => $position + 1,
				'sql'   => '',
			);
		}

		return $replacements;
	}

	/**
	 * Get the end of a replacement range that covers a token position.
	 *
	 * @param int     $position     Token position.
	 * @param array[] $replacements Replacement ranges.
	 * @return int|null Range end, or null.
	 */
	private function get_covering_mysql_replacement_range_end( int $position, array $replacements ): ?int {
		foreach ( $replacements as $replacement ) {
			if ( $position >= $replacement['start'] && $position < $replacement['end'] ) {
				return $replacement['end'];
			}
		}

		return null;
	}

	/**
	 * Get nested SELECT replacements for supported direct information_schema clause subqueries.
	 *
	 * @param string           $query         Original MySQL query.
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param array[]          $clause_ranges Clause token ranges.
	 * @return array[]|null Replacement ranges, or null when a nested SELECT is unsupported.
	 */
	private function get_direct_information_schema_nested_select_replacements( string $query, array $tokens, array $clause_ranges ): ?array {
		$replacements = array();
		foreach ( $clause_ranges as $range ) {
			for ( $position = $range['start']; $position < $range['end']; $position++ ) {
				if (
					! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
					|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id
					|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position + 1 ]->id
				) {
					continue;
				}

				$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $range['end'] );
				if ( null === $after_close ) {
					return null;
				}

				$select_start = $position + 1;
				$select_end   = $after_close - 1;
				$select_query = $this->get_mysql_token_range_bytes( $query, $tokens, $select_start, $select_end );
				if ( '' === $select_query ) {
					return null;
				}

				$translated_select = $this->translate_direct_information_schema_select_query( $select_query );
				if ( null === $translated_select ) {
					if ( $this->mysql_select_range_requires_direct_information_schema_rewrite( $tokens, $select_start, $select_end ) ) {
						return null;
					}

					$translated_select = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $select_start, $select_end );
				}

				$replacements[] = array(
					'start' => $select_start,
					'end'   => $select_end,
					'sql'   => $translated_select,
				);
				$position       = $after_close - 1;
			}
		}

		return $replacements;
	}

	/**
	 * Check whether every nested SELECT is covered by a complete replacement range.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $start        First token position.
	 * @param int              $end          Final token position, exclusive.
	 * @param array[]          $replacements Replacement ranges.
	 * @return bool Whether nested SELECTs are fully handled.
	 */
	private function direct_information_schema_nested_selects_are_covered( array $tokens, int $start, int $end, array $replacements ): bool {
		for ( $position = $start; $position < $end; $position++ ) {
			if ( WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position ]->id ) {
				continue;
			}

			if ( null === $this->get_covering_mysql_replacement_range_end( $position, $replacements ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Get direct information_schema nested SELECT replacements for simple DML predicates.
	 *
	 * Simple application-table UPDATE/DELETE predicates can safely read supported
	 * information_schema subqueries, but ordinary application-table subqueries
	 * should remain unsupported until they have a deliberate translation path.
	 *
	 * @param string           $query     Original MySQL query.
	 * @param WP_MySQL_Token[] $tokens    MySQL lexer token stream.
	 * @param int              $start     First predicate token position.
	 * @param int              $end       Final predicate token position, exclusive.
	 * @param array            $cte_names Known CTE names keyed lowercase.
	 * @return array[]|null Replacement ranges, empty when no nested SELECT is present, or null when unsupported.
	 */
	private function get_simple_mysql_dml_predicate_nested_select_replacements( string $query, array $tokens, int $start, int $end, array $cte_names = array() ): ?array {
		$has_nested_select             = false;
		$has_information_schema_select = false;
		$cte_replacements              = array();
		for ( $position = $start; $position < $end; $position++ ) {
			if (
				! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
				|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id
				|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position + 1 ]->id
			) {
				continue;
			}

			$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
			if ( null === $after_close ) {
				return null;
			}

			$select_start = $position + 1;
			$select_end   = $after_close - 1;
			if ( $this->mysql_select_range_requires_direct_information_schema_rewrite( $tokens, $select_start, $select_end ) ) {
				$has_information_schema_select = true;
			} elseif ( $this->mysql_select_range_references_only_cte_sources( $tokens, $select_start, $select_end, $cte_names ) ) {
				$cte_replacements[] = array(
					'start' => $position,
					'end'   => $after_close,
					'sql'   => '(' . $this->translate_mysql_token_sequence_to_postgresql( $tokens, $select_start, $select_end ) . ')',
				);
			} else {
				return null;
			}

			$has_nested_select = true;
			$position          = $after_close - 1;
		}

		if ( ! $has_nested_select ) {
			return array();
		}

		if ( $has_information_schema_select && ! empty( $cte_replacements ) ) {
			return null;
		}

		$replacements = $cte_replacements;
		if ( $has_information_schema_select ) {
			$information_schema_replacements = $this->get_direct_information_schema_nested_select_replacements(
				$query,
				$tokens,
				array(
					array(
						'start' => $start,
						'end'   => $end,
					),
				)
			);
			if (
				null === $information_schema_replacements
				|| ! $this->direct_information_schema_nested_selects_are_covered(
					$tokens,
					$start,
					$end,
					array_merge( $information_schema_replacements, $cte_replacements )
				)
			) {
				return null;
			}

			$replacements = array_merge( $replacements, $information_schema_replacements );
		} elseif ( ! $this->direct_information_schema_nested_selects_are_covered( $tokens, $start, $end, $cte_replacements ) ) {
			return null;
		}

		usort(
			$replacements,
			static function ( array $left, array $right ): int {
				return $left['start'] <=> $right['start'];
			}
		);

		return $replacements;
	}

	/**
	 * Check whether a SELECT range reads only CTE sources declared by the statement prefix.
	 *
	 * @param WP_MySQL_Token[]   $tokens    MySQL lexer token stream.
	 * @param int                $start     SELECT token position.
	 * @param int                $end       Final SELECT token position, exclusive.
	 * @param array<string,bool> $cte_names Known CTE names keyed lowercase.
	 * @return bool Whether all top-level FROM sources are known CTEs.
	 */
	private function mysql_select_range_references_only_cte_sources( array $tokens, int $start, int $end, array $cte_names ): bool {
		if ( empty( $cte_names ) || ! isset( $tokens[ $start ] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $start ]->id ) {
			return false;
		}

		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, $start + 1, $end );
		if ( null === $from_position ) {
			return false;
		}

		$from_end = $this->find_first_top_level_mysql_token(
			$tokens,
			array(
				WP_MySQL_Lexer::FOR_SYMBOL,
				WP_MySQL_Lexer::GROUP_SYMBOL,
				WP_MySQL_Lexer::HAVING_SYMBOL,
				WP_MySQL_Lexer::LIMIT_SYMBOL,
				WP_MySQL_Lexer::LOCK_SYMBOL,
				WP_MySQL_Lexer::ORDER_SYMBOL,
				WP_MySQL_Lexer::PROCEDURE_SYMBOL,
				WP_MySQL_Lexer::UNION_SYMBOL,
				WP_MySQL_Lexer::WHERE_SYMBOL,
			),
			$from_position + 1,
			$end
		) ?? $end;

		$position      = $from_position + 1;
		$expect_source = true;
		$source_count  = 0;
		while ( $position < $from_end ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				return false;
			}

			if ( $expect_source ) {
				$reference = $this->parse_mysql_table_reference( $tokens, $position, $from_end );
				if (
					null === $reference
					|| 'public' !== $reference['schema']
					|| ! isset( $cte_names[ strtolower( $reference['table'] ) ] )
				) {
					return false;
				}

				$position      = $reference['position'];
				$expect_source = false;
				++$source_count;
				continue;
			}

			if (
				WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id
				|| $this->is_mysql_join_token( $tokens[ $position ] )
			) {
				$expect_source = true;
			}

			++$position;
		}

		return $source_count > 0 && ! $expect_source;
	}

	/**
	 * Get a direct information_schema source for a qualifier.
	 *
	 * @param string $qualifier Qualifier token value.
	 * @param array  $context   Direct information_schema SELECT context.
	 * @return array|null Source, or null when the qualifier is not unique.
	 */
	private function get_direct_information_schema_source_for_qualifier( string $qualifier, array $context ): ?array {
		$matches = array();
		foreach ( $context['sources'] as $source ) {
			if ( 0 === strcasecmp( $qualifier, $source['alias'] ) ) {
				return $source;
			}

			if ( isset( $source['view'] ) && 0 === strcasecmp( $qualifier, $source['view'] ) ) {
				$matches[] = $source;
			}
		}

		return 1 === count( $matches ) ? $matches[0] : null;
	}

	/**
	 * Get SQL for an unqualified information_schema column token.
	 *
	 * @param WP_MySQL_Token $token   MySQL token.
	 * @param array          $context Direct information_schema SELECT context.
	 * @return string|false|null SQL, false when ambiguous, or null when not a known column.
	 */
	private function get_direct_information_schema_unqualified_column_sql( WP_MySQL_Token $token, array $context ) {
		$column = $this->get_direct_information_schema_unqualified_column_name( $token, $context );
		if ( false === $column ) {
			return false;
		}
		if ( null === $column ) {
			return null;
		}

		if ( isset( $context['using_columns'][ strtolower( $column ) ] ) ) {
			return $this->connection->quote_identifier( $column );
		}

		if ( 1 === count( $context['sources'] ) ) {
			return $this->connection->quote_identifier( $column );
		}

		foreach ( $context['sources'] as $source ) {
			if ( isset( $source['column_map'][ strtolower( $column ) ] ) ) {
				return $this->get_direct_information_schema_qualified_column_sql( $source, $column );
			}
		}

		return false;
	}

	/**
	 * Get an unqualified information_schema column name.
	 *
	 * @param WP_MySQL_Token $token   MySQL token.
	 * @param array          $context Direct information_schema SELECT context.
	 * @return string|false|null Column name, false when ambiguous, or null when unknown.
	 */
	private function get_direct_information_schema_unqualified_column_name( WP_MySQL_Token $token, array $context ) {
		$value = $this->get_direct_information_schema_identifier_token_value( $token );
		if ( null === $value ) {
			return null;
		}

		$matches = array();
		$key     = strtolower( $value );
		foreach ( $context['sources'] as $source ) {
			if ( isset( $source['column_map'][ $key ] ) ) {
				$matches[] = array(
					'source' => $source,
					'column' => $source['column_map'][ $key ],
				);
			}
		}

		if ( 0 === count( $matches ) ) {
			return null;
		}

		if ( count( $matches ) > 1 ) {
			$using_column = $context['using_columns'][ $key ] ?? null;
			if ( is_array( $using_column ) && isset( $using_column['column'], $using_column['aliases'] ) ) {
				foreach ( $matches as $match ) {
					if ( ! isset( $using_column['aliases'][ strtolower( $match['source']['alias'] ) ] ) ) {
						return false;
					}
				}

				return $using_column['column'];
			}

			return false;
		}

		return $matches[0]['column'];
	}

	/**
	 * Get SQL for a source-qualified information_schema column.
	 *
	 * @param array  $source Direct information_schema source.
	 * @param string $column Uppercase column name.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_qualified_column_sql( array $source, string $column ): string {
		return $this->connection->quote_identifier( $source['alias'] ) . '.' . $this->connection->quote_identifier( $column );
	}

	/**
	 * Get a supported information_schema column name for a token.
	 *
	 * @param WP_MySQL_Token      $token      MySQL token.
	 * @param array<string,string> $column_map Supported columns keyed by lowercase name.
	 * @return string|null Uppercase column name, or null.
	 */
	private function get_direct_information_schema_column_name_for_token( WP_MySQL_Token $token, array $column_map ): ?string {
		$value = $this->get_direct_information_schema_identifier_token_value( $token );
		if ( null === $value ) {
			return null;
		}

		return $column_map[ strtolower( $value ) ] ?? null;
	}

	/**
	 * Build a literal relation from PHP-computed information_schema rows.
	 *
	 * @param string[] $columns Uppercase column names.
	 * @param array[]  $rows    Rows keyed by uppercase column name.
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_literal_relation_sql( array $columns, array $rows ): string {
		if ( empty( $rows ) ) {
			$select = array();
			foreach ( $columns as $column ) {
				$select[] = 'NULL AS ' . $this->connection->quote_identifier( $column );
			}
			return 'SELECT ' . implode( ', ', $select ) . ' WHERE 1 = 0';
		}

		$selects = array();
		foreach ( $rows as $row ) {
			$select = array();
			foreach ( $columns as $column ) {
				$value = $row[ $column ] ?? null;
				if ( null === $value ) {
					$literal_sql = 'NULL';
				} elseif ( is_int( $value ) || is_float( $value ) || ( is_string( $value ) && 1 === preg_match( '/^-?[0-9]+(?:\.[0-9]+)?$/', $value ) ) ) {
					$literal_sql = (string) $value;
				} else {
					$literal_sql = $this->connection->quote( (string) $value );
				}
				$select[] = $literal_sql . ' AS ' . $this->connection->quote_identifier( $column );
			}
			$selects[] = 'SELECT ' . implode( ', ', $select );
		}

		return implode( ' UNION ALL ', $selects );
	}

	/**
	 * Get MySQL-facing display schema SQL for a backend schema expression.
	 *
	 * @param string $schema_sql SQL expression returning a backend schema.
	 * @return string SQL expression returning a MySQL-facing schema.
	 */
	private function get_direct_information_schema_display_schema_sql( string $schema_sql ): string {
		return sprintf(
			'CASE WHEN %1$s = %2$s THEN %3$s ELSE %1$s END',
			$schema_sql,
			$this->connection->quote( 'public' ),
			$this->connection->quote( $this->main_db_name )
		);
	}

	/**
	 * Get MySQL-facing display schema for a backend schema value.
	 *
	 * @param string $schema Backend schema.
	 * @return string MySQL-facing schema.
	 */
	private function get_direct_information_schema_display_schema( string $schema ): string {
		return 0 === strcasecmp( $schema, 'public' ) ? $this->main_db_name : $schema;
	}

	/**
	 * Get a MySQL data type expression from PostgreSQL catalog metadata.
	 *
	 * @param string      $alias                Catalog column table alias.
	 * @param bool        $include_domain_cases Whether domain_name is available and should be decoded.
	 * @param string|null $column_comment_sql   Optional PostgreSQL column comment SQL.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_catalog_data_type_expression( string $alias, bool $include_domain_cases = true, ?string $column_comment_sql = null ): string {
		$comment_type_sql         = null === $column_comment_sql
			? 'NULL'
			: $this->get_postgresql_catalog_column_comment_marker_sql( $column_comment_sql, self::MYSQL_COLUMN_COMMENT_TYPE_PREFIX );
		$column_comment_type_case = sprintf(
			'WHEN %1$s IS NOT NULL THEN %2$s
	',
			$comment_type_sql,
			$this->get_direct_information_schema_metadata_data_type_expression( $comment_type_sql, 'NULL' )
		);
		$enum_data_type_case      = $include_domain_cases
			? sprintf(
				'WHEN %1$s.data_type = \'USER-DEFINED\' AND %1$s.udt_name LIKE \'__wp_mysql_enum_%%\' THEN \'enum\'
	',
				$alias
			)
			: '';
		$set_data_type_case       = $include_domain_cases
			? sprintf(
				'WHEN %1$s.domain_name LIKE \'__wp_mysql_set_%%\' THEN \'set\'
	',
				$alias
			)
			: '';

		return sprintf(
			'CASE
	%2$s%3$s%4$s%5$s
	WHEN %1$s.data_type = \'character varying\' THEN \'varchar\'
	WHEN %1$s.data_type = \'character\' THEN \'char\'
	WHEN %1$s.data_type = \'integer\' THEN \'int\'
	WHEN %1$s.data_type = \'numeric\' THEN \'decimal\'
	WHEN %1$s.data_type = \'double precision\' THEN \'double\'
	WHEN %1$s.data_type = \'real\' THEN \'float\'
	WHEN %1$s.data_type = \'timestamp without time zone\' THEN \'datetime\'
	ELSE %1$s.data_type
END',
			$alias,
			$column_comment_type_case,
			$enum_data_type_case,
			$set_data_type_case,
			$include_domain_cases ? $this->get_postgresql_mysql_domain_type_cases( $alias, false ) : ''
		);
	}

	/**
	 * Get a MySQL column type expression from PostgreSQL catalog metadata.
	 *
	 * @param string      $catalog_alias                 Catalog column table alias.
	 * @param string|null $identity_sequence_comment_sql Optional identity sequence comment SQL.
	 * @param string|null $column_comment_sql            Optional PostgreSQL column comment SQL.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_catalog_column_type_expression(
		string $catalog_alias,
		?string $identity_sequence_comment_sql = null,
		?string $column_comment_sql = null,
		bool $include_helper_type_cases = true
	): string {
		$identity_sequence_type_case = '';
		if ( null !== $identity_sequence_comment_sql ) {
			$prefix                      = $this->connection->quote( self::MYSQL_IDENTITY_SEQUENCE_COMMENT_TYPE_PREFIX );
			$identity_sequence_type_case = sprintf(
				'WHEN %1$s LIKE %2$s || \'%%\' THEN SUBSTR(%1$s, LENGTH(%2$s) + 1)
	',
				$identity_sequence_comment_sql,
				$prefix
			);
		}

		$column_comment_type_case = '';
		if ( null !== $column_comment_sql ) {
			$column_type_comment_sql  = $this->get_postgresql_catalog_column_comment_marker_sql( $column_comment_sql, self::MYSQL_COLUMN_COMMENT_TYPE_PREFIX );
			$column_comment_type_case = sprintf(
				'WHEN %1$s IS NOT NULL THEN %1$s
	',
				$column_type_comment_sql
			);
		}

		$enum_column_type_case = $include_helper_type_cases
			? sprintf(
				'WHEN %1$s.data_type = \'USER-DEFINED\' AND %1$s.udt_name LIKE \'__wp_mysql_enum_%%\' THEN (
		SELECT \'enum(\' || pg_catalog.string_agg(pg_catalog.quote_literal(e.enumlabel), \',\' ORDER BY e.enumsortorder) || \')\'
		FROM pg_catalog.pg_type typ
		INNER JOIN pg_catalog.pg_namespace ns
			ON ns.oid = typ.typnamespace
		INNER JOIN pg_catalog.pg_enum e
			ON e.enumtypid = typ.oid
		WHERE ns.nspname = %1$s.udt_schema
			AND typ.typname = %1$s.udt_name
	)
	',
				$catalog_alias
			)
			: '';
		$set_column_type_case  = $include_helper_type_cases
			? sprintf(
				'WHEN %1$s.domain_name LIKE \'__wp_mysql_set_%%\' THEN COALESCE((SELECT %2$s
		FROM pg_catalog.pg_type domain_type
		INNER JOIN pg_catalog.pg_namespace domain_ns
			ON domain_ns.oid = domain_type.typnamespace
		WHERE domain_ns.nspname = %1$s.domain_schema
			AND domain_type.typname = %1$s.domain_name
	), \'set\')
	',
				$catalog_alias,
				$this->get_postgresql_catalog_column_comment_marker_sql( 'pg_catalog.obj_description(domain_type.oid, \'pg_type\')', self::MYSQL_COLUMN_COMMENT_TYPE_PREFIX )
			)
			: '';

		return sprintf(
			'CASE
	%2$s%3$s%4$s%5$s%6$s
	WHEN %1$s.data_type = \'character varying\' THEN
		\'varchar\' || CASE WHEN %1$s.character_maximum_length IS NULL THEN \'\' ELSE \'(\' || CAST(%1$s.character_maximum_length AS text) || \')\' END
	WHEN %1$s.data_type = \'character\' THEN
		\'char\' || CASE WHEN %1$s.character_maximum_length IS NULL THEN \'\' ELSE \'(\' || CAST(%1$s.character_maximum_length AS text) || \')\' END
	WHEN %1$s.data_type = \'integer\' THEN \'int\'
	WHEN %1$s.data_type = \'numeric\' AND %1$s.numeric_precision IS NULL THEN \'numeric\'
	WHEN %1$s.data_type = \'numeric\' THEN
		\'decimal\' || CASE
			WHEN %1$s.numeric_scale IS NULL THEN \'(\' || CAST(%1$s.numeric_precision AS text) || \')\'
			ELSE \'(\' || CAST(%1$s.numeric_precision AS text) || \',\' || CAST(%1$s.numeric_scale AS text) || \')\'
		END
	WHEN %1$s.data_type = \'double precision\' THEN \'double\'
	WHEN %1$s.data_type = \'real\' THEN \'float\'
	WHEN %1$s.data_type = \'timestamp without time zone\' THEN \'datetime\'
	ELSE %1$s.data_type
END',
			$catalog_alias,
			$identity_sequence_type_case,
			$column_comment_type_case,
			$enum_column_type_case,
			$set_column_type_case,
			$include_helper_type_cases ? $this->get_postgresql_mysql_domain_type_cases( $catalog_alias, true ) : ''
		);
	}

	/**
	 * Get SQL that reads the comment for a catalog column's identity sequence.
	 *
	 * @param string $catalog_alias Catalog column table alias.
	 * @return string SQL expression.
	 */
	private function get_postgresql_identity_sequence_comment_sql( string $catalog_alias ): string {
		return sprintf(
			'pg_catalog.obj_description(pg_catalog.pg_get_serial_sequence(format(\'%%I.%%I\', %1$s.table_schema, %1$s.table_name), %1$s.column_name)::regclass, \'pg_class\')',
			$catalog_alias
		);
	}

	/**
	 * Get CASE branches mapping PostgreSQL domains back to MySQL types.
	 *
	 * @param string $catalog_alias       Catalog column table alias.
	 * @param bool   $include_type_length Whether COLUMN_TYPE should preserve encoded length/unsigned metadata.
	 * @return string SQL CASE branches.
	 */
	private function get_postgresql_mysql_domain_type_cases( string $catalog_alias, bool $include_type_length ): string {
		$cases = array();
		foreach ( self::MYSQL_TEXT_DOMAIN_TYPES as $domain_name => $mysql_type ) {
			$cases[] = sprintf(
				'WHEN %s.domain_name = %s THEN %s',
				$catalog_alias,
				$this->connection->quote( $domain_name ),
				$this->connection->quote( $include_type_length ? $mysql_type : $this->get_base_mysql_dml_column_type( $mysql_type ) )
			);
		}
		foreach ( self::MYSQL_BINARY_DOMAIN_TYPES as $domain_name => $mysql_type ) {
			$cases[] = sprintf(
				'WHEN %s.domain_name = %s THEN %s',
				$catalog_alias,
				$this->connection->quote( $domain_name ),
				$this->connection->quote( $mysql_type )
			);
		}
		foreach ( array( 'binary', 'varbinary' ) as $type ) {
			$domain_name = '__wp_mysql_' . $type;
			$cases[]     = sprintf(
				'WHEN %s.domain_name = %s THEN %s',
				$catalog_alias,
				$this->connection->quote( $domain_name ),
				$this->connection->quote( $type )
			);
			$cases[]     = sprintf(
				$include_type_length
					? 'WHEN %1$s.domain_name LIKE %2$s THEN %3$s || \'(\' || SUBSTR(%1$s.domain_name, %4$d) || \')\''
					: 'WHEN %1$s.domain_name LIKE %2$s THEN %3$s',
				$catalog_alias,
				$this->connection->quote( $domain_name . '_%' ),
				$this->connection->quote( $type ),
				strlen( $domain_name ) + 2
			);
		}
		foreach ( array_keys( self::MYSQL_INTEGER_DOMAIN_BASE_TYPES ) as $type ) {
			$domain_name = '__wp_mysql_' . $type;
			$cases[]     = sprintf(
				'WHEN %s.domain_name = %s THEN %s',
				$catalog_alias,
				$this->connection->quote( $domain_name ),
				$this->connection->quote( $type )
			);
			$cases[]     = sprintf(
				'WHEN %s.domain_name = %s THEN %s',
				$catalog_alias,
				$this->connection->quote( $domain_name . '_unsigned' ),
				$this->connection->quote( $include_type_length ? $type . ' unsigned' : $type )
			);
			$cases[]     = sprintf(
				$include_type_length
					? 'WHEN %1$s.domain_name LIKE %2$s THEN %3$s || \'(\' || SUBSTR(%1$s.domain_name, %4$d, LENGTH(%1$s.domain_name) - %5$d) || \') unsigned\''
					: 'WHEN %1$s.domain_name LIKE %2$s THEN %3$s',
				$catalog_alias,
				$this->connection->quote( $domain_name . '_%_unsigned' ),
				$this->connection->quote( $type ),
				strlen( $domain_name ) + 2,
				strlen( $domain_name ) + 10
			);
			$cases[]     = sprintf(
				$include_type_length
					? 'WHEN %1$s.domain_name LIKE %2$s THEN %3$s || \'(\' || SUBSTR(%1$s.domain_name, %4$d) || \')\''
					: 'WHEN %1$s.domain_name LIKE %2$s THEN %3$s',
				$catalog_alias,
				$this->connection->quote( $domain_name . '_%' ),
				$this->connection->quote( $type ),
				strlen( $domain_name ) + 2
			);
		}
		foreach ( array( 'dec', 'fixed', 'float', 'double', 'real', 'numeric' ) as $type ) {
			$domain_name = '__wp_mysql_' . $type;
			$cases[]     = sprintf(
				'WHEN %s.domain_name = %s THEN %s',
				$catalog_alias,
				$this->connection->quote( $domain_name ),
				$this->connection->quote( $type )
			);
			$cases[]     = sprintf(
				$include_type_length
					? 'WHEN %1$s.domain_name LIKE %2$s THEN %3$s || \'(\' || REPLACE(SUBSTR(%1$s.domain_name, %4$d), \'_\', \',\') || \')\''
					: 'WHEN %1$s.domain_name LIKE %2$s THEN %3$s',
				$catalog_alias,
				$this->connection->quote( $domain_name . '_%' ),
				$this->connection->quote( $type ),
				strlen( $domain_name ) + 2
			);
		}

		return implode( "\n\t", $cases );
	}

	/**
	 * Get a MySQL-shaped column default expression from PostgreSQL catalog metadata.
	 *
	 * @param string $catalog_alias Catalog column table alias.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_column_default_expression( string $catalog_alias, ?string $column_comment_sql = null ): string {
		$fractional_timestamp_default_pattern = $this->connection->quote( "^\\s*left\\s*\\(\\s*to_char\\s*\\(\\s*\\(?\\s*current_timestamp\\(([0-6])\\)\\s+at\\s+time\\s+zone\\s+'UTC'(::text)?\\s*\\)?\\s*,\\s*'YYYY-MM-DD HH24:MI:SS\\.US'(::text)?\\s*\\)\\s*,\\s*2[1-6]\\s*\\)\\s*$" );
		$quoted_literal_default_pattern       = $this->connection->quote( '^\'(.*)\'::(character varying|character|text|bpchar|timestamp without time zone|timestamp with time zone|date|time without time zone|time with time zone|integer|bigint|smallint|numeric|decimal|double precision|real|boolean)$' );
		$column_default_comment_sql           = null === $column_comment_sql
			? 'NULL'
			: $this->get_postgresql_catalog_column_comment_marker_sql( $column_comment_sql, self::MYSQL_COLUMN_COMMENT_DEFAULT_PREFIX );
		return sprintf(
			'CASE
	WHEN %1$s.is_identity = \'YES\' THEN NULL
	WHEN LOWER(COALESCE(%1$s.column_default, \'\')) LIKE \'nextval(%%\' THEN NULL
	WHEN %5$s IS NOT NULL THEN %5$s
	WHEN %2$s THEN \'CURRENT_TIMESTAMP\'
	WHEN %1$s.column_default ~* %3$s THEN \'CURRENT_TIMESTAMP(\' || SUBSTRING(%1$s.column_default FROM %3$s) || \')\'
	WHEN %1$s.column_default ~ %4$s THEN REPLACE(SUBSTRING(%1$s.column_default FROM %4$s), CHR(39) || CHR(39), CHR(39))
	ELSE %1$s.column_default
END',
			$catalog_alias,
			$this->get_postgresql_catalog_current_timestamp_default_condition_sql( $catalog_alias, false ),
			$fractional_timestamp_default_pattern,
			$quoted_literal_default_pattern,
			$column_default_comment_sql
		);
	}

	/**
	 * Get internal MySQL metadata from a PostgreSQL column comment marker line.
	 *
	 * @param string $column_comment_sql SQL expression returning a PostgreSQL column comment.
	 * @param string $prefix             Internal marker prefix.
	 * @return string SQL expression returning decoded marker payload, or NULL.
	 */
	private function get_postgresql_catalog_column_comment_marker_sql( string $column_comment_sql, string $prefix ): string {
		$prefix_sql  = $this->connection->quote( $prefix );
		$comment_sql = sprintf( 'COALESCE(%s, \'\')', $column_comment_sql );
		$cases       = array();
		for ( $line_number = 1; $line_number <= count( self::POSTGRESQL_CATALOG_COLUMN_COMMENT_MARKER_PREFIXES ); ++$line_number ) {
			$line_sql = sprintf( 'split_part(%s, CHR(10), %d)', $comment_sql, $line_number );
			$cases[]  = sprintf(
				'WHEN LEFT(%1$s, LENGTH(%2$s)) = %2$s THEN %3$s',
				$line_sql,
				$prefix_sql,
				$this->get_postgresql_catalog_column_comment_marker_decode_sql( $line_sql, $prefix_sql )
			);
		}

		return sprintf(
			'CASE
	%1$s
	ELSE NULL
END',
			implode( "\n\t", $cases )
		);
	}

	/**
	 * Decode one marker payload from a PostgreSQL column comment line.
	 *
	 * @param string $comment_sql SQL expression returning a comment line.
	 * @param string $prefix_sql  Quoted SQL marker prefix.
	 * @return string SQL expression returning decoded marker payload.
	 */
	private function get_postgresql_catalog_column_comment_marker_decode_sql( string $comment_sql, string $prefix_sql ): string {
		return sprintf(
			'convert_from(
	decode(
		NULLIF(split_part(SUBSTRING(%1$s FROM LENGTH(%2$s) + 1), CHR(10), 1), \'\'),
		\'base64\'
	),
	\'UTF8\'
)',
			$comment_sql,
			$prefix_sql
		);
	}

	/**
	 * Get the MySQL-facing index comment after removing internal PostgreSQL catalog metadata.
	 *
	 * @param string $index_comment_sql SQL expression returning a PostgreSQL index comment.
	 * @return string SQL expression returning the user-facing MySQL comment.
	 */
	private function get_postgresql_catalog_index_comment_sql( string $index_comment_sql ): string {
		$type_prefix_sql     = $this->connection->quote( self::MYSQL_INDEX_COMMENT_TYPE_PREFIX );
		$sub_part_prefix_sql = $this->connection->quote( self::MYSQL_INDEX_COMMENT_SUB_PART_PREFIX );
		$comment_sql         = sprintf( 'COALESCE(%s, \'\')', $index_comment_sql );

		return sprintf(
			'CASE
	WHEN LEFT(%1$s, LENGTH(%2$s)) = %2$s THEN
		CASE
			WHEN POSITION(CHR(10) IN %1$s) > 0 THEN SUBSTRING(%1$s FROM POSITION(CHR(10) IN %1$s) + 1)
			ELSE \'\'
		END
	WHEN LEFT(%1$s, LENGTH(%3$s)) = %3$s THEN
		pg_catalog.regexp_replace(
			%1$s,
			\'^(\' || %3$s || \'[0-9]+:[0-9]+\' || CHR(10) || \')*\' || %3$s || \'[0-9]+:[0-9]+(\' || CHR(10) || \')?\',
			\'\'
		)
	ELSE %1$s
END',
			$comment_sql,
			$type_prefix_sql,
			$sub_part_prefix_sql
		);
	}

	/**
	 * Get MySQL index type metadata from a PostgreSQL index comment.
	 *
	 * @param string $index_comment_sql SQL expression returning a PostgreSQL index comment.
	 * @return string SQL expression returning the decoded MySQL index type, or NULL.
	 */
	private function get_postgresql_catalog_index_type_comment_sql( string $index_comment_sql ): string {
		$prefix_sql  = $this->connection->quote( self::MYSQL_INDEX_COMMENT_TYPE_PREFIX );
		$comment_sql = sprintf( 'COALESCE(%s, \'\')', $index_comment_sql );

		return sprintf(
			'CASE
	WHEN LEFT(%1$s, LENGTH(%2$s)) = %2$s THEN %3$s
	ELSE NULL
END',
			$comment_sql,
			$prefix_sql,
			$this->get_postgresql_catalog_column_comment_marker_decode_sql( $comment_sql, $prefix_sql )
		);
	}

	/**
	 * Get MySQL prefix length metadata from PostgreSQL catalog display sources.
	 *
	 * @param string $expression_sql    SQL expression yielding PostgreSQL index expression text.
	 * @param string $index_comment_sql SQL expression returning a PostgreSQL index comment.
	 * @param string $seq_in_index_sql  SQL expression returning the MySQL index part ordinal.
	 * @return string SQL expression returning a MySQL Sub_part value, or NULL.
	 */
	private function get_postgresql_catalog_display_index_sub_part_sql( string $expression_sql, string $index_comment_sql, string $seq_in_index_sql ): string {
		$prefix_sql              = $this->connection->quote( self::MYSQL_INDEX_COMMENT_SUB_PART_PREFIX );
		$comment_sql             = sprintf( 'COALESCE(%s, \'\')', $index_comment_sql );
		$expression_sub_part_sql = sprintf(
			'CASE WHEN %1$s IS NULL THEN NULL ELSE SUBSTRING(%2$s FROM \', 1, ([0-9]+)[)]$\') END',
			$this->get_postgresql_prefix_index_expression_column_name_sql( $expression_sql ),
			$expression_sql
		);

		return sprintf(
			'COALESCE(%1$s, (pg_catalog.regexp_match(
	%2$s,
	\'(^|\' || CHR(10) || \')\' || %3$s || CAST(%4$s AS text) || \':([0-9]+)($|\' || CHR(10) || \')\'
))[2])',
			$expression_sub_part_sql,
			$comment_sql,
			$prefix_sql,
			$seq_in_index_sql
		);
	}

	/**
	 * Get a SQL condition for PostgreSQL catalog defaults translated from MySQL CURRENT_TIMESTAMP.
	 *
	 * @param string $catalog_alias       Catalog column table alias.
	 * @param bool   $include_fractional Whether fractional precision defaults should match.
	 * @return string SQL condition.
	 */
	private function get_postgresql_catalog_current_timestamp_default_condition_sql( string $catalog_alias, bool $include_fractional = true ): string {
		$current_timestamp_default_pattern    = $this->connection->quote( "^\\s*to_char\\s*\\(\\s*\\(?\\s*current_timestamp(\\(\\))?\\s+at\\s+time\\s+zone\\s+'UTC'(::text)?\\s*\\)?\\s*,\\s*'YYYY-MM-DD HH24:MI:SS'(::text)?\\s*\\)\\s*$" );
		$fractional_timestamp_default_pattern = $this->connection->quote( "^\\s*left\\s*\\(\\s*to_char\\s*\\(\\s*\\(?\\s*current_timestamp\\(([0-6])\\)\\s+at\\s+time\\s+zone\\s+'UTC'(::text)?\\s*\\)?\\s*,\\s*'YYYY-MM-DD HH24:MI:SS\\.US'(::text)?\\s*\\)\\s*,\\s*2[1-6]\\s*\\)\\s*$" );
		$condition                            = sprintf( '%1$s.column_default ~* %2$s', $catalog_alias, $current_timestamp_default_pattern );

		if ( $include_fractional ) {
			$condition .= sprintf( ' OR %1$s.column_default ~* %2$s', $catalog_alias, $fractional_timestamp_default_pattern );
		}

		return '(' . $condition . ')';
	}

	/**
	 * Get a MySQL DATA_TYPE expression from MySQL column_type metadata.
	 *
	 * @param string $column_type_sql SQL expression for column_type.
	 * @param string $fallback_sql    Fallback SQL expression.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_metadata_data_type_expression( string $column_type_sql, string $fallback_sql ): string {
		return sprintf(
			'CASE
		WHEN %1$s IS NULL THEN %2$s
		WHEN LOWER(%1$s) LIKE \'bigint%%\' THEN \'bigint\'
		WHEN LOWER(%1$s) LIKE \'int1%%\' THEN \'int1\'
		WHEN LOWER(%1$s) LIKE \'int2%%\' THEN \'int2\'
		WHEN LOWER(%1$s) LIKE \'int3%%\' THEN \'int3\'
		WHEN LOWER(%1$s) LIKE \'int4%%\' THEN \'int4\'
		WHEN LOWER(%1$s) LIKE \'int8%%\' THEN \'int8\'
		WHEN LOWER(%1$s) LIKE \'mediumint%%\' THEN \'mediumint\'
		WHEN LOWER(%1$s) LIKE \'smallint%%\' THEN \'smallint\'
		WHEN LOWER(%1$s) LIKE \'tinyint%%\' THEN \'tinyint\'
	WHEN LOWER(%1$s) LIKE \'int%%\' THEN \'int\'
	WHEN LOWER(%1$s) LIKE \'integer%%\' THEN \'int\'
	WHEN LOWER(%1$s) LIKE \'varchar%%\' THEN \'varchar\'
	WHEN LOWER(%1$s) LIKE \'char%%\' THEN \'char\'
	WHEN LOWER(%1$s) LIKE \'varbinary%%\' THEN \'varbinary\'
	WHEN LOWER(%1$s) LIKE \'binary%%\' THEN \'binary\'
	WHEN LOWER(%1$s) LIKE \'decimal%%\' THEN \'decimal\'
	WHEN LOWER(%1$s) LIKE \'numeric%%\' THEN \'decimal\'
	WHEN LOWER(%1$s) LIKE \'datetime%%\' THEN \'datetime\'
	WHEN LOWER(%1$s) LIKE \'timestamp%%\' THEN \'timestamp\'
	WHEN LOWER(%1$s) LIKE \'enum%%\' THEN \'enum\'
	WHEN LOWER(%1$s) LIKE \'set%%\' THEN \'set\'
	WHEN LOWER(%1$s) LIKE \'double%%\' THEN \'double\'
	WHEN LOWER(%1$s) LIKE \'float%%\' THEN \'float\'
	WHEN LOWER(%1$s) LIKE \'longblob%%\' THEN \'longblob\'
	WHEN LOWER(%1$s) LIKE \'mediumblob%%\' THEN \'mediumblob\'
	WHEN LOWER(%1$s) LIKE \'tinyblob%%\' THEN \'tinyblob\'
	WHEN LOWER(%1$s) LIKE \'blob%%\' THEN \'blob\'
	WHEN LOWER(%1$s) LIKE \'longtext%%\' THEN \'longtext\'
	WHEN LOWER(%1$s) LIKE \'mediumtext%%\' THEN \'mediumtext\'
	WHEN LOWER(%1$s) LIKE \'tinytext%%\' THEN \'tinytext\'
	WHEN LOWER(%1$s) LIKE \'text%%\' THEN \'text\'
	ELSE LOWER(%1$s)
END',
			$column_type_sql,
			$fallback_sql
		);
	}

	/**
	 * Get CHARACTER_SET_NAME expression for a MySQL column type.
	 *
	 * @param string $column_type_sql SQL expression for column_type.
	 * @param string $metadata_sql    SQL expression for stored charset.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_character_set_expression( string $column_type_sql, string $metadata_sql, ?string $column_comment_sql = null, ?string $default_charset_sql = null ): string {
		$comment_charset_sql = null === $column_comment_sql
			? 'NULL'
			: $this->get_postgresql_catalog_column_comment_marker_sql( $column_comment_sql, self::MYSQL_COLUMN_COMMENT_CHARSET_PREFIX );
		$default_charset_sql = $default_charset_sql ?? $this->connection->quote( $this->charset );

		return sprintf(
			'CASE
	WHEN LOWER(%1$s) LIKE \'char%%\'
		OR LOWER(%1$s) LIKE \'varchar%%\'
		OR LOWER(%1$s) LIKE \'enum%%\'
		OR LOWER(%1$s) LIKE \'set%%\'
		OR LOWER(%1$s) LIKE \'%%text%%\' THEN COALESCE(%4$s, %2$s, %3$s)
	ELSE NULL
	END',
			$column_type_sql,
			$metadata_sql,
			$default_charset_sql,
			$comment_charset_sql
		);
	}

	/**
	 * Get COLLATION_NAME expression for a MySQL column type.
	 *
	 * @param string $column_type_sql SQL expression for column_type.
	 * @param string $metadata_sql    SQL expression for stored collation.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_collation_expression( string $column_type_sql, string $metadata_sql, ?string $column_comment_sql = null, ?string $default_collation_sql = null ): string {
		$comment_collation_sql = null === $column_comment_sql
			? 'NULL'
			: $this->get_postgresql_catalog_column_comment_marker_sql( $column_comment_sql, self::MYSQL_COLUMN_COMMENT_COLLATION_PREFIX );
		$default_collation_sql = $default_collation_sql ?? $this->connection->quote( $this->collation );

		return sprintf(
			'CASE
	WHEN LOWER(%1$s) LIKE \'char%%\'
		OR LOWER(%1$s) LIKE \'varchar%%\'
		OR LOWER(%1$s) LIKE \'enum%%\'
		OR LOWER(%1$s) LIKE \'set%%\'
		OR LOWER(%1$s) LIKE \'%%text%%\' THEN COALESCE(%4$s, %2$s, %3$s)
	ELSE NULL
	END',
			$column_type_sql,
			$metadata_sql,
			$default_collation_sql,
			$comment_collation_sql
		);
	}

	/**
	 * Get EXTRA expression for a catalog column.
	 *
	 * @param string $alias                                Catalog column table alias.
	 * @param bool   $include_postgresql_catalog_triggers Whether PostgreSQL trigger catalogs should be checked.
	 * @param string $column_comment_sql                  SQL expression returning a PostgreSQL column comment.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_column_extra_expression( string $alias, bool $include_postgresql_catalog_triggers = false, ?string $column_comment_sql = null ): string {
		if ( $include_postgresql_catalog_triggers ) {
			$default_generated = $this->get_postgresql_catalog_current_timestamp_default_condition_sql( $alias );
			if ( null !== $column_comment_sql ) {
				$default_generated = sprintf(
					'(%1$s OR %2$s IS NOT NULL)',
					$default_generated,
					$this->get_postgresql_catalog_column_comment_marker_sql( $column_comment_sql, self::MYSQL_COLUMN_COMMENT_DEFAULT_PREFIX )
				);
			}

			$on_update_trigger = sprintf(
				'EXISTS (
		SELECT 1
		FROM pg_catalog.pg_class t
		INNER JOIN pg_catalog.pg_namespace n
			ON n.oid = t.relnamespace
		INNER JOIN pg_catalog.pg_trigger tr
			ON tr.tgrelid = t.oid
		WHERE n.nspname = %1$s.table_schema
			AND t.relname = %1$s.table_name
			AND tr.tgname = \'__wp_pg_on_update_\' || %2$s
			AND NOT tr.tgisinternal
	)',
				$alias,
				$this->get_postgresql_on_update_current_timestamp_trigger_hash_sql(
					$alias . '.table_schema',
					$alias . '.table_name',
					$alias . '.column_name'
				)
			);

			return sprintf(
				'CASE
	WHEN %1$s.is_identity = \'YES\' THEN \'auto_increment\'
	WHEN LOWER(COALESCE(%1$s.column_default, \'\')) LIKE \'nextval(%%\' THEN \'auto_increment\'
	ELSE COALESCE(
		NULLIF(
			CONCAT_WS(
				\' \',
				CASE WHEN %2$s THEN \'DEFAULT_GENERATED\' ELSE NULL END,
				CASE WHEN %3$s THEN \'on update CURRENT_TIMESTAMP\' ELSE NULL END
			),
			\'\'
		),
		\'\'
	)
END',
				$alias,
				$default_generated,
				$on_update_trigger
			);
		}

		return sprintf(
			'CASE
	WHEN %1$s.is_identity = \'YES\' THEN \'auto_increment\'
	WHEN LOWER(COALESCE(%1$s.column_default, \'\')) LIKE \'nextval(%%\' THEN \'auto_increment\'
	ELSE \'\'
END',
			$alias
		);
	}

	/**
	 * Translate SELECT DISTINCT queries whose ORDER BY expression is not selected.
	 *
	 * PostgreSQL requires ORDER BY expressions in SELECT DISTINCT statements to
	 * appear in the projection. Grouping by the visible projection and ordering
	 * by a hidden aggregate keeps the MySQL-visible result shape and avoids
	 * changing DISTINCT cardinality.
	 *
	 * @param string $query         MySQL query.
	 * @param bool   $include_limit Whether to preserve the LIMIT/OFFSET clause.
	 * @return string|null PostgreSQL query, or null when the query is unsupported.
	 */
	private function translate_distinct_order_by_query( string $query, bool $include_limit = true ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0], $tokens[1] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		if ( WP_MySQL_Lexer::DISTINCT_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		$has_sql_calc_found_rows = false;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL === $tokens[ $position ]->id ) {
			$has_sql_calc_found_rows = true;
			++$position;
		}

		if (
			isset( $tokens[ $position ] )
			&& in_array(
				$tokens[ $position ]->id,
				array(
					WP_MySQL_Lexer::HIGH_PRIORITY_SYMBOL,
					WP_MySQL_Lexer::SQL_BIG_RESULT_SYMBOL,
					WP_MySQL_Lexer::SQL_BUFFER_RESULT_SYMBOL,
					WP_MySQL_Lexer::SQL_CACHE_SYMBOL,
					WP_MySQL_Lexer::SQL_NO_CACHE_SYMBOL,
					WP_MySQL_Lexer::SQL_SMALL_RESULT_SYMBOL,
					WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
				),
				true
			)
		) {
			return null;
		}

		$projection_start = $position;
		$statement_end    = $this->get_mysql_statement_end_position( $tokens, $projection_start );
		if ( null === $statement_end ) {
			return null;
		}

		$limit_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::LIMIT_SYMBOL,
			$projection_start,
			$statement_end
		);
		$select_end     = $limit_position ?? $statement_end;
		if ( null !== $limit_position && ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $statement_end ) ) {
			return null;
		}

		$order_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::ORDER_SYMBOL,
			$projection_start,
			$select_end
		);
		if ( null === $order_position ) {
			if ( ! $has_sql_calc_found_rows ) {
				return null;
			}

			$sql = 'SELECT DISTINCT ' . $this->translate_mysql_token_sequence_to_postgresql( $tokens, $projection_start, $select_end );
			if ( $include_limit && null !== $limit_position ) {
				$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
			}

			return $sql;
		}

		$from_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::FROM_SYMBOL,
			$projection_start,
			$order_position
		);
		if (
			null === $from_position
			|| null === $order_position
			|| $order_position + 2 >= $statement_end
			|| ! isset( $tokens[ $order_position + 1 ] )
			|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $order_position + 1 ]->id
		) {
			return null;
		}

		if (
			$this->contains_top_level_mysql_token(
				$tokens,
				$projection_start,
				$select_end,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::INTO_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		if (
			$this->contains_mysql_token(
				$tokens,
				$projection_start,
				$select_end,
				array(
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::AVG_SYMBOL,
					WP_MySQL_Lexer::COUNT_SYMBOL,
					WP_MySQL_Lexer::GROUP_CONCAT_SYMBOL,
					WP_MySQL_Lexer::MAX_SYMBOL,
					WP_MySQL_Lexer::MIN_SYMBOL,
					WP_MySQL_Lexer::SUM_SYMBOL,
				)
			)
		) {
			return null;
		}

		$projection_items = $this->parse_mysql_select_projection_items( $tokens, $projection_start, $from_position );
		if ( null === $projection_items ) {
			return null;
		}

		$scope_end = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::WHERE_SYMBOL,
			$from_position + 1,
			$order_position
		) ?? $order_position;
		$scope     = $this->get_mysql_select_scope( $tokens, $from_position + 1, $scope_end );
		if ( null === $scope ) {
			return null;
		}

		$order_items = $this->parse_mysql_select_order_by_items(
			$tokens,
			$order_position + 2,
			$select_end,
			$projection_items,
			$scope
		);
		if ( null === $order_items ) {
			return null;
		}

		$has_hidden_order_expression = false;
		foreach ( $order_items as $order_item ) {
			if ( null === $order_item['projection_index'] ) {
				$has_hidden_order_expression = true;
				break;
			}
		}

		if ( ! $has_hidden_order_expression ) {
			if ( ! $has_sql_calc_found_rows ) {
				return null;
			}

			$sql = 'SELECT DISTINCT ' . $this->translate_mysql_token_sequence_to_postgresql( $tokens, $projection_start, $select_end );
			if ( $include_limit && null !== $limit_position ) {
				$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
			}

			return $sql;
		}

		return $this->build_distinct_order_by_grouped_query(
			$tokens,
			$projection_items,
			$order_items,
			$from_position,
			$order_position,
			$limit_position,
			$statement_end,
			$include_limit
		);
	}

	/**
	 * Backward-compatible probe for the available post MIME type contextual rewrite.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_wordpress_available_post_mime_types_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id
		) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		return null !== $statement_end
			&& $this->is_wordpress_available_post_mime_types_select_shape( $tokens, 1, $statement_end )
			? $this->translate_mysql_select_statement_with_integer_string_coercion( $tokens, 1, $statement_end, true )
			: null;
	}

	/**
	 * Backward-compatible probe for the former approved-comments query translator.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when the generic simple SELECT path should not add the tie-breaker.
	 */
	private function translate_wordpress_approved_comments_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, 1, $statement_end );
		$select_end     = $limit_position ?? $statement_end;
		$from_position  = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, 1, $select_end );
		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, 1, $select_end );
		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, 1, $select_end );
		if (
			null === $from_position
			|| null === $where_position
			|| null === $order_position
			|| $from_position + 2 !== $where_position
		) {
			return null;
		}

		$table_name = $this->get_mysql_identifier_token_value( $tokens[ $from_position + 1 ] ?? null );
		if (
			null === $table_name
			|| ! $this->is_mysql_wordpress_table_name( $table_name, 'comments' )
			|| ! $this->is_supported_wordpress_approved_comments_select_projection( $tokens, 1, $from_position, $table_name )
			|| null === $this->get_simple_wordpress_approved_comments_order_tiebreaker_sql(
				$tokens,
				$table_name,
				$where_position,
				$order_position,
				$order_position,
				$select_end
			)
		) {
			return null;
		}

		return $this->translate_simple_mysql_select_query( $query );
	}

	/**
	 * Check whether an approved-comments SELECT returns comment rows or row columns.
	 *
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $start      First projection token position.
	 * @param int              $end        Final projection token position, exclusive.
	 * @param string           $table_name Selected comments table name.
	 * @return bool Whether the projection is supported.
	 */
	private function is_supported_wordpress_approved_comments_select_projection(
		array $tokens,
		int $start,
		int $end,
		string $table_name
	): bool {
		if ( $start + 1 === $end && WP_MySQL_Lexer::MULT_OPERATOR === $tokens[ $start ]->id ) {
			return true;
		}

		$projection_ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $projection_ranges ) {
			return false;
		}

		foreach ( $projection_ranges as $projection_range ) {
			$reference = $this->parse_mysql_column_reference( $tokens, $projection_range['start'], $projection_range['end'] );
			if (
				null === $reference
				|| $reference['end'] !== $projection_range['end']
				|| ( null !== $reference['qualifier'] && 0 !== strcasecmp( $reference['qualifier'], $table_name ) )
			) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Check whether a projection item is alias.*.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection token.
	 * @param int             $end    Final projection token, exclusive.
	 * @param string          $alias  Expected table alias.
	 * @return bool Whether the projection item is the qualified star.
	 */
	private function is_mysql_qualified_star_projection( array $tokens, int $start, int $end, string $alias ): bool {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		return $start + 3 === $end
			&& $this->is_mysql_identifier_like_token_value( $tokens[ $start ] ?? null, $alias )
			&& isset( $tokens[ $start + 1 ], $tokens[ $start + 2 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 1 ]->id
			&& WP_MySQL_Lexer::MULT_OPERATOR === $tokens[ $start + 2 ]->id;
	}

	/**
	 * Parse SELECT projection items with expression bounds and visible aliases.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection token position.
	 * @param int             $end    Final projection token position, exclusive.
	 * @return array<int, array{expression_start: int, expression_end: int, sql: string, alias: string}>|null Projection items.
	 */
	private function parse_mysql_select_projection_items( array $tokens, int $start, int $end ): ?array {
		$ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $ranges || count( $ranges ) < 1 ) {
			return null;
		}

		$items        = array();
		$alias_lookup = array();
		foreach ( $ranges as $range ) {
			$item = $this->parse_mysql_select_projection_item( $tokens, $range['start'], $range['end'] );
			if ( null === $item ) {
				return null;
			}

			$alias_key = strtolower( $item['alias'] );
			if ( isset( $alias_lookup[ $alias_key ] ) ) {
				return null;
			}

			$alias_lookup[ $alias_key ] = true;
			$items[]                    = $item;
		}

		return $items;
	}

	/**
	 * Parse one SELECT projection item.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection item token position.
	 * @param int             $end    Final projection item token position, exclusive.
	 * @return array{expression_start: int, expression_end: int, sql: string, alias: string}|null Projection item.
	 */
	private function parse_mysql_select_projection_item( array $tokens, int $start, int $end ): ?array {
		if ( $start >= $end ) {
			return null;
		}

		$expression_start = $start;
		$expression_end   = $end;
		$alias            = null;
		$as_position      = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::AS_SYMBOL, $start, $end );

		if ( null !== $as_position ) {
			if ( $as_position <= $start || $as_position + 2 !== $end ) {
				return null;
			}

			$alias = $this->get_mysql_projection_alias_token_value( $tokens[ $as_position + 1 ] ?? null );
			if ( null === $alias ) {
				return null;
			}

			$expression_end = $as_position;
		} else {
			$implicit_alias = $this->get_mysql_implicit_projection_alias( $tokens, $start, $end );
			if ( null !== $implicit_alias ) {
				$alias          = $implicit_alias;
				$expression_end = $end - 1;
			}
		}

		if ( $expression_start >= $expression_end ) {
			return null;
		}

		if ( null === $alias ) {
			$alias = $this->get_mysql_select_expression_default_output_name( $tokens, $expression_start, $expression_end );
			if ( null === $alias ) {
				return null;
			}
		}

		return array(
			'expression_start' => $expression_start,
			'expression_end'   => $expression_end,
			'sql'              => $this->translate_mysql_token_sequence_to_postgresql( $tokens, $expression_start, $expression_end ),
			'alias'            => $alias,
		);
	}

	/**
	 * Get an explicit projection alias token value.
	 *
	 * MySQL permits string-literal aliases in projection context. Keep that
	 * context local so predicate string literals continue to render as values.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return string|null Alias value, or null when unsupported.
	 */
	private function get_mysql_projection_alias_token_value( ?WP_MySQL_Token $token ): ?string {
		if ( null === $token ) {
			return null;
		}

		$identifier = $this->get_mysql_identifier_token_value( $token );
		if ( null !== $identifier ) {
			return $identifier;
		}

		if ( WP_MySQL_Lexer::SINGLE_QUOTED_TEXT === $token->id || WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $token->id ) {
			return $token->get_value();
		}

		$value = $token->get_value();
		if ( $this->is_mysql_unquoted_projection_alias_value( $value ) ) {
			return $value;
		}

		return null;
	}

	/**
	 * Check whether a token value is safe as an unquoted MySQL projection alias.
	 *
	 * @param string $value Token value.
	 * @return bool Whether the value is identifier-shaped.
	 */
	private function is_mysql_unquoted_projection_alias_value( string $value ): bool {
		if ( '' === $value ) {
			return false;
		}

		$first_character = $value[0];
		if ( '_' !== $first_character && ! ctype_alpha( $first_character ) ) {
			return false;
		}

		for ( $i = 1, $length = strlen( $value ); $i < $length; $i++ ) {
			$character = $value[ $i ];
			if ( '_' !== $character && '$' !== $character && ! ctype_alnum( $character ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Get an implicit projection alias when a complex expression is followed by a name.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection item token position.
	 * @param int             $end    Final projection item token position, exclusive.
	 * @return string|null Alias value, or null when absent.
	 */
	private function get_mysql_implicit_projection_alias( array $tokens, int $start, int $end ): ?string {
		if ( $start + 1 >= $end ) {
			return null;
		}

		$alias = $this->get_mysql_identifier_token_value( $tokens[ $end - 1 ] ?? null );
		if ( null === $alias ) {
			return null;
		}

		if ( isset( $tokens[ $end - 2 ] ) && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $end - 2 ]->id ) {
			return null;
		}

		return $alias;
	}

	/**
	 * Infer the default visible name for a projected expression.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token position.
	 * @param int             $end    Final expression token position, exclusive.
	 * @return string|null Output column name, or null when unsupported.
	 */
	private function get_mysql_select_expression_default_output_name( array $tokens, int $start, int $end ): ?string {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		if ( $start + 1 === $end ) {
			return $this->get_mysql_identifier_token_value( $tokens[ $start ] ?? null );
		}

		if (
			$start + 3 <= $end
			&& isset( $tokens[ $end - 2 ], $tokens[ $end - 1 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $end - 2 ]->id
		) {
			return $this->get_mysql_identifier_token_value( $tokens[ $end - 1 ] );
		}

		return null;
	}

	/**
	 * Parse ORDER BY items and connect them to projected expressions when possible.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int             $start            First ORDER BY item token position.
	 * @param int             $end              Final ORDER BY token position, exclusive.
	 * @param array           $projection_items Parsed projection items.
	 * @param array|null      $scope            Optional statement table scope for contextual expression coercions.
	 * @return array<int, array{expression_start: int, expression_end: int, sql: string, direction: string, direction_explicit: bool, projection_index: int|null, changed: bool}>|null
	 * ORDER BY items.
	 */
	private function parse_mysql_select_order_by_items(
		array $tokens,
		int $start,
		int $end,
		array $projection_items,
		?array $scope = null
	): ?array {
		$ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $ranges || count( $ranges ) < 1 ) {
			return null;
		}

		$items = array();
		foreach ( $ranges as $range ) {
			$expression_end     = $range['end'];
			$direction          = 'ASC';
			$direction_explicit = false;

			if (
				isset( $tokens[ $expression_end - 1 ] )
				&& (
					WP_MySQL_Lexer::ASC_SYMBOL === $tokens[ $expression_end - 1 ]->id
					|| WP_MySQL_Lexer::DESC_SYMBOL === $tokens[ $expression_end - 1 ]->id
				)
			) {
				$direction          = WP_MySQL_Lexer::DESC_SYMBOL === $tokens[ $expression_end - 1 ]->id ? 'DESC' : 'ASC';
				$direction_explicit = true;
				--$expression_end;
			}

			if ( $range['start'] >= $expression_end ) {
				return null;
			}

			$expression_sql = null === $scope
				? array(
					'sql'     => $this->translate_mysql_token_sequence_to_postgresql(
						$tokens,
						$range['start'],
						$expression_end
					),
					'changed' => false,
				)
				: $this->translate_mysql_expression_token_sequence_to_postgresql(
					$tokens,
					$range['start'],
					$expression_end,
					$scope
				);

			$items[] = array(
				'expression_start'   => $range['start'],
				'expression_end'     => $expression_end,
				'sql'                => $expression_sql['sql'],
				'direction'          => $direction,
				'direction_explicit' => $direction_explicit,
				'projection_index'   => $this->find_mysql_projection_for_order_expression(
					$tokens,
					$range['start'],
					$expression_end,
					$projection_items
				),
				'changed'            => $expression_sql['changed'],
			);
		}

		return $items;
	}

	/**
	 * Find a projection item that satisfies an ORDER BY expression.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int             $start            First ORDER BY expression token.
	 * @param int             $end              Final ORDER BY expression token, exclusive.
	 * @param array           $projection_items Parsed projection items.
	 * @return int|null Projection item index, or null when not projected.
	 */
	private function find_mysql_projection_for_order_expression( array $tokens, int $start, int $end, array $projection_items ): ?int {
		foreach ( $projection_items as $index => $projection_item ) {
			if (
				$this->are_mysql_token_ranges_equivalent(
					$tokens,
					$start,
					$end,
					$projection_item['expression_start'],
					$projection_item['expression_end']
				)
			) {
				return $index;
			}
		}

		if ( $start + 1 === $end ) {
			$ordinal = $this->get_mysql_order_by_ordinal_projection_index( $tokens[ $start ], count( $projection_items ) );
			if ( null !== $ordinal ) {
				return $ordinal;
			}

			$alias = $this->get_mysql_order_by_alias_token_value( $tokens[ $start ] );
			if ( null !== $alias ) {
				foreach ( $projection_items as $index => $projection_item ) {
					if ( strtolower( $alias ) === strtolower( $projection_item['alias'] ) ) {
						return $index;
					}
				}
			}
		}

		return null;
	}

	/**
	 * Get a one-token ORDER BY alias reference.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return string|null Alias value, or null when unsupported.
	 */
	private function get_mysql_order_by_alias_token_value( ?WP_MySQL_Token $token ): ?string {
		if ( null === $token ) {
			return null;
		}

		$identifier = $this->get_mysql_identifier_token_value( $token );
		if ( null !== $identifier ) {
			return $identifier;
		}

		if ( WP_MySQL_Lexer::SINGLE_QUOTED_TEXT === $token->id || WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $token->id ) {
			return null;
		}

		$value = $token->get_value();
		if ( $this->is_mysql_unquoted_projection_alias_value( $value ) ) {
			return $value;
		}

		return null;
	}

	/**
	 * Resolve a positional ORDER BY item to a projection index.
	 *
	 * @param WP_MySQL_Token $token            ORDER BY token.
	 * @param int            $projection_count Number of projected columns.
	 * @return int|null Zero-based projection index, or null when unsupported.
	 */
	private function get_mysql_order_by_ordinal_projection_index( WP_MySQL_Token $token, int $projection_count ): ?int {
		if (
			! in_array( $token->id, array( WP_MySQL_Lexer::INT_NUMBER, WP_MySQL_Lexer::LONG_NUMBER ), true )
			|| ! ctype_digit( $token->get_value() )
		) {
			return null;
		}

		$ordinal = (int) $token->get_value();
		if ( $ordinal < 1 || $ordinal > $projection_count ) {
			return null;
		}

		return $ordinal - 1;
	}

	/**
	 * Check whether a bounded token range contains any token IDs.
	 *
	 * @param WP_MySQL_Token[] $tokens    MySQL lexer token stream.
	 * @param int             $start     First token position, inclusive.
	 * @param int             $end       Final token position, exclusive.
	 * @param int[]           $token_ids Token IDs to detect.
	 * @return bool Whether any token ID was found.
	 */
	private function contains_mysql_token( array $tokens, int $start, int $end, array $token_ids ): bool {
		$lookup = array();
		foreach ( $token_ids as $token_id ) {
			$lookup[ $token_id ] = true;
		}

		for ( $i = $start; $i < $end; $i++ ) {
			if ( isset( $lookup[ $tokens[ $i ]->id ] ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Build a grouped derived-table rewrite for DISTINCT ORDER BY queries.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @param array           $order_items      Parsed ORDER BY items.
	 * @param int             $from_position    FROM token position.
	 * @param int             $order_position   ORDER token position.
	 * @param int|null        $limit_position   LIMIT token position, or null.
	 * @param int             $statement_end    Final statement token position, exclusive.
	 * @param bool            $include_limit    Whether to preserve the LIMIT/OFFSET clause.
	 * @return string PostgreSQL query.
	 */
	private function build_distinct_order_by_grouped_query(
		array $tokens,
		array $projection_items,
		array $order_items,
		int $from_position,
		int $order_position,
		?int $limit_position,
		int $statement_end,
		bool $include_limit = true
	): string {
		$derived_table_alias        = '__wp_pg_distinct';
		$quoted_derived_table_alias = $this->connection->quote_identifier( $derived_table_alias );
		$inner_projection_sql       = array();
		$outer_projection_sql       = array();
		$group_by_sql               = array();

		foreach ( $projection_items as $projection_item ) {
			$quoted_alias           = $this->connection->quote_identifier( $projection_item['alias'] );
			$inner_projection_sql[] = $projection_item['sql'] . ' AS ' . $quoted_alias;
			$outer_projection_sql[] = sprintf(
				'%s.%s AS %s',
				$quoted_derived_table_alias,
				$quoted_alias,
				$quoted_alias
			);
			$group_by_sql[]         = $projection_item['sql'];
		}

		foreach ( $order_items as $index => $order_item ) {
			if ( null !== $order_item['projection_index'] ) {
				continue;
			}

			$aggregate_function     = 'DESC' === $order_item['direction'] ? 'MAX' : 'MIN';
			$quoted_order_alias     = $this->connection->quote_identifier( $this->get_distinct_order_by_hidden_alias( $index ) );
			$inner_projection_sql[] = sprintf(
				'%s(%s) AS %s',
				$aggregate_function,
				$order_item['sql'],
				$quoted_order_alias
			);
		}

		$sql = sprintf(
			'SELECT %s FROM (SELECT %s %s GROUP BY %s) AS %s ORDER BY %s',
			implode( ', ', $outer_projection_sql ),
			implode( ', ', $inner_projection_sql ),
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, $from_position, $order_position ),
			implode( ', ', $group_by_sql ),
			$quoted_derived_table_alias,
			$this->get_distinct_order_by_outer_order_sql( $projection_items, $order_items, $quoted_derived_table_alias )
		);

		if ( $include_limit && null !== $limit_position ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
		}

		return $sql;
	}

	/**
	 * Get the hidden ORDER BY alias for a parsed order item.
	 *
	 * @param int $index ORDER BY item index.
	 * @return string Hidden alias.
	 */
	private function get_distinct_order_by_hidden_alias( int $index ): string {
		return '__wp_pg_order_' . $index;
	}

	/**
	 * Build the outer ORDER BY clause for a grouped DISTINCT rewrite.
	 *
	 * @param array  $projection_items           Parsed projection items.
	 * @param array  $order_items                Parsed ORDER BY items.
	 * @param string $quoted_derived_table_alias Quoted derived table alias.
	 * @return string Outer ORDER BY SQL.
	 */
	private function get_distinct_order_by_outer_order_sql( array $projection_items, array $order_items, string $quoted_derived_table_alias ): string {
		$order_sql = array();

		foreach ( $order_items as $index => $order_item ) {
			if ( null !== $order_item['projection_index'] ) {
				$order_alias = $projection_items[ $order_item['projection_index'] ]['alias'];
			} else {
				$order_alias = $this->get_distinct_order_by_hidden_alias( $index );
			}

			$order_sql[] = sprintf(
				'%s.%s %s',
				$quoted_derived_table_alias,
				$this->connection->quote_identifier( $order_alias ),
				$order_item['direction']
			);
		}

		return implode( ', ', $order_sql );
	}

	/**
	 * Translate aggregate/grouped SELECT ORDER BY clauses that PostgreSQL rejects.
	 *
	 * MySQL permits non-grouped ORDER BY expressions in grouped queries. Keep
	 * this rewrite limited to WordPress's scalar count and grouped archive/comment
	 * ID query shapes so unsupported grouping semantics still fail visibly.
	 *
	 * @param string $query         MySQL query.
	 * @param bool   $include_limit Whether to preserve the LIMIT/OFFSET clause.
	 * @return string|null PostgreSQL query, or null when the query is unsupported.
	 */
	private function translate_strict_aggregate_grouped_order_by_query( string $query, bool $include_limit = true ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		$projection_start = 1;
		$has_distinct     = false;
		if ( isset( $tokens[ $projection_start ] ) && WP_MySQL_Lexer::DISTINCT_SYMBOL === $tokens[ $projection_start ]->id ) {
			$has_distinct = true;
			++$projection_start;
		}

		if ( isset( $tokens[ $projection_start ] ) && WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL === $tokens[ $projection_start ]->id ) {
			++$projection_start;
		}

		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, $projection_start, $statement_end );
		$select_end     = $limit_position ?? $statement_end;
		if ( null !== $limit_position && ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $statement_end ) ) {
			return null;
		}

		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, $projection_start, $select_end );
		if (
			null === $order_position
			|| ! isset( $tokens[ $order_position + 1 ] )
			|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $order_position + 1 ]->id
			|| $order_position + 2 >= $select_end
		) {
			return null;
		}

		if (
			$this->contains_top_level_mysql_token(
				$tokens,
				$projection_start,
				$select_end,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::INTO_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		$group_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::GROUP_SYMBOL, $projection_start, $order_position );
		if ( null === $group_position ) {
			return $this->translate_strict_aggregate_only_order_by_query(
				$tokens,
				$projection_start,
				$order_position,
				$limit_position,
				$statement_end,
				$include_limit
			);
		}

		if (
			! isset( $tokens[ $group_position + 1 ] )
			|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $group_position + 1 ]->id
			|| $group_position + 2 >= $order_position
		) {
			return null;
		}

		return $this->translate_strict_grouped_order_by_query(
			$tokens,
			$projection_start,
			$group_position,
			$order_position,
			$limit_position,
			$statement_end,
			$has_distinct,
			$include_limit
		);
	}

	/**
	 * Drop ORDER BY from scalar COUNT-only aggregate queries.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param int             $projection_start First projection token position.
	 * @param int             $order_position ORDER token position.
	 * @param int|null        $limit_position LIMIT token position, or null.
	 * @param int             $statement_end  Final statement token position, exclusive.
	 * @param bool            $include_limit  Whether to preserve the LIMIT/OFFSET clause.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_strict_aggregate_only_order_by_query(
		array $tokens,
		int $projection_start,
		int $order_position,
		?int $limit_position,
		int $statement_end,
		bool $include_limit = true
	): ?string {
		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, $projection_start, $order_position );
		if ( null === $from_position || $projection_start === $from_position ) {
			return null;
		}

		if ( ! $this->is_mysql_count_only_projection( $tokens, $projection_start, $from_position ) ) {
			return null;
		}

		$sql = 'SELECT ' . $this->translate_mysql_token_sequence_to_postgresql( $tokens, $projection_start, $order_position );
		if ( $include_limit && null !== $limit_position ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
		}

		return $sql;
	}

	/**
	 * Translate targeted grouped ORDER BY expressions to aggregate-safe forms.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param int             $projection_start First projection token position.
	 * @param int             $group_position GROUP token position.
	 * @param int             $order_position ORDER token position.
	 * @param int|null        $limit_position LIMIT token position, or null.
	 * @param int             $statement_end  Final statement token position, exclusive.
	 * @param bool            $has_distinct   Whether the original SELECT used DISTINCT.
	 * @param bool            $include_limit  Whether to preserve the LIMIT/OFFSET clause.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_strict_grouped_order_by_query(
		array $tokens,
		int $projection_start,
		int $group_position,
		int $order_position,
		?int $limit_position,
		int $statement_end,
		bool $has_distinct,
		bool $include_limit = true
	): ?string {
		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, $projection_start, $group_position );
		if ( null === $from_position || $projection_start === $from_position ) {
			return null;
		}

		$projection_items = $this->parse_mysql_select_projection_items( $tokens, $projection_start, $from_position );
		if ( null === $projection_items ) {
			return null;
		}

		$group_items = $this->split_top_level_mysql_arguments( $tokens, $group_position + 2, $order_position );
		if ( null === $group_items || count( $group_items ) < 1 ) {
			return null;
		}

		$scope_end = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::WHERE_SYMBOL,
			$from_position + 1,
			$group_position
		) ?? $group_position;
		$scope     = $this->get_mysql_select_scope( $tokens, $from_position + 1, $scope_end );
		if ( null === $scope ) {
			return null;
		}

		$select_end  = $limit_position ?? $statement_end;
		$order_items = $this->parse_mysql_select_order_by_items(
			$tokens,
			$order_position + 2,
			$select_end,
			$projection_items,
			$scope
		);
		if ( null === $order_items ) {
			return null;
		}

		$archive_date_expression = $this->get_mysql_archive_grouped_date_expression_bounds( $tokens, $group_items );
		$is_comment_id_group     = $this->is_mysql_comment_id_grouped_select_shape( $tokens, $projection_items, $group_items );
		$is_post_id_group        = $this->is_mysql_post_id_grouped_select_shape( $tokens, $projection_items, $group_items );

		if (
			$has_distinct
			&& (
				null === $archive_date_expression
				|| ! $this->is_mysql_redundant_distinct_week_archive_select_shape(
					$tokens,
					$projection_items,
					$group_items,
					$archive_date_expression
				)
			)
		) {
			return $this->translate_distinct_strict_grouped_order_by_query(
				$tokens,
				$projection_start,
				$projection_items,
				$group_items,
				$order_items,
				$from_position,
				$group_position,
				$order_position,
				$limit_position,
				$statement_end,
				$include_limit
			);
		}

		if ( null === $archive_date_expression && ! $is_comment_id_group && ! $is_post_id_group ) {
			return null;
		}

		$order_sql = array();
		$rewritten = false;
		foreach ( $order_items as $order_item ) {
			if (
				null !== $order_item['projection_index']
				|| $this->is_mysql_grouped_order_expression( $tokens, $order_item, $group_items )
			) {
				$order_sql[] = $order_item['sql'] . ' ' . $order_item['direction'];
				continue;
			}

			if (
				null !== $archive_date_expression
				&& $this->is_mysql_archive_post_date_order_expression( $tokens, $order_item, $archive_date_expression )
			) {
				$order_sql[] = $this->get_strict_grouped_aggregate_order_sql( $order_item );
				$rewritten   = true;
				continue;
			}

			if (
				(
					$is_comment_id_group
					&& $this->is_mysql_comment_id_grouped_order_expression( $tokens, $order_item )
				)
				|| (
					$is_post_id_group
					&& $this->is_mysql_post_id_grouped_order_expression( $tokens, $order_item )
				)
			) {
				$order_sql[] = $this->get_strict_grouped_aggregate_order_sql( $order_item );
				$rewritten   = true;
				continue;
			}

			return null;
		}

		$tiebreaker_sql = $this->get_strict_grouped_posts_post_date_desc_order_id_tiebreaker_sql(
			$tokens,
			$order_items,
			$group_items,
			$is_post_id_group
		);
		if ( null !== $tiebreaker_sql ) {
			$order_sql[] = $tiebreaker_sql;
			$rewritten   = true;
		}

		if ( ! $rewritten ) {
			return null;
		}

		$replacements   = array();
		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $projection_start, $group_position );
		if ( null !== $archive_date_expression ) {
			$replacements = array_merge(
				$replacements,
				$this->get_mysql_archive_grouped_projection_replacements(
					$tokens,
					$projection_items,
					$archive_date_expression
				)
			);
		}

		if ( null !== $where_position ) {
			$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$where_position + 1,
				$group_position,
				$scope
			);
			if ( $where_sql['changed'] ) {
				$replacements[] = array(
					'start' => $where_position + 1,
					'end'   => $group_position,
					'sql'   => $where_sql['sql'],
				);
			}
		}

		$sql = 'SELECT ' . $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
			$tokens,
			$projection_start,
			$order_position,
			$replacements
		)
			. ' ORDER BY ' . implode( ', ', $order_sql );
		if ( $include_limit && null !== $limit_position ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
		}

		return $sql;
	}

	/**
	 * Translate DISTINCT grouped queries that need hidden ORDER BY projections.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int             $projection_start First projection token position.
	 * @param array           $projection_items Parsed projection items.
	 * @param array           $group_items      Parsed GROUP BY item ranges.
	 * @param array           $order_items      Parsed ORDER BY items.
	 * @param int             $from_position    FROM token position.
	 * @param int             $group_position   GROUP token position.
	 * @param int             $order_position   ORDER token position.
	 * @param int|null        $limit_position   LIMIT token position, or null.
	 * @param int             $statement_end    Final statement token position, exclusive.
	 * @param bool            $include_limit    Whether to preserve the LIMIT/OFFSET clause.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_distinct_strict_grouped_order_by_query(
		array $tokens,
		int $projection_start,
		array $projection_items,
		array $group_items,
		array $order_items,
		int $from_position,
		int $group_position,
		int $order_position,
		?int $limit_position,
		int $statement_end,
		bool $include_limit = true
	): ?string {
		$select_end = $limit_position ?? $statement_end;
		if (
			$this->contains_mysql_token(
				$tokens,
				$projection_start,
				$select_end,
				array(
					WP_MySQL_Lexer::SELECT_SYMBOL,
				)
			)
		) {
			return null;
		}

		$has_hidden_order_expression = false;
		foreach ( $order_items as $order_item ) {
			if ( null === $order_item['projection_index'] ) {
				$has_hidden_order_expression = true;
				break;
			}
		}

		if ( ! $has_hidden_order_expression ) {
			return null;
		}

		if (
			! $this->contains_mysql_aggregate_call( $tokens, $projection_start, $select_end )
			&& $this->is_mysql_distinct_grouped_projection_shape( $tokens, $projection_items, $group_items )
		) {
			return $this->build_distinct_strict_grouped_order_by_query(
				$tokens,
				$projection_items,
				$this->get_mysql_group_by_item_sql( $tokens, $group_items ),
				$order_items,
				$from_position,
				$group_position,
				$order_position,
				$limit_position,
				$statement_end,
				$include_limit
			);
		}

		$group_by_sql = $this->get_mysql_distinct_term_taxonomy_group_by_sql(
			$tokens,
			$projection_items,
			$group_items,
			$order_items,
			$from_position,
			$group_position
		);
		if ( null === $group_by_sql ) {
			return null;
		}

		return $this->build_distinct_strict_grouped_order_by_query(
			$tokens,
			$projection_items,
			$group_by_sql,
			$order_items,
			$from_position,
			$group_position,
			$order_position,
			$limit_position,
			$statement_end,
			$include_limit
		);
	}

	/**
	 * Translate parsed GROUP BY items to PostgreSQL SQL.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $group_items Parsed GROUP BY item ranges.
	 * @return string[] PostgreSQL GROUP BY expressions.
	 */
	private function get_mysql_group_by_item_sql( array $tokens, array $group_items ): array {
		$group_by_sql = array();
		foreach ( $group_items as $group_item ) {
			$group_by_sql[] = $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$group_item['start'],
				$group_item['end']
			);
		}

		return $group_by_sql;
	}

	/**
	 * Check whether DISTINCT projection expressions exactly match GROUP BY.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @param array           $group_items      Parsed GROUP BY item ranges.
	 * @return bool Whether grouping already preserves DISTINCT cardinality.
	 */
	private function is_mysql_distinct_grouped_projection_shape( array $tokens, array $projection_items, array $group_items ): bool {
		if ( count( $projection_items ) !== count( $group_items ) ) {
			return false;
		}

		$matched_group_items = array();
		foreach ( $projection_items as $projection_item ) {
			$matched = false;
			foreach ( $group_items as $group_index => $group_item ) {
				if ( isset( $matched_group_items[ $group_index ] ) ) {
					continue;
				}

				if (
					$this->are_mysql_token_ranges_equivalent(
						$tokens,
						$projection_item['expression_start'],
						$projection_item['expression_end'],
						$group_item['start'],
						$group_item['end']
					)
				) {
					$matched_group_items[ $group_index ] = true;
					$matched                             = true;
					break;
				}
			}

			if ( ! $matched ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Get GROUP BY expressions for the supported single-taxonomy term query.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @param array           $group_items      Parsed GROUP BY item ranges.
	 * @param array           $order_items      Parsed ORDER BY items.
	 * @param int             $from_position    FROM token position.
	 * @param int             $group_position   GROUP token position.
	 * @return string[]|null PostgreSQL GROUP BY expressions, or null when unsupported.
	 */
	private function get_mysql_distinct_term_taxonomy_group_by_sql(
		array $tokens,
		array $projection_items,
		array $group_items,
		array $order_items,
		int $from_position,
		int $group_position
	): ?array {
		if (
			! $this->is_mysql_distinct_term_taxonomy_projection_shape( $tokens, $projection_items )
			|| ! $this->is_mysql_distinct_term_taxonomy_group_shape( $tokens, $group_items )
			|| ! $this->is_mysql_distinct_term_taxonomy_order_shape( $tokens, $order_items )
		) {
			return null;
		}

		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $from_position + 1, $group_position );
		if (
			null === $where_position
			|| ! $this->is_mysql_distinct_term_taxonomy_from_shape( $tokens, $from_position, $where_position )
			|| ! $this->has_mysql_single_term_taxonomy_predicate( $tokens, $where_position + 1, $group_position )
		) {
			return null;
		}

		return array(
			't.term_id',
			'tt.term_taxonomy_id',
			'tt.taxonomy',
			'tt.description',
			'tt.parent',
		);
	}

	/**
	 * Check whether the projection is WordPress's term query result shape.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @return bool Whether the projection shape is supported.
	 */
	private function is_mysql_distinct_term_taxonomy_projection_shape( array $tokens, array $projection_items ): bool {
		if ( 6 !== count( $projection_items ) ) {
			return false;
		}

		$expected_columns = array(
			array( 't', 'term_id', 'term_id' ),
			array( 'tt', 'term_taxonomy_id', 'term_taxonomy_id' ),
			array( 'tt', 'taxonomy', 'taxonomy' ),
			array( 'tt', 'description', 'description' ),
			array( 'tt', 'parent', 'parent' ),
		);
		foreach ( $expected_columns as $index => $expected_column ) {
			if (
				! $this->is_mysql_projection_item_qualified_column(
					$tokens,
					$projection_items[ $index ],
					$expected_column[0],
					$expected_column[1],
					$expected_column[2]
				)
			) {
				return false;
			}
		}

		return $this->is_mysql_count_post_type_projection_item( $tokens, $projection_items[5] );
	}

	/**
	 * Check whether a projection item is a specific qualified column.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param array           $item   Parsed projection item.
	 * @param string          $alias  Expected table alias.
	 * @param string          $column Expected column name.
	 * @param string          $name   Expected output name.
	 * @return bool Whether the projection item matches.
	 */
	private function is_mysql_projection_item_qualified_column( array $tokens, array $item, string $alias, string $column, string $name ): bool {
		return strtolower( $item['alias'] ) === $name
			&& $this->is_mysql_exact_qualified_column_expression(
				$tokens,
				$item['expression_start'],
				$item['expression_end'],
				$alias,
				$column
			);
	}

	/**
	 * Check whether a projection item is COUNT(p.post_type) AS count.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param array           $item   Parsed projection item.
	 * @return bool Whether the projection item matches.
	 */
	private function is_mysql_count_post_type_projection_item( array $tokens, array $item ): bool {
		if ( 'count' !== strtolower( $item['alias'] ) ) {
			return false;
		}

		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $item['expression_start'], $item['expression_end'] );
		if (
			! isset( $tokens[ $bounds['start'] ], $tokens[ $bounds['start'] + 1 ] )
			|| ! $this->is_mysql_token_value( $tokens[ $bounds['start'] ], 'count' )
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $bounds['start'] + 1 ]->id
			|| $this->get_mysql_parenthesized_sequence_end( $tokens, $bounds['start'] + 1, $bounds['end'] ) !== $bounds['end']
		) {
			return false;
		}

		return $this->is_mysql_exact_qualified_column_expression(
			$tokens,
			$bounds['start'] + 2,
			$bounds['end'] - 1,
			'p',
			'post_type'
		);
	}

	/**
	 * Check whether GROUP BY is exactly t.term_id.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $group_items Parsed GROUP BY item ranges.
	 * @return bool Whether the group shape is supported.
	 */
	private function is_mysql_distinct_term_taxonomy_group_shape( array $tokens, array $group_items ): bool {
		return 1 === count( $group_items )
			&& $this->is_mysql_exact_qualified_column_expression(
				$tokens,
				$group_items[0]['start'],
				$group_items[0]['end'],
				't',
				'term_id'
			);
	}

	/**
	 * Check whether ORDER BY can be hidden for the supported term query.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $order_items Parsed ORDER BY items.
	 * @return bool Whether the order shape is supported.
	 */
	private function is_mysql_distinct_term_taxonomy_order_shape( array $tokens, array $order_items ): bool {
		if ( 1 !== count( $order_items ) || null !== $order_items[0]['projection_index'] ) {
			return false;
		}

		return $this->is_mysql_exact_qualified_column_expression(
			$tokens,
			$order_items[0]['expression_start'],
			$order_items[0]['expression_end'],
			't',
			'name'
		);
	}

	/**
	 * Check whether FROM begins with terms t joined to term_taxonomy tt.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int             $from_position FROM token position.
	 * @param int             $from_end      Final FROM-clause token, exclusive.
	 * @return bool Whether the FROM shape is supported.
	 */
	private function is_mysql_distinct_term_taxonomy_from_shape( array $tokens, int $from_position, int $from_end ): bool {
		$terms_reference = $this->parse_mysql_table_reference( $tokens, $from_position + 1, $from_end );
		if (
			null === $terms_reference
			|| ! $this->is_mysql_wordpress_table_reference( $terms_reference, 'terms', 't' )
		) {
			return false;
		}

		$position = $terms_reference['position'];
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::INNER_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::JOIN_SYMBOL !== $tokens[ $position ]->id ) {
			return false;
		}

		$term_taxonomy_reference = $this->parse_mysql_table_reference( $tokens, $position + 1, $from_end );
		if (
			null === $term_taxonomy_reference
			|| ! $this->is_mysql_wordpress_table_reference( $term_taxonomy_reference, 'term_taxonomy', 'tt' )
		) {
			return false;
		}

		$position = $term_taxonomy_reference['position'];
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::ON_SYMBOL !== $tokens[ $position ]->id ) {
			return false;
		}

		$predicate_end = $this->find_mysql_join_predicate_end( $tokens, $position + 1, $from_end );
		$pair          = $this->get_mysql_top_level_simple_column_equality_pair( $tokens, $position + 1, $predicate_end );
		return null !== $pair && $this->is_mysql_wordpress_term_split_column_equality_pair( $pair );
	}

	/**
	 * Check whether WHERE constrains tt.taxonomy to one string literal.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First WHERE predicate token.
	 * @param int             $end    Final WHERE predicate token, exclusive.
	 * @return bool Whether a single taxonomy predicate is present.
	 */
	private function has_mysql_single_term_taxonomy_predicate( array $tokens, int $start, int $end ): bool {
		$conjuncts = $this->split_mysql_top_level_boolean_conjuncts( $tokens, $start, $end );
		if ( null === $conjuncts ) {
			return false;
		}

		$matched = false;
		foreach ( $conjuncts as $conjunct ) {
			if ( ! $this->is_mysql_single_term_taxonomy_predicate( $tokens, $conjunct['start'], $conjunct['end'] ) ) {
				continue;
			}

			if ( $matched ) {
				return false;
			}

			$matched = true;
		}

		return $matched;
	}

	/**
	 * Check whether a predicate is tt.taxonomy = literal or IN (single literal).
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First predicate token.
	 * @param int             $end    Final predicate token, exclusive.
	 * @return bool Whether the predicate constrains one taxonomy value.
	 */
	private function is_mysql_single_term_taxonomy_predicate( array $tokens, int $start, int $end ): bool {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		$reference = $this->parse_mysql_column_reference( $tokens, $start, $end );
		if (
			null === $reference
			|| $reference['end'] >= $end
			|| 'tt' !== strtolower( (string) $reference['qualifier'] )
			|| 'taxonomy' !== strtolower( $reference['column'] )
		) {
			return false;
		}

		if (
			WP_MySQL_Lexer::EQUAL_OPERATOR === $tokens[ $reference['end'] ]->id
			&& $this->is_mysql_string_literal_range( $tokens, $reference['end'] + 1, $end )
		) {
			return true;
		}

		if (
			WP_MySQL_Lexer::IN_SYMBOL !== $tokens[ $reference['end'] ]->id
			|| ! isset( $tokens[ $reference['end'] + 1 ] )
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $reference['end'] + 1 ]->id
		) {
			return false;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $reference['end'] + 1, $end );
		if ( $after_close !== $end ) {
			return false;
		}

		$items = $this->split_top_level_mysql_arguments( $tokens, $reference['end'] + 2, $end - 1 );
		return null !== $items
			&& 1 === count( $items )
			&& $this->is_mysql_string_literal_range( $tokens, $items[0]['start'], $items[0]['end'] );
	}

	/**
	 * Check whether an expression is exactly a qualified column reference.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @param string          $alias  Expected table alias.
	 * @param string          $column Expected column name.
	 * @return bool Whether the expression matches.
	 */
	private function is_mysql_exact_qualified_column_expression( array $tokens, int $start, int $end, string $alias, string $column ): bool {
		$column_expression = $this->get_mysql_simple_qualified_column_expression( $tokens, $start, $end );
		return null !== $column_expression
			&& strtolower( $alias ) === $column_expression['qualifier']
			&& strtolower( $column ) === $column_expression['column'];
	}

	/**
	 * Build a derived-table rewrite for DISTINCT grouped ORDER BY queries.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @param string[]        $group_by_sql     PostgreSQL GROUP BY expressions.
	 * @param array           $order_items      Parsed ORDER BY items.
	 * @param int             $from_position    FROM token position.
	 * @param int             $group_position   GROUP token position.
	 * @param int             $order_position   ORDER token position.
	 * @param int|null        $limit_position   LIMIT token position, or null.
	 * @param int             $statement_end    Final statement token position, exclusive.
	 * @param bool            $include_limit    Whether to preserve the LIMIT/OFFSET clause.
	 * @return string PostgreSQL query.
	 */
	private function build_distinct_strict_grouped_order_by_query(
		array $tokens,
		array $projection_items,
		array $group_by_sql,
		array $order_items,
		int $from_position,
		int $group_position,
		int $order_position,
		?int $limit_position,
		int $statement_end,
		bool $include_limit = true
	): string {
		$derived_table_alias        = '__wp_pg_distinct';
		$quoted_derived_table_alias = $this->connection->quote_identifier( $derived_table_alias );
		$inner_projection_sql       = array();
		$outer_projection_sql       = array();

		foreach ( $projection_items as $projection_item ) {
			$quoted_alias           = $this->connection->quote_identifier( $projection_item['alias'] );
			$inner_projection_sql[] = $projection_item['sql'] . ' AS ' . $quoted_alias;
			$outer_projection_sql[] = sprintf(
				'%s.%s AS %s',
				$quoted_derived_table_alias,
				$quoted_alias,
				$quoted_alias
			);
		}

		foreach ( $order_items as $index => $order_item ) {
			if ( null !== $order_item['projection_index'] ) {
				continue;
			}

			$aggregate_function     = 'DESC' === $order_item['direction'] ? 'MAX' : 'MIN';
			$quoted_order_alias     = $this->connection->quote_identifier( $this->get_distinct_order_by_hidden_alias( $index ) );
			$inner_projection_sql[] = sprintf(
				'%s(%s) AS %s',
				$aggregate_function,
				$order_item['sql'],
				$quoted_order_alias
			);
		}

		$sql = sprintf(
			'SELECT %s FROM (SELECT DISTINCT %s %s GROUP BY %s) AS %s ORDER BY %s',
			implode( ', ', $outer_projection_sql ),
			implode( ', ', $inner_projection_sql ),
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, $from_position, $group_position ),
			implode( ', ', $group_by_sql ),
			$quoted_derived_table_alias,
			$this->get_distinct_order_by_outer_order_sql( $projection_items, $order_items, $quoted_derived_table_alias )
		);

		if ( $include_limit && null !== $limit_position ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
		}

		return $sql;
	}

	/**
	 * Translate grouped SELECT queries that reference projection aliases in HAVING.
	 *
	 * MySQL resolves SELECT aliases in HAVING, but PostgreSQL does not. Keep this
	 * rewrite limited to aliases whose projected expression is valid in a grouped
	 * HAVING clause so unsupported grouping shapes still fail visibly.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_grouped_having_alias_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		if (
			$this->contains_top_level_mysql_token(
				$tokens,
				1,
				$statement_end,
				array(
					WP_MySQL_Lexer::DISTINCT_SYMBOL,
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::HIGH_PRIORITY_SYMBOL,
					WP_MySQL_Lexer::INTO_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL,
					WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, 1, $statement_end );
		$select_end     = $limit_position ?? $statement_end;
		if ( null !== $limit_position && ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $statement_end ) ) {
			return null;
		}

		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, 1, $select_end );
		if (
			null !== $order_position
			&& (
				! isset( $tokens[ $order_position + 1 ] )
				|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $order_position + 1 ]->id
				|| $order_position + 2 >= $select_end
			)
		) {
			return null;
		}

		$having_end      = $order_position ?? $select_end;
		$having_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::HAVING_SYMBOL, 1, $having_end );
		if ( null === $having_position || $having_position + 1 >= $having_end ) {
			return null;
		}

		$group_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::GROUP_SYMBOL, 1, $having_position );
		if (
			null === $group_position
			|| ! isset( $tokens[ $group_position + 1 ] )
			|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $group_position + 1 ]->id
			|| $group_position + 2 >= $having_position
		) {
			return null;
		}

		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, 1, $group_position );
		if ( null === $from_position || 1 === $from_position ) {
			return null;
		}

		$group_items = $this->split_top_level_mysql_arguments( $tokens, $group_position + 2, $having_position );
		if ( null === $group_items || count( $group_items ) < 1 ) {
			return null;
		}

		$alias_expressions = $this->get_mysql_grouped_having_projection_alias_expressions(
			$tokens,
			1,
			$from_position,
			$group_items
		);
		if ( null === $alias_expressions || empty( $alias_expressions ) ) {
			return null;
		}

		$having_sql = $this->translate_mysql_having_alias_predicate_to_postgresql(
			$tokens,
			$having_position + 1,
			$having_end,
			$alias_expressions
		);
		if ( null === $having_sql ) {
			return null;
		}

		$replacements   = array();
		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $from_position + 1, $group_position );
		if ( null !== $where_position ) {
			$scope_end = $where_position;
		} else {
			$scope_end = $group_position;
		}

		$scope = $this->get_mysql_select_scope( $tokens, $from_position + 1, $scope_end );
		if ( null === $scope ) {
			return null;
		}

		if ( null !== $where_position ) {
			$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$where_position + 1,
				$group_position,
				$scope
			);
			if ( $where_sql['changed'] ) {
				$replacements[] = array(
					'start' => $where_position + 1,
					'end'   => $group_position,
					'sql'   => $where_sql['sql'],
				);
			}
		}

		$group_by_extensions = $this->get_mysql_grouped_having_group_by_projection_extensions(
			$tokens,
			1,
			$from_position,
			$group_position,
			$having_position,
			$group_items
		);
		if ( null === $group_by_extensions ) {
			return null;
		}

		if ( ! empty( $group_by_extensions ) ) {
			$replacements[] = array(
				'start' => $group_position + 2,
				'end'   => $having_position,
				'sql'   => $this->translate_mysql_token_sequence_to_postgresql( $tokens, $group_position + 2, $having_position )
					. ', ' . implode( ', ', $group_by_extensions ),
			);
		}

		$replacements[] = array(
			'start' => $having_position + 1,
			'end'   => $having_end,
			'sql'   => $having_sql,
		);

		return 'SELECT ' . $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
			$tokens,
			1,
			$statement_end,
			$replacements
		);
	}

	/**
	 * Get projection aliases that can be substituted safely in grouped HAVING.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param int             $start       First projection token position.
	 * @param int             $end         Final projection token position, exclusive.
	 * @param array           $group_items Parsed GROUP BY items.
	 * @return array<string, array{sql: string}>|null Alias expressions keyed by lowercase alias.
	 */
	private function get_mysql_grouped_having_projection_alias_expressions( array $tokens, int $start, int $end, array $group_items ): ?array {
		$ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $ranges || count( $ranges ) < 1 ) {
			return null;
		}

		$aliases = array();
		foreach ( $ranges as $range ) {
			$item = $this->parse_mysql_aliased_projection_expression( $tokens, $range['start'], $range['end'] );
			if ( null === $item ) {
				continue;
			}

			$alias_key = strtolower( $item['alias'] );
			if ( isset( $aliases[ $alias_key ] ) ) {
				return null;
			}

			if (
				! $this->contains_mysql_aggregate_call( $tokens, $item['expression_start'], $item['expression_end'] )
				&& ! $this->is_mysql_grouped_projection_expression( $tokens, $item, $group_items )
			) {
				continue;
			}

			$aliases[ $alias_key ] = array(
				'sql' => $this->translate_mysql_token_sequence_to_postgresql(
					$tokens,
					$item['expression_start'],
					$item['expression_end']
				),
			);
		}

		return $aliases;
	}

	/**
	 * Get GROUP BY extensions for selected columns equivalent to grouped columns.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param int             $projection_start First projection token position.
	 * @param int             $from_position  FROM token position.
	 * @param int             $group_position GROUP token position.
	 * @param int             $having_position HAVING token position.
	 * @param array           $group_items    Parsed GROUP BY items.
	 * @return string[]|null PostgreSQL GROUP BY expressions to append, or null when unsupported.
	 */
	private function get_mysql_grouped_having_group_by_projection_extensions(
		array $tokens,
		int $projection_start,
		int $from_position,
		int $group_position,
		int $having_position,
		array $group_items
	): ?array {
		$projection_items = $this->split_top_level_mysql_arguments( $tokens, $projection_start, $from_position );
		if ( null === $projection_items ) {
			return null;
		}

		$grouped_columns = array();
		foreach ( $group_items as $group_item ) {
			$grouped_column = $this->get_mysql_simple_qualified_column_expression(
				$tokens,
				$group_item['start'],
				$group_item['end']
			);
			if ( null !== $grouped_column ) {
				$grouped_columns[] = $grouped_column;
			}
		}

		if ( empty( $grouped_columns ) ) {
			return array();
		}

		$extensions         = array();
		$extension_keys     = array();
		$equivalent_columns = null;
		foreach ( $projection_items as $projection_item ) {
			$bounds = $this->get_mysql_projection_expression_bounds( $tokens, $projection_item['start'], $projection_item['end'] );
			if ( null === $bounds ) {
				continue;
			}

			$projection_column = $this->get_mysql_simple_qualified_column_expression( $tokens, $bounds['start'], $bounds['end'] );
			if ( null === $projection_column ) {
				continue;
			}

			if ( $this->is_mysql_projection_column_grouped( $projection_column, $grouped_columns ) ) {
				continue;
			}

			if ( null === $equivalent_columns ) {
				$equivalent_columns = $this->get_mysql_safe_grouped_having_column_equality_pairs(
					$tokens,
					$from_position,
					$group_position
				);
				if ( null === $equivalent_columns || empty( $equivalent_columns ) ) {
					return null;
				}
			}

			$extended = false;
			foreach ( $grouped_columns as $grouped_column ) {
				if (
					$projection_column['key'] !== $grouped_column['key']
					&& ! isset( $equivalent_columns[ $projection_column['key'] ][ $grouped_column['key'] ] )
				) {
					continue;
				}

				$extension_key = $projection_column['key'];
				if ( isset( $extension_keys[ $extension_key ] ) ) {
					$extended = true;
					break;
				}

				$extensions[]                     = $projection_column['sql'];
				$extension_keys[ $extension_key ] = true;
				$extended                         = true;
				break;
			}

			if ( ! $extended ) {
				return null;
			}
		}

		return $extensions;
	}

	/**
	 * Get expression bounds for a SELECT projection item.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection item token position.
	 * @param int             $end    Final projection item token position, exclusive.
	 * @return array{start: int, end: int}|null Expression bounds, or null when malformed.
	 */
	private function get_mysql_projection_expression_bounds( array $tokens, int $start, int $end ): ?array {
		if ( $start >= $end ) {
			return null;
		}

		$expression_end = $end;
		$as_position    = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::AS_SYMBOL, $start, $end );
		if ( null !== $as_position ) {
			if ( $as_position <= $start || $as_position + 2 !== $end ) {
				return null;
			}

			$expression_end = $as_position;
		} elseif ( null !== $this->get_mysql_implicit_projection_alias( $tokens, $start, $end ) ) {
			$expression_end = $end - 1;
		}

		return $start >= $expression_end
			? null
			: array(
				'start' => $start,
				'end'   => $expression_end,
			);
	}

	/**
	 * Parse a simple qualified column expression.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token position.
	 * @param int             $end    Final expression token position, exclusive.
	 * @return array{qualifier: string, column: string, key: string, sql: string}|null Column data, or null when unsupported.
	 */
	private function get_mysql_simple_qualified_column_expression( array $tokens, int $start, int $end ): ?array {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		return $this->get_mysql_unwrapped_simple_qualified_column_expression( $tokens, $bounds['start'], $bounds['end'] );
	}

	/**
	 * Parse a simple qualified column expression without removing wrapper parentheses.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token position.
	 * @param int             $end    Final expression token position, exclusive.
	 * @return array{qualifier: string, column: string, key: string, sql: string}|null Column data, or null when unsupported.
	 */
	private function get_mysql_unwrapped_simple_qualified_column_expression( array $tokens, int $start, int $end ): ?array {
		if (
			$start + 3 !== $end
			|| ! isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ] )
			|| WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $start + 1 ]->id
		) {
			return null;
		}

		$qualifier = $this->get_mysql_identifier_token_value( $tokens[ $start ] );
		$column    = $this->get_mysql_identifier_token_value( $tokens[ $start + 2 ] );
		if ( null === $qualifier || null === $column ) {
			return null;
		}

		$key = strtolower( $qualifier ) . '.' . strtolower( $column );
		return array(
			'qualifier' => strtolower( $qualifier ),
			'column'    => strtolower( $column ),
			'key'       => $key,
			'sql'       => $this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end ),
		);
	}

	/**
	 * Get safe qualified column equality pairs for grouped HAVING rewrites.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $from_position  FROM token position.
	 * @param int             $group_position GROUP token position.
	 * @return array<string, array<string, true>>|null Column equality adjacency map, or null when unsupported.
	 */
	private function get_mysql_safe_grouped_having_column_equality_pairs( array $tokens, int $from_position, int $group_position ): ?array {
		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $from_position + 1, $group_position );
		$from_end       = $where_position ?? $group_position;

		$pairs = $this->get_mysql_inner_join_column_equality_pairs( $tokens, $from_position + 1, $from_end );
		if ( null === $pairs ) {
			return null === $where_position
				? $this->get_mysql_wordpress_term_split_left_join_column_equality_pairs( $tokens, $from_position + 1, $from_end )
				: null;
		}

		if ( null === $where_position ) {
			return $pairs;
		}

		$where_pairs = $this->get_mysql_top_level_conjunct_column_equality_pairs( $tokens, $where_position + 1, $group_position );
		if ( null === $where_pairs ) {
			return null;
		}

		$this->merge_mysql_column_equality_pairs( $pairs, $where_pairs );
		return $pairs;
	}

	/**
	 * Get qualified column equality pairs from supported inner JOIN predicates.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First FROM-clause token position.
	 * @param int             $end    Final FROM-clause token position, exclusive.
	 * @return array<string, array<string, true>>|null Column equality adjacency map, or null when unsupported.
	 */
	private function get_mysql_inner_join_column_equality_pairs( array $tokens, int $start, int $end ): ?array {
		$pairs = array();

		for ( $position = $start; $position < $end; $position++ ) {
			$token_id = $tokens[ $position ]->id;
			if (
				WP_MySQL_Lexer::LEFT_SYMBOL === $token_id
				|| WP_MySQL_Lexer::NATURAL_SYMBOL === $token_id
				|| WP_MySQL_Lexer::OUTER_SYMBOL === $token_id
				|| WP_MySQL_Lexer::RIGHT_SYMBOL === $token_id
				|| WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL === $token_id
				|| WP_MySQL_Lexer::USING_SYMBOL === $token_id
			) {
				return null;
			}

			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $token_id ) {
				return null;
			}

			if ( WP_MySQL_Lexer::ON_SYMBOL !== $token_id ) {
				continue;
			}

			$predicate_end = $this->find_mysql_join_predicate_end( $tokens, $position + 1, $end );
			$join_pairs    = $this->get_mysql_top_level_conjunct_column_equality_pairs( $tokens, $position + 1, $predicate_end );
			if ( null === $join_pairs ) {
				return null;
			}

			$this->merge_mysql_column_equality_pairs( $pairs, $join_pairs );
			$position = $predicate_end - 1;
		}

		return $pairs;
	}

	/**
	 * Get equality pairs for WordPress core's legacy shared-term split query.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First FROM-clause token position.
	 * @param int             $end    Final FROM-clause token position, exclusive.
	 * @return array<string, array<string, true>>|null Column equality adjacency map, or null when unsupported.
	 */
	private function get_mysql_wordpress_term_split_left_join_column_equality_pairs( array $tokens, int $start, int $end ): ?array {
		$term_taxonomy_reference = $this->parse_mysql_table_reference( $tokens, $start, $end );
		if (
			null === $term_taxonomy_reference
			|| ! $this->is_mysql_wordpress_table_reference( $term_taxonomy_reference, 'term_taxonomy', 'tt' )
		) {
			return null;
		}

		$position = $term_taxonomy_reference['position'];
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::LEFT_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OUTER_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::JOIN_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$terms_reference = $this->parse_mysql_table_reference( $tokens, $position + 1, $end );
		if (
			null === $terms_reference
			|| ! $this->is_mysql_wordpress_table_reference( $terms_reference, 'terms', 't' )
		) {
			return null;
		}

		$position = $terms_reference['position'];
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::ON_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$predicate_end = $this->find_mysql_join_predicate_end( $tokens, $position + 1, $end );
		if ( $predicate_end !== $end ) {
			return null;
		}

		$pair = $this->get_mysql_top_level_simple_column_equality_pair( $tokens, $position + 1, $predicate_end );
		if ( null === $pair || ! $this->is_mysql_wordpress_term_split_column_equality_pair( $pair ) ) {
			return null;
		}

		return array(
			't.term_id'  => array(
				'tt.term_id' => true,
			),
			'tt.term_id' => array(
				't.term_id' => true,
			),
		);
	}

	/**
	 * Check whether a table reference matches a WordPress core table and alias.
	 *
	 * @param array  $reference Parsed table reference.
	 * @param string $table_base Expected unprefixed table name.
	 * @param string $alias      Expected alias.
	 * @return bool Whether the reference matches.
	 */
	private function is_mysql_wordpress_table_reference( array $reference, string $table_base, string $alias ): bool {
		$reference_alias = strtolower( null === $reference['alias'] ? $reference['table'] : $reference['alias'] );
		if ( $alias !== $reference_alias ) {
			return false;
		}

		return $this->is_mysql_wordpress_table_name( $reference['table'], $table_base );
	}

	/**
	 * Check whether a table name matches a WordPress core table base name.
	 *
	 * @param string $table_name Table name.
	 * @param string $table_base Expected unprefixed table name.
	 * @return bool Whether the table name matches.
	 */
	private function is_mysql_wordpress_table_name( string $table_name, string $table_base ): bool {
		$table_name = strtolower( $table_name );
		$table_base = strtolower( $table_base );
		return $table_base === $table_name
			|| substr( $table_name, -strlen( '_' . $table_base ) ) === '_' . $table_base;
	}

	/**
	 * Check whether an equality pair is t.term_id = tt.term_id.
	 *
	 * @param array $pair Parsed equality pair.
	 * @return bool Whether this is the WordPress shared-term split equality.
	 */
	private function is_mysql_wordpress_term_split_column_equality_pair( array $pair ): bool {
		return (
			't.term_id' === $pair['left']['key']
			&& 'tt.term_id' === $pair['right']['key']
		) || (
			'tt.term_id' === $pair['left']['key']
			&& 't.term_id' === $pair['right']['key']
		);
	}

	/**
	 * Find the end of a JOIN ON predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First ON predicate token position.
	 * @param int             $end    Final FROM-clause token position, exclusive.
	 * @return int Final ON predicate token position, exclusive.
	 */
	private function find_mysql_join_predicate_end( array $tokens, int $start, int $end ): int {
		$depth = 0;
		for ( $position = $start; $position < $end; $position++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $position ]->id ) {
				--$depth;
				continue;
			}

			if (
				0 === $depth
				&& (
					WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::INNER_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::JOIN_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::LEFT_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::NATURAL_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::RIGHT_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL === $tokens[ $position ]->id
				)
			) {
				return $position;
			}
		}

		return $end;
	}

	/**
	 * Get column equality pairs from a top-level AND predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First predicate token position.
	 * @param int             $end    Final predicate token position, exclusive.
	 * @return array<string, array<string, true>>|null Column equality adjacency map, or null when unsupported.
	 */
	private function get_mysql_top_level_conjunct_column_equality_pairs( array $tokens, int $start, int $end ): ?array {
		$conjuncts = $this->split_mysql_top_level_boolean_conjuncts( $tokens, $start, $end );
		if ( null === $conjuncts ) {
			return null;
		}

		$pairs = array();
		foreach ( $conjuncts as $conjunct ) {
			$pair = $this->get_mysql_top_level_simple_column_equality_pair(
				$tokens,
				$conjunct['start'],
				$conjunct['end']
			);
			if ( null === $pair ) {
				continue;
			}

			$pairs[ $pair['left']['key'] ][ $pair['right']['key'] ] = true;
			$pairs[ $pair['right']['key'] ][ $pair['left']['key'] ] = true;
		}

		return $pairs;
	}

	/**
	 * Split a boolean predicate into top-level AND conjuncts.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First predicate token position.
	 * @param int             $end    Final predicate token position, exclusive.
	 * @return array<int, array{start: int, end: int}>|null Conjunct bounds, or null when unsupported.
	 */
	private function split_mysql_top_level_boolean_conjuncts( array $tokens, int $start, int $end ): ?array {
		if ( $start >= $end ) {
			return null;
		}

		$conjuncts      = array();
		$conjunct_start = $start;
		$depth          = 0;

		for ( $position = $start; $position < $end; $position++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $position ]->id ) {
				--$depth;
				if ( $depth < 0 ) {
					return null;
				}
				continue;
			}

			if ( 0 !== $depth ) {
				continue;
			}

			if ( WP_MySQL_Lexer::OR_SYMBOL === $tokens[ $position ]->id || WP_MySQL_Lexer::XOR_SYMBOL === $tokens[ $position ]->id ) {
				return null;
			}

			if ( WP_MySQL_Lexer::AND_SYMBOL !== $tokens[ $position ]->id ) {
				continue;
			}

			if ( $conjunct_start === $position ) {
				return null;
			}

			$conjuncts[]    = array(
				'start' => $conjunct_start,
				'end'   => $position,
			);
			$conjunct_start = $position + 1;
		}

		if ( 0 !== $depth || $conjunct_start >= $end ) {
			return null;
		}

		$conjuncts[] = array(
			'start' => $conjunct_start,
			'end'   => $end,
		);

		return $conjuncts;
	}

	/**
	 * Parse a top-level simple qualified-column equality predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First predicate token position.
	 * @param int             $end    Final predicate token position, exclusive.
	 * @return array{left: array, right: array}|null Equality pair, or null when unsupported.
	 */
	private function get_mysql_top_level_simple_column_equality_pair( array $tokens, int $start, int $end ): ?array {
		$equal_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::EQUAL_OPERATOR, $start, $end );
		if (
			null === $equal_position
			|| null !== $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::EQUAL_OPERATOR, $equal_position + 1, $end )
		) {
			return null;
		}

		$left_column  = $this->get_mysql_unwrapped_simple_qualified_column_expression( $tokens, $start, $equal_position );
		$right_column = $this->get_mysql_unwrapped_simple_qualified_column_expression( $tokens, $equal_position + 1, $end );
		if ( null === $left_column || null === $right_column ) {
			return null;
		}

		return array(
			'left'  => $left_column,
			'right' => $right_column,
		);
	}

	/**
	 * Merge column equality adjacency maps.
	 *
	 * @param array $target Target adjacency map.
	 * @param array $source Source adjacency map.
	 */
	private function merge_mysql_column_equality_pairs( array &$target, array $source ): void {
		foreach ( $source as $left_key => $right_columns ) {
			foreach ( $right_columns as $right_key => $_ ) {
				$target[ $left_key ][ $right_key ] = true;
			}
		}
	}

	/**
	 * Check whether a selected column is already grouped.
	 *
	 * @param array $projection_column Selected column data.
	 * @param array $grouped_columns   Grouped column data.
	 * @return bool Whether the selected column is grouped.
	 */
	private function is_mysql_projection_column_grouped( array $projection_column, array $grouped_columns ): bool {
		foreach ( $grouped_columns as $grouped_column ) {
			if ( $projection_column['key'] === $grouped_column['key'] ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Parse a projection item that has an explicit or implicit alias.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection item token position.
	 * @param int             $end    Final projection item token position, exclusive.
	 * @return array{expression_start: int, expression_end: int, alias: string}|null Parsed alias expression, or null when absent.
	 */
	private function parse_mysql_aliased_projection_expression( array $tokens, int $start, int $end ): ?array {
		if ( $start >= $end ) {
			return null;
		}

		$expression_end = $end;
		$alias          = null;
		$as_position    = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::AS_SYMBOL, $start, $end );

		if ( null !== $as_position ) {
			if ( $as_position <= $start || $as_position + 2 !== $end ) {
				return null;
			}

			$alias = $this->get_mysql_projection_alias_token_value( $tokens[ $as_position + 1 ] ?? null );
			if ( null === $alias ) {
				return null;
			}

			$expression_end = $as_position;
		} else {
			$alias = $this->get_mysql_implicit_projection_alias( $tokens, $start, $end );
			if ( null === $alias ) {
				return null;
			}

			$expression_end = $end - 1;
		}

		if ( $start >= $expression_end ) {
			return null;
		}

		return array(
			'expression_start' => $start,
			'expression_end'   => $expression_end,
			'alias'            => $alias,
		);
	}

	/**
	 * Check whether a projection expression is already present in GROUP BY.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $item        Parsed projection item.
	 * @param array           $group_items Parsed GROUP BY items.
	 * @return bool Whether the projection expression is grouped.
	 */
	private function is_mysql_grouped_projection_expression( array $tokens, array $item, array $group_items ): bool {
		foreach ( $group_items as $group_item ) {
			if (
				$this->are_mysql_token_ranges_equivalent(
					$tokens,
					$item['expression_start'],
					$item['expression_end'],
					$group_item['start'],
					$group_item['end']
				)
			) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether a token range contains a MySQL aggregate function call.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token position.
	 * @param int             $end    Final expression token position, exclusive.
	 * @return bool Whether an aggregate call is present.
	 */
	private function contains_mysql_aggregate_call( array $tokens, int $start, int $end ): bool {
		$aggregate_token_ids = array(
			WP_MySQL_Lexer::AVG_SYMBOL,
			WP_MySQL_Lexer::BIT_AND_SYMBOL,
			WP_MySQL_Lexer::BIT_OR_SYMBOL,
			WP_MySQL_Lexer::BIT_XOR_SYMBOL,
			WP_MySQL_Lexer::COUNT_SYMBOL,
			WP_MySQL_Lexer::GROUP_CONCAT_SYMBOL,
			WP_MySQL_Lexer::MAX_SYMBOL,
			WP_MySQL_Lexer::MIN_SYMBOL,
			WP_MySQL_Lexer::STD_SYMBOL,
			WP_MySQL_Lexer::STDDEV_POP_SYMBOL,
			WP_MySQL_Lexer::STDDEV_SAMP_SYMBOL,
			WP_MySQL_Lexer::STDDEV_SYMBOL,
			WP_MySQL_Lexer::SUM_SYMBOL,
			WP_MySQL_Lexer::VAR_POP_SYMBOL,
			WP_MySQL_Lexer::VAR_SAMP_SYMBOL,
			WP_MySQL_Lexer::VARIANCE_SYMBOL,
		);

		for ( $position = $start; $position < $end; $position++ ) {
			if (
				isset( $tokens[ $position ], $tokens[ $position + 1 ] )
				&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
				&& WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				$after_subquery = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
				if ( null !== $after_subquery ) {
					$position = $after_subquery - 1;
					continue;
				}
			}

			if (
				isset( $tokens[ $position + 1 ] )
				&& in_array( $tokens[ $position ]->id, $aggregate_token_ids, true )
				&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Translate HAVING predicate aliases to their projection expressions.
	 *
	 * @param WP_MySQL_Token[] $tokens            MySQL lexer token stream.
	 * @param int             $start             First HAVING predicate token.
	 * @param int             $end               Final HAVING predicate token, exclusive.
	 * @param array           $alias_expressions Projection alias SQL keyed by lowercase alias.
	 * @return string|null Translated HAVING SQL, or null when no alias was changed.
	 */
	private function translate_mysql_having_alias_predicate_to_postgresql( array $tokens, int $start, int $end, array $alias_expressions ): ?string {
		$chunks        = array();
		$segment_start = $start;
		$changed       = false;

		for ( $position = $start; $position < $end; $position++ ) {
			if (
				isset( $tokens[ $position ], $tokens[ $position + 1 ] )
				&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
				&& WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				$after_subquery = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
				if ( null !== $after_subquery ) {
					$position = $after_subquery - 1;
					continue;
				}
			}

			$alias = $this->get_mysql_order_by_alias_token_value( $tokens[ $position ] ?? null );
			if (
				null === $alias
				|| ! $this->is_unqualified_mysql_having_alias_reference( $tokens, $position, $end )
				|| ! isset( $alias_expressions[ strtolower( $alias ) ] )
			) {
				continue;
			}

			if ( $segment_start < $position ) {
				$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $segment_start, $position );
			}

			$chunks[]      = '(' . $alias_expressions[ strtolower( $alias ) ]['sql'] . ')';
			$segment_start = $position + 1;
			$changed       = true;
		}

		if ( ! $changed ) {
			return null;
		}

		if ( $segment_start < $end ) {
			$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $segment_start, $end );
		}

		return implode( ' ', array_filter( $chunks, 'strlen' ) );
	}

	/**
	 * Check whether a HAVING token is an unqualified alias reference.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate alias token position.
	 * @param int             $end      Final HAVING predicate token, exclusive.
	 * @return bool Whether the token can be replaced as an alias.
	 */
	private function is_unqualified_mysql_having_alias_reference( array $tokens, int $position, int $end ): bool {
		if ( isset( $tokens[ $position - 1 ] ) && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position - 1 ]->id ) {
			return false;
		}

		if (
			isset( $tokens[ $position + 1 ] )
			&& (
				WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position + 1 ]->id
				|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position + 1 ]->id
			)
		) {
			return false;
		}

		return $position < $end;
	}

	/**
	 * Get projection replacements needed by grouped archive queries.
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param array           $projection_items        Parsed projection items.
	 * @param array           $archive_date_expression Shared date expression bounds.
	 * @return array<int, array{start: int, end: int, sql: string}> Replacement ranges.
	 */
	private function get_mysql_archive_grouped_projection_replacements( array $tokens, array $projection_items, array $archive_date_expression ): array {
		$replacements = array();

		foreach ( $projection_items as $projection_item ) {
			$bounds = $this->get_mysql_date_format_bounds(
				$tokens,
				$projection_item['expression_start'],
				$projection_item['expression_end']
			);
			if (
				null === $bounds
				|| '%Y-%m-%d' !== $bounds['format']
				|| $bounds['close'] + 1 !== $projection_item['expression_end']
				|| ! $this->are_mysql_token_ranges_equivalent(
					$tokens,
					$archive_date_expression['start'],
					$archive_date_expression['end'],
					$bounds['expression_start'],
					$bounds['expression_end']
				)
			) {
				continue;
			}

			$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$bounds['expression_start'],
				$bounds['expression_end']
			);
			$sql            = $this->get_postgresql_mysql_date_format_sql(
				$bounds['format'],
				sprintf( 'MAX(%s)', $expression_sql )
			);
			if ( null === $sql ) {
				continue;
			}

			$replacements[] = array(
				'start' => $projection_item['expression_start'],
				'end'   => $projection_item['expression_end'],
				'sql'   => $sql,
			);
		}

		return $replacements;
	}

	/**
	 * Check whether DISTINCT is redundant for the supported weekly archive shape.
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param array           $projection_items        Parsed projection items.
	 * @param array           $group_items             Parsed GROUP BY item ranges.
	 * @param array           $archive_date_expression Shared date expression bounds.
	 * @return bool Whether this is the supported weekly archive projection.
	 */
	private function is_mysql_redundant_distinct_week_archive_select_shape(
		array $tokens,
		array $projection_items,
		array $group_items,
		array $archive_date_expression
	): bool {
		if ( 4 !== count( $projection_items ) || 2 !== count( $group_items ) ) {
			return false;
		}

		$expected_aliases = array( 'week', 'yr', 'yyyymmdd', 'posts' );
		foreach ( $expected_aliases as $index => $alias ) {
			if ( strtolower( $projection_items[ $index ]['alias'] ) !== $alias ) {
				return false;
			}
		}

		return $this->is_mysql_week_expression_for_archive_date(
			$tokens,
			$projection_items[0]['expression_start'],
			$projection_items[0]['expression_end'],
			$archive_date_expression
		)
			&& $this->is_mysql_year_expression_for_archive_date(
				$tokens,
				$projection_items[1]['expression_start'],
				$projection_items[1]['expression_end'],
				$archive_date_expression
			)
			&& $this->is_mysql_year_month_day_format_expression_for_archive_date(
				$tokens,
				$projection_items[2]['expression_start'],
				$projection_items[2]['expression_end'],
				$archive_date_expression
			)
			&& $this->is_mysql_count_aggregate_expression(
				$tokens,
				$projection_items[3]['expression_start'],
				$projection_items[3]['expression_end']
			)
			&& $this->do_mysql_group_items_include_week_and_year_for_archive_date(
				$tokens,
				$group_items,
				$archive_date_expression
			);
	}

	/**
	 * Check whether an expression is WEEK(archive_date, 1).
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param int             $start                   First expression token.
	 * @param int             $end                     Final expression token, exclusive.
	 * @param array           $archive_date_expression Shared date expression bounds.
	 * @return bool Whether the expression matches the archive week.
	 */
	private function is_mysql_week_expression_for_archive_date( array $tokens, int $start, int $end, array $archive_date_expression ): bool {
		$expression = $this->get_mysql_week_argument_expression_bounds( $tokens, $start, $end );

		return null !== $expression
			&& $this->are_mysql_token_ranges_equivalent(
				$tokens,
				$archive_date_expression['start'],
				$archive_date_expression['end'],
				$expression['start'],
				$expression['end']
			);
	}

	/**
	 * Check whether an expression is YEAR(archive_date).
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param int             $start                   First expression token.
	 * @param int             $end                     Final expression token, exclusive.
	 * @param array           $archive_date_expression Shared date expression bounds.
	 * @return bool Whether the expression matches the archive year.
	 */
	private function is_mysql_year_expression_for_archive_date( array $tokens, int $start, int $end, array $archive_date_expression ): bool {
		$expression = $this->get_mysql_extract_argument_expression_bounds( $tokens, $start, $end, 'YEAR' );

		return null !== $expression
			&& $this->are_mysql_token_ranges_equivalent(
				$tokens,
				$archive_date_expression['start'],
				$archive_date_expression['end'],
				$expression['start'],
				$expression['end']
			);
	}

	/**
	 * Check whether an expression is DATE_FORMAT(archive_date, '%Y-%m-%d').
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param int             $start                   First expression token.
	 * @param int             $end                     Final expression token, exclusive.
	 * @param array           $archive_date_expression Shared date expression bounds.
	 * @return bool Whether the expression matches the archive date format.
	 */
	private function is_mysql_year_month_day_format_expression_for_archive_date( array $tokens, int $start, int $end, array $archive_date_expression ): bool {
		$bounds = $this->get_mysql_date_format_bounds( $tokens, $start, $end );

		return null !== $bounds
			&& '%Y-%m-%d' === $bounds['format']
			&& $bounds['close'] + 1 === $end
			&& $this->are_mysql_token_ranges_equivalent(
				$tokens,
				$archive_date_expression['start'],
				$archive_date_expression['end'],
				$bounds['expression_start'],
				$bounds['expression_end']
			);
	}

	/**
	 * Check whether GROUP BY contains WEEK(archive_date, 1) and YEAR(archive_date).
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param array           $group_items             Parsed GROUP BY item ranges.
	 * @param array           $archive_date_expression Shared date expression bounds.
	 * @return bool Whether both grouped date keys are present.
	 */
	private function do_mysql_group_items_include_week_and_year_for_archive_date( array $tokens, array $group_items, array $archive_date_expression ): bool {
		$has_week = false;
		$has_year = false;

		foreach ( $group_items as $group_item ) {
			$has_week = $has_week || $this->is_mysql_week_expression_for_archive_date(
				$tokens,
				$group_item['start'],
				$group_item['end'],
				$archive_date_expression
			);
			$has_year = $has_year || $this->is_mysql_year_expression_for_archive_date(
				$tokens,
				$group_item['start'],
				$group_item['end'],
				$archive_date_expression
			);
		}

		return $has_week && $has_year;
	}

	/**
	 * Check whether a projection is exactly one COUNT aggregate.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection token position.
	 * @param int             $end    Final projection token position, exclusive.
	 * @return bool Whether the projection is COUNT-only.
	 */
	private function is_mysql_count_only_projection( array $tokens, int $start, int $end ): bool {
		$ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $ranges || 1 !== count( $ranges ) ) {
			return false;
		}

		$expression_bounds = $this->get_mysql_select_projection_expression_bounds(
			$tokens,
			$ranges[0]['start'],
			$ranges[0]['end']
		);
		if ( null === $expression_bounds ) {
			return false;
		}

		return $this->is_mysql_count_aggregate_expression(
			$tokens,
			$expression_bounds['start'],
			$expression_bounds['end']
		);
	}

	/**
	 * Get expression bounds for a projection item, excluding any alias.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection item token position.
	 * @param int             $end    Final projection item token position, exclusive.
	 * @return array{start: int, end: int}|null Expression bounds, or null when malformed.
	 */
	private function get_mysql_select_projection_expression_bounds( array $tokens, int $start, int $end ): ?array {
		if ( $start >= $end ) {
			return null;
		}

		$expression_end = $end;
		$as_position    = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::AS_SYMBOL, $start, $end );
		if ( null !== $as_position ) {
			if (
				$as_position <= $start
				|| $as_position + 2 !== $end
				|| null === $this->get_mysql_projection_alias_token_value( $tokens[ $as_position + 1 ] ?? null )
			) {
				return null;
			}

			$expression_end = $as_position;
		} else {
			$implicit_alias = $this->get_mysql_implicit_projection_alias( $tokens, $start, $end );
			if ( null !== $implicit_alias ) {
				$expression_end = $end - 1;
			}
		}

		if ( $start >= $expression_end ) {
			return null;
		}

		return array(
			'start' => $start,
			'end'   => $expression_end,
		);
	}

	/**
	 * Check whether an expression is a COUNT aggregate call.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @return bool Whether the expression is COUNT(...).
	 */
	private function is_mysql_count_aggregate_expression( array $tokens, int $start, int $end ): bool {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		return isset( $tokens[ $start ], $tokens[ $start + 1 ] )
			&& $this->is_mysql_token_value( $tokens[ $start ], 'count' )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $start + 1 ]->id
			&& $this->get_mysql_parenthesized_sequence_end( $tokens, $start + 1, $end ) === $end;
	}

	/**
	 * Get the shared post_date expression from archive date grouping.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $group_items Parsed GROUP BY item ranges.
	 * @return array{start: int, end: int}|null Shared post_date expression bounds, or null.
	 */
	private function get_mysql_archive_grouped_date_expression_bounds( array $tokens, array $group_items ): ?array {
		$group_count = count( $group_items );
		if ( 1 > $group_count || 3 < $group_count ) {
			return null;
		}

		$year_expression       = null;
		$week_expression       = null;
		$month_expression      = null;
		$dayofmonth_expression = null;
		$supported_expressions = 0;
		foreach ( $group_items as $group_item ) {
			$expression = $this->get_mysql_extract_argument_expression_bounds(
				$tokens,
				$group_item['start'],
				$group_item['end'],
				'YEAR'
			);
			if ( null !== $expression ) {
				$year_expression = $expression;
				++$supported_expressions;
				continue;
			}

			$expression = $this->get_mysql_week_argument_expression_bounds(
				$tokens,
				$group_item['start'],
				$group_item['end']
			);
			if ( null !== $expression ) {
				$week_expression = $expression;
				++$supported_expressions;
				continue;
			}

			$expression = $this->get_mysql_extract_argument_expression_bounds(
				$tokens,
				$group_item['start'],
				$group_item['end'],
				'MONTH'
			);
			if ( null !== $expression ) {
				$month_expression = $expression;
				++$supported_expressions;
				continue;
			}

			$expression = $this->get_mysql_extract_argument_expression_bounds(
				$tokens,
				$group_item['start'],
				$group_item['end'],
				'DAY'
			);
			if ( null !== $expression ) {
				$dayofmonth_expression = $expression;
				++$supported_expressions;
			}
		}

		if (
			$group_count !== $supported_expressions
			|| null === $year_expression
		) {
			return null;
		}

		if ( null !== $week_expression ) {
			if (
				2 !== $group_count
				|| null !== $month_expression
				|| null !== $dayofmonth_expression
				|| ! $this->are_mysql_token_ranges_equivalent(
					$tokens,
					$year_expression['start'],
					$year_expression['end'],
					$week_expression['start'],
					$week_expression['end']
				)
			) {
				return null;
			}
		} elseif (
			(
				2 <= $group_count
				&& null === $month_expression
			)
			|| (
				3 === $group_count
				&& null === $dayofmonth_expression
			)
			|| (
				null !== $month_expression
				&& ! $this->are_mysql_token_ranges_equivalent(
					$tokens,
					$year_expression['start'],
					$year_expression['end'],
					$month_expression['start'],
					$month_expression['end']
				)
			)
			|| (
				null !== $dayofmonth_expression
				&& ! $this->are_mysql_token_ranges_equivalent(
					$tokens,
					$year_expression['start'],
					$year_expression['end'],
					$dayofmonth_expression['start'],
					$dayofmonth_expression['end']
				)
			)
		) {
			return null;
		}

		if (
			! $this->is_mysql_column_reference_expression(
				$tokens,
				$year_expression['start'],
				$year_expression['end'],
				'post_date',
				'posts',
				true
			)
		) {
			return null;
		}

		return $year_expression;
	}

	/**
	 * Get the argument expression for a supported date/time extract function.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @param string          $unit   Expected date/time unit.
	 * @return array{start: int, end: int}|null Argument bounds, or null.
	 */
	private function get_mysql_extract_argument_expression_bounds( array $tokens, int $start, int $end, string $unit ): ?array {
		$expression_bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$bounds            = $this->get_mysql_extract_function_bounds(
			$tokens,
			$expression_bounds['start'],
			$expression_bounds['end']
		);
		if (
			null === $bounds
			|| $bounds['unit'] !== $unit
			|| $bounds['close'] + 1 !== $expression_bounds['end']
		) {
			return null;
		}

		return array(
			'start' => $bounds['expression_start'],
			'end'   => $bounds['expression_end'],
		);
	}

	/**
	 * Get the argument expression for a supported WEEK() function.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @return array{start: int, end: int}|null Argument bounds, or null.
	 */
	private function get_mysql_week_argument_expression_bounds( array $tokens, int $start, int $end ): ?array {
		$expression_bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$bounds            = $this->get_mysql_week_function_bounds(
			$tokens,
			$expression_bounds['start'],
			$expression_bounds['end']
		);
		if (
			null === $bounds
			|| $bounds['close'] + 1 !== $expression_bounds['end']
		) {
			return null;
		}

		return array(
			'start' => $bounds['expression_start'],
			'end'   => $bounds['expression_end'],
		);
	}

	/**
	 * Check whether ORDER BY references the archive post_date expression.
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param array           $order_item              Parsed ORDER BY item.
	 * @param array           $archive_date_expression Shared date expression bounds.
	 * @return bool Whether the ORDER BY expression is supported.
	 */
	private function is_mysql_archive_post_date_order_expression( array $tokens, array $order_item, array $archive_date_expression ): bool {
		return $this->are_mysql_token_ranges_equivalent(
			$tokens,
			$order_item['expression_start'],
			$order_item['expression_end'],
			$archive_date_expression['start'],
			$archive_date_expression['end']
		) || $this->is_mysql_column_reference_expression(
			$tokens,
			$order_item['expression_start'],
			$order_item['expression_end'],
			'post_date',
			'posts',
			true
		);
	}

	/**
	 * Check whether a SELECT is grouped by the selected comments.comment_ID.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @param array           $group_items      Parsed GROUP BY item ranges.
	 * @return bool Whether this is the supported comment ID grouped shape.
	 */
	private function is_mysql_comment_id_grouped_select_shape( array $tokens, array $projection_items, array $group_items ): bool {
		return 1 === count( $projection_items )
			&& 1 === count( $group_items )
			&& $this->is_mysql_comment_id_expression(
				$tokens,
				$projection_items[0]['expression_start'],
				$projection_items[0]['expression_end']
			)
			&& $this->is_mysql_comment_id_expression(
				$tokens,
				$group_items[0]['start'],
				$group_items[0]['end']
			);
	}

	/**
	 * Check whether an expression references comments.comment_ID.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @return bool Whether the expression is comments.comment_ID.
	 */
	private function is_mysql_comment_id_expression( array $tokens, int $start, int $end ): bool {
		return $this->is_mysql_column_reference_expression( $tokens, $start, $end, 'comment_ID', 'comments', true );
	}

	/**
	 * Check whether a grouped comment ID ORDER BY expression can be aggregated.
	 *
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param array           $order_item Parsed ORDER BY item.
	 * @return bool Whether the ORDER BY expression is supported.
	 */
	private function is_mysql_comment_id_grouped_order_expression( array $tokens, array $order_item ): bool {
		if (
			$this->is_mysql_column_reference_expression(
				$tokens,
				$order_item['expression_start'],
				$order_item['expression_end'],
				'comment_date',
				'comments',
				false
			)
			|| $this->is_mysql_column_reference_expression(
				$tokens,
				$order_item['expression_start'],
				$order_item['expression_end'],
				'comment_date_gmt',
				'comments',
				false
			)
			|| $this->is_mysql_qualified_column_reference_expression(
				$tokens,
				$order_item['expression_start'],
				$order_item['expression_end'],
				'meta_value'
			)
		) {
			return true;
		}

		$cast_bounds = $this->get_mysql_typed_cast_bounds(
			$tokens,
			$order_item['expression_start'],
			$order_item['expression_end'],
			array( 'character' )
		);
		if ( null === $cast_bounds || $cast_bounds['close'] + 1 !== $order_item['expression_end'] ) {
			return false;
		}

		return $this->is_mysql_qualified_column_reference_expression(
			$tokens,
			$cast_bounds['expression_start'],
			$cast_bounds['expression_end'],
			'meta_value'
		);
	}

	/**
	 * Check whether a SELECT is grouped by the selected posts.ID.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @param array           $group_items      Parsed GROUP BY item ranges.
	 * @return bool Whether this is the supported post ID grouped shape.
	 */
	private function is_mysql_post_id_grouped_select_shape( array $tokens, array $projection_items, array $group_items ): bool {
		return 1 === count( $projection_items )
			&& 1 === count( $group_items )
			&& $this->is_mysql_post_id_expression(
				$tokens,
				$projection_items[0]['expression_start'],
				$projection_items[0]['expression_end']
			)
			&& $this->is_mysql_post_id_expression(
				$tokens,
				$group_items[0]['start'],
				$group_items[0]['end']
			);
	}

	/**
	 * Check whether an expression references posts.ID.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @return bool Whether the expression is posts.ID.
	 */
	private function is_mysql_post_id_expression( array $tokens, int $start, int $end ): bool {
		return $this->is_mysql_column_reference_expression( $tokens, $start, $end, 'ID', 'posts', true );
	}

	/**
	 * Check whether a grouped post ID ORDER BY expression can be aggregated.
	 *
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param array           $order_item Parsed ORDER BY item.
	 * @return bool Whether the ORDER BY expression is supported.
	 */
	private function is_mysql_post_id_grouped_order_expression( array $tokens, array $order_item ): bool {
		if (
			$this->is_mysql_column_reference_expression(
				$tokens,
				$order_item['expression_start'],
				$order_item['expression_end'],
				'post_date',
				'posts',
				false
			)
			|| $this->is_mysql_column_reference_expression(
				$tokens,
				$order_item['expression_start'],
				$order_item['expression_end'],
				'post_date_gmt',
				'posts',
				false
			)
			|| $this->is_mysql_qualified_column_reference_expression(
				$tokens,
				$order_item['expression_start'],
				$order_item['expression_end'],
				'meta_value'
			)
		) {
			return true;
		}

		return $this->is_mysql_meta_value_cast_expression(
			$tokens,
			$order_item['expression_start'],
			$order_item['expression_end']
		) || $this->is_mysql_meta_value_plus_zero_expression(
			$tokens,
			$order_item['expression_start'],
			$order_item['expression_end']
		);
	}

	/**
	 * Check whether an expression is a supported metadata value CAST.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @return bool Whether the expression casts a qualified meta_value reference.
	 */
	private function is_mysql_meta_value_cast_expression( array $tokens, int $start, int $end ): bool {
		$cast_bounds = $this->get_mysql_typed_cast_bounds(
			$tokens,
			$start,
			$end,
			array( 'character', 'integer', 'decimal', 'date_time' )
		);

		return null !== $cast_bounds
			&& $cast_bounds['close'] + 1 === $end
			&& $this->is_mysql_qualified_column_reference_expression(
				$tokens,
				$cast_bounds['expression_start'],
				$cast_bounds['expression_end'],
				'meta_value'
			);
	}

	/**
	 * Check whether an expression is metadata value plus zero numeric ordering.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @return bool Whether the expression numerically orders meta_value.
	 */
	private function is_mysql_meta_value_plus_zero_expression( array $tokens, int $start, int $end ): bool {
		$reference = $this->parse_mysql_column_reference( $tokens, $start, $end );
		if (
			null !== $reference
			&& null !== $reference['qualifier']
			&& isset( $tokens[ $reference['end'] ] )
			&& WP_MySQL_Lexer::PLUS_OPERATOR === $tokens[ $reference['end'] ]->id
		) {
			$literal = $this->parse_mysql_numeric_literal( $tokens, $reference['end'] + 1, $end );
			return null !== $literal
				&& $literal['end'] === $end
				&& $this->is_mysql_zero_numeric_literal_range( $tokens, $literal['start'], $literal['end'] )
				&& $this->is_mysql_qualified_column_reference_expression( $tokens, $start, $reference['end'], 'meta_value' );
		}

		$literal = $this->parse_mysql_numeric_literal( $tokens, $start, $end );
		if (
			null === $literal
			|| ! $this->is_mysql_zero_numeric_literal_range( $tokens, $literal['start'], $literal['end'] )
			|| ! isset( $tokens[ $literal['end'] ] )
			|| WP_MySQL_Lexer::PLUS_OPERATOR !== $tokens[ $literal['end'] ]->id
		) {
			return false;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $literal['end'] + 1, $end );
		return null !== $reference
			&& $reference['end'] === $end
			&& null !== $reference['qualifier']
			&& $this->is_mysql_qualified_column_reference_expression( $tokens, $reference['start'], $reference['end'], 'meta_value' );
	}

	/**
	 * Check whether an ORDER BY expression is already valid for the GROUP BY.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $order_item  Parsed ORDER BY item.
	 * @param array           $group_items Parsed GROUP BY item ranges.
	 * @return bool Whether the expression is grouped.
	 */
	private function is_mysql_grouped_order_expression( array $tokens, array $order_item, array $group_items ): bool {
		foreach ( $group_items as $group_item ) {
			if (
				$this->are_mysql_token_ranges_equivalent(
					$tokens,
					$order_item['expression_start'],
					$order_item['expression_end'],
					$group_item['start'],
					$group_item['end']
				)
			) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Build an aggregate-safe ORDER BY item for grouped SELECTs.
	 *
	 * @param array $order_item Parsed ORDER BY item.
	 * @return string PostgreSQL ORDER BY item SQL.
	 */
	private function get_strict_grouped_aggregate_order_sql( array $order_item ): string {
		$aggregate_function = 'DESC' === $order_item['direction'] ? 'MAX' : 'MIN';

		return sprintf(
			'%s(%s) %s',
			$aggregate_function,
			$order_item['sql'],
			$order_item['direction']
		);
	}

	/**
	 * Get the MySQL-compatible ID tie-breaker for grouped posts date ordering.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $order_items      Parsed ORDER BY items.
	 * @param array           $group_items      Parsed GROUP BY item ranges.
	 * @param bool            $is_post_id_group Whether the query groups by posts.ID.
	 * @return string|null PostgreSQL ORDER BY item SQL, or null when not applicable.
	 */
	private function get_strict_grouped_posts_post_date_desc_order_id_tiebreaker_sql(
		array $tokens,
		array $order_items,
		array $group_items,
		bool $is_post_id_group
	): ?string {
		if (
			! $is_post_id_group
			|| 1 !== count( $order_items )
			|| 1 !== count( $group_items )
			|| 'DESC' !== $order_items[0]['direction']
			|| ! $this->is_mysql_column_reference_expression(
				$tokens,
				$order_items[0]['expression_start'],
				$order_items[0]['expression_end'],
				'post_date',
				'posts',
				false
			)
		) {
			return null;
		}

		return $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$group_items[0]['start'],
			$group_items[0]['end']
		) . ' DESC';
	}

	/**
	 * Check whether an expression is a supported column reference.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int             $start            First expression token.
	 * @param int             $end              Final expression token, exclusive.
	 * @param string          $column_name      Expected column name.
	 * @param string|null     $qualifier_suffix Optional table-name suffix for qualified references.
	 * @param bool            $allow_bare       Whether unqualified references are allowed.
	 * @return bool Whether the expression is a supported column reference.
	 */
	private function is_mysql_column_reference_expression(
		array $tokens,
		int $start,
		int $end,
		string $column_name,
		?string $qualifier_suffix,
		bool $allow_bare
	): bool {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		if ( $allow_bare && $start + 1 === $end ) {
			$identifier = $this->get_mysql_identifier_token_value( $tokens[ $start ] ?? null );
			return null !== $identifier && strtolower( $identifier ) === strtolower( $column_name );
		}

		if (
			$start + 3 !== $end
			|| ! isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ] )
			|| WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $start + 1 ]->id
		) {
			return false;
		}

		$qualifier = $this->get_mysql_identifier_token_value( $tokens[ $start ] );
		$column    = $this->get_mysql_identifier_token_value( $tokens[ $start + 2 ] );
		if ( null === $qualifier || null === $column || strtolower( $column ) !== strtolower( $column_name ) ) {
			return false;
		}

		return null === $qualifier_suffix
			|| strtolower( $qualifier ) === strtolower( $qualifier_suffix )
			|| '_' . strtolower( $qualifier_suffix ) === substr( strtolower( $qualifier ), -1 * ( strlen( $qualifier_suffix ) + 1 ) );
	}

	/**
	 * Check whether an expression is a qualified column reference.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param int             $start       First expression token.
	 * @param int             $end         Final expression token, exclusive.
	 * @param string          $column_name Expected column name.
	 * @return bool Whether the expression is a qualified column reference.
	 */
	private function is_mysql_qualified_column_reference_expression( array $tokens, int $start, int $end, string $column_name ): bool {
		return $this->is_mysql_column_reference_expression( $tokens, $start, $end, $column_name, null, false );
	}

	/**
	 * Check whether two expression token ranges are structurally equivalent.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param int             $left_start  First left expression token.
	 * @param int             $left_end    Final left expression token, exclusive.
	 * @param int             $right_start First right expression token.
	 * @param int             $right_end   Final right expression token, exclusive.
	 * @return bool Whether the token ranges are equivalent.
	 */
	private function are_mysql_token_ranges_equivalent(
		array $tokens,
		int $left_start,
		int $left_end,
		int $right_start,
		int $right_end
	): bool {
		$left_bounds  = $this->normalize_mysql_expression_bounds( $tokens, $left_start, $left_end );
		$right_bounds = $this->normalize_mysql_expression_bounds( $tokens, $right_start, $right_end );

		$left_start  = $left_bounds['start'];
		$left_end    = $left_bounds['end'];
		$right_start = $right_bounds['start'];
		$right_end   = $right_bounds['end'];

		if ( $left_end - $left_start !== $right_end - $right_start ) {
			return false;
		}

		for ( $left = $left_start, $right = $right_start; $left < $left_end; $left++, $right++ ) {
			if ( ! $this->are_mysql_tokens_equivalent( $tokens[ $left ], $tokens[ $right ] ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Normalize expression bounds by removing full-range wrapper parentheses.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @return array{start: int, end: int} Normalized bounds.
	 */
	private function normalize_mysql_expression_bounds( array $tokens, int $start, int $end ): array {
		while (
			$start + 2 <= $end
			&& isset( $tokens[ $start ] )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $start ]->id
			&& $this->get_mysql_parenthesized_sequence_end( $tokens, $start, $end ) === $end
		) {
			++$start;
			--$end;
		}

		return array(
			'start' => $start,
			'end'   => $end,
		);
	}

	/**
	 * Check whether two individual MySQL tokens are structurally equivalent.
	 *
	 * @param WP_MySQL_Token $left  Left token.
	 * @param WP_MySQL_Token $right Right token.
	 * @return bool Whether the tokens are equivalent.
	 */
	private function are_mysql_tokens_equivalent( WP_MySQL_Token $left, WP_MySQL_Token $right ): bool {
		$left_identifier  = $this->get_mysql_identifier_token_value( $left );
		$right_identifier = $this->get_mysql_identifier_token_value( $right );
		if ( null !== $left_identifier || null !== $right_identifier ) {
			return null !== $left_identifier
				&& null !== $right_identifier
				&& strtolower( $left_identifier ) === strtolower( $right_identifier );
		}

		if ( $left->id !== $right->id ) {
			return false;
		}

		if ( WP_MySQL_Lexer::SINGLE_QUOTED_TEXT === $left->id || WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $left->id ) {
			return $left->get_value() === $right->get_value();
		}

		return strtolower( $left->get_bytes() ) === strtolower( $right->get_bytes() );
	}

	/**
	 * Check whether a SELECT query uses the MySQL SQL_CALC_FOUND_ROWS modifier.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the query asks for FOUND_ROWS tracking.
	 */
	private function is_sql_calc_found_rows_select_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0], $tokens[1] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return false;
		}

		if ( null === $this->get_mysql_statement_end_position( $tokens, 1 ) ) {
			return false;
		}

		if ( WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL === $tokens[1]->id ) {
			return true;
		}

		return isset( $tokens[2] )
			&& WP_MySQL_Lexer::DISTINCT_SYMBOL === $tokens[1]->id
			&& WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL === $tokens[2]->id;
	}

	/**
	 * Translate WordPress SELECT SQL_CALC_FOUND_ROWS queries.
	 *
	 * PostgreSQL has no SQL_CALC_FOUND_ROWS modifier. WordPress issues these
	 * queries for pagination, followed by SELECT FOUND_ROWS(); this first pass
	 * executes the paginated query itself while preserving compatible clauses.
	 *
	 * @param string $query MySQL query.
	 * @param bool   $include_limit Whether to preserve the LIMIT/OFFSET clause.
	 * @return string|null PostgreSQL query, or null when the query is unsupported.
	 */
	private function translate_sql_calc_found_rows_select_query( string $query, bool $include_limit = true ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL !== $tokens[1]->id
		) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 2 );
		if ( null === $statement_end ) {
			return null;
		}

		$select_end     = $statement_end;
		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, 2, $statement_end );
		if ( null !== $limit_position ) {
			if ( ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $statement_end ) ) {
				return null;
			}
			$select_end = $limit_position;
		}

		$contextual_sql = $this->translate_mysql_select_statement_with_integer_string_coercion(
			$tokens,
			2,
			$select_end,
			false
		);
		if ( null !== $contextual_sql ) {
			if ( $include_limit && null !== $limit_position ) {
				$contextual_sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
			}

			return $contextual_sql;
		}

		$sql = 'SELECT ' . $this->translate_mysql_token_sequence_to_postgresql( $tokens, 2, $select_end );
		if ( $include_limit && null !== $limit_position ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
		}

		return $sql;
	}

	/**
	 * Apply conservative MySQL-to-PostgreSQL token compatibility rewrites.
	 *
	 * Complex WordPress queries often use PostgreSQL-compatible SQL except for
	 * MySQL identifier casing. This fallback quotes backticked and mixed-case
	 * identifiers without trying to emulate unsupported MySQL-only syntax.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when no compatibility rewrite applies.
	 */
	private function translate_mysql_compatible_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) ) {
			return null;
		}

		if (
			! in_array(
				$tokens[0]->id,
				array(
					WP_MySQL_Lexer::DELETE_SYMBOL,
					WP_MySQL_Lexer::INSERT_SYMBOL,
					WP_MySQL_Lexer::REPLACE_SYMBOL,
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::UPDATE_SYMBOL,
				),
				true
			)
		) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		if ( WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[0]->id ) {
			$contextual_sql = $this->translate_mysql_select_statement_with_integer_string_coercion(
				$tokens,
				1,
				$statement_end,
				true
			);
			if ( null !== $contextual_sql ) {
				return $contextual_sql;
			}

			$contextual_sql = $this->translate_mysql_count_aggregate_projection_alias_query(
				$tokens,
				1,
				$statement_end
			);
			if ( null !== $contextual_sql ) {
				return $contextual_sql;
			}
		}

		if ( $this->contains_unsupported_mysql_date_arithmetic_function( $tokens, 0, $statement_end ) ) {
			return null;
		}

		if ( $this->contains_unsupported_mysql_date_format_function( $tokens, 0, $statement_end ) ) {
			return null;
		}

		if ( $this->contains_unsupported_mysql_rand_function( $tokens, 0, $statement_end ) ) {
			return null;
		}

		if ( $this->contains_unsupported_mysql_week_function( $tokens, 0, $statement_end ) ) {
			return null;
		}

		if ( $this->contains_unsupported_mysql_convert_function( $tokens, 0, $statement_end ) ) {
			return null;
		}

		if ( $this->contains_unsupported_mysql_common_function( $tokens, 0, $statement_end ) ) {
			return null;
		}

		if ( ! $this->needs_mysql_compatible_rewrite( $tokens, 0, $statement_end ) ) {
			return null;
		}

		return $this->translate_mysql_token_sequence_to_postgresql( $tokens, 0, $statement_end );
	}

	/**
	 * Check whether a query must fail closed while information_schema is selected.
	 *
	 * The PostgreSQL backend does not use MySQL database state for unqualified
	 * names. Without broad information_schema routing, table-scoped statements
	 * under USE information_schema would otherwise target public tables.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the query should be rejected before backend execution.
	 */
	private function should_reject_information_schema_backend_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) ) {
			return false;
		}

		if ( WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[0]->id ) {
			$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
			if ( null !== $statement_end ) {
				if ( null !== $this->translate_direct_information_schema_select_query( $query ) ) {
					return false;
				}

				if ( $this->select_references_direct_information_schema_relation( $tokens, 1, $statement_end ) ) {
					return true;
				}

				if ( $this->information_schema_select_query_targets_main_database_explicitly( $query, $tokens, $statement_end ) ) {
					return false;
				}
			}

			return 0 === strcasecmp( $this->db_name, 'information_schema' )
				&& $this->information_schema_select_has_table_reference( $tokens );
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if (
			null !== $statement_end
			&& WP_MySQL_Lexer::INSERT_SYMBOL === $tokens[0]->id
			&& $this->select_references_direct_information_schema_relation( $tokens, 1, $statement_end )
		) {
			if ( null !== $this->translate_simple_mysql_insert_select_query( $query ) ) {
				return false;
			}

			return true;
		}

		if ( 0 !== strcasecmp( $this->db_name, 'information_schema' ) ) {
			return false;
		}

		if (
			WP_MySQL_Lexer::DESCRIBE_SYMBOL === $tokens[0]->id
			|| WP_MySQL_Lexer::DESC_SYMBOL === $tokens[0]->id
		) {
			$position        = 1;
			$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
			if (
				null !== $table_reference
				&& $this->is_at_mysql_query_end( $tokens, $position )
				&& $this->is_explicit_main_database_table_reference( $table_reference )
			) {
				return false;
			}

			if (
				null !== $table_reference
				&& $this->is_at_mysql_query_end( $tokens, $position )
				&& (
					null === $table_reference['schema']
					|| 0 === strcasecmp( $table_reference['schema'], 'information_schema' )
				)
				&& null !== $this->get_direct_information_schema_relation_columns( $table_reference['table'] )
			) {
				return false;
			}
		}

		if (
			in_array(
				$tokens[0]->id,
				array(
					WP_MySQL_Lexer::EXPLAIN_SYMBOL,
					WP_MySQL_Lexer::WITH_SYMBOL,
				),
				true
			)
		) {
			return true;
		}

		if ( $this->information_schema_write_query_targets_main_database_explicitly( $query, $tokens ) ) {
			return false;
		}

		return in_array(
			$tokens[0]->id,
			array(
				WP_MySQL_Lexer::ALTER_SYMBOL,
				WP_MySQL_Lexer::ANALYZE_SYMBOL,
				WP_MySQL_Lexer::CHECK_SYMBOL,
				WP_MySQL_Lexer::CREATE_SYMBOL,
				WP_MySQL_Lexer::DESCRIBE_SYMBOL,
				WP_MySQL_Lexer::DELETE_SYMBOL,
				WP_MySQL_Lexer::DESC_SYMBOL,
				WP_MySQL_Lexer::DROP_SYMBOL,
				WP_MySQL_Lexer::INSERT_SYMBOL,
				WP_MySQL_Lexer::LOCK_SYMBOL,
				WP_MySQL_Lexer::OPTIMIZE_SYMBOL,
				WP_MySQL_Lexer::REPLACE_SYMBOL,
				WP_MySQL_Lexer::REPAIR_SYMBOL,
				WP_MySQL_Lexer::TRUNCATE_SYMBOL,
				WP_MySQL_Lexer::UPDATE_SYMBOL,
			),
			true
		);
	}

	/**
	 * Check whether a write/admin query under USE information_schema explicitly targets the main database.
	 *
	 * Unqualified write targets should continue to resolve as information_schema
	 * while that database is selected. Explicit main-database or public targets
	 * can safely continue into the existing PostgreSQL translators.
	 *
	 * @param string           $query  MySQL query.
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @return bool Whether the guarded query targets only the main database explicitly.
	 */
	private function information_schema_write_query_targets_main_database_explicitly( string $query, array $tokens ): bool {
		if ( ! isset( $tokens[0] ) ) {
			return false;
		}

		if ( WP_MySQL_Lexer::INSERT_SYMBOL === $tokens[0]->id || WP_MySQL_Lexer::REPLACE_SYMBOL === $tokens[0]->id ) {
			return $this->insert_or_replace_query_targets_main_database_explicitly(
				$tokens,
				WP_MySQL_Lexer::INSERT_SYMBOL === $tokens[0]->id
			);
		}

		$token_methods = array(
			WP_MySQL_Lexer::UPDATE_SYMBOL   => 'simple_update_query_targets_main_database_explicitly',
			WP_MySQL_Lexer::DELETE_SYMBOL   => 'simple_delete_query_targets_main_database_explicitly',
			WP_MySQL_Lexer::TRUNCATE_SYMBOL => 'truncate_query_targets_main_database_explicitly',
			WP_MySQL_Lexer::CREATE_SYMBOL   => 'create_query_targets_main_database_explicitly',
			WP_MySQL_Lexer::ALTER_SYMBOL    => 'alter_table_query_targets_main_database_explicitly',
			WP_MySQL_Lexer::DROP_SYMBOL     => 'drop_query_targets_main_database_explicitly',
		);
		if ( isset( $token_methods[ $tokens[0]->id ] ) ) {
			return $this->{$token_methods[ $tokens[0]->id ]}( $tokens );
		}

		if ( in_array( $tokens[0]->id, array( WP_MySQL_Lexer::ANALYZE_SYMBOL, WP_MySQL_Lexer::CHECK_SYMBOL, WP_MySQL_Lexer::OPTIMIZE_SYMBOL, WP_MySQL_Lexer::REPAIR_SYMBOL ), true ) ) {
			return $this->table_administration_query_targets_main_database_explicitly( $query );
		}

		return WP_MySQL_Lexer::LOCK_SYMBOL === $tokens[0]->id
			&& $this->lock_tables_query_targets_main_database_explicitly( $query );
	}

	/**
	 * Check whether a parsed table reference explicitly names the main database.
	 *
	 * @param array{schema: string|null, table: string}|null $table_reference Parsed table reference.
	 * @return bool Whether the reference is explicitly main-database qualified.
	 */
	private function is_explicit_main_database_table_reference( ?array $table_reference ): bool {
		if ( null === $table_reference || null === $table_reference['schema'] ) {
			return false;
		}

		return 0 === strcasecmp( $table_reference['schema'], $this->main_db_name )
			|| 0 === strcasecmp( $table_reference['schema'], 'public' );
	}

	/**
	 * Check whether an INSERT/REPLACE query explicitly targets the main database.
	 *
	 * @param WP_MySQL_Token[] $tokens    MySQL lexer token stream.
	 * @param bool             $is_insert Whether the query is INSERT.
	 * @return bool Whether the target table is explicitly main-database qualified.
	 */
	private function insert_or_replace_query_targets_main_database_explicitly( array $tokens, bool $is_insert ): bool {
		$position = 1;
		if ( $is_insert ) {
			$this->consume_mysql_insert_priority_modifier( $tokens, $position );
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::IGNORE_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
			}
		} else {
			$this->consume_mysql_replace_priority_modifier( $tokens, $position );
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::INTO_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
		return $this->is_explicit_main_database_table_reference( $table_reference );
	}

	/**
	 * Check whether a simple UPDATE query explicitly targets the main database.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @return bool Whether the target table is explicitly main-database qualified.
	 */
	private function simple_update_query_targets_main_database_explicitly( array $tokens ): bool {
		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return false;
		}

		$position = 1;
		$this->consume_mysql_update_modifiers( $tokens, $position, $statement_end );
		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
		if ( ! $this->is_explicit_main_database_table_reference( $table_reference ) ) {
			return false;
		}

		return $this->consume_optional_simple_table_alias( $tokens, $position, $statement_end )
			&& isset( $tokens[ $position ] )
			&& WP_MySQL_Lexer::SET_SYMBOL === $tokens[ $position ]->id;
	}

	/**
	 * Check whether a simple DELETE query explicitly targets the main database.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @return bool Whether the target table is explicitly main-database qualified.
	 */
	private function simple_delete_query_targets_main_database_explicitly( array $tokens ): bool {
		$position = 1;
		$this->consume_mysql_delete_modifiers( $tokens, $position );
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::FROM_SYMBOL !== $tokens[ $position ]->id ) {
			return false;
		}

		++$position;
		$statement_end = $this->get_mysql_statement_end_position( $tokens, $position );
		if ( null === $statement_end ) {
			return false;
		}

		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
		return $this->is_explicit_main_database_table_reference( $table_reference )
			&& $this->consume_optional_simple_table_alias( $tokens, $position, $statement_end );
	}

	/**
	 * Consume a simple table alias when present.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $position      Current token position, updated when an alias is consumed.
	 * @param int              $statement_end Final statement token, exclusive.
	 * @return bool Whether the alias shape is valid.
	 */
	private function consume_optional_simple_table_alias( array $tokens, int &$position, int $statement_end ): bool {
		if ( $position + 1 < $statement_end && WP_MySQL_Lexer::AS_SYMBOL === ( $tokens[ $position ]->id ?? null ) ) {
			if ( null === $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null ) ) {
				return false;
			}

			$position += 2;
			return true;
		}

		$implicit_alias = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null !== $implicit_alias ) {
			++$position;
		}

		return true;
	}

	/**
	 * Check whether a TRUNCATE query explicitly targets the main database.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @return bool Whether the target table is explicitly main-database qualified.
	 */
	private function truncate_query_targets_main_database_explicitly( array $tokens ): bool {
		$position = 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::TABLE_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
		return $this->is_explicit_main_database_table_reference( $table_reference );
	}

	/**
	 * Check whether a CREATE query explicitly targets the main database.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @return bool Whether the target table is explicitly main-database qualified.
	 */
	private function create_query_targets_main_database_explicitly( array $tokens ): bool {
		$position = 1;
		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::OR_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::REPLACE_SYMBOL === $tokens[ $position + 1 ]->id
		) {
			$position += 2;
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::TEMPORARY_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::VIEW_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
			$view_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
			return $this->is_explicit_main_database_table_reference( $view_reference );
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::TABLE_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
			if (
				isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
				&& WP_MySQL_Lexer::IF_SYMBOL === $tokens[ $position ]->id
				&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $position + 1 ]->id
				&& WP_MySQL_Lexer::EXISTS_SYMBOL === $tokens[ $position + 2 ]->id
			) {
				$position += 3;
			}

			$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
			return $this->is_explicit_main_database_table_reference( $table_reference );
		}

		while (
			isset( $tokens[ $position ] )
			&& in_array(
				$tokens[ $position ]->id,
				array(
					WP_MySQL_Lexer::UNIQUE_SYMBOL,
					WP_MySQL_Lexer::FULLTEXT_SYMBOL,
					WP_MySQL_Lexer::SPATIAL_SYMBOL,
				),
				true
			)
		) {
			++$position;
		}

		if (
			! isset( $tokens[ $position ] )
			|| WP_MySQL_Lexer::INDEX_SYMBOL !== $tokens[ $position ]->id
		) {
			return false;
		}

		++$position;
		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
			&& WP_MySQL_Lexer::IF_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $position + 1 ]->id
			&& WP_MySQL_Lexer::EXISTS_SYMBOL === $tokens[ $position + 2 ]->id
		) {
			$position += 3;
		}

		if ( null === $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null, true ) ) {
			return false;
		}
		++$position;

		while (
			isset( $tokens[ $position ] )
			&& in_array( $tokens[ $position ]->id, array( WP_MySQL_Lexer::USING_SYMBOL, WP_MySQL_Lexer::TYPE_SYMBOL ), true )
		) {
			$position += 2;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::ON_SYMBOL !== $tokens[ $position ]->id ) {
			return false;
		}

		++$position;
		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position, true );
		return $this->is_explicit_main_database_table_reference( $table_reference );
	}

	/**
	 * Check whether an ALTER TABLE query explicitly targets the main database.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @return bool Whether the target table is explicitly main-database qualified.
	 */
	private function alter_table_query_targets_main_database_explicitly( array $tokens ): bool {
		if ( isset( $tokens[1] ) && WP_MySQL_Lexer::VIEW_SYMBOL === $tokens[1]->id ) {
			$position       = 2;
			$view_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
			return $this->is_explicit_main_database_table_reference( $view_reference );
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null !== $statement_end && $this->contains_mysql_unsupported_view_prefix_clause( $tokens, 1, $statement_end ) ) {
			for ( $position = 1; $position < $statement_end; $position++ ) {
				if ( WP_MySQL_Lexer::VIEW_SYMBOL !== $tokens[ $position ]->id ) {
					continue;
				}

				++$position;
				$view_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
				return $this->is_explicit_main_database_table_reference( $view_reference );
			}
		}

		if ( ! isset( $tokens[1] ) || WP_MySQL_Lexer::TABLE_SYMBOL !== $tokens[1]->id ) {
			return false;
		}

		$position        = 2;
		$table_reference = $this->get_mysql_dbdelta_alter_table_target_reference( $tokens, $position );
		return $this->is_explicit_main_database_table_reference( $table_reference );
	}

	/**
	 * Check whether a DROP query explicitly targets the main database.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @return bool Whether all target tables are explicitly main-database qualified.
	 */
	private function drop_query_targets_main_database_explicitly( array $tokens ): bool {
		if (
			isset( $tokens[1] )
			&& in_array( $tokens[1]->id, array( WP_MySQL_Lexer::TABLE_SYMBOL, WP_MySQL_Lexer::VIEW_SYMBOL ), true )
		) {
			$statement_end = $this->get_mysql_statement_end_position( $tokens, 2 );
			if ( null === $statement_end ) {
				return false;
			}

			$position = 2;
			if (
				isset( $tokens[ $position ], $tokens[ $position + 1 ] )
				&& WP_MySQL_Lexer::IF_SYMBOL === $tokens[ $position ]->id
				&& WP_MySQL_Lexer::EXISTS_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				$position += 2;
			}

			$matched = false;
			while ( $position < $statement_end ) {
				$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
				if ( ! $this->is_explicit_main_database_table_reference( $table_reference ) ) {
					return false;
				}

				$matched = true;
				if ( $position === $statement_end ) {
					break;
				}

				if (
					WP_MySQL_Lexer::VIEW_SYMBOL === $tokens[1]->id
					&& isset( $tokens[ $position ] )
					&& in_array( $tokens[ $position ]->id, array( WP_MySQL_Lexer::CASCADE_SYMBOL, WP_MySQL_Lexer::RESTRICT_SYMBOL ), true )
				) {
					++$position;
					return $position === $statement_end;
				}

				if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::COMMA_SYMBOL !== $tokens[ $position ]->id ) {
					return false;
				}
				++$position;
			}

			return $matched;
		}

		if ( ! isset( $tokens[1] ) || WP_MySQL_Lexer::INDEX_SYMBOL !== $tokens[1]->id ) {
			return false;
		}

		$position = 2;
		if ( null === $this->get_mysql_index_identifier_token_value( $tokens[ $position ] ?? null ) ) {
			return false;
		}
		++$position;

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::ON_SYMBOL !== $tokens[ $position ]->id ) {
			return false;
		}

		++$position;
		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
		return $this->is_explicit_main_database_table_reference( $table_reference );
	}

	/**
	 * Check whether table administration targets explicitly name the main database.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether all target tables are explicitly main-database qualified.
	 */
	private function table_administration_query_targets_main_database_explicitly( string $query ): bool {
		try {
			$table_administration_query = $this->get_mysql_table_administration_query( $query );
		} catch ( InvalidArgumentException $e ) {
			return false;
		}

		foreach ( $table_administration_query['tables'] ?? array() as $table_reference ) {
			if ( ! $this->is_explicit_main_database_table_reference( $table_reference ) ) {
				return false;
			}
		}

		return ! empty( $table_administration_query['tables'] );
	}

	/**
	 * Check whether LOCK TABLE targets explicitly name the main database.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether all lock targets are explicitly main-database qualified.
	 */
	private function lock_tables_query_targets_main_database_explicitly( string $query ): bool {
		try {
			$lock_tables_query = $this->get_mysql_lock_tables_query( $query );
		} catch ( InvalidArgumentException $e ) {
			return false;
		}

		if ( null === $lock_tables_query || 'lock' !== ( $lock_tables_query['operation'] ?? null ) ) {
			return false;
		}

		foreach ( $lock_tables_query['tables'] ?? array() as $table_reference ) {
			if ( ! $this->is_explicit_main_database_table_reference( $table_reference ) ) {
				return false;
			}
		}

		return ! empty( $lock_tables_query['tables'] );
	}

	/**
	 * Translate SELECTs that explicitly target only main-database tables while information_schema is selected.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_information_schema_main_database_select_query( string $query ): ?string {
		if ( 0 !== strcasecmp( $this->db_name, 'information_schema' ) ) {
			return null;
		}

		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		if (
			$this->select_references_direct_information_schema_relation( $tokens, 1, $statement_end )
			|| $this->contains_top_level_mysql_token(
				$tokens,
				1,
				$statement_end,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::INTO_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		if (
			$this->contains_unsupported_mysql_date_arithmetic_function( $tokens, 0, $statement_end )
			|| $this->contains_unsupported_mysql_date_format_function( $tokens, 0, $statement_end )
			|| $this->contains_unsupported_mysql_rand_function( $tokens, 0, $statement_end )
			|| $this->contains_unsupported_mysql_week_function( $tokens, 0, $statement_end )
			|| $this->contains_unsupported_mysql_convert_function( $tokens, 0, $statement_end )
			|| $this->contains_unsupported_mysql_common_function( $tokens, 0, $statement_end )
			|| $this->contains_unsupported_mysql_group_concat_function( $tokens, 0, $statement_end )
		) {
			return null;
		}

		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, 1, $statement_end );
		if ( null === $from_position ) {
			$nested_select_replacements = $this->get_information_schema_main_database_nested_select_replacements(
				$query,
				$tokens,
				array(
					array(
						'start' => 1,
						'end'   => $statement_end,
					),
				)
			);
			if (
				null === $nested_select_replacements
				|| array() === $nested_select_replacements
				|| ! $this->direct_information_schema_nested_selects_are_covered( $tokens, 1, $statement_end, $nested_select_replacements )
			) {
				return null;
			}

			return 'SELECT ' . $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
				$tokens,
				1,
				$statement_end,
				$nested_select_replacements
			);
		}

		if ( 1 === $from_position ) {
			return null;
		}

		$from_end = $this->find_first_top_level_mysql_token(
			$tokens,
			array(
				WP_MySQL_Lexer::FOR_SYMBOL,
				WP_MySQL_Lexer::GROUP_SYMBOL,
				WP_MySQL_Lexer::HAVING_SYMBOL,
				WP_MySQL_Lexer::LIMIT_SYMBOL,
				WP_MySQL_Lexer::LOCK_SYMBOL,
				WP_MySQL_Lexer::ORDER_SYMBOL,
				WP_MySQL_Lexer::PROCEDURE_SYMBOL,
				WP_MySQL_Lexer::UNION_SYMBOL,
				WP_MySQL_Lexer::WHERE_SYMBOL,
			),
			$from_position + 1,
			$statement_end
		) ?? $statement_end;

		$replacements = $this->get_information_schema_main_database_select_table_replacements(
			$query,
			$tokens,
			$from_position + 1,
			$from_end
		);
		if ( null === $replacements ) {
			return null;
		}

		$nested_select_ranges = array(
			array(
				'start' => 1,
				'end'   => $from_position,
			),
		);
		$clause_starts        = array_filter(
			array(
				$this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $from_end, $statement_end ),
				$this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::GROUP_SYMBOL, $from_end, $statement_end ),
				$this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::HAVING_SYMBOL, $from_end, $statement_end ),
				$this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, $from_end, $statement_end ),
				$this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, $from_end, $statement_end ),
			),
			'is_int'
		);
		sort( $clause_starts );
		foreach ( $clause_starts as $index => $start ) {
			$nested_select_ranges[] = array(
				'start' => $start,
				'end'   => $clause_starts[ $index + 1 ] ?? $statement_end,
			);
		}

		$nested_select_replacements = $this->get_information_schema_main_database_nested_select_replacements(
			$query,
			$tokens,
			$nested_select_ranges
		);
		if ( null === $nested_select_replacements ) {
			return null;
		}

		$replacements = array_merge( $replacements, $nested_select_replacements );
		usort(
			$replacements,
			static function ( array $left, array $right ): int {
				return $left['start'] <=> $right['start'];
			}
		);

		if ( ! $this->direct_information_schema_nested_selects_are_covered( $tokens, 1, $statement_end, $replacements ) ) {
			return null;
		}

		return $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
			$tokens,
			0,
			$statement_end,
			$replacements
		);
	}

	/**
	 * Get replacement ranges for explicitly main-database-qualified SELECT table sources.
	 *
	 * @param string           $query  Original MySQL query.
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First FROM-clause token after FROM.
	 * @param int             $end    Final FROM-clause token, exclusive.
	 * @return array[]|null Replacement ranges, or null when the source list is unsupported.
	 */
	private function get_information_schema_main_database_select_table_replacements( string $query, array $tokens, int $start, int $end ): ?array {
		$position     = $start;
		$expect_next  = true;
		$replacements = array();

		while ( $position < $end ) {
			if ( $expect_next ) {
				if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
					$derived_replacement = $this->get_information_schema_main_database_derived_select_replacement(
						$query,
						$tokens,
						$position,
						$end
					);
					if ( null === $derived_replacement ) {
						return null;
					}

					$replacements[] = $derived_replacement['replacement'];
					$position       = $derived_replacement['position'];
					$expect_next    = false;
					continue;
				}

				$reference_start  = $position;
				$reference        = $this->parse_mysql_table_reference( $tokens, $position, $end );
				$reference_schema = $this->get_mysql_identifier_token_value( $tokens[ $reference_start ] ?? null );
				if (
					null === $reference
					|| ! isset( $tokens[ $reference_start + 1 ], $tokens[ $reference_start + 2 ] )
					|| WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $reference_start + 1 ]->id
					|| null === $reference_schema
					|| (
						0 !== strcasecmp( $reference_schema, $this->main_db_name )
						&& 0 !== strcasecmp( $reference_schema, 'public' )
					)
				) {
					return null;
				}

				$replacements[] = array(
					'start' => $reference_start,
					'end'   => $reference_start + 3,
					'sql'   => $this->translate_mysql_identifier_token_to_postgresql( $tokens[ $reference_start + 2 ] ?? null ),
				);
				$position       = $reference['position'];
				$expect_next    = false;
				continue;
			}

			if (
				WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id
				|| $this->is_mysql_join_token( $tokens[ $position ] )
			) {
				$expect_next = true;
			}

			++$position;
		}

		return empty( $replacements ) || $expect_next ? null : $replacements;
	}

	/**
	 * Get a replacement for an explicitly main-database derived SELECT source.
	 *
	 * @param string           $query    Original MySQL query.
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Opening parenthesis position.
	 * @param int              $end      Final FROM-clause token, exclusive.
	 * @return array{replacement: array, position: int}|null Replacement and next token position.
	 */
	private function get_information_schema_main_database_derived_select_replacement( string $query, array $tokens, int $position, int $end ): ?array {
		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
		if (
			null === $after_close
			|| ! isset( $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$select_start = $position + 1;
		$select_end   = $after_close - 1;
		$select_query = $this->get_mysql_token_range_sql( $query, $tokens, $select_start, $select_end );
		if ( null === $select_query ) {
			return null;
		}

		$translated_select = $this->translate_information_schema_main_database_select_query( $select_query );
		if ( null === $translated_select ) {
			return null;
		}

		return array(
			'replacement' => array(
				'start' => $select_start,
				'end'   => $select_end,
				'sql'   => $translated_select,
			),
			'position'    => $this->skip_mysql_table_alias( $tokens, $after_close, $end ),
		);
	}

	/**
	 * Get replacements for nested explicitly main-database SELECTs.
	 *
	 * @param string           $query  Original MySQL query.
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param array[]          $ranges Token ranges to scan.
	 * @return array[]|null Replacement ranges, or null when a nested SELECT is unsupported.
	 */
	private function get_information_schema_main_database_nested_select_replacements( string $query, array $tokens, array $ranges ): ?array {
		$replacements = array();
		foreach ( $ranges as $range ) {
			for ( $position = $range['start']; $position < $range['end']; $position++ ) {
				if (
					! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
					|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id
					|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position + 1 ]->id
				) {
					continue;
				}

				$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $range['end'] );
				if ( null === $after_close ) {
					return null;
				}

				$select_start = $position + 1;
				$select_end   = $after_close - 1;
				$select_query = $this->get_mysql_token_range_sql( $query, $tokens, $select_start, $select_end );
				if ( null === $select_query ) {
					return null;
				}

				$translated_select = $this->translate_information_schema_main_database_select_query( $select_query );
				if ( null === $translated_select ) {
					return null;
				}

				$replacements[] = array(
					'start' => $select_start,
					'end'   => $select_end,
					'sql'   => $translated_select,
				);
				$position       = $after_close - 1;
			}
		}

		return $replacements;
	}

	/**
	 * Check whether a SELECT under USE information_schema explicitly reads one main database table.
	 *
	 * This mirrors the existing simple SELECT translator, which strips the current
	 * MySQL database qualifier only for a single top-level table source.
	 *
	 * @param string           $query         MySQL query.
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $statement_end Final statement token position, exclusive.
	 * @return bool Whether this SELECT can safely continue to the simple SELECT translator.
	 */
	private function information_schema_select_query_targets_main_database_explicitly( string $query, array $tokens, int $statement_end ): bool {
		if ( 0 !== strcasecmp( $this->db_name, 'information_schema' ) ) {
			return false;
		}

		if ( null !== $this->translate_information_schema_main_database_select_query( $query ) ) {
			return true;
		}

		if ( null === $this->translate_simple_mysql_select_query( $query ) ) {
			return false;
		}

		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, 1, $statement_end );
		if ( null === $from_position ) {
			return false;
		}

		$source_end = $this->find_first_top_level_mysql_token(
			$tokens,
			array(
				WP_MySQL_Lexer::LIMIT_SYMBOL,
				WP_MySQL_Lexer::ORDER_SYMBOL,
				WP_MySQL_Lexer::WHERE_SYMBOL,
			),
			$from_position + 1,
			$statement_end
		) ?? $statement_end;

		$position        = $from_position + 1;
		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
		if ( ! $this->is_explicit_main_database_table_reference( $table_reference ) ) {
			return false;
		}

		return $this->consume_optional_simple_table_alias( $tokens, $position, $source_end )
			&& $position === $source_end;
	}

	/**
	 * Check whether a SELECT under USE information_schema reaches a table source.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @return bool Whether the SELECT should be rejected.
	 */
	private function information_schema_select_has_table_reference( array $tokens ): bool {
		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return true;
		}

		return $this->mysql_select_range_has_non_dual_table_reference( $tokens, 0, $statement_end );
	}

	/**
	 * Check whether a SELECT token range names information_schema directly.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return bool Whether the range references an information_schema relation.
	 */
	private function select_references_direct_information_schema_relation( array $tokens, int $start, int $end ): bool {
		for ( $position = $start; $position + 2 < $end; $position++ ) {
			if (
				WP_MySQL_Lexer::DOT_SYMBOL !== ( $tokens[ $position + 1 ]->id ?? null )
				|| 0 !== strcasecmp(
					(string) $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] ?? null ),
					'information_schema'
				)
			) {
				continue;
			}

			$relation = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position + 2 ] ?? null );
			if ( null !== $relation ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Add explicit aliases to multi-expression COUNT aggregate projections.
	 *
	 * PostgreSQL labels every unaliased COUNT expression as "count". WordPress
	 * later converts fetched objects to ARRAY_N by reading object properties, so
	 * duplicate labels collapse the result row before ARRAY_N can preserve order.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int              $projection_start First projection token position.
	 * @param int              $statement_end    Final statement token position, exclusive.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_mysql_count_aggregate_projection_alias_query( array $tokens, int $projection_start, int $statement_end ): ?string {
		if (
			! isset( $tokens[0] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id
			|| $this->contains_top_level_mysql_token(
				$tokens,
				$projection_start,
				$statement_end,
				array(
					WP_MySQL_Lexer::DISTINCT_SYMBOL,
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::HIGH_PRIORITY_SYMBOL,
					WP_MySQL_Lexer::INTO_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL,
					WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		$from_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::FROM_SYMBOL,
			$projection_start,
			$statement_end
		);
		if ( null === $from_position || $projection_start === $from_position ) {
			return null;
		}

		$projection_ranges = $this->split_top_level_mysql_arguments( $tokens, $projection_start, $from_position );
		if ( null === $projection_ranges || count( $projection_ranges ) < 2 ) {
			return null;
		}

		$projection_sql = array();
		$alias_lookup   = array();
		foreach ( $projection_ranges as $range ) {
			$expression_bounds = $this->get_mysql_select_projection_expression_bounds(
				$tokens,
				$range['start'],
				$range['end']
			);
			if (
				null === $expression_bounds
				|| $expression_bounds['start'] !== $range['start']
				|| $expression_bounds['end'] !== $range['end']
				|| ! $this->is_mysql_count_aggregate_expression(
					$tokens,
					$expression_bounds['start'],
					$expression_bounds['end']
				)
			) {
				return null;
			}

			$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$expression_bounds['start'],
				$expression_bounds['end']
			);
			$alias_key      = strtolower( $expression_sql );
			if ( isset( $alias_lookup[ $alias_key ] ) ) {
				return null;
			}

			$alias_lookup[ $alias_key ] = true;
			$projection_sql[]           = sprintf(
				'%s AS %s',
				$expression_sql,
				$this->connection->quote_identifier( $expression_sql )
			);
		}

		return sprintf(
			'SELECT %s %s',
			implode( ', ', $projection_sql ),
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, $from_position, $statement_end )
		);
	}

	/**
	 * Tokenize a MySQL query with the configured lexer implementation.
	 *
	 * @param string $query MySQL query.
	 * @return WP_MySQL_Token[] MySQL lexer token stream.
	 */
	private function get_mysql_tokens( string $query ): array {
		$sql_mode = $this->get_sql_mode();
		if ( $query === $this->mysql_token_cache_query && $sql_mode === $this->mysql_token_cache_sql_mode ) {
			return $this->mysql_token_cache_tokens;
		}

		$lexer  = new WP_MySQL_Lexer( $query, $this->mysql_version, $this->active_sql_modes );
		$tokens = $lexer instanceof WP_MySQL_Native_Lexer ? $lexer->native_token_stream() : $lexer->remaining_tokens();

		$this->mysql_token_cache_query    = $query;
		$this->mysql_token_cache_sql_mode = $sql_mode;
		$this->mysql_token_cache_tokens   = $tokens;

		return $tokens;
	}

	/**
	 * Check whether a table name is a WordPress options table.
	 *
	 * @param string $table_name Table identifier value.
	 * @return bool Whether the table is an options table.
	 */
	private function is_wordpress_options_table_name( string $table_name ): bool {
		$table_name = strtolower( $table_name );
		return 'options' === $table_name || '_options' === substr( $table_name, -8 );
	}

	/**
	 * Parse a parenthesized MySQL identifier list.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Current token position, updated on success.
	 * @return string[]|null Identifier values, or null when unsupported.
	 */
	private function parse_mysql_identifier_list( array $tokens, int &$position ): ?array {
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		$identifiers = array();

		while ( isset( $tokens[ $position ] ) ) {
			$identifier = $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] );
			if ( null === $identifier ) {
				return null;
			}

			$identifiers[] = $identifier;
			++$position;

			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				continue;
			}

			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				return $identifiers;
			}

			return null;
		}

		return null;
	}

	/**
	 * Locate the top-level ON DUPLICATE KEY UPDATE clause.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Token position where scanning starts.
	 * @return int|null Token position of ON, or null when not found.
	 */
	private function find_on_duplicate_key_update_clause( array $tokens, int $position ): ?int {
		$depth = 0;
		for ( $i = $position; isset( $tokens[ $i ] ) && WP_MySQL_Lexer::EOF !== $tokens[ $i ]->id; $i++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $i ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $i ]->id ) {
				--$depth;
				if ( $depth < 0 ) {
					return null;
				}
				continue;
			}

			if (
				0 === $depth
				&& WP_MySQL_Lexer::ON_SYMBOL === $tokens[ $i ]->id
				&& isset( $tokens[ $i + 3 ] )
				&& WP_MySQL_Lexer::DUPLICATE_SYMBOL === $tokens[ $i + 1 ]->id
				&& WP_MySQL_Lexer::KEY_SYMBOL === $tokens[ $i + 2 ]->id
				&& WP_MySQL_Lexer::UPDATE_SYMBOL === $tokens[ $i + 3 ]->id
			) {
				return $i;
			}
		}

		return null;
	}

	/**
	 * Parse ON DUPLICATE KEY UPDATE assignments for the supported upsert shape.
	 *
	 * @param string           $table_name           Target table name.
	 * @param WP_MySQL_Token[] $tokens              MySQL lexer token stream.
	 * @param int             $position            Current token position, updated on success.
	 * @param int              $end                 Final assignment token position, exclusive.
	 * @param array           $column_lookup       Insert-column lookup by lowercase name.
	 * @param array           $table_column_lookup Table-column metadata lookup by lowercase name.
	 * @param array           $source_aliases      Optional VALUES-row alias lookup.
	 * @param array|null      $assignment_effects  Optional side effects detected while parsing.
	 * @return string[]|null PostgreSQL SET assignments, or null when unsupported.
	 */
	private function parse_upsert_update_assignments( string $table_name, array $tokens, int &$position, int $end, array $column_lookup, array $table_column_lookup, array $source_aliases = array(), ?array &$assignment_effects = null ): ?array {
		$assignment_effects   = array();
		$assignments          = array();
		$scope                = $this->get_mysql_single_table_scope( $table_name );
		$values_column_lookup = $this->get_mysql_upsert_values_column_lookup( $column_lookup, $table_column_lookup );

		while ( $position < $end ) {
			$target = $this->parse_mysql_upsert_assignment_target( $table_name, $tokens, $position, $end );
			if (
				null === $target
				|| ! isset( $table_column_lookup[ strtolower( $target['column'] ) ] )
			) {
				return null;
			}

			$target_column = $target['column'];
			$assignment_effects['assigned_columns'][ strtolower( $target_column ) ] = $target_column;
			$position = $target['end'];
			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::EQUAL_OPERATOR !== $tokens[ $position ]->id ) {
				return null;
			}

			++$position;
			$value_start    = $position;
			$assignment_end = $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::COMMA_SYMBOL,
				$value_start,
				$end
			) ?? $end;

			if ( $value_start >= $assignment_end ) {
				return null;
			}

				$target_metadata = $table_column_lookup[ strtolower( $target_column ) ];
				$source_column   = $this->get_mysql_upsert_values_assignment_source_column( $tokens, $value_start, $assignment_end, $values_column_lookup, $source_aliases );
			if ( $this->is_mysql_default_value_token_sequence( $tokens, $value_start, $assignment_end ) ) {
				$value_sql = $this->get_mysql_dml_default_assignment_sql_for_column( $target_metadata );
			} else {
				$default_function_sql = $this->get_mysql_dml_default_function_assignment_sql( $tokens, $value_start, $assignment_end, $table_column_lookup );
				if ( null !== $default_function_sql ) {
					$value_sql = $default_function_sql;
				} elseif ( null !== $source_column ) {
					$value_sql = sprintf(
						'excluded.%s',
						$this->connection->quote_identifier( $source_column )
					);
				} else {
					$last_insert_id_assignment = $this->get_mysql_upsert_last_insert_id_assignment(
						$table_name,
						$target_column,
						$tokens,
						$value_start,
						$assignment_end,
						$scope,
						$table_column_lookup
					);
					if ( false === $last_insert_id_assignment ) {
						return null;
					}
					if ( is_array( $last_insert_id_assignment ) ) {
						if (
							isset( $assignment_effects['last_insert_id_column'] )
							&& 0 !== strcasecmp( (string) $assignment_effects['last_insert_id_column'], $last_insert_id_assignment['column'] )
						) {
							return null;
						}

						$value_sql                                   = $last_insert_id_assignment['sql'];
						$assignment_effects['last_insert_id_column'] = $last_insert_id_assignment['column'];
					} else {
						$scalar_subquery_sql = null;

						$value_replacements = $this->get_mysql_upsert_values_expression_replacements(
							$tokens,
							$value_start,
							$assignment_end,
							$values_column_lookup,
							$source_aliases
						);

						$default_replacements = null;
						if ( null !== $value_replacements ) {
							$default_replacements = $this->get_mysql_upsert_default_expression_replacements(
								$tokens,
								$value_start,
								$assignment_end,
								$table_column_lookup
							);
						}

						$subquery_replacements = null;
						if ( null !== $value_replacements && null !== $default_replacements ) {
							$subquery_replacements = $this->get_mysql_upsert_scalar_subquery_expression_replacements(
								$tokens,
								$value_start,
								$assignment_end,
								$scope
							);
						}

						$target_column_replacements = null;
						if ( null !== $value_replacements && null !== $default_replacements && null !== $subquery_replacements ) {
							$target_column_replacements = $this->get_mysql_upsert_target_column_expression_replacements(
								$table_name,
								$tokens,
								$value_start,
								$assignment_end,
								$scope,
								$table_column_lookup,
								array_merge( $value_replacements, $default_replacements, $subquery_replacements )
							);
						}

						$expression_replacements = null !== $value_replacements && null !== $default_replacements && null !== $subquery_replacements && null !== $target_column_replacements
							? array_merge( $value_replacements, $default_replacements, $subquery_replacements, $target_column_replacements )
							: null;
						if ( null !== $expression_replacements ) {
							usort(
								$expression_replacements,
								static function ( array $a, array $b ): int {
									return ( $a['start'] ?? 0 ) <=> ( $b['start'] ?? 0 );
								}
							);
						}
						if (
							null === $scalar_subquery_sql
							&& is_array( $subquery_replacements )
							&& 1 === count( $subquery_replacements )
							&& $value_start === $subquery_replacements[0]['start']
							&& $assignment_end === $subquery_replacements[0]['end']
						) {
							$scalar_subquery_sql     = $subquery_replacements[0]['sql'];
							$expression_replacements = array();
						}
						if (
							null === $expression_replacements
							|| ! $this->is_supported_simple_mysql_upsert_expression_fragment(
								$tokens,
								$value_start,
								$assignment_end,
								$expression_replacements
							)
							|| $this->contains_unsupported_mysql_convert_function_outside_replacements( $tokens, $value_start, $assignment_end, $expression_replacements )
							|| $this->contains_unsupported_mysql_common_function_outside_replacements( $tokens, $value_start, $assignment_end, $expression_replacements )
							|| ! $this->mysql_upsert_expression_column_references_resolve_to_scope(
								$tokens,
								$value_start,
								$assignment_end,
								$expression_replacements,
								$scope
							)
						) {
							$scalar_subquery_sql = $this->get_mysql_upsert_scalar_subquery_assignment_sql(
								$tokens,
								$value_start,
								$assignment_end,
								$scope
							);
							if ( null === $scalar_subquery_sql ) {
								return null;
							}
							$expression_replacements = array();
						}

						$this->validate_strict_mysql_dml_value_for_column( $target_metadata, $tokens, $value_start, $assignment_end );

						$value_sql = $scalar_subquery_sql ?? null;
						if (
							null !== $value_sql
							&& $this->is_mysql_text_family_column_type( (string) ( $target_metadata['column_type'] ?? '' ) )
						) {
							$value_sql = sprintf( 'CAST(%s AS text)', $value_sql );
						} elseif (
							null !== $value_sql
							&& ! $this->is_mysql_strict_sql_mode_active()
							&& $this->is_mysql_integer_family_column_type( (string) ( $target_metadata['column_type'] ?? '' ) )
						) {
							$value_sql = $this->get_postgresql_mysql_integer_cast_sql( $value_sql );
						}
						if ( null === $value_sql ) {
							$value_sql = $this->get_strict_mysql_dml_value_sql_for_column( $target_metadata, $tokens, $value_start, $assignment_end );
						}
						if ( null === $value_sql ) {
							$value_sql = $this->get_non_strict_mysql_dml_value_sql_for_column( $target_metadata, $tokens, $value_start, $assignment_end );
						}
						if ( null === $value_sql ) {
							if ( empty( $expression_replacements ) ) {
								$expression_sql = $this->translate_mysql_expression_token_sequence_to_postgresql(
									$tokens,
									$value_start,
									$assignment_end,
									$scope
								);
								$value_sql      = $expression_sql['sql'];
								$changed        = $expression_sql['changed'];
							} else {
								$value_sql = $this->translate_mysql_upsert_expression_token_sequence_with_replacements_to_postgresql(
									$tokens,
									$value_start,
									$assignment_end,
									$expression_replacements
								);
								if ( null === $value_sql ) {
									return null;
								}
								$changed = true;
							}
							if (
								$changed
								&& $this->is_mysql_text_family_column_type( (string) ( $target_metadata['column_type'] ?? '' ) )
							) {
								$value_sql = sprintf( 'CAST(%s AS text)', $value_sql );
							}
						}
						$guarded_value_sql = $this->get_strict_mysql_dml_temporal_expression_sql_for_column(
							$target_metadata,
							$tokens,
							$value_start,
							$assignment_end,
							$value_sql
						);
						if ( null !== $guarded_value_sql ) {
							$value_sql = $guarded_value_sql;
						}
					}
				}
			}

			$assignments[] = sprintf(
				'%s = %s',
				$this->connection->quote_identifier( $target_column ),
				$value_sql
			);
			$position      = $assignment_end;

			if ( $position === $end ) {
				break;
			}

			++$position;
		}

		return count( $assignments ) > 0 ? $assignments : null;
	}

	/**
	 * Parse the supported LAST_INSERT_ID(column) upsert assignment side effect.
	 *
	 * MySQL plugins commonly use "id = LAST_INSERT_ID(id)" so mysqli_insert_id()
	 * returns the existing row id on duplicate-key updates. Only the no-op
	 * AUTO_INCREMENT self-assignment is safe to emulate here.
	 *
	 * @param string           $table_name           Target table name.
	 * @param string           $target_column        Assignment target column.
	 * @param WP_MySQL_Token[] $tokens               MySQL lexer token stream.
	 * @param int              $start                First expression token.
	 * @param int              $end                  Final expression token, exclusive.
	 * @param array            $scope                Statement table scope.
	 * @param array            $table_column_lookup  Table-column metadata lookup by lowercase name.
	 * @return array{column: string, sql: string}|false|null Assignment data, false for unsupported LAST_INSERT_ID usage, or null when not applicable.
	 */
	private function get_mysql_upsert_last_insert_id_assignment( string $table_name, string $target_column, array $tokens, int $start, int $end, array $scope, array $table_column_lookup ) {
		$bounds = $this->get_mysql_common_function_bounds( $tokens, $start, $end );
		if ( null === $bounds || 'last_insert_id' !== $bounds['function'] ) {
			return $this->contains_mysql_last_insert_id_function_call( $tokens, $start, $end ) ? false : null;
		}

		if ( $bounds['close'] + 1 !== $end ) {
			return false;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
		if ( null === $arguments || 1 !== count( $arguments ) ) {
			return false;
		}

		$argument  = $arguments[0];
		$reference = $this->parse_mysql_column_reference( $tokens, $argument['start'], $argument['end'] );
		if (
			null === $reference
			|| $reference['end'] !== $argument['end']
			|| 0 !== strcasecmp( $reference['column'], $target_column )
			|| null === $this->get_mysql_column_type_for_reference( $reference, $scope )
		) {
			return false;
		}

		if (
			null !== $reference['qualifier']
			&& ! $this->is_mysql_dml_table_qualifier( $reference['qualifier'], $table_name, null )
		) {
			return false;
		}

		$column_key = strtolower( $reference['column'] );
		if (
			! isset( $table_column_lookup[ $column_key ] )
			|| ! $this->is_mysql_auto_increment_column_metadata( $table_column_lookup[ $column_key ] )
		) {
			return false;
		}

		return array(
			'column' => (string) ( $table_column_lookup[ $column_key ]['column_name'] ?? $reference['column'] ),
			'sql'    => $this->get_postgresql_dml_column_reference_sql(
				(string) ( $table_column_lookup[ $column_key ]['column_name'] ?? $reference['column'] ),
				$table_name
			),
		);
	}

	/**
	 * Check whether a range contains a LAST_INSERT_ID(...) function call.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token.
	 * @param int              $end    Final token, exclusive.
	 * @return bool Whether LAST_INSERT_ID() appears in the range.
	 */
	private function contains_mysql_last_insert_id_function_call( array $tokens, int $start, int $end ): bool {
		for ( $position = $start; $position < $end; $position++ ) {
			$bounds = $this->get_mysql_common_function_bounds( $tokens, $position, $end );
			if ( null !== $bounds && 'last_insert_id' === $bounds['function'] ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Parse the target column for an ON DUPLICATE KEY UPDATE assignment.
	 *
	 * @param string           $table_name Target table name.
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $position   Assignment target start.
	 * @param int              $end        Final assignment token position, exclusive.
	 * @return array{column: string, end: int}|null Assignment target, or null when unsupported.
	 */
	private function parse_mysql_upsert_assignment_target( string $table_name, array $tokens, int $position, int $end ): ?array {
		$first_identifier = $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first_identifier ) {
			return null;
		}

		if ( $position + 2 >= $end || WP_MySQL_Lexer::DOT_SYMBOL !== ( $tokens[ $position + 1 ]->id ?? null ) ) {
			return array(
				'column' => $first_identifier,
				'end'    => $position + 1,
			);
		}

		$second_identifier = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 2 ] ?? null );
		if ( null === $second_identifier ) {
			return null;
		}

		if ( $position + 4 < $end && WP_MySQL_Lexer::DOT_SYMBOL === ( $tokens[ $position + 3 ]->id ?? null ) ) {
			$third_identifier = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 4 ] ?? null );
			if (
				null === $third_identifier
				|| 0 !== strcasecmp( $first_identifier, $this->main_db_name )
				|| ! $this->is_mysql_dml_table_qualifier( $second_identifier, $table_name, null )
			) {
				return null;
			}

			return array(
				'column' => $third_identifier,
				'end'    => $position + 5,
			);
		}

		if ( ! $this->is_mysql_dml_table_qualifier( $first_identifier, $table_name, null ) ) {
			return null;
		}

		return array(
			'column' => $second_identifier,
			'end'    => $position + 3,
		);
	}

	/**
	 * Get SQL for a MySQL DEFAULT(column) assignment expression.
	 *
	 * @param WP_MySQL_Token[] $tokens              MySQL lexer token stream.
	 * @param int              $start               First expression token.
	 * @param int              $end                 Final expression token, exclusive.
	 * @param array            $table_column_lookup Table-column metadata lookup by lowercase name.
	 * @return string|null PostgreSQL SQL expression, or null when not supported.
	 */
	private function get_mysql_dml_default_function_assignment_sql( array $tokens, int $start, int $end, array $table_column_lookup ): ?string {
		if (
			$start + 4 !== $end
			|| WP_MySQL_Lexer::DEFAULT_SYMBOL !== ( $tokens[ $start ]->id ?? null )
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== ( $tokens[ $start + 1 ]->id ?? null )
			|| WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== ( $tokens[ $start + 3 ]->id ?? null )
		) {
			return null;
		}

		$column_name = $this->get_mysql_dml_identifier_token_value( $tokens[ $start + 2 ] ?? null );
		if ( null === $column_name ) {
			return null;
		}

		$column_metadata = $table_column_lookup[ strtolower( $column_name ) ] ?? null;
		if ( null === $column_metadata ) {
			return null;
		}

		return $this->get_mysql_dml_default_assignment_sql_for_column( $column_metadata );
	}

	/**
	 * Get SQL for a MySQL DEFAULT assignment expression.
	 *
	 * @param array $column_metadata Column metadata row.
	 * @return string PostgreSQL SQL expression.
	 */
	private function get_mysql_dml_default_assignment_sql_for_column( array $column_metadata ): string {
		$default_sql = $this->get_mysql_dml_default_sql_from_metadata( $column_metadata );
		if ( null !== $default_sql ) {
			return $default_sql;
		}

		return 'NULL';
	}

	/**
	 * Get PostgreSQL SQL for a supported scalar subquery upsert assignment.
	 *
	 * This supports constant/no-table scalar SELECTs, optional MySQL FROM DUAL,
	 * and uncorrelated COUNT(*)/COUNT(column) from a single current-database table.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First expression token.
	 * @param int              $end    Final expression token, exclusive.
	 * @param array            $scope  Statement table scope.
	 * @return string|null PostgreSQL scalar subquery SQL, or null when unsupported.
	 */
	private function get_mysql_upsert_scalar_subquery_assignment_sql( array $tokens, int $start, int $end, array $scope ): ?string {
		$after_subquery = $this->get_mysql_parenthesized_sequence_end( $tokens, $start, $end );
		if (
			null === $after_subquery
			|| $after_subquery !== $end
			|| ! isset( $tokens[ $start + 1 ] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $start + 1 ]->id
		) {
			return null;
		}

		$select_start     = $start + 1;
		$projection_start = $select_start + 1;
		$select_end       = $end - 1;
		if ( $projection_start >= $select_end ) {
			return null;
		}

		if (
			$this->contains_top_level_mysql_token(
				$tokens,
				$projection_start,
				$select_end,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		$from_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::FROM_SYMBOL,
			$projection_start,
			$select_end
		);
		if ( null !== $from_position ) {
			$limit_position = $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::LIMIT_SYMBOL,
				$from_position + 1,
				$select_end
			);
			$order_position = $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::ORDER_SYMBOL,
				$from_position + 1,
				null === $limit_position ? $select_end : $limit_position
			);
			if (
				null !== $limit_position
				&& null !== $this->find_top_level_mysql_token(
					$tokens,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					$limit_position + 1,
					$select_end
				)
			) {
				return null;
			}

			$tail_start     = $order_position ?? $limit_position ?? $select_end;
			$where_position = $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::WHERE_SYMBOL,
				$from_position + 1,
				$tail_start
			);
			$source_end     = $where_position ?? $tail_start;
			if ( $from_position + 2 === $source_end && WP_MySQL_Lexer::DUAL_SYMBOL === ( $tokens[ $from_position + 1 ]->id ?? null ) ) {
				$projection = $this->split_top_level_mysql_arguments( $tokens, $projection_start, $from_position );
				if ( null === $projection || 1 !== count( $projection ) ) {
					return null;
				}

				if ( ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $projection[0]['start'], $projection[0]['end'] ) ) {
					return null;
				}

				$expression_sql = $this->translate_mysql_expression_token_sequence_to_postgresql(
					$tokens,
					$projection[0]['start'],
					$projection[0]['end'],
					$scope
				);

				$where_sql = '';
				if ( null !== $where_position ) {
					$where_end = $order_position ?? $limit_position ?? $select_end;
					if (
						$where_position + 1 >= $where_end
						|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $where_position + 1, $where_end )
						|| ! $this->mysql_expression_column_references_resolve_to_scope( $tokens, $where_position + 1, $where_end, $scope )
					) {
						return null;
					}

					$translated_where = $this->translate_mysql_predicate_token_sequence_to_postgresql(
						$tokens,
						$where_position + 1,
						$where_end,
						$scope
					);
					$where_sql        = ' WHERE ' . $translated_where['sql'];
				}

				$order_sql = '';
				if ( null !== $order_position ) {
					$order_end   = $limit_position ?? $select_end;
					$order_items = $this->split_top_level_mysql_arguments( $tokens, $order_position + 2, $order_end );
					if ( null === $order_items || empty( $order_items ) ) {
						return null;
					}
					foreach ( $order_items as $order_item ) {
						$order_item_end = $order_item['end'];
						if (
							$order_item['start'] < $order_item_end
							&& (
								WP_MySQL_Lexer::ASC_SYMBOL === ( $tokens[ $order_item_end - 1 ]->id ?? null )
								|| WP_MySQL_Lexer::DESC_SYMBOL === ( $tokens[ $order_item_end - 1 ]->id ?? null )
							)
						) {
							--$order_item_end;
						}
						if (
							$order_item['start'] >= $order_item_end
							|| ! $this->mysql_expression_column_references_resolve_to_scope( $tokens, $order_item['start'], $order_item_end, $scope )
						) {
							return null;
						}
					}

					$order_sql = $this->translate_mysql_joined_dml_order_by_clause_to_postgresql(
						$tokens,
						$order_position,
						$order_end,
						$scope
					);
					if ( null === $order_sql ) {
						return null;
					}
				}

				$limit_sql = '';
				if ( null !== $limit_position ) {
					if ( ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $select_end ) ) {
						return null;
					}

					$limit_sql = $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $select_end );
				}

				return sprintf(
					'(SELECT %s%s%s%s)',
					$expression_sql['sql'],
					$where_sql,
					$order_sql,
					$limit_sql
				);
			}

			$reference_position = $from_position + 1;
			$reference          = $this->parse_mysql_main_database_table_reference( $tokens, $reference_position, $source_end );
			if ( null === $reference || $reference_position !== $source_end ) {
				return null;
			}

				$projection = $this->split_top_level_mysql_arguments( $tokens, $projection_start, $from_position );
			if ( null === $projection || 1 !== count( $projection ) ) {
				return null;
			}

				$subquery_scope = $this->get_mysql_single_table_scope( $reference['table'], $reference['alias'] );
				$projection_sql = $this->get_mysql_upsert_table_scalar_subquery_projection_sql(
					$tokens,
					$projection[0]['start'],
					$projection[0]['end'],
					$reference['table'],
					$reference['alias'],
					$subquery_scope
				);
			if ( null === $projection_sql ) {
				return null;
			}

				$where_sql = '';
			if ( null !== $where_position ) {
				$where_end = $order_position ?? $limit_position ?? $select_end;
				if (
					$where_position + 1 >= $where_end
					|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $where_position + 1, $where_end )
					|| ! $this->mysql_expression_column_references_resolve_to_scope( $tokens, $where_position + 1, $where_end, $subquery_scope )
				) {
					return null;
				}

				$translated_where = $this->translate_mysql_predicate_token_sequence_to_postgresql(
					$tokens,
					$where_position + 1,
					$where_end,
					$subquery_scope
				);
				$where_sql        = ' WHERE ' . $translated_where['sql'];
			}

				$order_sql = '';
			if ( null !== $order_position ) {
				$order_end   = $limit_position ?? $select_end;
				$order_items = $this->split_top_level_mysql_arguments( $tokens, $order_position + 2, $order_end );
				if ( null === $order_items || empty( $order_items ) ) {
					return null;
				}
				foreach ( $order_items as $order_item ) {
					$order_item_end = $order_item['end'];
					if (
						$order_item['start'] < $order_item_end
						&& (
							WP_MySQL_Lexer::ASC_SYMBOL === ( $tokens[ $order_item_end - 1 ]->id ?? null )
							|| WP_MySQL_Lexer::DESC_SYMBOL === ( $tokens[ $order_item_end - 1 ]->id ?? null )
						)
					) {
						--$order_item_end;
					}
					if (
						$order_item['start'] >= $order_item_end
						|| ! $this->mysql_expression_column_references_resolve_to_scope( $tokens, $order_item['start'], $order_item_end, $subquery_scope )
					) {
						return null;
					}
				}

				$order_sql = $this->translate_mysql_joined_dml_order_by_clause_to_postgresql(
					$tokens,
					$order_position,
					$order_end,
					$subquery_scope
				);
				if ( null === $order_sql ) {
					return null;
				}
			}

				$limit_sql = '';
			if ( null !== $limit_position ) {
				if ( ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $select_end ) ) {
					return null;
				}

				$limit_sql = $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $select_end );
			}

				return sprintf(
					'(SELECT %s FROM %s%s%s%s)',
					$projection_sql,
					$this->get_postgresql_dml_table_reference_sql( $reference['table'], $reference['alias'] ),
					$where_sql,
					$order_sql,
					$limit_sql
				);
		}
		if ( null === $from_position ) {
			$projection_end = $select_end;
		}

		$projection = $this->split_top_level_mysql_arguments( $tokens, $projection_start, $projection_end );
		if ( null === $projection || 1 !== count( $projection ) ) {
			return null;
		}

		if ( ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $projection[0]['start'], $projection[0]['end'] ) ) {
			return null;
		}

		$expression_sql = $this->translate_mysql_expression_token_sequence_to_postgresql(
			$tokens,
			$projection[0]['start'],
			$projection[0]['end'],
			$scope
		);

		return sprintf(
			'(SELECT %s)',
			$expression_sql['sql']
		);
	}

	/**
	 * Get PostgreSQL SQL for a supported table-backed scalar subquery projection.
	 *
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $start      First projection token.
	 * @param int              $end        Final projection token, exclusive.
	 * @param string           $table_name Subquery source table name.
	 * @param string|null      $alias      Optional subquery source alias.
	 * @param array            $scope      Subquery source table scope.
	 * @return string|null PostgreSQL projection SQL, or null when unsupported.
	 */
	private function get_mysql_upsert_table_scalar_subquery_projection_sql( array $tokens, int $start, int $end, string $table_name, ?string $alias, array $scope ): ?string {
		$count_sql = $this->get_mysql_upsert_count_subquery_projection_sql( $tokens, $start, $end, $table_name, $alias );
		if ( null !== $count_sql ) {
			return $count_sql;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $start, $end );
		if (
			null === $reference
			|| $reference['end'] !== $end
			|| null === $this->get_mysql_column_type_for_reference( $reference, $scope )
		) {
			return null;
		}

		return $this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] );
	}

	/**
	 * Get PostgreSQL SQL for a supported table-backed COUNT() scalar subquery projection.
	 *
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $start      First projection token.
	 * @param int              $end        Final projection token, exclusive.
	 * @param string           $table_name Subquery source table name.
	 * @param string|null      $alias      Optional subquery source alias.
	 * @return string|null PostgreSQL COUNT() SQL, or null when unsupported.
	 */
	private function get_mysql_upsert_count_subquery_projection_sql( array $tokens, int $start, int $end, string $table_name, ?string $alias ): ?string {
		if (
			! isset( $tokens[ $start ], $tokens[ $start + 1 ] )
			|| WP_MySQL_Lexer::COUNT_SYMBOL !== $tokens[ $start ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $start + 1 ]->id
		) {
			return null;
		}

		$after_count = $this->get_mysql_parenthesized_sequence_end( $tokens, $start + 1, $end );
		if ( null === $after_count || $after_count !== $end ) {
			return null;
		}

		$argument_start = $start + 2;
		$argument_end   = $after_count - 1;
		if (
			$argument_start + 1 === $argument_end
			&& WP_MySQL_Lexer::MULT_OPERATOR === ( $tokens[ $argument_start ]->id ?? null )
		) {
			return 'COUNT(*)';
		}

		if ( $this->is_supported_mysql_upsert_literal_select_expression( $tokens, $argument_start, $argument_end ) ) {
			$expression_sql = $this->translate_mysql_expression_token_sequence_to_postgresql(
				$tokens,
				$argument_start,
				$argument_end,
				array()
			);

			return sprintf( 'COUNT(%s)', $expression_sql['sql'] );
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $argument_start, $argument_end );
		if ( null === $reference || $reference['end'] !== $argument_end ) {
			return null;
		}

		if ( null === $this->get_mysql_table_column_type( 'public', $table_name, $reference['column'] ) ) {
			return null;
		}

		$qualifier = null;
		if ( null !== $reference['qualifier'] ) {
			if ( null !== $alias ) {
				if ( 0 !== strcasecmp( $reference['qualifier'], $alias ) ) {
					return null;
				}

				$qualifier = $alias;
			} else {
				if ( 0 !== strcasecmp( $reference['qualifier'], $table_name ) ) {
					return null;
				}

				$qualifier = $table_name;
			}
		}

		return sprintf(
			'COUNT(%s)',
			$this->get_postgresql_dml_column_reference_sql( $reference['column'], $qualifier )
		);
	}

	/**
	 * Get the columns accepted by MySQL VALUES(column) in an upsert assignment.
	 *
	 * MySQL permits VALUES(column) for omitted table columns; PostgreSQL's
	 * excluded row has those defaulted/null values as well. VALUES-row aliases
	 * remain constrained separately to the explicit INSERT column list.
	 *
	 * @param array $column_lookup       Insert-column lookup by lowercase name.
	 * @param array $table_column_lookup Table-column metadata lookup by lowercase name.
	 * @return array<string,string> Lookup of lowercase column name to canonical column name.
	 */
	private function get_mysql_upsert_values_column_lookup( array $column_lookup, array $table_column_lookup ): array {
		$values_column_lookup = array();
		foreach ( $column_lookup as $column_key => $column_name ) {
			$values_column_lookup[ strtolower( (string) $column_key ) ] = is_string( $column_name )
				? $column_name
				: (string) $column_key;
		}

		foreach ( $table_column_lookup as $column_key => $column_metadata ) {
			if ( isset( $values_column_lookup[ strtolower( (string) $column_key ) ] ) ) {
				continue;
			}

			$column_name = (string) ( $column_metadata['column_name'] ?? '' );
			if ( '' === $column_name ) {
				continue;
			}

			$values_column_lookup[ strtolower( $column_name ) ] = $column_name;
		}

		return $values_column_lookup;
	}

	/**
	 * Get the source column from a supported VALUES(column) upsert assignment expression.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $start         First expression token.
	 * @param int              $end           Final expression token, exclusive.
	 * @param array            $column_lookup VALUES-column lookup by lowercase name.
	 * @param array            $source_aliases Optional VALUES-row alias lookup.
	 * @return string|null Source column name, or null when the expression is not VALUES(column).
	 */
	private function get_mysql_upsert_values_assignment_source_column( array $tokens, int $start, int $end, array $column_lookup, array $source_aliases = array() ): ?string {
		if (
			$start + 4 === $end
			&& isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ], $tokens[ $start + 3 ] )
			&& WP_MySQL_Lexer::VALUES_SYMBOL === $tokens[ $start ]->id
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $start + 1 ]->id
			&& WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $start + 3 ]->id
		) {
			$source_column = $this->get_mysql_dml_identifier_token_value( $tokens[ $start + 2 ] );
			$source_key    = null === $source_column ? null : strtolower( $source_column );
			if ( null === $source_key || ! isset( $column_lookup[ $source_key ] ) ) {
				return null;
			}

			return is_string( $column_lookup[ $source_key ] ) ? $column_lookup[ $source_key ] : $source_column;
		}

		return $this->get_mysql_upsert_alias_assignment_source_column( $tokens, $start, $end, $source_aliases );
	}

	/**
	 * Get replacements for supported VALUES(column) references in an upsert expression.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $start         First expression token.
	 * @param int              $end           Final expression token, exclusive.
	 * @param array            $column_lookup VALUES-column lookup by lowercase name.
	 * @param array            $source_aliases Optional VALUES-row alias lookup.
	 * @return array[]|null Replacement ranges, or null when VALUES() is malformed/unsupported.
	 */
	private function get_mysql_upsert_values_expression_replacements( array $tokens, int $start, int $end, array $column_lookup, array $source_aliases = array() ): ?array {
		$replacements = array();

		for ( $position = $start; $position < $end; $position++ ) {
			if ( WP_MySQL_Lexer::VALUES_SYMBOL === $tokens[ $position ]->id ) {
				if (
					$position + 4 > $end
					|| ! isset( $tokens[ $position + 1 ], $tokens[ $position + 2 ], $tokens[ $position + 3 ] )
					|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
					|| WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== $tokens[ $position + 3 ]->id
				) {
					return null;
				}

				$source_column = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 2 ] );
				$source_key    = null === $source_column ? null : strtolower( $source_column );
				if ( null === $source_key || ! isset( $column_lookup[ $source_key ] ) ) {
					return null;
				}
				$source_column = is_string( $column_lookup[ $source_key ] ) ? $column_lookup[ $source_key ] : $source_column;

				$replacements[] = array(
					'start' => $position,
					'end'   => $position + 4,
					'sql'   => sprintf(
						'excluded.%s',
						$this->connection->quote_identifier( $source_column )
					),
				);
				$position      += 3;
				continue;
			}

			$alias_reference = $this->get_mysql_upsert_alias_expression_reference( $tokens, $position, $start, $end, $source_aliases );
			if ( null === $alias_reference ) {
				continue;
			}

			if ( false === $alias_reference ) {
				return null;
			}

			$replacements[] = array(
				'start' => $position,
				'end'   => $alias_reference['end'],
				'sql'   => sprintf(
					'excluded.%s',
					$this->connection->quote_identifier( $alias_reference['column'] )
				),
			);
			$position       = $alias_reference['end'] - 1;
		}

		return $replacements;
	}

	/**
	 * Get replacements for supported DEFAULT(column) references in an upsert expression.
	 *
	 * @param WP_MySQL_Token[] $tokens              MySQL lexer token stream.
	 * @param int              $start               First expression token.
	 * @param int              $end                 Final expression token, exclusive.
	 * @param array            $table_column_lookup Table-column metadata lookup by lowercase name.
	 * @return array[]|null Replacement ranges, or null when DEFAULT() is malformed/unsupported.
	 */
	private function get_mysql_upsert_default_expression_replacements( array $tokens, int $start, int $end, array $table_column_lookup ): ?array {
		$replacements = array();

		for ( $position = $start; $position < $end; $position++ ) {
			if ( WP_MySQL_Lexer::DEFAULT_SYMBOL !== $tokens[ $position ]->id ) {
				continue;
			}

			if (
				$position + 4 > $end
				|| ! isset( $tokens[ $position + 1 ], $tokens[ $position + 2 ], $tokens[ $position + 3 ] )
				|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
				|| WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== $tokens[ $position + 3 ]->id
			) {
				return null;
			}

			$column_name = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 2 ] );
			$column_key  = null === $column_name ? null : strtolower( $column_name );
			if ( null === $column_key || ! isset( $table_column_lookup[ $column_key ] ) ) {
				return null;
			}

			$replacements[] = array(
				'start' => $position,
				'end'   => $position + 4,
				'sql'   => $this->get_mysql_dml_default_assignment_sql_for_column( $table_column_lookup[ $column_key ] ),
			);
			$position      += 3;
		}

		return $replacements;
	}

	/**
	 * Get replacements for supported scalar subqueries in an upsert expression.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First expression token.
	 * @param int              $end    Final expression token, exclusive.
	 * @param array            $scope  Statement table scope.
	 * @return array[]|null Replacement ranges, or null when a scalar subquery is unsupported.
	 */
	private function get_mysql_upsert_scalar_subquery_expression_replacements( array $tokens, int $start, int $end, array $scope ): ?array {
		$replacements = array();

		for ( $position = $start; $position < $end; $position++ ) {
			if (
				! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
				|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id
				|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position + 1 ]->id
			) {
				continue;
			}

			$after_subquery = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
			if ( null === $after_subquery ) {
				return null;
			}

			$sql = $this->get_mysql_upsert_scalar_subquery_assignment_sql( $tokens, $position, $after_subquery, $scope );
			if ( null === $sql ) {
				return null;
			}

			$replacements[] = array(
				'start' => $position,
				'end'   => $after_subquery,
				'sql'   => $sql,
			);
			$position       = $after_subquery - 1;
		}

		return $replacements;
	}

	/**
	 * Get replacements for target-row column references in an upsert expression.
	 *
	 * PostgreSQL exposes both the target row and excluded row inside
	 * ON CONFLICT DO UPDATE. Qualify validated target-row references so names
	 * shared by excluded cannot become ambiguous.
	 *
	 * @param string           $table_name          Target table name.
	 * @param WP_MySQL_Token[] $tokens              MySQL lexer token stream.
	 * @param int              $start               First expression token.
	 * @param int              $end                 Final expression token, exclusive.
	 * @param array            $scope               Statement table scope.
	 * @param array            $table_column_lookup Table-column metadata lookup by lowercase name.
	 * @param array[]          $protected_ranges    Ranges already handled by larger replacements.
	 * @return array[]|null Replacement ranges, or null when a column-like reference is unsupported.
	 */
	private function get_mysql_upsert_target_column_expression_replacements( string $table_name, array $tokens, int $start, int $end, array $scope, array $table_column_lookup, array $protected_ranges ): ?array {
		$replacements = array();

		for ( $position = $start; $position < $end; $position++ ) {
			$protected_end = $this->get_covering_mysql_replacement_range_end( $position, $protected_ranges );
			if ( null !== $protected_end ) {
				$position = $protected_end - 1;
				continue;
			}

			if ( $this->is_mysql_qualified_reference_suffix_position( $tokens, $position, $start ) ) {
				continue;
			}

			if ( null !== $this->translate_mysql_nonparenthesized_timestamp_function_to_postgresql( $tokens, $position, $end ) ) {
				continue;
			}

			$temporal_cast_end = $this->get_mysql_temporal_cast_or_convert_expression_end( $tokens, $position, $end );
			if ( null !== $temporal_cast_end ) {
				$position = $temporal_cast_end - 1;
				continue;
			}

			if ( null === $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] ?? null ) ) {
				continue;
			}

			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === ( $tokens[ $position + 1 ]->id ?? null ) ) {
				continue;
			}

			$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
			if ( null === $reference ) {
				continue;
			}

			if (
				null !== $reference['qualifier']
				&& ! $this->is_mysql_dml_table_qualifier( $reference['qualifier'], $table_name, null )
			) {
				return null;
			}

			$column_key = strtolower( $reference['column'] );
			if (
				null === $this->get_mysql_column_type_for_reference( $reference, $scope )
				|| ! isset( $table_column_lookup[ $column_key ] )
			) {
				return null;
			}

			$column_name    = (string) ( $table_column_lookup[ $column_key ]['column_name'] ?? $reference['column'] );
			$replacements[] = array(
				'start' => $reference['start'],
				'end'   => $reference['end'],
				'sql'   => $this->get_postgresql_dml_column_reference_sql( $column_name, $table_name ),
			);
			$position       = $reference['end'] - 1;
		}

		return $replacements;
	}

	/**
	 * Check whether unreplaced expression segments contain unsupported CONVERT() forms.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $start        First expression token.
	 * @param int              $end          Final expression token, exclusive.
	 * @param array[]          $replacements Replacement ranges.
	 * @return bool Whether an unsupported CONVERT() appears outside replacements.
	 */
	private function contains_unsupported_mysql_convert_function_outside_replacements( array $tokens, int $start, int $end, array $replacements ): bool {
		$segment_start = $start;
		foreach ( $replacements as $replacement ) {
			if (
				$segment_start < $replacement['start']
				&& $this->contains_unsupported_mysql_convert_function( $tokens, $segment_start, $replacement['start'] )
			) {
				return true;
			}

			$segment_start = max( $segment_start, $replacement['end'] );
		}

		return $segment_start < $end
			&& $this->contains_unsupported_mysql_convert_function( $tokens, $segment_start, $end );
	}

	/**
	 * Check whether unreplaced expression segments contain unsupported common functions.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $start        First expression token.
	 * @param int              $end          Final expression token, exclusive.
	 * @param array[]          $replacements Replacement ranges.
	 * @return bool Whether an unsupported common function appears outside replacements.
	 */
	private function contains_unsupported_mysql_common_function_outside_replacements( array $tokens, int $start, int $end, array $replacements ): bool {
		$segment_start = $start;
		foreach ( $replacements as $replacement ) {
			if (
				$segment_start < $replacement['start']
				&& $this->contains_unsupported_mysql_common_function( $tokens, $segment_start, $replacement['start'] )
			) {
				return true;
			}

			$segment_start = max( $segment_start, $replacement['end'] );
		}

		return $segment_start < $end
			&& $this->contains_unsupported_mysql_common_function( $tokens, $segment_start, $end );
	}

	/**
	 * Translate an upsert assignment expression while replacing VALUES()/DEFAULT() references.
	 *
	 * Runtime functions that wrap replacement expressions need to see the translated
	 * replacement inside their arguments so they keep MySQL semantics.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $start        First expression token.
	 * @param int              $end          Final expression token, exclusive.
	 * @param array[]          $replacements Replacement ranges.
	 * @return string|null PostgreSQL SQL, or null when unsupported.
	 */
	private function translate_mysql_upsert_expression_token_sequence_with_replacements_to_postgresql( array $tokens, int $start, int $end, array $replacements ): ?string {
		if ( empty( $replacements ) ) {
			return $this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end );
		}

		usort(
			$replacements,
			static function ( array $a, array $b ): int {
				return ( $a['start'] ?? 0 ) <=> ( $b['start'] ?? 0 );
			}
		);

			$temporal_arithmetic_sql = $this->translate_mysql_upsert_temporal_arithmetic_expression_with_replacements_to_postgresql(
				$tokens,
				$start,
				$end,
				$replacements
			);
		if ( null !== $temporal_arithmetic_sql ) {
			return $temporal_arithmetic_sql;
		}

			$chunks   = array();
			$position = $start;
		while ( $position < $end ) {
			$replacement = $this->get_mysql_token_sequence_replacement_at_position( $replacements, $position );
			if ( null !== $replacement ) {
				$chunks[] = $replacement['sql'];
				$position = $replacement['end'];
				continue;
			}

			$function = $this->translate_mysql_common_function_with_replacements_to_postgresql( $tokens, $position, $end, $replacements );
			if ( false === $function ) {
				return null;
			}
			if ( is_array( $function ) ) {
				$chunks[] = $function['sql'];
				$position = $function['position'] + 1;
				continue;
			}

			$segment_end = $end;
			foreach ( $replacements as $candidate ) {
				if ( $candidate['start'] > $position ) {
					$segment_end = min( $segment_end, $candidate['start'] );
					break;
				}
			}

			for ( $scan = $position; $scan < $segment_end; $scan++ ) {
				$bounds = $this->get_mysql_common_function_bounds( $tokens, $scan, $end );
				if (
					null !== $bounds
					&& $this->mysql_token_sequence_replacements_intersect_range( $replacements, $scan, $bounds['close'] + 1 )
				) {
					$segment_end = $scan;
					break;
				}
			}

			if ( $segment_end <= $position ) {
				return null;
			}

			$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $position, $segment_end );
			$position = $segment_end;
		}

			return implode( ' ', array_filter( $chunks, 'strlen' ) );
	}

	/**
	 * Translate a MySQL temporal arithmetic expression while preserving upsert replacements.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $start        First expression token.
	 * @param int              $end          Final expression token, exclusive.
	 * @param array[]          $replacements Replacement ranges.
	 * @return string|null PostgreSQL SQL, or null when the expression is not supported temporal arithmetic.
	 */
	private function translate_mysql_upsert_temporal_arithmetic_expression_with_replacements_to_postgresql( array $tokens, int $start, int $end, array $replacements ): ?string {
		$date_arithmetic = $this->get_mysql_date_arithmetic_function_bounds( $tokens, $start, $end );
		if ( null !== $date_arithmetic && $date_arithmetic['close'] + 1 === $end ) {
			return $this->get_postgresql_mysql_temporal_arithmetic_sql_with_replacements(
				$tokens,
				$date_arithmetic,
				$replacements
			);
		}

		$infix_arithmetic = $this->get_mysql_infix_interval_expression_bounds( $tokens, $start, $end );
		if ( null !== $infix_arithmetic && $infix_arithmetic['close'] + 1 === $end ) {
			return $this->get_postgresql_mysql_temporal_arithmetic_sql_with_replacements(
				$tokens,
				$infix_arithmetic,
				$replacements
			);
		}

		$bounds = $this->get_mysql_common_function_bounds( $tokens, $start, $end );
		if (
			null === $bounds
			|| $bounds['close'] + 1 !== $end
			|| 'timestampadd' !== $bounds['function']
		) {
			return null;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
		if ( null === $arguments || 3 !== count( $arguments ) ) {
			return null;
		}

		$interval = $this->get_mysql_timestampadd_interval(
			$tokens,
			$arguments[0]['start'],
			$arguments[0]['end'],
			$arguments[1]['start'],
			$arguments[1]['end']
		);
		if ( null === $interval ) {
			return null;
		}

		$interval_sql = $interval['sql'] ?? null;
		if ( null === $interval_sql ) {
			$value_sql = $this->translate_mysql_upsert_expression_token_sequence_with_replacements_to_postgresql(
				$tokens,
				$arguments[1]['start'],
				$arguments[1]['end'],
				$this->get_mysql_token_sequence_replacements_for_range( $replacements, $arguments[1]['start'], $arguments[1]['end'] )
			);
			if ( null === $value_sql ) {
				return null;
			}

			$interval_sql = $this->get_postgresql_mysql_interval_sql( $value_sql, $interval['unit'] );
		}

		$datetime_sql = $this->translate_mysql_upsert_expression_token_sequence_with_replacements_to_postgresql(
			$tokens,
			$arguments[2]['start'],
			$arguments[2]['end'],
			$this->get_mysql_token_sequence_replacements_for_range( $replacements, $arguments[2]['start'], $arguments[2]['end'] )
		);
		if ( null === $datetime_sql ) {
			return null;
		}

		return sprintf(
			'(%1$s + %2$s)',
			$this->get_postgresql_zero_date_safe_timestamp_sql( $datetime_sql ),
			$interval_sql
		);
	}

	/**
	 * Get PostgreSQL SQL for date arithmetic bounds while preserving upsert replacements.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param array            $bounds       Date arithmetic bounds.
	 * @param array[]          $replacements Replacement ranges.
	 * @return string|null PostgreSQL SQL, or null when translation fails.
	 */
	private function get_postgresql_mysql_temporal_arithmetic_sql_with_replacements( array $tokens, array $bounds, array $replacements ): ?string {
		$expression_sql = $this->translate_mysql_upsert_expression_token_sequence_with_replacements_to_postgresql(
			$tokens,
			$bounds['expression_start'],
			$bounds['expression_end'],
			$this->get_mysql_token_sequence_replacements_for_range( $replacements, $bounds['expression_start'], $bounds['expression_end'] )
		);
		if ( null === $expression_sql ) {
			return null;
		}

		$interval_sql = $bounds['interval_sql'] ?? null;
		if ( null === $interval_sql ) {
			$value_sql = $this->translate_mysql_upsert_expression_token_sequence_with_replacements_to_postgresql(
				$tokens,
				$bounds['interval_value_start'],
				$bounds['interval_value_end'],
				$this->get_mysql_token_sequence_replacements_for_range( $replacements, $bounds['interval_value_start'], $bounds['interval_value_end'] )
			);
			if ( null === $value_sql ) {
				return null;
			}

			$interval_sql = $this->get_postgresql_mysql_interval_sql( $value_sql, $bounds['interval_unit'] );
		}

		return sprintf(
			'(%1$s %2$s %3$s)',
			$this->get_postgresql_zero_date_safe_timestamp_sql( $expression_sql ),
			$bounds['operator'],
			$interval_sql
		);
	}

	/**
	 * Translate a supported MySQL runtime function containing replacement ranges.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $position     Function token position.
	 * @param int              $end          Final token position, exclusive.
	 * @param array[]          $replacements Replacement ranges.
	 * @return array{sql:string,position:int}|false|null Translation data, false when unsupported, or null when not a split function.
	 */
	private function translate_mysql_common_function_with_replacements_to_postgresql( array $tokens, int $position, int $end, array $replacements ) {
		$bounds = $this->get_mysql_common_function_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		$function_end = $bounds['close'] + 1;
		if ( ! $this->mysql_token_sequence_replacements_intersect_range( $replacements, $position, $function_end ) ) {
			return null;
		}

		if ( in_array( $bounds['function'], array( 'last_insert_id', 'timestampadd', 'timestampdiff' ), true ) ) {
			return false;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
		if ( null === $arguments ) {
			return false;
		}

		if ( 'substring' === $bounds['function'] ) {
			$arguments = $this->get_mysql_substring_function_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
			if ( null === $arguments ) {
				return false;
			}
		}

		if ( 'trim' === $bounds['function'] ) {
			$trim_bounds = $this->get_mysql_trim_function_bounds( $tokens, $position, $end );
			if ( null === $trim_bounds ) {
				return false;
			}

			$value_sql = $this->translate_mysql_upsert_expression_token_sequence_with_replacements_to_postgresql(
				$tokens,
				$trim_bounds['argument_start'],
				$trim_bounds['argument_end'],
				$this->get_mysql_token_sequence_replacements_for_range( $replacements, $trim_bounds['argument_start'], $trim_bounds['argument_end'] )
			);
			if ( null === $value_sql ) {
				return false;
			}

			$remove_sql = null;
			if ( null !== $trim_bounds['remove_start'] && null !== $trim_bounds['remove_end'] ) {
				$remove_sql = $this->translate_mysql_upsert_expression_token_sequence_with_replacements_to_postgresql(
					$tokens,
					$trim_bounds['remove_start'],
					$trim_bounds['remove_end'],
					$this->get_mysql_token_sequence_replacements_for_range( $replacements, $trim_bounds['remove_start'], $trim_bounds['remove_end'] )
				);
				if ( null === $remove_sql ) {
					return false;
				}
			}

			return array(
				'sql'      => $this->get_postgresql_mysql_trim_sql( $trim_bounds['direction'], $value_sql, $trim_bounds['remove'], $remove_sql ),
				'position' => $trim_bounds['close'],
			);
		}

		$argument_sql = array();
		foreach ( $arguments as $argument ) {
			$sql = $this->translate_mysql_upsert_expression_token_sequence_with_replacements_to_postgresql(
				$tokens,
				$argument['start'],
				$argument['end'],
				$this->get_mysql_token_sequence_replacements_for_range( $replacements, $argument['start'], $argument['end'] )
			);
			if ( null === $sql ) {
				return false;
			}

			$argument_sql[] = $sql;
		}

		if ( 'if' === $bounds['function'] && 3 === count( $argument_sql ) ) {
			$condition_sql = $this->is_mysql_boolean_condition_expression(
				$tokens,
				$arguments[0]['start'],
				$arguments[0]['end']
			)
				? '(' . $argument_sql[0] . ')'
				: $this->get_postgresql_mysql_truthy_expression_sql( $argument_sql[0] );
			$sql           = sprintf( 'CASE WHEN %s THEN %s ELSE %s END', $condition_sql, $argument_sql[1], $argument_sql[2] );
		} else {
			$sql = $this->get_postgresql_mysql_common_function_sql( $bounds['function'], $argument_sql );
			if ( null === $sql ) {
				return false;
			}
		}

		return array(
			'sql'      => $sql,
			'position' => $bounds['close'],
		);
	}

	/**
	 * Get a replacement that starts at the given token position.
	 *
	 * @param array[] $replacements Replacement ranges.
	 * @param int     $position     Token position.
	 * @return array|null Replacement range, or null when none starts here.
	 */
	private function get_mysql_token_sequence_replacement_at_position( array $replacements, int $position ): ?array {
		foreach ( $replacements as $replacement ) {
			if ( $replacement['start'] === $position ) {
				return $replacement;
			}
		}

		return null;
	}

	/**
	 * Get replacement ranges fully contained by a token range.
	 *
	 * @param array[] $replacements Replacement ranges.
	 * @param int     $start        Range start.
	 * @param int     $end          Range end.
	 * @return array[] Replacement ranges contained by the range.
	 */
	private function get_mysql_token_sequence_replacements_for_range( array $replacements, int $start, int $end ): array {
		$ranged_replacements = array();
		foreach ( $replacements as $replacement ) {
			if ( $replacement['start'] >= $start && $replacement['end'] <= $end ) {
				$ranged_replacements[] = $replacement;
			}
		}

		return $ranged_replacements;
	}

	/**
	 * Check whether replacement ranges overlap a token range.
	 *
	 * @param array[] $replacements Replacement ranges.
	 * @param int     $start        Range start.
	 * @param int     $end          Range end.
	 * @return bool Whether any replacement overlaps the range.
	 */
	private function mysql_token_sequence_replacements_intersect_range( array $replacements, int $start, int $end ): bool {
		foreach ( $replacements as $replacement ) {
			if ( $replacement['start'] < $end && $replacement['end'] > $start ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Get an exact alias source column from an upsert assignment expression.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param int              $start          First expression token.
	 * @param int              $end            Final expression token, exclusive.
	 * @param array            $source_aliases Optional VALUES-row alias lookup.
	 * @return string|null Source column name, or null when the expression is not an alias reference.
	 */
	private function get_mysql_upsert_alias_assignment_source_column( array $tokens, int $start, int $end, array $source_aliases ): ?string {
		$reference = $this->get_mysql_upsert_alias_expression_reference( $tokens, $start, $start, $end, $source_aliases );
		if ( ! is_array( $reference ) || $reference['end'] !== $end ) {
			return null;
		}

		return $reference['column'];
	}

	/**
	 * Resolve a VALUES-row alias reference inside an upsert expression.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param int              $position       Candidate reference position.
	 * @param int              $start          First expression token.
	 * @param int              $end            Final expression token, exclusive.
	 * @param array            $source_aliases Optional VALUES-row alias lookup.
	 * @return array{column: string, end: int}|false|null Reference data, false for malformed alias use, or null when not an alias reference.
	 */
	private function get_mysql_upsert_alias_expression_reference( array $tokens, int $position, int $start, int $end, array $source_aliases ) {
		if ( empty( $source_aliases ) || ! isset( $tokens[ $position ] ) ) {
			return null;
		}

		$identifier = $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] );
		if ( null === $identifier ) {
			return null;
		}

		$identifier_key = strtolower( $identifier );
		if ( ( $source_aliases['row'] ?? null ) === $identifier_key ) {
			if (
			$position + 2 >= $end
			|| WP_MySQL_Lexer::DOT_SYMBOL !== ( $tokens[ $position + 1 ]->id ?? null )
			) {
				return false;
			}

			$source_column = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 2 ] ?? null );
			if ( null === $source_column ) {
				return false;
			}

			$source_key = strtolower( $source_column );
			if ( ! isset( $source_aliases['qualified'][ $source_key ] ) ) {
				return false;
			}

			return array(
				'column' => $source_aliases['qualified'][ $source_key ],
				'end'    => $position + 3,
			);
		}

		if (
			isset( $source_aliases['unqualified'][ $identifier_key ] )
			&& ( $position <= $start || WP_MySQL_Lexer::DOT_SYMBOL !== ( $tokens[ $position - 1 ]->id ?? null ) )
			&& ( $position + 1 >= $end || WP_MySQL_Lexer::DOT_SYMBOL !== ( $tokens[ $position + 1 ]->id ?? null ) )
			&& ( $position + 1 >= $end || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== ( $tokens[ $position + 1 ]->id ?? null ) )
		) {
			return array(
				'column' => $source_aliases['unqualified'][ $identifier_key ],
				'end'    => $position + 1,
			);
		}

		return null;
	}

	/**
	 * Check whether an upsert expression is simple after removing replacement ranges.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $start        First expression token.
	 * @param int              $end          Final expression token, exclusive.
	 * @param array[]          $replacements Replacement ranges.
	 * @return bool Whether the expression is supported.
	 */
	private function is_supported_simple_mysql_upsert_expression_fragment( array $tokens, int $start, int $end, array $replacements ): bool {
		if ( ! empty( $replacements ) ) {
			usort(
				$replacements,
				static function ( array $a, array $b ): int {
					return ( $a['start'] ?? 0 ) <=> ( $b['start'] ?? 0 );
				}
			);

			for ( $position = $start; $position < $end; ) {
				$temporal_arithmetic_sql = $this->translate_mysql_upsert_temporal_arithmetic_expression_with_replacements_to_postgresql(
					$tokens,
					$position,
					$end,
					$replacements
				);
				if ( null !== $temporal_arithmetic_sql ) {
					$position = $end;
					continue;
				}

				$date_arithmetic = $this->translate_mysql_date_arithmetic_to_postgresql( $tokens, $position, $end );
				if ( null !== $date_arithmetic ) {
					$position = $date_arithmetic['position'] + 1;
					continue;
				}

				$infix_interval = $this->translate_mysql_infix_interval_expression_to_postgresql( $tokens, $position, $end );
				if ( null !== $infix_interval ) {
					$position = $infix_interval['position'] + 1;
					continue;
				}

				$replacement = $this->get_mysql_token_sequence_replacement_at_position( $replacements, $position );
				if ( null !== $replacement ) {
					$position = $replacement['end'];
					continue;
				}

				$function = $this->translate_mysql_common_function_with_replacements_to_postgresql( $tokens, $position, $end, $replacements );
				if ( false === $function ) {
					return false;
				}
				if ( is_array( $function ) ) {
					$position = $function['position'] + 1;
					continue;
				}

				$segment_end = $end;
				foreach ( $replacements as $candidate ) {
					if ( $candidate['start'] > $position ) {
						$segment_end = min( $segment_end, $candidate['start'] );
						break;
					}
				}

				if ( $segment_end <= $position || ! $this->is_supported_simple_mysql_upsert_expression_segment( $tokens, $position, $segment_end ) ) {
					return false;
				}

				$position = $segment_end;
			}

			return true;
		}

		$segment_start = $start;
		foreach ( $replacements as $replacement ) {
			if (
				$segment_start < $replacement['start']
				&& ! $this->is_supported_simple_mysql_upsert_expression_segment( $tokens, $segment_start, $replacement['start'] )
			) {
				return false;
			}

			$segment_start = $replacement['end'];
		}

		return $segment_start >= $end
			|| $this->is_supported_simple_mysql_upsert_expression_segment( $tokens, $segment_start, $end );
	}

	/**
	 * Check upsert expression column references after removing replacement ranges.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $start        First expression token.
	 * @param int              $end          Final expression token, exclusive.
	 * @param array[]          $replacements Replacement ranges.
	 * @param array            $scope        Statement table scope.
	 * @return bool Whether all column-like references resolve to the supplied scope.
	 */
	private function mysql_upsert_expression_column_references_resolve_to_scope( array $tokens, int $start, int $end, array $replacements, array $scope ): bool {
		$segment_start = $start;
		foreach ( $replacements as $replacement ) {
			if (
				$segment_start < $replacement['start']
				&& ! $this->mysql_expression_column_references_resolve_to_scope( $tokens, $segment_start, $replacement['start'], $scope )
			) {
				return false;
			}

			$segment_start = $replacement['end'];
		}

		return $segment_start >= $end
			|| $this->mysql_expression_column_references_resolve_to_scope( $tokens, $segment_start, $end, $scope );
	}

	/**
	 * Check whether an upsert expression segment contains supported tokens.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First segment token.
	 * @param int              $end    Final segment token, exclusive.
	 * @return bool Whether the segment is supported.
	 */
	private function is_supported_simple_mysql_upsert_expression_segment( array $tokens, int $start, int $end ): bool {
		for ( $position = $start; $position < $end; $position++ ) {
			$date_arithmetic = $this->translate_mysql_date_arithmetic_to_postgresql( $tokens, $position, $end );
			if ( null !== $date_arithmetic ) {
				$position = $date_arithmetic['position'];
				continue;
			}

			$infix_interval = $this->translate_mysql_infix_interval_expression_to_postgresql( $tokens, $position, $end );
			if ( null !== $infix_interval ) {
				$position = $infix_interval['position'];
				continue;
			}

			$temporal_cast_end = $this->get_mysql_temporal_cast_or_convert_expression_end( $tokens, $position, $end );
			if ( null !== $temporal_cast_end ) {
				$position = $temporal_cast_end - 1;
				continue;
			}

			$common_function = $this->translate_mysql_common_function_to_postgresql( $tokens, $position, $end );
			if ( null !== $common_function ) {
				$position = $common_function['position'];
				continue;
			}

			if ( WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $tokens[ $position ]->id ) {
				continue;
			}

			if ( ! $this->is_supported_simple_mysql_expression_token( $tokens[ $position ] ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Validate the narrow SET clause supported by the simple UPDATE translator.
	 *
	 * @param string           $table_name Table name.
	 * @param string|null      $alias      Optional table alias.
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $start      First SET-clause token position.
	 * @param int              $end        Final SET-clause token position, exclusive.
	 * @return bool Whether the SET clause is supported.
	 */
	private function is_supported_simple_update_set_clause( string $table_name, ?string $alias, array $tokens, int $start, int $end ): bool {
		for ( $position = $start; $position < $end; ) {
			$target = $this->parse_simple_mysql_update_assignment_target( $table_name, $alias, $tokens, $position, $end );
			if ( null === $target || ! isset( $tokens[ $target['end'] ] ) || WP_MySQL_Lexer::EQUAL_OPERATOR !== $tokens[ $target['end'] ]->id ) {
				return false;
			}

			$value_start    = $target['end'] + 1;
			$assignment_end = $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::COMMA_SYMBOL,
				$value_start,
				$end
			) ?? $end;

			if (
				$value_start >= $assignment_end
				|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $value_start, $assignment_end )
			) {
				return false;
			}

			$position = $assignment_end;
			if ( $position === $end ) {
				return true;
			}

			++$position;
		}

		return false;
	}

	/**
	 * Validate a simple SELECT projection list.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection token position.
	 * @param int             $end    Final projection token position, exclusive.
	 * @return bool Whether the projection is supported.
	 */
	private function is_supported_simple_select_projection( array $tokens, int $start, int $end ): bool {
		if ( $start + 1 === $end && WP_MySQL_Lexer::MULT_OPERATOR === $tokens[ $start ]->id ) {
			return true;
		}

		if ( $this->is_supported_simple_select_count_projection( $tokens, $start, $end ) ) {
			return true;
		}

		$ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $ranges || array() === $ranges ) {
			return false;
		}

		foreach ( $ranges as $range ) {
			$reference = $this->parse_mysql_column_reference( $tokens, $range['start'], $range['end'] );
			if ( null === $reference || $reference['end'] !== $range['end'] ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Validate the supported COUNT(identifier|*) projection shape.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection token position.
	 * @param int             $end    Final projection token position, exclusive.
	 * @return bool Whether the aggregate projection is supported.
	 */
	private function is_supported_simple_select_count_projection( array $tokens, int $start, int $end ): bool {
		if (
			! isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ], $tokens[ $start + 3 ] )
			|| WP_MySQL_Lexer::COUNT_SYMBOL !== $tokens[ $start ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $start + 1 ]->id
			|| (
				WP_MySQL_Lexer::MULT_OPERATOR !== $tokens[ $start + 2 ]->id
				&& null === $this->get_mysql_identifier_token_value( $tokens[ $start + 2 ] )
			)
			|| WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== $tokens[ $start + 3 ]->id
		) {
			return false;
		}

		if ( $start + 4 === $end ) {
			return true;
		}

		return $start + 6 === $end
			&& WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $start + 4 ]->id
			&& null !== $this->get_mysql_identifier_token_value( $tokens[ $start + 5 ] );
	}

	/**
	 * Translate a supported simple SELECT projection to PostgreSQL.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection token position.
	 * @param int             $end    Final projection token position, exclusive.
	 * @return string PostgreSQL projection SQL.
	 */
	private function translate_simple_select_projection_to_postgresql( array $tokens, int $start, int $end ): string {
		if ( $this->is_supported_simple_select_count_projection( $tokens, $start, $end ) ) {
			$count_argument_sql = WP_MySQL_Lexer::MULT_OPERATOR === $tokens[ $start + 2 ]->id
				? '*'
				: $this->translate_mysql_identifier_token_to_postgresql( $tokens[ $start + 2 ] );
			$sql                = sprintf(
				'COUNT(%s)',
				$count_argument_sql
			);

			if ( $start + 6 === $end ) {
				$sql .= ' ' . $tokens[ $start + 4 ]->get_bytes() . ' ' . $this->translate_mysql_identifier_token_to_postgresql( $tokens[ $start + 5 ] );
			}

			return $sql;
		}

		return $this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end );
	}

	/**
	 * Translate a SELECT while applying metadata-backed expression coercions.
	 *
	 * @param WP_MySQL_Token[] $tokens                   MySQL lexer token stream.
	 * @param int             $projection_start         First token after SELECT modifiers to render.
	 * @param int             $statement_end            Final statement token position, exclusive.
	 * @param bool            $require_contextual_change Whether unchanged statements should fall through.
	 * @return string|null PostgreSQL SELECT SQL, or null when no safe contextual translation applies.
	 */
	private function translate_mysql_select_statement_with_integer_string_coercion(
		array $tokens,
		int $projection_start,
		int $statement_end,
		bool $require_contextual_change
	): ?string {
		$replacements = $this->get_mysql_select_statement_contextual_replacements(
			$tokens,
			$projection_start,
			$statement_end
		);
		if ( null === $replacements ) {
			return null;
		}

		if ( $require_contextual_change && empty( $replacements ) ) {
			return null;
		}

		return 'SELECT ' . $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
			$tokens,
			$projection_start,
			$statement_end,
			$replacements
		);
	}

	/**
	 * Get metadata-backed replacements for SELECT WHERE and ORDER BY clauses.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int              $projection_start First token after SELECT modifiers to render.
	 * @param int              $statement_end    Final statement token position, exclusive.
	 * @return array[]|null Replacement ranges, or null when contextual rewriting is unavailable.
	 */
	private function get_mysql_select_statement_contextual_replacements(
		array $tokens,
		int $projection_start,
		int $statement_end
	): ?array {
		$where_position  = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::WHERE_SYMBOL,
			$projection_start,
			$statement_end
		);
		$having_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::HAVING_SYMBOL,
			$projection_start,
			$statement_end
		);
		$order_position  = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::ORDER_SYMBOL,
			$projection_start,
			$statement_end
		);
		if ( null === $where_position && null === $having_position && null === $order_position ) {
			return null;
		}

		$first_clause_position = min( array_filter( array( $where_position, $having_position, $order_position ), 'is_int' ) );
		$from_position         = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::FROM_SYMBOL,
			$projection_start,
			$first_clause_position
		);
		if ( null === $from_position ) {
			return null;
		}

		$from_end = $this->find_first_top_level_mysql_token(
			$tokens,
			array(
				WP_MySQL_Lexer::FOR_SYMBOL,
				WP_MySQL_Lexer::GROUP_SYMBOL,
				WP_MySQL_Lexer::HAVING_SYMBOL,
				WP_MySQL_Lexer::LIMIT_SYMBOL,
				WP_MySQL_Lexer::LOCK_SYMBOL,
				WP_MySQL_Lexer::ORDER_SYMBOL,
				WP_MySQL_Lexer::PROCEDURE_SYMBOL,
				WP_MySQL_Lexer::UNION_SYMBOL,
				WP_MySQL_Lexer::WHERE_SYMBOL,
			),
			$from_position + 1,
			$statement_end
		) ?? $statement_end;

		$scope = $this->get_mysql_select_scope( $tokens, $from_position + 1, $from_end );
		if ( null === $scope ) {
			return null;
		}

		$replacements = $this->get_mysql_select_projection_contextual_replacements(
			$tokens,
			$projection_start,
			$from_position,
			$scope
		);
		if ( null === $replacements ) {
			return null;
		}

		$group_position_before_having = null === $having_position
			? null
			: $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::GROUP_SYMBOL, $projection_start, $having_position );

		if ( null !== $where_position ) {
			$where_end = $this->find_first_top_level_mysql_token(
				$tokens,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				),
				$where_position + 1,
				$statement_end
			) ?? $statement_end;

			$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$where_position + 1,
				$where_end,
				$scope
			);
			if ( $where_sql['changed'] && ( null === $having_position || null !== $group_position_before_having ) ) {
				$replacements[] = array(
					'start' => $where_position + 1,
					'end'   => $where_end,
					'sql'   => $where_sql['sql'],
				);
			}
		}

		if ( null !== $having_position && null === $group_position_before_having ) {
			$having_end = $this->find_first_top_level_mysql_token(
				$tokens,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				),
				$having_position + 1,
				$statement_end
			) ?? $statement_end;

			$having_replacements = $this->get_mysql_having_without_group_by_contextual_replacements(
				$tokens,
				$projection_start,
				$from_position,
				$having_position,
				$having_end,
				$where_position,
				$scope
			);
			if ( null !== $having_replacements ) {
				$replacements = array_merge( $replacements, $having_replacements );
			}
		}

		if (
			null !== $order_position
			&& isset( $tokens[ $order_position + 1 ] )
			&& WP_MySQL_Lexer::BY_SYMBOL === $tokens[ $order_position + 1 ]->id
		) {
			$order_end = $this->find_first_top_level_mysql_token(
				$tokens,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				),
				$order_position + 2,
				$statement_end
			) ?? $statement_end;

			$order_sql = $this->translate_mysql_order_by_token_sequence_to_postgresql(
				$tokens,
				$order_position + 2,
				$order_end,
				$scope,
				! $this->contains_top_level_mysql_token(
					$tokens,
					$projection_start,
					$statement_end,
					array(
						WP_MySQL_Lexer::DISTINCT_SYMBOL,
						WP_MySQL_Lexer::GROUP_SYMBOL,
						WP_MySQL_Lexer::HAVING_SYMBOL,
					)
				)
			);
			if ( $order_sql['changed'] ) {
				$replacements[] = array(
					'start' => $order_position + 2,
					'end'   => $order_end,
					'sql'   => $order_sql['sql'],
				);
			}
		}

		$replacements = array_merge(
			$replacements,
			$this->get_mysql_select_implicit_order_contextual_replacements(
				$tokens,
				$projection_start,
				$from_position,
				$from_end,
				$where_position,
				$order_position,
				$statement_end
			)
		);

		return $replacements;
	}

	/**
	 * Get replacements for SELECT shapes where WordPress depends on MySQL's implicit index order.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int              $projection_start First projection token position.
	 * @param int              $from_position    FROM token position.
	 * @param int              $from_end         Final FROM-clause token, exclusive.
	 * @param int|null         $where_position   WHERE token position, or null.
	 * @param int|null         $order_position   ORDER token position, or null.
	 * @param int              $statement_end    Final statement token position, exclusive.
	 * @return array[] Replacement ranges.
	 */
	private function get_mysql_select_implicit_order_contextual_replacements(
		array $tokens,
		int $projection_start,
		int $from_position,
		int $from_end,
		?int $where_position,
		?int $order_position,
		int $statement_end
	): array {
		if ( $this->is_wordpress_available_post_mime_types_select_shape( $tokens, $projection_start, $statement_end ) ) {
			return array(
				array(
					'start' => $projection_start,
					'end'   => $projection_start + 1,
					'sql'   => '',
				),
				array(
					'start' => $statement_end,
					'end'   => $statement_end,
					'sql'   => 'GROUP BY post_mime_type ORDER BY MIN("ID") ASC',
				),
			);
		}

		if (
			null !== $order_position
			|| null === $where_position
			|| ! $this->is_wordpress_term_cache_priming_select_shape(
				$tokens,
				$projection_start,
				$from_position,
				$from_end,
				$where_position,
				$statement_end
			)
		) {
			return array();
		}

		return array(
			array(
				'start' => $statement_end,
				'end'   => $statement_end,
				'sql'   => 'ORDER BY tt.term_taxonomy_id ASC',
			),
		);
	}

	/**
	 * Check for WordPress's get_available_post_mime_types() SELECT shape.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int              $projection_start First projection token position.
	 * @param int              $statement_end    Final statement token position, exclusive.
	 * @return bool Whether the SELECT needs first-post-ID ordering.
	 */
	private function is_wordpress_available_post_mime_types_select_shape( array $tokens, int $projection_start, int $statement_end ): bool {
		$table_name = $this->get_mysql_identifier_token_value( $tokens[ $projection_start + 3 ] ?? null );

		return $projection_start + 12 === $statement_end
			&& isset( $tokens[ $projection_start + 11 ] )
			&& WP_MySQL_Lexer::DISTINCT_SYMBOL === $tokens[ $projection_start ]->id
			&& $this->is_mysql_identifier_like_token_value( $tokens[ $projection_start + 1 ], 'post_mime_type' )
			&& WP_MySQL_Lexer::FROM_SYMBOL === $tokens[ $projection_start + 2 ]->id
			&& null !== $table_name
			&& $this->is_mysql_wordpress_table_name( $table_name, 'posts' )
			&& WP_MySQL_Lexer::WHERE_SYMBOL === $tokens[ $projection_start + 4 ]->id
			&& $this->is_mysql_identifier_like_token_value( $tokens[ $projection_start + 5 ], 'post_type' )
			&& WP_MySQL_Lexer::EQUAL_OPERATOR === $tokens[ $projection_start + 6 ]->id
			&& $this->is_mysql_string_literal_token( $tokens[ $projection_start + 7 ] )
			&& WP_MySQL_Lexer::AND_SYMBOL === $tokens[ $projection_start + 8 ]->id
			&& $this->is_mysql_identifier_like_token_value( $tokens[ $projection_start + 9 ], 'post_mime_type' )
			&& WP_MySQL_Lexer::NOT_EQUAL_OPERATOR === $tokens[ $projection_start + 10 ]->id
			&& $this->is_mysql_string_literal_token( $tokens[ $projection_start + 11 ] )
			&& '' === $tokens[ $projection_start + 11 ]->get_value();
	}

	/**
	 * Check for WordPress term cache priming's shared-term row shape.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int              $projection_start First projection token position.
	 * @param int              $from_position    FROM token position.
	 * @param int              $from_end         Final FROM-clause token, exclusive.
	 * @param int              $where_position   WHERE token position.
	 * @param int              $statement_end    Final statement token position, exclusive.
	 * @return bool Whether the SELECT needs term_taxonomy_id ordering.
	 */
	private function is_wordpress_term_cache_priming_select_shape(
		array $tokens,
		int $projection_start,
		int $from_position,
		int $from_end,
		int $where_position,
		int $statement_end
	): bool {
		$projection_ranges = $this->split_top_level_mysql_arguments( $tokens, $projection_start, $from_position );
		if (
			null === $projection_ranges
			|| 2 !== count( $projection_ranges )
			|| ! $this->is_mysql_qualified_star_projection(
				$tokens,
				$projection_ranges[0]['start'],
				$projection_ranges[0]['end'],
				't'
			)
			|| ! $this->is_mysql_qualified_star_projection(
				$tokens,
				$projection_ranges[1]['start'],
				$projection_ranges[1]['end'],
				'tt'
			)
			|| $from_end !== $where_position
			|| ! $this->is_mysql_distinct_term_taxonomy_from_shape( $tokens, $from_position, $from_end )
		) {
			return false;
		}

		$where_bounds    = $this->normalize_mysql_expression_bounds( $tokens, $where_position + 1, $statement_end );
		$where_reference = $this->parse_mysql_column_reference( $tokens, $where_bounds['start'], $where_bounds['end'] );
		if (
			null === $where_reference
			|| 't' !== strtolower( (string) $where_reference['qualifier'] )
			|| 'term_id' !== strtolower( $where_reference['column'] )
			|| ! isset( $tokens[ $where_reference['end'] ], $tokens[ $where_reference['end'] + 1 ] )
			|| WP_MySQL_Lexer::IN_SYMBOL !== $tokens[ $where_reference['end'] ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $where_reference['end'] + 1 ]->id
		) {
			return false;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end(
			$tokens,
			$where_reference['end'] + 1,
			$where_bounds['end']
		);
		if ( $after_close !== $where_bounds['end'] ) {
			return false;
		}

		$items = $this->split_top_level_mysql_arguments( $tokens, $where_reference['end'] + 2, $where_bounds['end'] - 1 );
		if ( null === $items || empty( $items ) ) {
			return false;
		}

		foreach ( $items as $item ) {
			if (
				$item['start'] + 1 !== $item['end']
				|| ! isset( $tokens[ $item['start'] ] )
				|| ! in_array(
					$tokens[ $item['start'] ]->id,
					array(
						WP_MySQL_Lexer::INT_NUMBER,
						WP_MySQL_Lexer::LONG_NUMBER,
						WP_MySQL_Lexer::ULONGLONG_NUMBER,
					),
					true
				)
			) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Get replacements for MySQL HAVING predicates that are row filters.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int              $projection_start First token after SELECT modifiers.
	 * @param int              $from_position    FROM token position.
	 * @param int              $having_position  HAVING token position.
	 * @param int              $having_end       Final HAVING predicate token, exclusive.
	 * @param int|null         $where_position   WHERE token position, or null.
	 * @param array            $scope            Statement table scope.
	 * @return array[]|null Replacement ranges, or null when HAVING must stay grouped.
	 */
	private function get_mysql_having_without_group_by_contextual_replacements(
		array $tokens,
		int $projection_start,
		int $from_position,
		int $having_position,
		int $having_end,
		?int $where_position,
		array $scope
	): ?array {
		if (
			$having_position + 1 >= $having_end
			|| null !== $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::GROUP_SYMBOL, $projection_start, $having_position )
			|| $this->contains_mysql_aggregate_call( $tokens, $projection_start, $from_position )
			|| $this->contains_mysql_aggregate_call( $tokens, $having_position + 1, $having_end )
		) {
			return null;
		}

		$having_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
			$tokens,
			$having_position + 1,
			$having_end,
			$scope
		);

		if ( null === $where_position ) {
			return array(
				array(
					'start' => $having_position,
					'end'   => $having_end,
					'sql'   => 'WHERE ' . $having_sql['sql'],
				),
			);
		}

		if ( $where_position > $having_position ) {
			return null;
		}

		$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
			$tokens,
			$where_position + 1,
			$having_position,
			$scope
		);

		return array(
			array(
				'start' => $where_position + 1,
				'end'   => $having_position,
				'sql'   => sprintf(
					'(%s) AND (%s)',
					$where_sql['sql'],
					$having_sql['sql']
				),
			),
			array(
				'start' => $having_position,
				'end'   => $having_end,
				'sql'   => '',
			),
		);
	}

	/**
	 * Get metadata-backed replacements for SELECT projection expressions.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First projection token position.
	 * @param int              $end    FROM token position.
	 * @param array            $scope  Statement table scope.
	 * @return array[]|null Replacement ranges, or null when projection parsing fails.
	 */
	private function get_mysql_select_projection_contextual_replacements( array $tokens, int $start, int $end, array $scope ): ?array {
		$ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $ranges ) {
			return null;
		}

		$replacements = array();
		foreach ( $ranges as $range ) {
			$expression_start = $range['start'];
			$expression_end   = $range['end'];
			$projection_item  = $this->parse_mysql_select_projection_item( $tokens, $range['start'], $range['end'] );
			if ( null !== $projection_item ) {
				$expression_start = $projection_item['expression_start'];
				$expression_end   = $projection_item['expression_end'];
			}

			$replacement_sql = $this->translate_mysql_sum_text_column_aggregate_to_postgresql(
				$tokens,
				$expression_start,
				$expression_end,
				$scope
			);
			if ( null === $replacement_sql ) {
				continue;
			}

			$replacements[] = array(
				'start' => $expression_start,
				'end'   => $expression_end,
				'sql'   => $replacement_sql,
			);
		}

		return $replacements;
	}

	/**
	 * Translate SUM(text_column) with MySQL numeric text coercion.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First projection expression token.
	 * @param int              $end    Final projection expression token, exclusive.
	 * @param array            $scope  Statement table scope.
	 * @return string|null PostgreSQL aggregate SQL, or null when unsupported.
	 */
	private function translate_mysql_sum_text_column_aggregate_to_postgresql( array $tokens, int $start, int $end, array $scope ): ?string {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		if (
			$start + 4 > $end
			|| ! isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $end - 1 ] )
			|| WP_MySQL_Lexer::SUM_SYMBOL !== $tokens[ $start ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $start + 1 ]->id
			|| WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== $tokens[ $end - 1 ]->id
		) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $start + 2, $end - 1 );
		if (
			null === $reference
			|| $reference['end'] !== $end - 1
			|| ! $this->is_mysql_text_family_column_reference( $reference, $scope )
		) {
			return null;
		}

		return sprintf(
			'SUM(%s)',
			$this->get_postgresql_mysql_numeric_cast_sql(
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
			)
		);
	}

	/**
	 * Translate tokens while replacing known bounded token ranges.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int             $start        First token position.
	 * @param int             $end          Final token position, exclusive.
	 * @param array[]         $replacements Replacement ranges with translated SQL.
	 * @return string PostgreSQL SQL fragment.
	 */
	private function translate_mysql_token_sequence_with_replacements_to_postgresql(
		array $tokens,
		int $start,
		int $end,
		array $replacements
	): string {
		$chunks   = array();
		$position = $start;

		foreach ( $replacements as $replacement ) {
			if ( $position < $replacement['start'] ) {
				$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $position, $replacement['start'] );
			}

			$chunks[] = $replacement['sql'];
			$position = $replacement['end'];
		}

		if ( $position < $end ) {
			$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $position, $end );
		}

		return implode( ' ', array_filter( $chunks, 'strlen' ) );
	}

	/**
	 * Translate tokens while applying replacement ranges bounded to the requested range.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int             $start        First token position.
	 * @param int             $end          Final token position, exclusive.
	 * @param array[]         $replacements Replacement ranges with translated SQL.
	 * @return string PostgreSQL SQL fragment.
	 */
	private function translate_mysql_token_sequence_with_optional_replacements_to_postgresql(
		array $tokens,
		int $start,
		int $end,
		array $replacements
	): string {
		$range_replacements = $this->get_mysql_replacements_for_token_range( $replacements, $start, $end );
		if ( empty( $range_replacements ) ) {
			return $this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end );
		}

		return $this->translate_mysql_token_sequence_with_replacements_to_postgresql( $tokens, $start, $end, $range_replacements );
	}

	/**
	 * Get replacement ranges fully contained in a token range.
	 *
	 * @param array[] $replacements Replacement ranges with translated SQL.
	 * @param int     $start        First token position.
	 * @param int     $end          Final token position, exclusive.
	 * @return array[] Replacement ranges in the requested range.
	 */
	private function get_mysql_replacements_for_token_range( array $replacements, int $start, int $end ): array {
		$range_replacements = array();
		foreach ( $replacements as $replacement ) {
			if ( $replacement['start'] >= $start && $replacement['end'] <= $end ) {
				$range_replacements[] = $replacement;
			}
		}

		return $range_replacements;
	}

	/**
	 * Get the original SQL text for a token range.
	 *
	 * @param string           $query  Original MySQL query.
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return string|null Query slice, or null when the range is invalid.
	 */
	private function get_mysql_token_range_sql( string $query, array $tokens, int $start, int $end ): ?string {
		if ( $start >= $end || ! isset( $tokens[ $start ], $tokens[ $end - 1 ] ) ) {
			return null;
		}

		$range_start = $tokens[ $start ]->start;
		$last_token  = $tokens[ $end - 1 ];
		$range_end   = $last_token->start + $last_token->length;

		return substr( $query, $range_start, $range_end - $range_start );
	}

	/**
	 * Translate ORDER BY items with metadata-backed expression coercions.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First ORDER BY item token position.
	 * @param int             $end    Final ORDER BY token position, exclusive.
	 * @param array           $scope  Statement table scope.
	 * @param bool            $allow_wordpress_posts_id_tiebreaker Whether to add WordPress posts ID tie-breakers.
	 * @return array{sql: string, changed: bool} Translated ORDER BY SQL and change flag.
	 */
	private function translate_mysql_order_by_token_sequence_to_postgresql(
		array $tokens,
		int $start,
		int $end,
		array $scope,
		bool $allow_wordpress_posts_id_tiebreaker
	): array {
		$order_items = $this->parse_mysql_select_order_by_items( $tokens, $start, $end, array(), $scope );
		if ( null === $order_items ) {
			return array(
				'sql'     => $this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end ),
				'changed' => false,
			);
		}

		$changed   = false;
		$order_sql = array();
		foreach ( $order_items as $order_item ) {
			$changed = $changed || $order_item['changed'];

			$item_sql = $order_item['sql'];
			if ( $order_item['direction_explicit'] ) {
				$item_sql .= ' ' . $order_item['direction'];
			}

			$order_sql[] = $item_sql;
		}

		$tiebreaker_sql = null;
		if ( $allow_wordpress_posts_id_tiebreaker ) {
			$tiebreaker_sql = $this->get_wordpress_posts_post_date_desc_order_id_tiebreaker_sql( $tokens, $order_items, $scope );
			if ( null === $tiebreaker_sql ) {
				$tiebreaker_sql = $this->get_wordpress_posts_menu_order_title_order_id_tiebreaker_sql( $tokens, $order_items, $scope );
			}
		}
		if ( null !== $tiebreaker_sql ) {
			$order_sql[] = $tiebreaker_sql;
			$changed     = true;
		}

		return array(
			'sql'     => $changed
				? implode( ', ', $order_sql )
				: $this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end ),
			'changed' => $changed,
		);
	}

	/**
	 * Get the MySQL-compatible posts date tie-breaker for a simple SELECT.
	 *
	 * WordPress's posts table has the MySQL type_status_date index ending in ID.
	 * MySQL scans that index backward for default post_date DESC queries, so rows
	 * with equal post_date values are returned by descending ID.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param string          $table_name     Selected table name.
	 * @param int             $order_position ORDER token position.
	 * @param int             $end            Final ORDER BY token position, exclusive.
	 * @return string|null PostgreSQL ORDER BY item SQL, or null when not applicable.
	 */
	private function get_simple_wordpress_posts_post_date_desc_order_id_tiebreaker_sql(
		array $tokens,
		string $table_name,
		int $order_position,
		int $end
	): ?string {
		if (
			! $this->is_mysql_wordpress_table_name( $table_name, 'posts' )
			|| ! isset( $tokens[ $end - 1 ] )
			|| WP_MySQL_Lexer::DESC_SYMBOL !== $tokens[ $end - 1 ]->id
		) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $order_position + 2, $end - 1 );
		if (
			null === $reference
			|| $reference['end'] !== $end - 1
			|| 'post_date' !== strtolower( $reference['column'] )
		) {
			return null;
		}

		if ( null !== $reference['qualifier'] ) {
			return sprintf(
				'%s.%s DESC',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['start'] + 1 ),
				$this->connection->quote_identifier( 'ID' )
			);
		}

		return $this->connection->quote_identifier( 'ID' ) . ' DESC';
	}

	/**
	 * Get the MySQL-compatible approved-comments date tie-breaker.
	 *
	 * get_approved_comments() orders by comment_date_gmt only. MySQL returns
	 * equal-date rows in comment_ID order for WordPress's comments table shape,
	 * so make that ordering explicit for PostgreSQL.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param string           $table_name     Selected table name.
	 * @param int|null         $where_position WHERE token position, or null.
	 * @param int|null         $where_end      Final WHERE token position, exclusive.
	 * @param int              $order_position ORDER token position.
	 * @param int              $end            Final ORDER BY token position, exclusive.
	 * @return string|null PostgreSQL ORDER BY item SQL, or null when not applicable.
	 */
	private function get_simple_wordpress_approved_comments_order_tiebreaker_sql(
		array $tokens,
		string $table_name,
		?int $where_position,
		?int $where_end,
		int $order_position,
		int $end
	): ?string {
		if (
			! $this->is_mysql_wordpress_table_name( $table_name, 'comments' )
			|| null === $where_position
			|| null === $where_end
			|| ! $this->is_simple_wordpress_approved_comments_where_clause( $tokens, $where_position + 1, $where_end )
		) {
			return null;
		}

		$order_items = $this->split_top_level_mysql_arguments( $tokens, $order_position + 2, $end );
		if ( null === $order_items || 1 !== count( $order_items ) ) {
			return null;
		}

		$order_item = $order_items[0];
		$direction  = 'ASC';
		$item_end   = $order_item['end'];
		if ( isset( $tokens[ $item_end - 1 ] ) ) {
			if ( WP_MySQL_Lexer::DESC_SYMBOL === $tokens[ $item_end - 1 ]->id ) {
				return null;
			}
			if ( WP_MySQL_Lexer::ASC_SYMBOL === $tokens[ $item_end - 1 ]->id ) {
				$item_end  = $item_end - 1;
				$direction = 'ASC';
			}
		}

		if (
			'ASC' !== $direction
			|| ! $this->is_mysql_column_reference_expression(
				$tokens,
				$order_item['start'],
				$item_end,
				'comment_date_gmt',
				'comments',
				true
			)
		) {
			return null;
		}

		return $this->connection->quote_identifier( 'comment_ID' ) . ' ASC';
	}

	/**
	 * Check for get_approved_comments()'s single-post approved comments filter.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First WHERE predicate token.
	 * @param int              $end    Final WHERE predicate token, exclusive.
	 * @return bool Whether the WHERE clause matches the approved-comments shape.
	 */
	private function is_simple_wordpress_approved_comments_where_clause( array $tokens, int $start, int $end ): bool {
		$conjuncts = $this->split_mysql_top_level_boolean_conjuncts( $tokens, $start, $end );
		if ( null === $conjuncts ) {
			return false;
		}

		$has_post_id  = false;
		$has_approved = false;
		foreach ( $conjuncts as $conjunct ) {
			$match = $this->get_simple_wordpress_comments_literal_equality(
				$tokens,
				$conjunct['start'],
				$conjunct['end']
			);
			if ( null === $match ) {
				continue;
			}

			if ( 'comment_post_id' === $match['column'] ) {
				$has_post_id = true;
				continue;
			}

			if ( 'comment_approved' === $match['column'] && '1' === $match['value'] ) {
				$has_approved = true;
			}
		}

		return $has_post_id && $has_approved;
	}

	/**
	 * Parse a comments-table column = literal predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First predicate token.
	 * @param int              $end    Final predicate token, exclusive.
	 * @return array{column: string, value: string}|null Parsed column and literal value.
	 */
	private function get_simple_wordpress_comments_literal_equality( array $tokens, int $start, int $end ): ?array {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		$equal_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::EQUAL_OPERATOR, $start, $end );
		if (
			null === $equal_position
			|| null !== $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::EQUAL_OPERATOR, $equal_position + 1, $end )
		) {
			return null;
		}

		$match = $this->get_simple_wordpress_comments_literal_equality_side(
			$tokens,
			$start,
			$equal_position,
			$equal_position + 1,
			$end
		);
		if ( null !== $match ) {
			return $match;
		}

		return $this->get_simple_wordpress_comments_literal_equality_side(
			$tokens,
			$equal_position + 1,
			$end,
			$start,
			$equal_position
		);
	}

	/**
	 * Parse one column/literal side of a comments-table equality predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $column_start  First column token.
	 * @param int              $column_end    Final column token, exclusive.
	 * @param int              $literal_start First literal token.
	 * @param int              $literal_end   Final literal token, exclusive.
	 * @return array{column: string, value: string}|null Parsed column and literal value.
	 */
	private function get_simple_wordpress_comments_literal_equality_side(
		array $tokens,
		int $column_start,
		int $column_end,
		int $literal_start,
		int $literal_end
	): ?array {
		$reference = $this->parse_mysql_column_reference( $tokens, $column_start, $column_end );
		if (
			null === $reference
			|| $reference['end'] !== $column_end
			|| (
				null !== $reference['qualifier']
				&& ! $this->is_mysql_wordpress_table_name( $reference['qualifier'], 'comments' )
			)
		) {
			return null;
		}

		$literal = $this->get_simple_wordpress_comments_literal_value( $tokens, $literal_start, $literal_end );
		if ( null === $literal ) {
			return null;
		}

		return array(
			'column' => strtolower( $reference['column'] ),
			'value'  => $literal,
		);
	}

	/**
	 * Get a supported literal value for the approved-comments WHERE predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First literal token.
	 * @param int              $end    Final literal token, exclusive.
	 * @return string|null Literal value, "literal" for unconstrained post IDs, or null.
	 */
	private function get_simple_wordpress_comments_literal_value( array $tokens, int $start, int $end ): ?string {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		if ( $this->is_mysql_string_literal_range( $tokens, $start, $end ) ) {
			return $tokens[ $start ]->get_value();
		}

		$literal = $this->parse_mysql_numeric_literal( $tokens, $start, $end );
		if ( null !== $literal && $literal['end'] === $end ) {
			return 'literal';
		}

		return null;
	}

	/**
	 * Get the MySQL-compatible posts date tie-breaker for a parsed ORDER BY.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $order_items Parsed ORDER BY items.
	 * @param array           $scope       Statement table scope.
	 * @return string|null PostgreSQL ORDER BY item SQL, or null when not applicable.
	 */
	private function get_wordpress_posts_post_date_desc_order_id_tiebreaker_sql( array $tokens, array $order_items, array $scope ): ?string {
		if (
			1 !== count( $order_items )
			|| ! empty( $scope['unknown'] )
			|| 1 !== count( $scope['tables'] )
			|| 'DESC' !== $order_items[0]['direction']
		) {
			return null;
		}

		$order_item = $order_items[0];
		$reference  = $this->parse_mysql_column_reference(
			$tokens,
			$order_item['expression_start'],
			$order_item['expression_end']
		);
		if (
			null === $reference
			|| $reference['end'] !== $order_item['expression_end']
			|| 'post_date' !== strtolower( $reference['column'] )
		) {
			return null;
		}

		$table = $this->get_mysql_single_scope_table_for_column_reference( $reference, $scope );
		if ( null === $table || ! $this->is_mysql_wordpress_table_name( $table['table'], 'posts' ) ) {
			return null;
		}

		if ( null !== $reference['qualifier'] ) {
			return sprintf(
				'%s.%s DESC',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['start'] + 1 ),
				$this->connection->quote_identifier( 'ID' )
			);
		}

		return $this->connection->quote_identifier( 'ID' ) . ' DESC';
	}

	/**
	 * Get the MySQL-compatible posts title tie-breaker for admin page searches.
	 *
	 * MySQL returns tied page rows for WordPress's menu_order/title ordering in
	 * primary-key order. PostgreSQL may return those ties in physical order,
	 * which changes the parent group selected by WP_Posts_List_Table paging.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $order_items Parsed ORDER BY items.
	 * @param array           $scope       Statement table scope.
	 * @return string|null PostgreSQL ORDER BY item SQL, or null when not applicable.
	 */
	private function get_wordpress_posts_menu_order_title_order_id_tiebreaker_sql( array $tokens, array $order_items, array $scope ): ?string {
		if (
			2 !== count( $order_items )
			|| ! empty( $scope['unknown'] )
			|| 1 !== count( $scope['tables'] )
		) {
			return null;
		}

		$expected_columns = array( 'menu_order', 'post_title' );
		$references       = array();
		$matched_table    = null;
		foreach ( $expected_columns as $index => $expected_column ) {
			if ( 'ASC' !== $order_items[ $index ]['direction'] ) {
				return null;
			}

			$reference = $this->parse_mysql_column_reference(
				$tokens,
				$order_items[ $index ]['expression_start'],
				$order_items[ $index ]['expression_end']
			);
			if (
				null === $reference
				|| $reference['end'] !== $order_items[ $index ]['expression_end']
				|| strtolower( $reference['column'] ) !== $expected_column
			) {
				return null;
			}

			$table = $this->get_mysql_single_scope_table_for_column_reference( $reference, $scope );
			if ( null === $table || ! $this->is_mysql_wordpress_table_name( $table['table'], 'posts' ) ) {
				return null;
			}

			if ( null !== $matched_table && $matched_table !== $table ) {
				return null;
			}

			$matched_table = $table;
			$references[]  = $reference;
		}

		$qualifier_reference = null !== $references[0]['qualifier'] ? $references[0] : $references[1];
		if ( null !== $qualifier_reference['qualifier'] ) {
			return sprintf(
				'%s.%s ASC',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $qualifier_reference['start'], $qualifier_reference['start'] + 1 ),
				$this->connection->quote_identifier( 'ID' )
			);
		}

		return $this->connection->quote_identifier( 'ID' ) . ' ASC';
	}

	/**
	 * Translate expression tokens with metadata-backed numeric text coercions.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token position.
	 * @param int             $end    Final expression token position, exclusive.
	 * @param array           $scope  Statement table scope.
	 * @return array{sql: string, changed: bool} Translated expression SQL and change flag.
	 */
	private function translate_mysql_expression_token_sequence_to_postgresql(
		array $tokens,
		int $start,
		int $end,
		array $scope
	): array {
		$chunks        = array();
		$segment_start = $start;
		$changed       = false;

		for ( $position = $start; $position < $end; $position++ ) {
			if (
				isset( $tokens[ $position ], $tokens[ $position + 1 ] )
				&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
				&& WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				$after_subquery = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
				if ( null !== $after_subquery ) {
					$position = $after_subquery - 1;
					continue;
				}
			}

			$translated_expression = $this->translate_mysql_text_column_numeric_arithmetic_to_postgresql(
				$tokens,
				$position,
				$end,
				$scope
			);
			if ( null === $translated_expression ) {
				$translated_expression = $this->translate_mysql_wordpress_text_order_expression_to_postgresql(
					$tokens,
					$position,
					$start,
					$end,
					$scope
				);
			}
			if ( null === $translated_expression ) {
				$translated_expression = $this->translate_mysql_wordpress_text_expression_predicate_to_postgresql(
					$tokens,
					$position,
					$start,
					$end,
					$scope
				);
			}
			if ( null === $translated_expression ) {
				continue;
			}

			if ( $segment_start < $position ) {
				$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $segment_start, $position );
			}

			$chunks[]      = $translated_expression['sql'];
			$segment_start = $translated_expression['position'] + 1;
			$position      = $translated_expression['position'];
			$changed       = true;
		}

		if ( ! $changed ) {
			return array(
				'sql'     => $this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end ),
				'changed' => false,
			);
		}

		if ( $segment_start < $end ) {
			$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $segment_start, $end );
		}

		return array(
			'sql'     => implode( ' ', array_filter( $chunks, 'strlen' ) ),
			'changed' => true,
		);
	}

	/**
	 * Translate WordPress text ORDER BY expressions with MySQL collation semantics.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate expression start position.
	 * @param int             $start    First expression token position.
	 * @param int             $end      Final expression token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_wordpress_text_order_expression_to_postgresql(
		array $tokens,
		int $position,
		int $start,
		int $end,
		array $scope
	): ?array {
		if ( $position !== $start ) {
			return null;
		}

		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		if ( $bounds['start'] !== $start || $bounds['end'] !== $end ) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $bounds['start'], $bounds['end'] );
		if (
			null === $reference
			|| $reference['end'] !== $bounds['end']
			|| ! $this->is_mysql_case_insensitive_wordpress_text_column_reference( $reference, $scope )
		) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'LOWER(%s)',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
			),
			'position' => $bounds['end'] - 1,
		);
	}

	/**
	 * Translate WordPress text predicates embedded in expressions.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $start    First expression token position.
	 * @param int             $end      Final expression token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_wordpress_text_expression_predicate_to_postgresql(
		array $tokens,
		int $position,
		int $start,
		int $end,
		array $scope
	): ?array {
		if ( ! $this->is_mysql_expression_predicate_start_context( $tokens, $position, $start ) ) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if (
			null === $reference
			|| ! $this->is_mysql_case_insensitive_wordpress_text_column_reference( $reference, $scope )
		) {
			return null;
		}

		return $this->translate_mysql_wordpress_text_like_predicate_to_postgresql(
			$tokens,
			$reference,
			$reference['end'],
			$end
		);
	}

	/**
	 * Check whether an expression position starts a boolean predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $start    First expression token position.
	 * @return bool Whether the candidate follows a boolean expression boundary.
	 */
	private function is_mysql_expression_predicate_start_context( array $tokens, int $position, int $start ): bool {
		if ( $position <= $start ) {
			return false;
		}

		$previous_token_id = $tokens[ $position - 1 ]->id ?? null;
		if ( $this->is_mysql_expression_predicate_left_boundary_token_id( $previous_token_id ) ) {
			return true;
		}

		return WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $previous_token_id
			&& $position - 1 > $start
			&& $this->is_mysql_expression_predicate_left_boundary_token_id( $tokens[ $position - 2 ]->id ?? null );
	}

	/**
	 * Check whether a token can precede a predicate inside an expression.
	 *
	 * @param int|null $token_id MySQL token ID.
	 * @return bool Whether the token is a predicate boundary.
	 */
	private function is_mysql_expression_predicate_left_boundary_token_id( ?int $token_id ): bool {
		return in_array(
			$token_id,
			array(
				WP_MySQL_Lexer::AND_SYMBOL,
				WP_MySQL_Lexer::OR_SYMBOL,
				WP_MySQL_Lexer::WHEN_SYMBOL,
				WP_MySQL_Lexer::XOR_SYMBOL,
			),
			true
		);
	}

	/**
	 * Translate predicate tokens with metadata-backed integer string coercion.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First predicate token position.
	 * @param int             $end    Final predicate token position, exclusive.
	 * @param array           $scope  Statement table scope.
	 * @param array[]         $replacements Replacement ranges with translated SQL.
	 * @return array{sql: string, changed: bool} Translated predicate SQL and change flag.
	 */
	private function translate_mysql_predicate_token_sequence_to_postgresql(
		array $tokens,
		int $start,
		int $end,
		array $scope,
		array $replacements = array()
	): array {
		$chunks        = array();
		$segment_start = $start;
		$changed       = false;

		for ( $position = $start; $position < $end; $position++ ) {
			if ( $this->is_mysql_qualified_reference_suffix_position( $tokens, $position, $start ) ) {
				continue;
			}

			if (
				isset( $tokens[ $position ], $tokens[ $position + 1 ] )
				&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
				&& WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				$after_subquery = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
				if ( null !== $after_subquery ) {
					$translated_subquery = $this->translate_mysql_parenthesized_select_predicate_to_postgresql(
						$tokens,
						$position,
						$after_subquery,
						$scope
					);
					if ( null !== $translated_subquery ) {
						if ( $segment_start < $position ) {
							$chunks[] = $this->translate_mysql_token_sequence_with_optional_replacements_to_postgresql( $tokens, $segment_start, $position, $replacements );
						}

						$chunks[]      = $translated_subquery['sql'];
						$segment_start = $translated_subquery['position'] + 1;
						$position      = $translated_subquery['position'];
						$changed       = true;
						continue;
					}

					$position = $after_subquery - 1;
					continue;
				}
			}

			$translated_predicate = $this->translate_mysql_integer_column_string_predicate_to_postgresql(
				$tokens,
				$position,
				$end,
				$scope
			);
			if ( null === $translated_predicate ) {
				continue;
			}

			if ( $segment_start < $position ) {
				$chunks[] = $this->translate_mysql_token_sequence_with_optional_replacements_to_postgresql( $tokens, $segment_start, $position, $replacements );
			}

			$chunks[]      = $translated_predicate['sql'];
			$segment_start = $translated_predicate['position'] + 1;
			$position      = $translated_predicate['position'];
			$changed       = true;
		}

		if ( ! $changed ) {
			return array(
				'sql'     => $this->translate_mysql_token_sequence_with_optional_replacements_to_postgresql( $tokens, $start, $end, $replacements ),
				'changed' => ! empty( $replacements ),
			);
		}

		if ( $segment_start < $end ) {
			$chunks[] = $this->translate_mysql_token_sequence_with_optional_replacements_to_postgresql( $tokens, $segment_start, $end, $replacements );
		}

		return array(
			'sql'     => implode( ' ', array_filter( $chunks, 'strlen' ) ),
			'changed' => true,
		);
	}

	/**
	 * Translate one integer-column predicate against string literals.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_integer_column_string_predicate_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$truthiness = $this->translate_mysql_numeric_literal_truthiness_predicate_to_postgresql(
			$tokens,
			$position,
			$end
		);
		if ( null !== $truthiness ) {
			return $truthiness;
		}

		$decimal_like = $this->translate_mysql_decimal_cast_like_predicate_to_postgresql(
			$tokens,
			$position,
			$end
		);
		if ( null !== $decimal_like ) {
			return $decimal_like;
		}

		$temporal_comparison = $this->translate_mysql_temporal_expression_column_comparison_to_postgresql(
			$tokens,
			$position,
			$end,
			$scope
		);
		if ( null !== $temporal_comparison ) {
			return $temporal_comparison;
		}

		$wordpress_text_predicate = $this->translate_mysql_wordpress_text_predicate_to_postgresql(
			$tokens,
			$position,
			$end,
			$scope
		);
		if ( null !== $wordpress_text_predicate ) {
			return $wordpress_text_predicate;
		}

		$in_predicate = $this->translate_mysql_integer_column_string_in_predicate_to_postgresql(
			$tokens,
			$position,
			$end,
			$scope
		);
		if ( null !== $in_predicate ) {
			return $in_predicate;
		}

		$comparison = $this->translate_mysql_integer_column_string_comparison_to_postgresql(
			$tokens,
			$position,
			$end,
			$scope
		);
		if ( null !== $comparison ) {
			return $comparison;
		}

		$numeric_comparison = $this->translate_mysql_text_column_numeric_comparison_to_postgresql(
			$tokens,
			$position,
			$end,
			$scope
		);
		if ( null !== $numeric_comparison ) {
			return $numeric_comparison;
		}

		return $this->translate_mysql_metadata_column_reference_to_postgresql(
			$tokens,
			$position,
			$end,
			$scope
		);
	}

	/**
	 * Translate temporal expression comparisons against text-backed temporal columns.
	 *
	 * PostgreSQL stores MySQL date/datetime/timestamp columns as text so invalid
	 * MySQL dates remain readable. Compare temporal expressions as fixed ISO text
	 * in this metadata-backed lane to avoid timestamp/text operator errors without
	 * casting zero or partial-zero column values.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_temporal_expression_column_comparison_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$temporal_expression = $this->parse_mysql_temporal_comparison_expression( $tokens, $position, $end );
		if (
			null !== $temporal_expression
			&& isset( $tokens[ $temporal_expression['end'] ] )
			&& $this->is_mysql_comparison_operator_token( $tokens[ $temporal_expression['end'] ] )
		) {
			$reference   = $this->parse_mysql_column_reference( $tokens, $temporal_expression['end'] + 1, $end );
			$column_type = null === $reference ? null : $this->get_mysql_temporal_column_type_for_reference( $reference, $scope );
			if (
				null !== $reference
				&& null !== $column_type
				&& $this->is_mysql_temporal_comparison_predicate_boundary( $tokens, $reference['end'], $end )
			) {
				return array(
					'sql'      => sprintf(
						'%s %s %s',
						$this->get_postgresql_mysql_temporal_expression_comparison_text_sql(
							$this->translate_mysql_token_sequence_to_postgresql( $tokens, $temporal_expression['start'], $temporal_expression['end'] ),
							$temporal_expression['returns_timestamp']
						),
						$tokens[ $temporal_expression['end'] ]->get_bytes(),
						$this->get_postgresql_mysql_temporal_column_comparison_text_sql(
							$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] ),
							$column_type
						)
					),
					'position' => $reference['end'] - 1,
				);
			}
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if (
			null === $reference
			|| ! isset( $tokens[ $reference['end'] ] )
			|| ! $this->is_mysql_comparison_operator_token( $tokens[ $reference['end'] ] )
		) {
			return null;
		}

		$column_type = $this->get_mysql_temporal_column_type_for_reference( $reference, $scope );
		if ( null === $column_type ) {
			return null;
		}

		$temporal_expression = $this->parse_mysql_temporal_comparison_expression( $tokens, $reference['end'] + 1, $end );
		if (
			null === $temporal_expression
			|| ! $this->is_mysql_temporal_comparison_predicate_boundary( $tokens, $temporal_expression['end'], $end )
		) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'%s %s %s',
				$this->get_postgresql_mysql_temporal_column_comparison_text_sql(
					$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] ),
					$column_type
				),
				$tokens[ $reference['end'] ]->get_bytes(),
				$this->get_postgresql_mysql_temporal_expression_comparison_text_sql(
					$this->translate_mysql_token_sequence_to_postgresql( $tokens, $temporal_expression['start'], $temporal_expression['end'] ),
					$temporal_expression['returns_timestamp']
				)
			),
			'position' => $temporal_expression['end'] - 1,
		);
	}

	/**
	 * Parse a MySQL temporal expression usable in metadata-backed comparisons.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Expression start position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{start: int, end: int, returns_timestamp: bool}|null Expression bounds, or null when unsupported.
	 */
	private function parse_mysql_temporal_comparison_expression( array $tokens, int $position, int $end ): ?array {
		if ( ! isset( $tokens[ $position ] ) || $position >= $end ) {
			return null;
		}

		if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
			if ( null === $after_close || $after_close > $end ) {
				return null;
			}

			$inner = $this->parse_mysql_temporal_comparison_expression( $tokens, $position + 1, $after_close - 1 );
			if ( null === $inner || $inner['start'] !== $position + 1 || $inner['end'] !== $after_close - 1 ) {
				return null;
			}

			return array(
				'start'             => $position,
				'end'               => $after_close,
				'returns_timestamp' => $inner['returns_timestamp'],
			);
		}

		$date_arithmetic = $this->get_mysql_date_arithmetic_function_bounds( $tokens, $position, $end );
		if ( null !== $date_arithmetic ) {
			return array(
				'start'             => $position,
				'end'               => $date_arithmetic['close'] + 1,
				'returns_timestamp' => true,
			);
		}

		$common_function = $this->get_mysql_common_function_bounds( $tokens, $position, $end );
		if (
			null !== $common_function
			&& $this->is_mysql_temporal_comparison_common_function_name( $common_function['function'] )
			&& null !== $this->translate_mysql_common_function_to_postgresql( $tokens, $position, $end )
		) {
			return array(
				'start'             => $position,
				'end'               => $common_function['close'] + 1,
				'returns_timestamp' => 'timestampadd' === $common_function['function'],
			);
		}

		$nonparenthesized_function = $this->translate_mysql_nonparenthesized_timestamp_function_to_postgresql( $tokens, $position, $end );
		if (
			null !== $nonparenthesized_function
			&& $this->is_mysql_temporal_comparison_nonparenthesized_function_token( $tokens[ $position ] )
		) {
			return array(
				'start'             => $position,
				'end'               => $position + 1,
				'returns_timestamp' => false,
			);
		}

		return null;
	}

	/**
	 * Check whether a temporal comparison operand ends at a predicate boundary.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Token position after the operand.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @return bool Whether the operand is complete.
	 */
	private function is_mysql_temporal_comparison_predicate_boundary( array $tokens, int $position, int $end ): bool {
		if ( $position >= $end || ! isset( $tokens[ $position ] ) ) {
			return true;
		}

		return $this->is_mysql_boolean_predicate_left_boundary_token_id( $tokens[ $position ]->id )
			|| in_array(
				$tokens[ $position ]->id,
				array(
					WP_MySQL_Lexer::CLOSE_PAR_SYMBOL,
					WP_MySQL_Lexer::COMMA_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::LOGICAL_AND_OPERATOR,
					WP_MySQL_Lexer::LOGICAL_OR_OPERATOR,
					WP_MySQL_Lexer::ON_SYMBOL,
				),
				true
			);
	}

	/**
	 * Check whether a common function returns a temporal value suitable for text comparison.
	 *
	 * @param string $function_name Normalized common MySQL function name.
	 * @return bool Whether the function is date/datetime-like.
	 */
	private function is_mysql_temporal_comparison_common_function_name( string $function_name ): bool {
		return in_array(
			$function_name,
			array(
				'curdate',
				'date',
				'from_unixtime',
				'localtime',
				'localtimestamp',
				'now',
				'timestampadd',
				'utc_date',
				'utc_timestamp',
			),
			true
		);
	}

	/**
	 * Check whether a non-parenthesized temporal function token is date/datetime-like.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token returns a date/datetime value.
	 */
	private function is_mysql_temporal_comparison_nonparenthesized_function_token( WP_MySQL_Token $token ): bool {
		return in_array(
			strtolower( $token->get_value() ),
			array(
				'current_date',
				'current_timestamp',
				'localtime',
				'localtimestamp',
			),
			true
		);
	}

	/**
	 * Resolve a column reference to date/datetime/timestamp MySQL metadata.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return string|null MySQL column type, or null when not temporal.
	 */
	private function get_mysql_temporal_column_type_for_reference( array $reference, array $scope ): ?string {
		$column_type = $this->get_mysql_column_type_for_reference( $reference, $scope );
		if ( null === $column_type ) {
			return null;
		}

		return in_array(
			$this->get_base_mysql_dml_column_type( $column_type ),
			array(
				'date',
				'datetime',
				'timestamp',
			),
			true
		) ? $column_type : null;
	}

	/**
	 * Get PostgreSQL text SQL for a temporal expression comparison operand.
	 *
	 * @param string $expression_sql    PostgreSQL temporal expression SQL.
	 * @param bool   $returns_timestamp Whether the expression SQL is already a timestamp.
	 * @return string PostgreSQL text expression SQL.
	 */
	private function get_postgresql_mysql_temporal_expression_comparison_text_sql( string $expression_sql, bool $returns_timestamp ): string {
		if ( $returns_timestamp ) {
			return sprintf(
				'TO_CHAR(%s, %s)',
				$expression_sql,
				$this->connection->quote( 'YYYY-MM-DD HH24:MI:SS' )
			);
		}

		return $this->get_postgresql_mysql_temporal_text_comparison_sql( $expression_sql );
	}

	/**
	 * Get PostgreSQL text SQL for a text-backed MySQL temporal column operand.
	 *
	 * @param string $column_sql  PostgreSQL column reference SQL.
	 * @param string $column_type MySQL column type metadata.
	 * @return string PostgreSQL text expression SQL.
	 */
	private function get_postgresql_mysql_temporal_column_comparison_text_sql( string $column_sql, string $column_type ): string {
		if ( 'date' !== $this->get_base_mysql_dml_column_type( $column_type ) ) {
			return sprintf( 'CAST(%s AS text)', $column_sql );
		}

		return $this->get_postgresql_mysql_temporal_text_comparison_sql( $column_sql );
	}

	/**
	 * Get normalized PostgreSQL text SQL for a text-returning temporal operand.
	 *
	 * @param string $expression_sql PostgreSQL expression SQL.
	 * @return string PostgreSQL text expression SQL.
	 */
	private function get_postgresql_mysql_temporal_text_comparison_sql( string $expression_sql ): string {
		$expression_text_sql = sprintf( 'CAST(%s AS text)', $expression_sql );

		return sprintf(
			"CASE WHEN %1\$s IS NULL THEN NULL WHEN %1\$s = '' THEN '' WHEN %1\$s ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN %1\$s || ' 00:00:00' ELSE %1\$s END",
			$expression_text_sql
		);
	}

	/**
	 * Check whether a scanner position is inside a qualified reference suffix.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $start    First predicate token position.
	 * @return bool Whether the position follows a dot in the same predicate.
	 */
	private function is_mysql_qualified_reference_suffix_position( array $tokens, int $position, int $start ): bool {
		return $position > $start
			&& isset( $tokens[ $position - 1 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position - 1 ]->id;
	}

	/**
	 * Translate WordPress text predicates with MySQL case-insensitive collation semantics.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_wordpress_text_predicate_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if (
			null !== $reference
			&& $this->is_mysql_case_insensitive_wordpress_text_column_reference( $reference, $scope )
		) {
			$like = $this->translate_mysql_wordpress_text_like_predicate_to_postgresql(
				$tokens,
				$reference,
				$reference['end'],
				$end
			);
			if ( null !== $like ) {
				return $like;
			}

			$in = $this->translate_mysql_wordpress_text_in_predicate_to_postgresql(
				$tokens,
				$reference,
				$reference['end'],
				$end
			);
			if ( null !== $in ) {
				return $in;
			}

			$comparison = $this->translate_mysql_wordpress_text_comparison_to_postgresql(
				$tokens,
				$reference,
				$reference['end'],
				$end
			);
			if ( null !== $comparison ) {
				return $comparison;
			}
		}

		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| ! $this->is_mysql_string_literal_token( $tokens[ $position ] )
			|| ! $this->is_mysql_case_insensitive_equality_operator_token( $tokens[ $position + 1 ] )
		) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $position + 2, $end );
		if (
			null === $reference
			|| ! $this->is_mysql_case_insensitive_wordpress_text_column_reference( $reference, $scope )
		) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'LOWER(%s) %s LOWER(%s)',
				$this->translate_mysql_token_to_postgresql( $tokens[ $position ] ),
				$tokens[ $position + 1 ]->get_bytes(),
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
			),
			'position' => $reference['end'] - 1,
		);
	}

	/**
	 * Translate a WordPress text LIKE predicate with case-insensitive semantics.
	 *
	 * @param WP_MySQL_Token[] $tokens            MySQL lexer token stream.
	 * @param array           $reference         Parsed column reference.
	 * @param int             $operator_position Candidate LIKE or NOT position.
	 * @param int             $end               Final predicate token position, exclusive.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_wordpress_text_like_predicate_to_postgresql(
		array $tokens,
		array $reference,
		int $operator_position,
		int $end
	): ?array {
		$not_sql = '';
		if (
			isset( $tokens[ $operator_position ], $tokens[ $operator_position + 1 ] )
			&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $operator_position ]->id
			&& WP_MySQL_Lexer::LIKE_SYMBOL === $tokens[ $operator_position + 1 ]->id
		) {
			$not_sql = ' NOT';
			++$operator_position;
		}

		if (
			! isset( $tokens[ $operator_position ], $tokens[ $operator_position + 1 ] )
			|| WP_MySQL_Lexer::LIKE_SYMBOL !== $tokens[ $operator_position ]->id
		) {
			return null;
		}

		$pattern = $this->get_mysql_string_like_pattern_sql( $tokens, $operator_position + 1, $end );
		if ( null === $pattern ) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'LOWER(%s)%s LIKE LOWER(%s)%s',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] ),
				$not_sql,
				$pattern['pattern_sql'],
				$pattern['escape_sql']
			),
			'position' => $pattern['end'] - 1,
		);
	}

	/**
	 * Translate a WordPress text equality predicate with case-insensitive semantics.
	 *
	 * @param WP_MySQL_Token[] $tokens            MySQL lexer token stream.
	 * @param array           $reference         Parsed column reference.
	 * @param int             $operator_position Candidate comparison operator position.
	 * @param int             $end               Final predicate token position, exclusive.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_wordpress_text_comparison_to_postgresql(
		array $tokens,
		array $reference,
		int $operator_position,
		int $end
	): ?array {
		if (
			! isset( $tokens[ $operator_position ], $tokens[ $operator_position + 1 ] )
			|| $operator_position + 1 >= $end
			|| ! $this->is_mysql_case_insensitive_equality_operator_token( $tokens[ $operator_position ] )
			|| ! $this->is_mysql_string_literal_token( $tokens[ $operator_position + 1 ] )
		) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'LOWER(%s) %s LOWER(%s)',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] ),
				$tokens[ $operator_position ]->get_bytes(),
				$this->translate_mysql_token_to_postgresql( $tokens[ $operator_position + 1 ] )
			),
			'position' => $operator_position + 1,
		);
	}

	/**
	 * Translate a WordPress text IN predicate with case-insensitive semantics.
	 *
	 * @param WP_MySQL_Token[] $tokens            MySQL lexer token stream.
	 * @param array           $reference         Parsed column reference.
	 * @param int             $operator_position Candidate IN or NOT position.
	 * @param int             $end               Final predicate token position, exclusive.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_wordpress_text_in_predicate_to_postgresql(
		array $tokens,
		array $reference,
		int $operator_position,
		int $end
	): ?array {
		$not_sql = '';
		if (
			isset( $tokens[ $operator_position ], $tokens[ $operator_position + 1 ] )
			&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $operator_position ]->id
			&& WP_MySQL_Lexer::IN_SYMBOL === $tokens[ $operator_position + 1 ]->id
		) {
			$not_sql = ' NOT';
			++$operator_position;
		}

		if (
			! isset( $tokens[ $operator_position ], $tokens[ $operator_position + 1 ] )
			|| WP_MySQL_Lexer::IN_SYMBOL !== $tokens[ $operator_position ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $operator_position + 1 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $operator_position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		$items = $this->split_top_level_mysql_arguments( $tokens, $operator_position + 2, $after_close - 1 );
		if ( empty( $items ) ) {
			return null;
		}

		$item_sql = array();
		foreach ( $items as $item ) {
			if ( ! $this->is_mysql_string_literal_range( $tokens, $item['start'], $item['end'] ) ) {
				return null;
			}

			$item_sql[] = 'LOWER(' . $this->translate_mysql_token_to_postgresql( $tokens[ $item['start'] ] ) . ')';
		}

		return array(
			'sql'      => sprintf(
				'LOWER(%s)%s IN (%s)',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] ),
				$not_sql,
				implode( ', ', $item_sql )
			),
			'position' => $after_close - 1,
		);
	}

	/**
	 * Get a simple string LIKE pattern SQL fragment.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Pattern token position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @return array{pattern_sql: string, escape_sql: string, end: int}|null Pattern SQL, or null when unsupported.
	 */
	private function get_mysql_string_like_pattern_sql( array $tokens, int $position, int $end ): ?array {
		if (
			! isset( $tokens[ $position ] )
			|| $position >= $end
			|| ! $this->is_mysql_string_literal_token( $tokens[ $position ] )
		) {
			return null;
		}

		$pattern_sql = $this->translate_mysql_token_to_postgresql( $tokens[ $position ] );
		$escape_sql  = '';
		$pattern_end = $position + 1;

		if ( isset( $tokens[ $pattern_end ] ) && WP_MySQL_Lexer::ESCAPE_SYMBOL === $tokens[ $pattern_end ]->id ) {
			if (
				! isset( $tokens[ $pattern_end + 1 ] )
				|| $pattern_end + 1 >= $end
				|| ! $this->is_mysql_string_literal_token( $tokens[ $pattern_end + 1 ] )
			) {
				return null;
			}

			$escape_sql   = ' ESCAPE ' . $this->translate_mysql_token_to_postgresql( $tokens[ $pattern_end + 1 ] );
			$pattern_end += 2;
		} else {
			$escape_sql = $this->get_mysql_no_backslash_like_escape_sql();
		}

		return array(
			'pattern_sql' => $pattern_sql,
			'escape_sql'  => $escape_sql,
			'end'         => $pattern_end,
		);
	}

	/**
	 * Get the PostgreSQL LIKE escape clause needed for NO_BACKSLASH_ESCAPES.
	 *
	 * PostgreSQL treats backslash as the default LIKE escape character. MySQL's
	 * NO_BACKSLASH_ESCAPES mode removes that default unless an explicit ESCAPE
	 * clause is present.
	 *
	 * @return string PostgreSQL ESCAPE clause, or an empty string.
	 */
	private function get_mysql_no_backslash_like_escape_sql(): string {
		return $this->is_sql_mode_active( 'NO_BACKSLASH_ESCAPES' ) ? " ESCAPE ''" : '';
	}

	/**
	 * Check whether a column is a case-insensitive WordPress text lookup column.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return bool Whether the reference should use MySQL case-insensitive text predicates.
	 */
	private function is_mysql_case_insensitive_wordpress_text_column_reference( array $reference, array $scope ): bool {
		$table = $this->get_mysql_table_for_column_reference( $reference, $scope );
		if ( null === $table || ! $this->is_mysql_wordpress_case_insensitive_text_column( $table['table'], $reference['column'] ) ) {
			return false;
		}

		if (
			$this->is_mysql_wordpress_table_name( $table['table'], 'postmeta' )
			&& null === $reference['qualifier']
		) {
			return false;
		}

		$column_type = $this->get_mysql_column_type_for_reference( $reference, $scope );
		if ( null === $column_type || ! $this->is_mysql_text_family_column_type( $column_type ) ) {
			return false;
		}

		$collation = $this->get_mysql_column_collation_for_reference( $reference, $scope );
		return null !== $collation && 1 === preg_match( '/(^|_)ci($|_)/', strtolower( trim( $collation ) ) );
	}

	/**
	 * Resolve a column reference to one table in the statement scope.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return array|null Table metadata, or null when missing/ambiguous.
	 */
	private function get_mysql_table_for_column_reference( array $reference, array $scope ): ?array {
		if ( null !== $reference['qualifier'] ) {
			$alias = strtolower( $reference['qualifier'] );
			$table = $scope['aliases'][ $alias ] ?? null;
			if ( null === $table || ! empty( $table['derived'] ) || null === ( $table['table'] ?? null ) ) {
				return null;
			}

			return $table;
		}

		if ( ! empty( $scope['unknown'] ) ) {
			return null;
		}

		$matched_table = null;
		foreach ( $scope['tables'] as $table ) {
			if (
				count( $scope['tables'] ) > 1
				&& ! $this->mysql_table_has_column_metadata( $table['schema'], $table['table'] )
			) {
				return null;
			}

			if ( null === $this->get_mysql_table_column_type( $table['schema'], $table['table'], $reference['column'] ) ) {
				continue;
			}

			if ( null !== $matched_table ) {
				return null;
			}

			$matched_table = $table;
		}

		return $matched_table;
	}

	/**
	 * Resolve a column reference when a statement scope has exactly one table.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return array|null Table metadata, or null when missing/ambiguous.
	 */
	private function get_mysql_single_scope_table_for_column_reference( array $reference, array $scope ): ?array {
		if ( null !== $reference['qualifier'] ) {
			$alias = strtolower( $reference['qualifier'] );
			$table = $scope['aliases'][ $alias ] ?? null;
			if ( null === $table || ! empty( $table['derived'] ) || null === ( $table['table'] ?? null ) ) {
				return null;
			}

			return $table;
		}

		if ( ! empty( $scope['unknown'] ) || 1 !== count( $scope['tables'] ) ) {
			return null;
		}

		return $scope['tables'][0];
	}

	/**
	 * Check whether a table/column pair is in a WordPress text lookup surface.
	 *
	 * @param string $table_name  Table name.
	 * @param string $column_name Column name.
	 * @return bool Whether this is a supported text lookup column.
	 */
	private function is_mysql_wordpress_case_insensitive_text_column( string $table_name, string $column_name ): bool {
		$column_name = strtolower( $column_name );

		if ( $this->is_mysql_wordpress_table_name( $table_name, 'posts' ) ) {
			return in_array( $column_name, array( 'post_content', 'post_excerpt', 'post_title' ), true );
		}

		if ( $this->is_mysql_wordpress_table_name( $table_name, 'terms' ) ) {
			return in_array( $column_name, array( 'name', 'slug' ), true );
		}

		if ( $this->is_mysql_wordpress_table_name( $table_name, 'term_taxonomy' ) ) {
			return in_array( $column_name, array( 'description', 'taxonomy' ), true );
		}

		if ( $this->is_mysql_wordpress_table_name( $table_name, 'postmeta' ) ) {
			return 'meta_value' === $column_name;
		}

		if ( $this->is_mysql_wordpress_table_name( $table_name, 'users' ) ) {
			return in_array(
				$column_name,
				array(
					'display_name',
					'user_email',
					'user_login',
					'user_nicename',
					'user_url',
				),
				true
			);
		}

		return false;
	}

	/**
	 * Check whether a token is a case-insensitive equality operator candidate.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is an equality or inequality operator.
	 */
	private function is_mysql_case_insensitive_equality_operator_token( WP_MySQL_Token $token ): bool {
		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::EQUAL_OPERATOR,
				WP_MySQL_Lexer::NOT_EQUAL_OPERATOR,
			),
			true
		);
	}

	/**
	 * Translate a parenthesized SELECT predicate with inner and outer metadata scope.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param int             $position       Opening parenthesis position.
	 * @param int             $after_subquery Position after the closing parenthesis.
	 * @param array           $outer_scope    Outer statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unchanged/unsupported.
	 */
	private function translate_mysql_parenthesized_select_predicate_to_postgresql(
		array $tokens,
		int $position,
		int $after_subquery,
		array $outer_scope
	): ?array {
		$select_position = $position + 1;
		$statement_end   = $after_subquery - 1;
		if (
			! isset( $tokens[ $select_position ] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $select_position ]->id
		) {
			return null;
		}

		$projection_start = $select_position + 1;
		$from_position    = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::FROM_SYMBOL,
			$projection_start,
			$statement_end
		);
		if ( null === $from_position ) {
			return null;
		}

		$from_end = $this->find_first_top_level_mysql_token(
			$tokens,
			array(
				WP_MySQL_Lexer::FOR_SYMBOL,
				WP_MySQL_Lexer::GROUP_SYMBOL,
				WP_MySQL_Lexer::HAVING_SYMBOL,
				WP_MySQL_Lexer::LIMIT_SYMBOL,
				WP_MySQL_Lexer::LOCK_SYMBOL,
				WP_MySQL_Lexer::ORDER_SYMBOL,
				WP_MySQL_Lexer::PROCEDURE_SYMBOL,
				WP_MySQL_Lexer::UNION_SYMBOL,
				WP_MySQL_Lexer::WHERE_SYMBOL,
			),
			$from_position + 1,
			$statement_end
		) ?? $statement_end;

		$inner_scope = $this->get_mysql_select_scope( $tokens, $from_position + 1, $from_end );
		if ( null === $inner_scope ) {
			return null;
		}

		$scope          = $this->merge_mysql_inner_and_outer_scopes( $inner_scope, $outer_scope );
		$replacements   = array();
		$where_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::WHERE_SYMBOL,
			$projection_start,
			$statement_end
		);
		if ( null !== $where_position ) {
			$where_end = $this->find_first_top_level_mysql_token(
				$tokens,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				),
				$where_position + 1,
				$statement_end
			) ?? $statement_end;

			$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$where_position + 1,
				$where_end,
				$scope
			);
			if ( $where_sql['changed'] ) {
				$replacements[] = array(
					'start' => $where_position + 1,
					'end'   => $where_end,
					'sql'   => $where_sql['sql'],
				);
			}
		}

		if ( empty( $replacements ) ) {
			return null;
		}

		return array(
			'sql'      => '(' . $this->translate_mysql_token_sequence_with_replacements_to_postgresql( $tokens, $select_position, $statement_end, $replacements ) . ')',
			'position' => $after_subquery - 1,
		);
	}

	/**
	 * Merge SELECT scopes so inner aliases shadow correlated outer aliases.
	 *
	 * @param array $inner_scope Inner SELECT table scope.
	 * @param array $outer_scope Outer SELECT table scope.
	 * @return array Combined scope.
	 */
	private function merge_mysql_inner_and_outer_scopes( array $inner_scope, array $outer_scope ): array {
		$scope = $inner_scope;
		foreach ( $outer_scope['aliases'] as $alias => $table ) {
			if ( ! isset( $scope['aliases'][ $alias ] ) ) {
				$scope['aliases'][ $alias ] = $table;
			}
		}

		if ( ! empty( $outer_scope['unknown'] ) ) {
			$scope['unknown'] = true;
		}

		return $scope;
	}

	/**
	 * Translate a numeric literal used as a standalone boolean predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_numeric_literal_truthiness_predicate_to_postgresql(
		array $tokens,
		int $position,
		int $end
	): ?array {
		$literal = $this->parse_mysql_numeric_literal( $tokens, $position, $end );
		if ( null === $literal || ! $this->is_mysql_boolean_predicate_literal_context( $tokens, $literal['start'], $literal['end'], $end ) ) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'(%s <> 0)',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $literal['start'], $literal['end'] )
			),
			'position' => $literal['end'] - 1,
		);
	}

	/**
	 * Check whether a numeric literal is a standalone boolean predicate operand.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First literal token.
	 * @param int             $end    Final literal token, exclusive.
	 * @param int             $limit  Final predicate token position, exclusive.
	 * @return bool Whether the literal is in predicate truthiness context.
	 */
	private function is_mysql_boolean_predicate_literal_context( array $tokens, int $start, int $end, int $limit ): bool {
		if ( $this->is_mysql_between_bound_literal_context( $tokens, $start ) ) {
			return false;
		}

		$previous_token_id = $tokens[ $start - 1 ]->id ?? null;
		$next_token_id     = $tokens[ $end ]->id ?? null;

		$left_boundary = 0 === $start
			|| $this->is_mysql_boolean_predicate_left_boundary_token_id( $previous_token_id )
			|| (
				WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $previous_token_id
				&& $this->is_mysql_boolean_predicate_left_boundary_token_id( $tokens[ $start - 2 ]->id ?? null )
			);
		if ( ! $left_boundary ) {
			return false;
		}

		return $end >= $limit || in_array(
			$next_token_id,
			array(
				WP_MySQL_Lexer::AND_SYMBOL,
				WP_MySQL_Lexer::CLOSE_PAR_SYMBOL,
				WP_MySQL_Lexer::OR_SYMBOL,
				WP_MySQL_Lexer::XOR_SYMBOL,
			),
			true
		);
	}

	/**
	 * Check whether a numeric literal belongs to a BETWEEN range.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First literal token.
	 * @return bool Whether the literal is a BETWEEN bound.
	 */
	private function is_mysql_between_bound_literal_context( array $tokens, int $start ): bool {
		$previous_token_id = $tokens[ $start - 1 ]->id ?? null;

		if ( WP_MySQL_Lexer::BETWEEN_SYMBOL === $previous_token_id ) {
			return true;
		}

		if (
			WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $previous_token_id
			&& WP_MySQL_Lexer::BETWEEN_SYMBOL === ( $tokens[ $start - 2 ]->id ?? null )
		) {
			return true;
		}

		$and_position = null;
		if ( WP_MySQL_Lexer::AND_SYMBOL === $previous_token_id ) {
			$and_position = $start - 1;
		} elseif (
			WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $previous_token_id
			&& WP_MySQL_Lexer::AND_SYMBOL === ( $tokens[ $start - 2 ]->id ?? null )
		) {
			$and_position = $start - 2;
		}

		return null !== $and_position && $this->is_mysql_between_upper_bound_separator( $tokens, $and_position );
	}

	/**
	 * Check whether an AND token separates the lower and upper BETWEEN bounds.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int             $and_position Candidate AND token position.
	 * @return bool Whether the AND token belongs to BETWEEN.
	 */
	private function is_mysql_between_upper_bound_separator( array $tokens, int $and_position ): bool {
		if ( ! isset( $tokens[ $and_position ] ) || WP_MySQL_Lexer::AND_SYMBOL !== $tokens[ $and_position ]->id ) {
			return false;
		}

		$depth = 0;
		for ( $i = $and_position - 1; $i >= 0; $i-- ) {
			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $i ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $i ]->id ) {
				--$depth;
				if ( $depth < 0 ) {
					return false;
				}
				continue;
			}

			if ( 0 !== $depth ) {
				continue;
			}

			if ( WP_MySQL_Lexer::BETWEEN_SYMBOL === $tokens[ $i ]->id ) {
				return true;
			}

			if (
				$this->is_mysql_boolean_predicate_left_boundary_token_id( $tokens[ $i ]->id )
				|| WP_MySQL_Lexer::HAVING_SYMBOL === $tokens[ $i ]->id
				|| WP_MySQL_Lexer::ON_SYMBOL === $tokens[ $i ]->id
				|| WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $i ]->id
			) {
				return false;
			}
		}

		return false;
	}

	/**
	 * Check whether a token can precede a standalone boolean predicate operand.
	 *
	 * @param int|null $token_id MySQL token ID.
	 * @return bool Whether the token is a boolean left boundary.
	 */
	private function is_mysql_boolean_predicate_left_boundary_token_id( ?int $token_id ): bool {
		return in_array(
			$token_id,
			array(
				WP_MySQL_Lexer::AND_SYMBOL,
				WP_MySQL_Lexer::NOT_SYMBOL,
				WP_MySQL_Lexer::OR_SYMBOL,
				WP_MySQL_Lexer::WHERE_SYMBOL,
				WP_MySQL_Lexer::XOR_SYMBOL,
			),
			true
		);
	}

	/**
	 * Translate DECIMAL casts used with string-pattern operators.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_decimal_cast_like_predicate_to_postgresql(
		array $tokens,
		int $position,
		int $end
	): ?array {
		$cast_bounds = $this->get_mysql_typed_cast_bounds( $tokens, $position, $end, array( 'decimal' ) );
		if ( null === $cast_bounds ) {
			return null;
		}

		$operator_position = $cast_bounds['close'] + 1;
		$not_sql           = '';
		if (
			isset( $tokens[ $operator_position ], $tokens[ $operator_position + 1 ] )
			&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $operator_position ]->id
			&& WP_MySQL_Lexer::LIKE_SYMBOL === $tokens[ $operator_position + 1 ]->id
		) {
			$not_sql            = ' NOT';
			$operator_position += 1;
		}

		if (
			! isset( $tokens[ $operator_position ], $tokens[ $operator_position + 1 ] )
			|| WP_MySQL_Lexer::LIKE_SYMBOL !== $tokens[ $operator_position ]->id
		) {
			return null;
		}

		$pattern_end = $this->get_mysql_like_pattern_end( $tokens, $operator_position + 1, $end );
		if ( null === $pattern_end ) {
			return null;
		}

		$has_explicit_escape = isset( $tokens[ $operator_position + 2 ] )
			&& WP_MySQL_Lexer::ESCAPE_SYMBOL === $tokens[ $operator_position + 2 ]->id;

		return array(
			'sql'      => sprintf(
				'CAST(%s AS text)%s LIKE %s%s',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $position, $cast_bounds['close'] + 1 ),
				$not_sql,
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $operator_position + 1, $pattern_end ),
				$has_explicit_escape ? '' : $this->get_mysql_no_backslash_like_escape_sql()
			),
			'position' => $pattern_end - 1,
		);
	}

	/**
	 * Get the end of a simple LIKE pattern expression.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Pattern token position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @return int|null Pattern end position, exclusive.
	 */
	private function get_mysql_like_pattern_end( array $tokens, int $position, int $end ): ?int {
		if ( ! isset( $tokens[ $position ] ) || $position >= $end ) {
			return null;
		}

		$pattern_end = $position + 1;
		if (
			isset( $tokens[ $pattern_end ], $tokens[ $pattern_end + 1 ] )
			&& WP_MySQL_Lexer::ESCAPE_SYMBOL === $tokens[ $pattern_end ]->id
			&& $pattern_end + 1 < $end
		) {
			$pattern_end += 2;
		}

		return $pattern_end;
	}

	/**
	 * Translate metadata-backed qualified column casing when MySQL casing differs.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unchanged/unsupported.
	 */
	private function translate_mysql_metadata_column_reference_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if ( null === $reference || null === $reference['qualifier'] ) {
			return null;
		}

		$resolved_column = $this->get_mysql_column_name_for_reference( $reference, $scope );
		if ( null === $resolved_column || $resolved_column === $reference['column'] ) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'%s.%s',
				$this->translate_mysql_token_to_postgresql( $tokens[ $reference['start'] ], $tokens[ $reference['start'] + 1 ] ?? null ),
				$this->translate_mysql_identifier_value_to_postgresql( $resolved_column )
			),
			'position' => $reference['end'] - 1,
		);
	}

	/**
	 * Resolve the stored MySQL column name for a scoped column reference.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return string|null Stored column name, or null when missing/ambiguous.
	 */
	private function get_mysql_column_name_for_reference( array $reference, array $scope ): ?string {
		if ( null === $reference['qualifier'] ) {
			return null;
		}

		$alias = strtolower( $reference['qualifier'] );
		if ( ! isset( $scope['aliases'][ $alias ] ) ) {
			return null;
		}

		$table = $scope['aliases'][ $alias ];
		if ( ! empty( $table['derived'] ) || null === ( $table['table'] ?? null ) ) {
			return null;
		}

		return $this->get_mysql_table_column_name( $table['schema'], $table['table'], $reference['column'] );
	}

	/**
	 * Get the metadata-backed stored column name for a MySQL column reference.
	 *
	 * @param string $table_schema Backend schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Referenced column name.
	 * @return string|null Stored column name, or null when no safe casing rewrite exists.
	 */
	private function get_mysql_table_column_name(
		string $table_schema,
		string $table_name,
		string $column_name
	): ?string {
		$metadata = $this->get_mysql_table_catalog_column_metadata_row( $table_schema, $table_name, $column_name );
		if ( null !== $metadata && array_key_exists( 'column_name', $metadata ) ) {
			return (string) $metadata['column_name'];
		}

		$exact_metadata = $this->get_mysql_table_catalog_column_metadata_rows(
			$table_schema,
			$table_name,
			$column_name,
			true
		);
		return 1 === count( $exact_metadata ) && array_key_exists( 'column_name', $exact_metadata[0] )
			? (string) $exact_metadata[0]['column_name']
			: null;
	}

	/**
	 * Translate a stored identifier value for PostgreSQL.
	 *
	 * @param string $identifier Identifier value.
	 * @return string PostgreSQL identifier SQL.
	 */
	private function translate_mysql_identifier_value_to_postgresql( string $identifier ): string {
		return $this->should_quote_bare_mysql_identifier( $identifier )
			? $this->connection->quote_identifier( $identifier )
			: $identifier;
	}

	/**
	 * Check whether a CAST type is MySQL DECIMAL/NUMERIC.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First cast type token.
	 * @param int             $end    Final cast type token, exclusive.
	 * @return bool Whether the type is supported.
	 */
	private function is_mysql_decimal_cast_type( array $tokens, int $start, int $end ): bool {
		if (
			! isset( $tokens[ $start ] )
			|| ! in_array(
				$tokens[ $start ]->id,
				array(
					WP_MySQL_Lexer::DECIMAL_SYMBOL,
					WP_MySQL_Lexer::NUMERIC_SYMBOL,
				),
				true
			)
		) {
			return false;
		}

		if ( $start + 1 === $end ) {
			return true;
		}

		return isset( $tokens[ $start + 1 ] )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $start + 1 ]->id
			&& $this->get_mysql_parenthesized_sequence_end( $tokens, $start + 1, $end ) === $end;
	}

	/**
	 * Translate an integer-column IN list containing string literals.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_integer_column_string_in_predicate_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if ( null === $reference ) {
			return null;
		}

		$in_position = $reference['end'];
		$not_sql     = '';
		if (
			isset( $tokens[ $in_position ], $tokens[ $in_position + 1 ] )
			&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $in_position ]->id
			&& WP_MySQL_Lexer::IN_SYMBOL === $tokens[ $in_position + 1 ]->id
		) {
			$not_sql      = ' NOT';
			$in_position += 1;
		}

		if (
			! isset( $tokens[ $in_position ], $tokens[ $in_position + 1 ] )
			|| WP_MySQL_Lexer::IN_SYMBOL !== $tokens[ $in_position ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $in_position + 1 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $in_position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		$items = $this->split_top_level_mysql_arguments( $tokens, $in_position + 2, $after_close - 1 );
		if ( null === $items ) {
			return null;
		}

		$changed  = false;
		$item_sql = array();
		foreach ( $items as $item ) {
			if ( $this->is_mysql_string_literal_range( $tokens, $item['start'], $item['end'] ) ) {
				$item_sql[] = $this->get_postgresql_mysql_integer_cast_sql(
					$this->translate_mysql_token_to_postgresql( $tokens[ $item['start'] ] )
				);
				$changed    = true;
				continue;
			}

			$item_sql[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $item['start'], $item['end'] );
		}

		if ( ! $changed ) {
			return null;
		}

		if ( ! $this->is_mysql_integer_column_reference( $reference, $scope ) ) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'%s%s IN (%s)',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] ),
				$not_sql,
				implode( ', ', $item_sql )
			),
			'position' => $after_close - 1,
		);
	}

	/**
	 * Translate an integer-column comparison against a string literal.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_integer_column_string_comparison_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if (
			null !== $reference
			&& isset( $tokens[ $reference['end'] ], $tokens[ $reference['end'] + 1 ] )
			&& $reference['end'] + 1 < $end
			&& $this->is_mysql_comparison_operator_token( $tokens[ $reference['end'] ] )
			&& $this->is_mysql_string_literal_token( $tokens[ $reference['end'] + 1 ] )
			&& $this->is_mysql_integer_column_reference( $reference, $scope )
		) {
			return array(
				'sql'      => sprintf(
					'%s %s %s',
					$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] ),
					$tokens[ $reference['end'] ]->get_bytes(),
					$this->get_postgresql_mysql_integer_cast_sql(
						$this->translate_mysql_token_to_postgresql( $tokens[ $reference['end'] + 1 ] )
					)
				),
				'position' => $reference['end'] + 1,
			);
		}

		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| ! $this->is_mysql_string_literal_token( $tokens[ $position ] )
			|| ! $this->is_mysql_comparison_operator_token( $tokens[ $position + 1 ] )
		) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $position + 2, $end );
		if ( null === $reference || ! $this->is_mysql_integer_column_reference( $reference, $scope ) ) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'%s %s %s',
				$this->get_postgresql_mysql_integer_cast_sql(
					$this->translate_mysql_token_to_postgresql( $tokens[ $position ] )
				),
				$tokens[ $position + 1 ]->get_bytes(),
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
			),
			'position' => $reference['end'] - 1,
		);
	}

	/**
	 * Translate a text-column comparison against a numeric literal.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_text_column_numeric_comparison_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if (
			null !== $reference
			&& isset( $tokens[ $reference['end'] ] )
			&& $this->is_mysql_comparison_operator_token( $tokens[ $reference['end'] ] )
			&& $this->is_mysql_text_family_column_reference( $reference, $scope )
		) {
			$literal = $this->parse_mysql_numeric_literal( $tokens, $reference['end'] + 1, $end );
			if ( null !== $literal ) {
				return array(
					'sql'      => sprintf(
						'%s %s %s',
						$this->get_postgresql_mysql_numeric_cast_sql(
							$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
						),
						$tokens[ $reference['end'] ]->get_bytes(),
						$this->translate_mysql_token_sequence_to_postgresql( $tokens, $literal['start'], $literal['end'] )
					),
					'position' => $literal['end'] - 1,
				);
			}
		}

		$literal = $this->parse_mysql_numeric_literal( $tokens, $position, $end );
		if (
			null === $literal
			|| ! isset( $tokens[ $literal['end'] ] )
			|| ! $this->is_mysql_comparison_operator_token( $tokens[ $literal['end'] ] )
		) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $literal['end'] + 1, $end );
		if ( null === $reference || ! $this->is_mysql_text_family_column_reference( $reference, $scope ) ) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'%s %s %s',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $literal['start'], $literal['end'] ),
				$tokens[ $literal['end'] ]->get_bytes(),
				$this->get_postgresql_mysql_numeric_cast_sql(
					$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
				)
			),
			'position' => $reference['end'] - 1,
		);
	}

	/**
	 * Translate a text-column numeric arithmetic expression.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate expression position.
	 * @param int             $end      Final expression token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_text_column_numeric_arithmetic_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if (
				null !== $reference
				&& isset( $tokens[ $reference['end'] ] )
				&& in_array(
					$tokens[ $reference['end'] ]->id,
					array(
						WP_MySQL_Lexer::MINUS_OPERATOR,
						WP_MySQL_Lexer::PLUS_OPERATOR,
					),
					true
				)
				&& $this->is_mysql_text_family_column_reference( $reference, $scope )
			) {
			$literal = $this->parse_mysql_numeric_literal( $tokens, $reference['end'] + 1, $end );
			if ( null !== $literal ) {
				$reference_sql = $this->get_postgresql_mysql_numeric_cast_sql(
					$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
				);
				if ( $this->is_mysql_zero_numeric_literal_range( $tokens, $literal['start'], $literal['end'] ) ) {
					return array(
						'sql'      => $reference_sql,
						'position' => $literal['end'] - 1,
					);
				}

				return array(
					'sql'      => sprintf(
						'%s %s %s',
						$reference_sql,
						$tokens[ $reference['end'] ]->get_bytes(),
						$this->translate_mysql_token_sequence_to_postgresql( $tokens, $literal['start'], $literal['end'] )
					),
					'position' => $literal['end'] - 1,
				);
			}
		}

		$literal = $this->parse_mysql_numeric_literal( $tokens, $position, $end );
		if (
				null === $literal
				|| ! isset( $tokens[ $literal['end'] ] )
				|| ! in_array(
					$tokens[ $literal['end'] ]->id,
					array(
						WP_MySQL_Lexer::MINUS_OPERATOR,
						WP_MySQL_Lexer::PLUS_OPERATOR,
					),
					true
				)
			) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $literal['end'] + 1, $end );
		if ( null === $reference || ! $this->is_mysql_text_family_column_reference( $reference, $scope ) ) {
			return null;
		}

		$reference_sql = $this->get_postgresql_mysql_numeric_cast_sql(
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
		);
		if (
				WP_MySQL_Lexer::PLUS_OPERATOR === $tokens[ $literal['end'] ]->id
				&& $this->is_mysql_zero_numeric_literal_range( $tokens, $literal['start'], $literal['end'] )
			) {
			return array(
				'sql'      => $reference_sql,
				'position' => $reference['end'] - 1,
			);
		}

			return array(
				'sql'      => sprintf(
					'%s %s %s',
					$this->translate_mysql_token_sequence_to_postgresql( $tokens, $literal['start'], $literal['end'] ),
					$tokens[ $literal['end'] ]->get_bytes(),
					$reference_sql
				),
				'position' => $reference['end'] - 1,
			);
	}

	/**
	 * Build a single-table statement scope.
	 *
	 * @param string      $table_name Table name.
	 * @param string|null $alias      Optional table alias.
	 * @param string      $schema     Metadata schema.
	 * @return array Statement scope.
	 */
	private function get_mysql_single_table_scope(
		string $table_name,
		?string $alias = null,
		string $schema = 'public'
	): array {
		$resolved_schema = 'public' === $schema
			? $this->get_mysql_unqualified_dml_table_backend_schema( $table_name )
			: $this->resolve_mysql_table_schema_for_introspection( $schema, $table_name );
		$table           = array(
			'schema' => $resolved_schema,
			'table'  => $table_name,
		);

		return array(
			'tables'  => array( $table ),
			'aliases' => array(
				strtolower( null === $alias ? $table_name : $alias ) => $table,
			),
		);
	}

	/**
	 * Resolve the backend schema for a parsed table reference.
	 *
	 * @param array{schema: string, table: string, alias: string|null, position: int, schema_qualified?: bool} $reference Parsed table reference.
	 * @return string Backend schema.
	 */
	private function get_mysql_table_reference_backend_schema( array $reference ): string {
		if ( empty( $reference['schema_qualified'] ) && 'public' === $reference['schema'] ) {
			return $this->get_mysql_unqualified_dml_table_backend_schema( $reference['table'] );
		}

		return $this->resolve_mysql_table_schema_for_introspection( $reference['schema'], $reference['table'] );
	}

	/**
	 * Check whether a statement scope reads any non-public backend schema.
	 *
	 * @param array $scope Statement table scope.
	 * @return bool Whether the scope references a non-public schema.
	 */
	private function mysql_scope_references_non_public_schema( array $scope ): bool {
		foreach ( $scope['tables'] ?? array() as $table ) {
			if ( 'public' !== ( $table['schema'] ?? 'public' ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Translate a MySQL table-reference range with schema-aware table rendering.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First table-reference token.
	 * @param int              $end    Final table-reference token, exclusive.
	 * @return string|null PostgreSQL SQL, or null when the range is unsupported.
	 */
	private function translate_mysql_table_reference_range_to_postgresql( array $tokens, int $start, int $end ): ?string {
		$chunks        = array();
		$segment_start = $start;
		$position      = $start;
		$expect_next   = true;

		while ( $position < $end ) {
			if ( $expect_next ) {
				if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === ( $tokens[ $position ]->id ?? null ) ) {
					return null;
				}

				$reference = $this->parse_mysql_table_reference( $tokens, $position, $end );
				if ( null === $reference ) {
					return null;
				}

				if ( $segment_start < $position ) {
					$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $segment_start, $position );
				}

				$chunks[]      = $this->get_postgresql_table_reference_sql( $reference );
				$position      = $reference['position'];
				$segment_start = $position;
				$expect_next   = false;
				continue;
			}

			if (
				WP_MySQL_Lexer::COMMA_SYMBOL === ( $tokens[ $position ]->id ?? null )
				|| $this->is_mysql_join_token( $tokens[ $position ] )
			) {
				$expect_next = true;
			}

			++$position;
		}

		if ( $segment_start < $end ) {
			$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $segment_start, $end );
		}

		return implode( ' ', array_filter( $chunks, 'strlen' ) );
	}

	/**
	 * Render a parsed table reference for PostgreSQL.
	 *
	 * @param array{schema: string, table: string, alias: string|null, position: int, schema_qualified?: bool} $reference Parsed table reference.
	 * @return string PostgreSQL table reference SQL.
	 */
	private function get_postgresql_table_reference_sql( array $reference ): string {
		$sql = $this->get_postgresql_table_identifier_sql(
			$this->get_mysql_table_reference_backend_schema( $reference ),
			$reference['table']
		);

		if ( null !== $reference['alias'] ) {
			$sql .= ' AS ' . $this->connection->quote_identifier( $reference['alias'] );
		}

		return $sql;
	}

	/**
	 * Parse top-level SELECT table references into a metadata lookup scope.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First FROM-clause token after FROM.
	 * @param int             $end    Final FROM-clause token, exclusive.
	 * @return array|null Statement scope, or null when ambiguous/unsupported.
	 */
	private function get_mysql_select_scope( array $tokens, int $start, int $end ): ?array {
		$scope       = array(
			'tables'  => array(),
			'aliases' => array(),
			'unknown' => false,
		);
		$position    = $start;
		$expect_next = true;

		while ( $position < $end ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				$after_parentheses = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
				if ( null === $after_parentheses ) {
					return null;
				}

				$position = $after_parentheses;
				if ( $expect_next ) {
					$scope['unknown'] = true;
					$position         = $this->skip_mysql_table_alias( $tokens, $position, $end );
					$expect_next      = false;
				}
				continue;
			}

			if ( $expect_next ) {
				$reference = $this->parse_mysql_table_reference( $tokens, $position, $end );
				if ( null === $reference ) {
					return null;
				}

				$table = array(
					'schema' => $this->get_mysql_table_reference_backend_schema( $reference ),
					'table'  => $reference['table'],
				);
				$alias = strtolower( null === $reference['alias'] ? $reference['table'] : $reference['alias'] );
				if ( isset( $scope['aliases'][ $alias ] ) ) {
					return null;
				}

				$scope['tables'][]          = $table;
				$scope['aliases'][ $alias ] = $table;
				$position                   = $reference['position'];
				$expect_next                = false;
				continue;
			}

			if (
				WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id
				|| $this->is_mysql_join_token( $tokens[ $position ] )
			) {
				$expect_next = true;
			}

			++$position;
		}

		return empty( $scope['tables'] ) || $expect_next ? null : $scope;
	}

	/**
	 * Parse an unqualified or main database-qualified MySQL table target.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Table-name start position, updated on success.
	 * @return string|null Table name, or null when unsupported.
	 */
	private function parse_mysql_main_database_table_name( array $tokens, int &$position ): ?string {
		$first_identifier = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null, true );
		if ( null === $first_identifier ) {
			return null;
		}

		++$position;
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $position ]->id ) {
			return $first_identifier;
		}

		$table_name = $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null, true );
		if ( null === $table_name || 0 !== strcasecmp( $first_identifier, $this->main_db_name ) ) {
			return null;
		}

		$position += 2;
		return $table_name;
	}

	/**
	 * Parse an unqualified or main database-qualified MySQL table reference.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Table-reference start position, updated on success.
	 * @param int              $end      Final token position, exclusive.
	 * @return array{table: string, alias: string|null}|null Parsed table reference, or null when unsupported.
	 */
	private function parse_mysql_main_database_table_reference( array $tokens, int &$position, int $end ): ?array {
		$table_name = $this->parse_mysql_main_database_table_name( $tokens, $position );
		if ( null === $table_name ) {
			return null;
		}

		$alias = null;
		if ( $position + 1 < $end && WP_MySQL_Lexer::AS_SYMBOL === ( $tokens[ $position ]->id ?? null ) ) {
			$alias = $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null );
			if ( null === $alias ) {
				return null;
			}

			$position += 2;
		} else {
			$implicit_alias = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
			if ( null !== $implicit_alias ) {
				$alias = $implicit_alias;
				++$position;
			}
		}

		return array(
			'table' => $table_name,
			'alias' => $alias,
		);
	}

	/**
	 * Render a PostgreSQL DML table reference with optional alias.
	 *
	 * @param string      $table_name Table name.
	 * @param string|null $alias      Optional table alias.
	 * @return string PostgreSQL table reference SQL.
	 */
	private function get_postgresql_dml_table_reference_sql( string $table_name, ?string $alias ): string {
		$sql = $this->get_postgresql_unqualified_dml_table_reference_sql( $table_name );
		if ( null !== $alias ) {
			$sql .= ' AS ' . $this->connection->quote_identifier( $alias );
		}

		return $sql;
	}

	/**
	 * Render a PostgreSQL target ctid reference for bounded UPDATE/DELETE rewrites.
	 *
	 * @param string|null $alias Optional table alias.
	 * @return string PostgreSQL ctid reference SQL.
	 */
	private function get_postgresql_dml_ctid_reference_sql( ?string $alias ): string {
		if ( null === $alias ) {
			return 'ctid';
		}

		return $this->connection->quote_identifier( $alias ) . '.ctid';
	}

	/**
	 * Render a PostgreSQL target-column reference for DML predicates.
	 *
	 * @param string      $column Column name.
	 * @param string|null $alias  Optional table alias.
	 * @return string PostgreSQL column reference SQL.
	 */
	private function get_postgresql_dml_column_reference_sql( string $column, ?string $alias ): string {
		$column_sql = $this->connection->quote_identifier( $column );
		if ( null === $alias ) {
			return $column_sql;
		}

		return $this->connection->quote_identifier( $alias ) . '.' . $column_sql;
	}

	/**
	 * Check whether a MySQL table qualifier names the current DML target.
	 *
	 * @param string      $qualifier  MySQL qualifier.
	 * @param string      $table_name Table name.
	 * @param string|null $alias      Optional table alias.
	 * @return bool Whether the qualifier is supported.
	 */
	private function is_mysql_dml_table_qualifier( string $qualifier, string $table_name, ?string $alias ): bool {
		return 0 === strcasecmp( $qualifier, $table_name )
			|| ( null !== $alias && 0 === strcasecmp( $qualifier, $alias ) );
	}

	/**
	 * Get PostgreSQL SQL for an unqualified or main database-qualified table target.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First table-reference token position.
	 * @param int              $end    Final table-reference token position, exclusive.
	 * @return string PostgreSQL table reference SQL.
	 */
	private function get_mysql_main_database_table_reference_sql( array $tokens, int $start, int $end ): string {
		if (
			$start + 3 === $end
			&& isset( $tokens[ $start + 1 ], $tokens[ $start + 2 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 1 ]->id
		) {
			if ( WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $tokens[ $start + 2 ]->id ) {
				return $this->connection->quote_identifier( $tokens[ $start + 2 ]->get_value() );
			}

			return $this->translate_mysql_identifier_token_to_postgresql( $tokens[ $start + 2 ] );
		}

		if ( isset( $tokens[ $start ] ) && WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $tokens[ $start ]->id ) {
			$table_name   = $tokens[ $start ]->get_value();
			$table_schema = $this->get_mysql_unqualified_dml_table_backend_schema( $table_name );
			if ( 'public' !== $table_schema ) {
				return $this->get_postgresql_schema_identifier( $table_schema, $table_name );
			}

			return $this->connection->quote_identifier( $table_name );
		}

		$table_name = $this->get_mysql_identifier_token_value( $tokens[ $start ] ?? null, true );
		if ( null !== $table_name ) {
			$table_schema = $this->get_mysql_unqualified_dml_table_backend_schema( $table_name );
			if ( 'public' !== $table_schema ) {
				return $this->get_postgresql_schema_identifier( $table_schema, $table_name );
			}
		}

		return $this->translate_mysql_identifier_token_to_postgresql( $tokens[ $start ] ?? null );
	}

	/**
	 * Parse a simple table reference and optional alias.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Table reference start position.
	 * @param int             $end      Final FROM-clause token, exclusive.
	 * @return array{schema: string, table: string, alias: string|null, position: int, schema_qualified: bool}|null Parsed table reference.
	 */
	private function parse_mysql_table_reference( array $tokens, int $position, int $end ): ?array {
		$first_identifier = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first_identifier ) {
			return null;
		}

		$schema           = 'public';
		$table            = $first_identifier;
		$schema_qualified = false;
		++$position;

		if ( $position + 1 < $end && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position ]->id ) {
			$second_identifier = $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null );
			if ( null === $second_identifier ) {
				return null;
			}

			$schema           = $first_identifier;
			$table            = $second_identifier;
			$schema_qualified = true;
			$position        += 2;
		}

		$alias = null;
		if ( $position + 1 < $end && WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $position ]->id ) {
			$alias = $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null );
			if ( null === $alias ) {
				return null;
			}

			$position += 2;
		} else {
			$implicit_alias = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
			if ( null !== $implicit_alias ) {
				$alias = $implicit_alias;
				++$position;
			}
		}

		return array(
			'schema'           => $schema,
			'table'            => $table,
			'alias'            => $alias,
			'position'         => $position,
			'schema_qualified' => $schema_qualified,
		);
	}

	/**
	 * Skip a derived-table alias when one is present.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Current token position.
	 * @param int             $end      Final FROM-clause token, exclusive.
	 * @return int Position after the alias.
	 */
	private function skip_mysql_table_alias( array $tokens, int $position, int $end ): int {
		if ( $position + 1 < $end && WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $position ]->id ) {
			return null === $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null )
				? $position
				: $position + 2;
		}

		return null === $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null )
			? $position
			: $position + 1;
	}

	/**
	 * Check whether a token starts a JOIN table operand.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is a JOIN separator.
	 */
	private function is_mysql_join_token( WP_MySQL_Token $token ): bool {
		return WP_MySQL_Lexer::JOIN_SYMBOL === $token->id || WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL === $token->id;
	}

	/**
	 * Parse a simple column reference.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Column reference start position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{start: int, end: int, qualifier: string|null, column: string}|null Parsed reference.
	 */
	private function parse_mysql_column_reference( array $tokens, int $position, int $end ): ?array {
		$first_identifier = $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first_identifier ) {
			return null;
		}

		if ( $position + 2 < $end && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position + 1 ]->id ) {
			$column = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 2 ] ?? null );
			if ( null === $column ) {
				return null;
			}

			return array(
				'start'     => $position,
				'end'       => $position + 3,
				'qualifier' => $first_identifier,
				'column'    => $column,
			);
		}

		return array(
			'start'     => $position,
			'end'       => $position + 1,
			'qualifier' => null,
			'column'    => $first_identifier,
		);
	}

	/**
	 * Check whether a column reference resolves to one integer-family MySQL column.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return bool Whether the reference is a known integer column.
	 */
	private function is_mysql_integer_column_reference( array $reference, array $scope ): bool {
		$column_type = $this->get_mysql_column_type_for_reference( $reference, $scope );
		return null !== $column_type && $this->is_mysql_integer_family_column_type( $column_type );
	}

	/**
	 * Check whether a column reference resolves to one text-family MySQL column.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return bool Whether the reference is a known text column.
	 */
	private function is_mysql_text_family_column_reference( array $reference, array $scope ): bool {
		$column_type = $this->get_mysql_column_type_for_reference( $reference, $scope );
		return null !== $column_type && $this->is_mysql_text_family_column_type( $column_type );
	}

	/**
	 * Check whether a MySQL column type belongs to the text family.
	 *
	 * @param string $column_type MySQL column type metadata.
	 * @return bool Whether the type stores textual data.
	 */
	private function is_mysql_text_family_column_type( string $column_type ): bool {
		return in_array(
			$this->get_base_mysql_dml_column_type( $column_type ),
			array(
				'char',
				'longtext',
				'mediumtext',
				'text',
				'tinytext',
				'varchar',
			),
			true
		);
	}

	/**
	 * Resolve a column reference to stored MySQL column type metadata.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return string|null MySQL column type, or null when missing/ambiguous.
	 */
	private function get_mysql_column_type_for_reference( array $reference, array $scope ): ?string {
		if ( null !== $reference['qualifier'] ) {
			$alias = strtolower( $reference['qualifier'] );
			if ( ! isset( $scope['aliases'][ $alias ] ) ) {
				return null;
			}

			$table = $scope['aliases'][ $alias ];
			if ( ! empty( $table['derived'] ) || null === ( $table['table'] ?? null ) ) {
				return null;
			}

			return $this->get_mysql_table_column_type( $table['schema'], $table['table'], $reference['column'] );
		}

		if ( ! empty( $scope['unknown'] ) ) {
			return null;
		}

		$matched_type = null;
		foreach ( $scope['tables'] as $table ) {
			if ( ! empty( $table['derived'] ) || null === ( $table['table'] ?? null ) ) {
				return null;
			}

			if (
				count( $scope['tables'] ) > 1
				&& ! $this->mysql_table_has_column_metadata( $table['schema'], $table['table'] )
			) {
				return null;
			}

			$column_type = $this->get_mysql_table_column_type( $table['schema'], $table['table'], $reference['column'] );
			if ( null === $column_type ) {
				continue;
			}

			if ( null !== $matched_type ) {
				return null;
			}

			$matched_type = $column_type;
		}

		return $matched_type;
	}

	/**
	 * Resolve a column reference to stored MySQL collation metadata.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return string|null MySQL collation, or null when missing/ambiguous.
	 */
	private function get_mysql_column_collation_for_reference( array $reference, array $scope ): ?string {
		if ( null !== $reference['qualifier'] ) {
			$alias = strtolower( $reference['qualifier'] );
			if ( ! isset( $scope['aliases'][ $alias ] ) ) {
				return null;
			}

			$table = $scope['aliases'][ $alias ];
			if ( ! empty( $table['derived'] ) || null === ( $table['table'] ?? null ) ) {
				return null;
			}

			return $this->get_mysql_table_column_collation( $table['schema'], $table['table'], $reference['column'] );
		}

		if ( ! empty( $scope['unknown'] ) ) {
			return null;
		}

		$matched_collation = null;
		foreach ( $scope['tables'] as $table ) {
			if ( ! empty( $table['derived'] ) || null === ( $table['table'] ?? null ) ) {
				return null;
			}

			if (
				count( $scope['tables'] ) > 1
				&& ! $this->mysql_table_has_column_metadata( $table['schema'], $table['table'] )
			) {
				return null;
			}

			$collation = $this->get_mysql_table_column_collation( $table['schema'], $table['table'], $reference['column'] );
			if ( null === $collation ) {
				continue;
			}

			if ( null !== $matched_collation ) {
				return null;
			}

			$matched_collation = $collation;
		}

		return $matched_collation;
	}

	/**
	 * Check whether a token range is exactly one string literal.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First token position.
	 * @param int             $end    Final token position, exclusive.
	 * @return bool Whether the range is one string literal.
	 */
	private function is_mysql_string_literal_range( array $tokens, int $start, int $end ): bool {
		return $start + 1 === $end && isset( $tokens[ $start ] ) && $this->is_mysql_string_literal_token( $tokens[ $start ] );
	}

	/**
	 * Check whether a token range is a literal zero value.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First literal token.
	 * @param int             $end    Final literal token, exclusive.
	 * @return bool Whether the literal is zero.
	 */
	private function is_mysql_zero_literal_range( array $tokens, int $start, int $end ): bool {
		if ( $this->is_mysql_string_literal_range( $tokens, $start, $end ) ) {
			return 1 === preg_match( '/^[[:space:]]*[+]?0+[[:space:]]*$/', $tokens[ $start ]->get_value() );
		}

		$literal = $this->parse_mysql_numeric_literal( $tokens, $start, $end );
		return null !== $literal
			&& $literal['start'] === $start
			&& $literal['end'] === $end
			&& $this->is_mysql_zero_numeric_literal_range( $tokens, $start, $end );
	}

	/**
	 * Parse a numeric literal, including an optional unary sign.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Literal start position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{start: int, end: int}|null Numeric literal bounds.
	 */
	private function parse_mysql_numeric_literal( array $tokens, int $position, int $end ): ?array {
		if ( ! isset( $tokens[ $position ] ) || $position >= $end ) {
			return null;
		}

		if (
			(
				WP_MySQL_Lexer::PLUS_OPERATOR === $tokens[ $position ]->id
				|| WP_MySQL_Lexer::MINUS_OPERATOR === $tokens[ $position ]->id
			)
			&& isset( $tokens[ $position + 1 ] )
			&& $position + 1 < $end
			&& $this->is_mysql_numeric_literal_token( $tokens[ $position + 1 ] )
		) {
			return array(
				'start' => $position,
				'end'   => $position + 2,
			);
		}

		if ( $this->is_mysql_numeric_literal_token( $tokens[ $position ] ) ) {
			return array(
				'start' => $position,
				'end'   => $position + 1,
			);
		}

		return null;
	}

	/**
	 * Check whether a numeric literal range represents zero.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First literal token.
	 * @param int             $end    Final literal token, exclusive.
	 * @return bool Whether the literal is numeric zero.
	 */
	private function is_mysql_zero_numeric_literal_range( array $tokens, int $start, int $end ): bool {
		if ( ! isset( $tokens[ $start ] ) ) {
			return false;
		}

		if (
			$start + 2 === $end
			&& (
				WP_MySQL_Lexer::PLUS_OPERATOR === $tokens[ $start ]->id
				|| WP_MySQL_Lexer::MINUS_OPERATOR === $tokens[ $start ]->id
			)
		) {
			++$start;
		}

		return $start + 1 === $end
			&& $this->is_mysql_numeric_literal_token( $tokens[ $start ] )
			&& 0.0 === (float) $tokens[ $start ]->get_value();
	}

	/**
	 * Check whether a numeric literal range is an integer token.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First literal token.
	 * @param int             $end    Final literal token, exclusive.
	 * @return bool Whether the literal is a signed or unsigned integer token.
	 */
	private function is_mysql_integer_numeric_literal_range( array $tokens, int $start, int $end ): bool {
		if ( ! isset( $tokens[ $start ] ) ) {
			return false;
		}

		if (
			$start + 2 === $end
			&& (
				WP_MySQL_Lexer::PLUS_OPERATOR === $tokens[ $start ]->id
				|| WP_MySQL_Lexer::MINUS_OPERATOR === $tokens[ $start ]->id
			)
		) {
			++$start;
		}

		return $start + 1 === $end
			&& in_array(
				$tokens[ $start ]->id,
				array(
					WP_MySQL_Lexer::INT_NUMBER,
					WP_MySQL_Lexer::LONG_NUMBER,
					WP_MySQL_Lexer::ULONGLONG_NUMBER,
				),
				true
			);
	}

	/**
	 * Check whether a token is a numeric literal.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is a numeric literal.
	 */
	private function is_mysql_numeric_literal_token( WP_MySQL_Token $token ): bool {
		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::DECIMAL_NUMBER,
				WP_MySQL_Lexer::FLOAT_NUMBER,
				WP_MySQL_Lexer::INT_NUMBER,
				WP_MySQL_Lexer::LONG_NUMBER,
				WP_MySQL_Lexer::ULONGLONG_NUMBER,
			),
			true
		);
	}

	/**
	 * Check whether a token is a string literal.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is a string literal.
	 */
	private function is_mysql_string_literal_token( WP_MySQL_Token $token ): bool {
		return WP_MySQL_Lexer::SINGLE_QUOTED_TEXT === $token->id || WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $token->id;
	}

	/**
	 * Check whether a token is a simple comparison operator.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is a comparison operator.
	 */
	private function is_mysql_comparison_operator_token( WP_MySQL_Token $token ): bool {
		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::EQUAL_OPERATOR,
				WP_MySQL_Lexer::GREATER_OR_EQUAL_OPERATOR,
				WP_MySQL_Lexer::GREATER_THAN_OPERATOR,
				WP_MySQL_Lexer::LESS_OR_EQUAL_OPERATOR,
				WP_MySQL_Lexer::LESS_THAN_OPERATOR,
				WP_MySQL_Lexer::NOT_EQUAL_OPERATOR,
			),
			true
		);
	}

	/**
	 * Validate the simple expression fragments used by translated DML/SELECT.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First fragment token position.
	 * @param int             $end    Final fragment token position, exclusive.
	 * @return bool Whether the expression fragment is supported.
	 */
	private function is_supported_simple_mysql_expression_fragment( array $tokens, int $start, int $end ): bool {
		for ( $i = $start; $i < $end; $i++ ) {
			$date_arithmetic = $this->translate_mysql_date_arithmetic_to_postgresql( $tokens, $i, $end );
			if ( null !== $date_arithmetic ) {
				$i = $date_arithmetic['position'];
				continue;
			}

			$infix_interval = $this->translate_mysql_infix_interval_expression_to_postgresql( $tokens, $i, $end );
			if ( null !== $infix_interval ) {
				$i = $infix_interval['position'];
				continue;
			}

			$temporal_cast_end = $this->get_mysql_temporal_cast_or_convert_expression_end( $tokens, $i, $end );
			if ( null !== $temporal_cast_end ) {
				$i = $temporal_cast_end - 1;
				continue;
			}

			$common_function = $this->translate_mysql_common_function_to_postgresql( $tokens, $i, $end );
			if ( null !== $common_function ) {
				$i = $common_function['position'];
				continue;
			}

			if ( ! $this->is_supported_simple_mysql_expression_token( $tokens[ $i ] ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Validate a simple expression fragment while skipping handled replacement ranges.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $start        First fragment token position.
	 * @param int              $end          Final fragment token position, exclusive.
	 * @param array[]          $replacements Replacement ranges with translated SQL.
	 * @return bool Whether the expression fragment is supported.
	 */
	private function is_supported_simple_mysql_expression_fragment_with_replacements( array $tokens, int $start, int $end, array $replacements ): bool {
		if ( empty( $replacements ) ) {
			return $this->is_supported_simple_mysql_expression_fragment( $tokens, $start, $end );
		}

		for ( $i = $start; $i < $end; $i++ ) {
			$replacement_end = $this->get_covering_mysql_replacement_range_end( $i, $replacements );
			if ( null !== $replacement_end ) {
				$i = $replacement_end - 1;
				continue;
			}

			if ( ! $this->is_supported_simple_mysql_expression_token( $tokens[ $i ] ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Check that identifier references in a simple expression resolve to scope columns.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First expression token.
	 * @param int              $end    Final expression token, exclusive.
	 * @param array            $scope  Statement table scope.
	 * @return bool Whether all column-like references resolve to the supplied scope.
	 */
	private function mysql_expression_column_references_resolve_to_scope( array $tokens, int $start, int $end, array $scope ): bool {
		for ( $position = $start; $position < $end; $position++ ) {
			if ( $this->is_mysql_qualified_reference_suffix_position( $tokens, $position, $start ) ) {
				continue;
			}

			if ( null !== $this->translate_mysql_nonparenthesized_timestamp_function_to_postgresql( $tokens, $position, $end ) ) {
				continue;
			}

			$temporal_cast_end = $this->get_mysql_temporal_cast_or_convert_expression_end( $tokens, $position, $end );
			if ( null !== $temporal_cast_end ) {
				$position = $temporal_cast_end - 1;
				continue;
			}

			if ( null === $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] ?? null ) ) {
				continue;
			}

			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === ( $tokens[ $position + 1 ]->id ?? null ) ) {
				continue;
			}

			$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
			if ( null === $reference ) {
				continue;
			}

			if ( null === $this->get_mysql_column_type_for_reference( $reference, $scope ) ) {
				return false;
			}

			$position = $reference['end'] - 1;
		}

		return true;
	}

	/**
	 * Get the end position for a supported temporal CAST/CONVERT expression.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position First expression token.
	 * @param int              $end      Final expression token, exclusive.
	 * @return int|null End position, exclusive, or null when not a supported temporal CAST/CONVERT expression.
	 */
	private function get_mysql_temporal_cast_or_convert_expression_end( array $tokens, int $position, int $end ): ?int {
		$temporal_cast = $this->get_mysql_typed_cast_or_convert_bounds(
			$tokens,
			$position,
			$end,
			array(
				'cast'    => array( 'date_time', 'date' ),
				'convert' => array( 'date' ),
			)
		);

		return null === $temporal_cast ? null : $temporal_cast['close'] + 1;
	}

	/**
	 * Check that qualified references in a simple expression use statement aliases.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First expression token.
	 * @param int              $end    Final expression token, exclusive.
	 * @param array            $scope  Statement table scope.
	 * @return bool Whether all qualified references use the supplied scope.
	 */
	private function mysql_expression_qualified_references_resolve_to_scope( array $tokens, int $start, int $end, array $scope ): bool {
		for ( $position = $start; $position < $end; $position++ ) {
			if ( $this->is_mysql_qualified_reference_suffix_position( $tokens, $position, $start ) ) {
				continue;
			}

			if ( null !== $this->translate_mysql_nonparenthesized_timestamp_function_to_postgresql( $tokens, $position, $end ) ) {
				continue;
			}

			$temporal_cast_end = $this->get_mysql_temporal_cast_or_convert_expression_end( $tokens, $position, $end );
			if ( null !== $temporal_cast_end ) {
				$position = $temporal_cast_end - 1;
				continue;
			}

			if ( null === $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] ?? null ) ) {
				continue;
			}

			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === ( $tokens[ $position + 1 ]->id ?? null ) ) {
				continue;
			}

			$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
			if ( null === $reference ) {
				continue;
			}

			if (
				null !== $reference['qualifier']
				&& ! isset( $scope['aliases'][ strtolower( $reference['qualifier'] ) ] )
			) {
				return false;
			}

			$position = $reference['end'] - 1;
		}

		return true;
	}

	/**
	 * Validate a token for a simple expression fragment.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is supported.
	 */
	private function is_supported_simple_mysql_expression_token( WP_MySQL_Token $token ): bool {
		if ( null !== $this->get_mysql_dml_identifier_token_value( $token ) ) {
			return true;
		}

		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::AND_SYMBOL,
				WP_MySQL_Lexer::CASE_SYMBOL,
				WP_MySQL_Lexer::CLOSE_PAR_SYMBOL,
				WP_MySQL_Lexer::COALESCE_SYMBOL,
				WP_MySQL_Lexer::COMMA_SYMBOL,
				WP_MySQL_Lexer::DECIMAL_NUMBER,
				WP_MySQL_Lexer::DOT_SYMBOL,
				WP_MySQL_Lexer::EQUAL_OPERATOR,
				WP_MySQL_Lexer::ELSE_SYMBOL,
				WP_MySQL_Lexer::END_SYMBOL,
				WP_MySQL_Lexer::FALSE_SYMBOL,
				WP_MySQL_Lexer::FLOAT_NUMBER,
				WP_MySQL_Lexer::GREATER_OR_EQUAL_OPERATOR,
				WP_MySQL_Lexer::GREATER_THAN_OPERATOR,
				WP_MySQL_Lexer::HEX_NUMBER,
				WP_MySQL_Lexer::IN_SYMBOL,
				WP_MySQL_Lexer::INT_NUMBER,
				WP_MySQL_Lexer::IS_SYMBOL,
				WP_MySQL_Lexer::LESS_OR_EQUAL_OPERATOR,
				WP_MySQL_Lexer::LESS_THAN_OPERATOR,
				WP_MySQL_Lexer::LIKE_SYMBOL,
				WP_MySQL_Lexer::LONG_NUMBER,
				WP_MySQL_Lexer::MINUS_OPERATOR,
				WP_MySQL_Lexer::MULT_OPERATOR,
				WP_MySQL_Lexer::NOT_SYMBOL,
				WP_MySQL_Lexer::NOT_EQUAL_OPERATOR,
				WP_MySQL_Lexer::NULL_SYMBOL,
				WP_MySQL_Lexer::NOW_SYMBOL,
				WP_MySQL_Lexer::OPEN_PAR_SYMBOL,
				WP_MySQL_Lexer::OR_SYMBOL,
				WP_MySQL_Lexer::PLUS_OPERATOR,
				WP_MySQL_Lexer::REGEXP_SYMBOL,
				WP_MySQL_Lexer::SINGLE_QUOTED_TEXT,
				WP_MySQL_Lexer::CURRENT_TIMESTAMP_SYMBOL,
				WP_MySQL_Lexer::SUBSTR_SYMBOL,
				WP_MySQL_Lexer::SUBSTRING_SYMBOL,
				WP_MySQL_Lexer::THEN_SYMBOL,
				WP_MySQL_Lexer::TRUE_SYMBOL,
				WP_MySQL_Lexer::ULONGLONG_NUMBER,
				WP_MySQL_Lexer::WHEN_SYMBOL,
				WP_MySQL_Lexer::XOR_SYMBOL,
			),
			true
		);
	}

	/**
	 * Validate a simple ORDER BY clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  ORDER token position.
	 * @param int             $end    Final clause token position, exclusive.
	 * @return bool Whether the ORDER BY clause is supported.
	 */
	private function is_supported_simple_select_order_by_clause( array $tokens, int $start, int $end ): bool {
		if (
			$start + 2 >= $end
			|| WP_MySQL_Lexer::ORDER_SYMBOL !== $tokens[ $start ]->id
			|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $start + 1 ]->id
		) {
			return false;
		}

		$reference_end = $end;
		if (
			WP_MySQL_Lexer::ASC_SYMBOL === ( $tokens[ $end - 1 ]->id ?? null )
			|| WP_MySQL_Lexer::DESC_SYMBOL === ( $tokens[ $end - 1 ]->id ?? null )
		) {
			--$reference_end;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $start + 2, $reference_end );
		return null !== $reference && $reference['end'] === $reference_end;
	}

	/**
	 * Validate a safe trailing SELECT LIMIT clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  LIMIT token position.
	 * @param int             $end    Final clause token position, exclusive.
	 * @return bool Whether the LIMIT clause is supported.
	 */
	private function is_supported_simple_select_limit_clause( array $tokens, int $start, int $end ): bool {
		if (
			! isset( $tokens[ $start ], $tokens[ $start + 1 ] )
			|| WP_MySQL_Lexer::LIMIT_SYMBOL !== $tokens[ $start ]->id
		) {
			return false;
		}

		if ( $start + 2 === $end ) {
			return $this->is_supported_simple_select_limit_number( $tokens[ $start + 1 ] );
		}

		return $start + 4 === $end
			&& isset( $tokens[ $start + 2 ], $tokens[ $start + 3 ] )
			&& WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $start + 2 ]->id
			&& $this->is_supported_simple_select_limit_number( $tokens[ $start + 1 ] )
			&& $this->is_supported_simple_select_limit_number( $tokens[ $start + 3 ] );
	}

	/**
	 * Validate a LIMIT number token.
	 *
	 * @param WP_MySQL_Token $token MySQL lexer token.
	 * @return bool Whether the token is a supported non-negative integer.
	 */
	private function is_supported_simple_select_limit_number( WP_MySQL_Token $token ): bool {
		$is_parameter_marker = WP_MySQL_Lexer::PARAM_MARKER === $token->id;
		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::INT_NUMBER,
				WP_MySQL_Lexer::LONG_NUMBER,
				WP_MySQL_Lexer::PARAM_MARKER,
				WP_MySQL_Lexer::ULONGLONG_NUMBER,
			),
			true
		) && ( $is_parameter_marker || ctype_digit( $token->get_value() ) );
	}

	/**
	 * Check whether a DML ORDER BY clause has a non-empty item list.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  ORDER token position.
	 * @param int              $end    Final clause token position, exclusive.
	 * @return bool Whether this is a non-empty ORDER BY clause.
	 */
	private function is_nonempty_mysql_order_by_clause( array $tokens, int $start, int $end ): bool {
		if (
			$start + 2 >= $end
			|| WP_MySQL_Lexer::ORDER_SYMBOL !== ( $tokens[ $start ]->id ?? null )
			|| WP_MySQL_Lexer::BY_SYMBOL !== ( $tokens[ $start + 1 ]->id ?? null )
		) {
			return false;
		}

		$items = $this->split_top_level_mysql_arguments( $tokens, $start + 2, $end );
		return null !== $items && ! empty( $items );
	}

	/**
	 * Translate a joined DML ORDER BY clause against the statement table scope.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  ORDER token position.
	 * @param int              $end    Final clause token position, exclusive.
	 * @param array            $scope  Statement table scope.
	 * @return string|null PostgreSQL ORDER BY clause SQL, or null when unsupported.
	 */
	private function translate_mysql_joined_dml_order_by_clause_to_postgresql( array $tokens, int $start, int $end, array $scope ): ?string {
		if (
			$start + 2 >= $end
			|| WP_MySQL_Lexer::ORDER_SYMBOL !== ( $tokens[ $start ]->id ?? null )
			|| WP_MySQL_Lexer::BY_SYMBOL !== ( $tokens[ $start + 1 ]->id ?? null )
		) {
			return null;
		}

		$item_ranges = $this->split_top_level_mysql_arguments( $tokens, $start + 2, $end );
		if ( null === $item_ranges || empty( $item_ranges ) ) {
			return null;
		}

		$items = array();
		foreach ( $item_ranges as $item_range ) {
			$item_start = $item_range['start'];
			$item_end   = $item_range['end'];
			$direction  = '';
			if (
				$item_start < $item_end
				&& (
					WP_MySQL_Lexer::ASC_SYMBOL === ( $tokens[ $item_end - 1 ]->id ?? null )
					|| WP_MySQL_Lexer::DESC_SYMBOL === ( $tokens[ $item_end - 1 ]->id ?? null )
				)
			) {
				$direction = ' ' . strtoupper( $tokens[ $item_end - 1 ]->get_bytes() );
				--$item_end;
			}

			if (
				$item_start >= $item_end
				|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $item_start, $item_end )
				|| ! $this->mysql_expression_qualified_references_resolve_to_scope( $tokens, $item_start, $item_end, $scope )
			) {
				return null;
			}

			$expression = $this->translate_mysql_expression_token_sequence_to_postgresql(
				$tokens,
				$item_start,
				$item_end,
				$scope
			);
			$items[]    = $expression['sql'] . $direction;
		}

		return ' ORDER BY ' . implode( ', ', $items );
	}

	/**
	 * Translate a safe DML LIMIT row-count clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  LIMIT token position.
	 * @param int              $end    Final clause token position, exclusive.
	 * @param bool             $allow_offset_count Whether LIMIT offset,count is supported for this DML statement.
	 * @return string|null PostgreSQL LIMIT clause SQL, or null when unsupported.
	 */
	private function translate_simple_dml_limit_clause_to_postgresql( array $tokens, int $start, int $end, bool $allow_offset_count = false ): ?string {
		if (
			WP_MySQL_Lexer::LIMIT_SYMBOL !== ( $tokens[ $start ]->id ?? null )
			|| ! isset( $tokens[ $start + 1 ] )
		) {
			return null;
		}

		if ( $start + 2 === $end && $this->is_supported_simple_select_limit_number( $tokens[ $start + 1 ] ) ) {
			return ' LIMIT ' . $tokens[ $start + 1 ]->get_bytes();
		}

		if (
			$allow_offset_count
			&& $start + 4 === $end
			&& isset( $tokens[ $start + 2 ], $tokens[ $start + 3 ] )
			&& WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $start + 2 ]->id
			&& $this->is_supported_simple_select_limit_number( $tokens[ $start + 1 ] )
			&& $this->is_supported_simple_select_limit_number( $tokens[ $start + 3 ] )
		) {
			return ' LIMIT ' . $tokens[ $start + 3 ]->get_bytes() . ' OFFSET ' . $tokens[ $start + 1 ]->get_bytes();
		}

		if (
			$allow_offset_count
			&& $start + 4 === $end
			&& isset( $tokens[ $start + 2 ], $tokens[ $start + 3 ] )
			&& WP_MySQL_Lexer::OFFSET_SYMBOL === $tokens[ $start + 2 ]->id
			&& $this->is_supported_simple_select_limit_number( $tokens[ $start + 1 ] )
			&& $this->is_supported_simple_select_limit_number( $tokens[ $start + 3 ] )
		) {
			return ' LIMIT ' . $tokens[ $start + 1 ]->get_bytes() . ' OFFSET ' . $tokens[ $start + 3 ]->get_bytes();
		}

		return null;
	}

	/**
	 * Translate a supported trailing SELECT LIMIT clause to PostgreSQL.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  LIMIT token position.
	 * @param int             $end    Final clause token position, exclusive.
	 * @return string PostgreSQL LIMIT clause.
	 */
	private function translate_simple_select_limit_clause_to_postgresql( array $tokens, int $start, int $end ): string {
		if ( $start + 4 === $end ) {
			return ' LIMIT ' . $tokens[ $start + 3 ]->get_bytes() . ' OFFSET ' . $tokens[ $start + 1 ]->get_bytes();
		}

		return ' LIMIT ' . $tokens[ $start + 1 ]->get_bytes();
	}

	/**
	 * Strip MySQL SELECT row-locking clauses.
	 *
	 * SQLite strips these clauses because file-level locking already protects the
	 * database. The PostgreSQL adapter uses the same compatibility behavior so
	 * MySQL plugin queries keep running even when the test backend is SQLite.
	 *
	 * @param string $query MySQL SELECT query.
	 * @return string|null PostgreSQL SQL without the locking clause, or null when absent.
	 */
	private function translate_mysql_select_row_locking_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		$locking_start = $this->find_mysql_select_row_locking_clause_start( $tokens, 1, $statement_end );
		if ( null === $locking_start ) {
			return null;
		}

		$stripped_query = $this->translate_mysql_token_sequence_to_postgresql( $tokens, 0, $locking_start );
		return $this->translate_mysql_select_query_for_postgresql( $stripped_query )['sql'];
	}

	/**
	 * Find a supported trailing SELECT row-locking clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token to scan.
	 * @param int              $end    Final statement token position, exclusive.
	 * @return int|null Locking clause start position, or null when absent.
	 */
	private function find_mysql_select_row_locking_clause_start( array $tokens, int $start, int $end ): ?int {
		$depth = 0;
		for ( $i = $start; $i < $end; $i++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $i ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $i ]->id ) {
				--$depth;
				if ( $depth < 0 ) {
					return null;
				}
				continue;
			}

			if ( 0 !== $depth ) {
				continue;
			}

			if (
				WP_MySQL_Lexer::FOR_SYMBOL === $tokens[ $i ]->id
				&& isset( $tokens[ $i + 1 ] )
				&& in_array( $tokens[ $i + 1 ]->id, array( WP_MySQL_Lexer::SHARE_SYMBOL, WP_MySQL_Lexer::UPDATE_SYMBOL ), true )
			) {
				if ( $end === $this->parse_supported_mysql_select_row_locking_clause( $tokens, $i, $end ) ) {
					return $i;
				}

				throw new InvalidArgumentException( 'Unsupported SELECT locking clause.' );
			}

			if (
				WP_MySQL_Lexer::LOCK_SYMBOL === $tokens[ $i ]->id
				&& isset( $tokens[ $i + 1 ] )
				&& WP_MySQL_Lexer::IN_SYMBOL === $tokens[ $i + 1 ]->id
			) {
				if ( $end === $this->parse_supported_mysql_select_row_locking_clause( $tokens, $i, $end ) ) {
					return $i;
				}

				throw new InvalidArgumentException( 'Unsupported SELECT locking clause.' );
			}
		}

		return null;
	}

	/**
	 * Parse a supported MySQL SELECT row-locking clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First locking token.
	 * @param int              $end    Final statement token position, exclusive.
	 * @return int|null Position after the clause, or null when unsupported.
	 */
	private function parse_supported_mysql_select_row_locking_clause( array $tokens, int $start, int $end ): ?int {
		if (
			isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ], $tokens[ $start + 3 ] )
			&& WP_MySQL_Lexer::LOCK_SYMBOL === $tokens[ $start ]->id
			&& WP_MySQL_Lexer::IN_SYMBOL === $tokens[ $start + 1 ]->id
			&& WP_MySQL_Lexer::SHARE_SYMBOL === $tokens[ $start + 2 ]->id
			&& WP_MySQL_Lexer::MODE_SYMBOL === $tokens[ $start + 3 ]->id
		) {
			return $start + 4;
		}

		if (
			! isset( $tokens[ $start ], $tokens[ $start + 1 ] )
			|| WP_MySQL_Lexer::FOR_SYMBOL !== $tokens[ $start ]->id
			|| ! in_array( $tokens[ $start + 1 ]->id, array( WP_MySQL_Lexer::SHARE_SYMBOL, WP_MySQL_Lexer::UPDATE_SYMBOL ), true )
		) {
			return null;
		}

		$position = $start + 2;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OF_SYMBOL === $tokens[ $position ]->id ) {
			$position = $this->parse_mysql_select_locking_table_reference_list( $tokens, $position + 1, $end );
			if ( null === $position ) {
				return null;
			}
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::NOWAIT_SYMBOL === $tokens[ $position ]->id ) {
			return $position + 1;
		}

		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::SKIP_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::LOCKED_SYMBOL === $tokens[ $position + 1 ]->id
		) {
			return $position + 2;
		}

		return $position;
	}

	/**
	 * Parse an OF table-reference list in a SELECT locking clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First table-reference token.
	 * @param int              $end    Final statement token position, exclusive.
	 * @return int|null Position after the list, or null when unsupported.
	 */
	private function parse_mysql_select_locking_table_reference_list( array $tokens, int $start, int $end ): ?int {
		$position = $this->parse_mysql_select_locking_table_reference( $tokens, $start, $end );
		if ( null === $position ) {
			return null;
		}

		while ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
			$position = $this->parse_mysql_select_locking_table_reference( $tokens, $position + 1, $end );
			if ( null === $position ) {
				return null;
			}
		}

		return $position;
	}

	/**
	 * Parse one table reference in a SELECT locking clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First table-reference token.
	 * @param int              $end    Final statement token position, exclusive.
	 * @return int|null Position after the table reference, or null when unsupported.
	 */
	private function parse_mysql_select_locking_table_reference( array $tokens, int $start, int $end ): ?int {
		if ( $start >= $end || null === $this->get_mysql_identifier_token_value( $tokens[ $start ] ?? null ) ) {
			return null;
		}

		$position = $start + 1;
		while (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position ]->id
			&& null !== $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] )
		) {
			$position += 2;
		}

		return $position;
	}

	/**
	 * Find the token position ending a single MySQL statement.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Token position where scanning starts.
	 * @return int|null EOF or semicolon token position, or null for multi-statements.
	 */
	private function get_mysql_statement_end_position( array $tokens, int $position ): ?int {
		for ( $i = $position; isset( $tokens[ $i ] ); $i++ ) {
			if ( WP_MySQL_Lexer::EOF === $tokens[ $i ]->id ) {
				return $i;
			}

			if ( WP_MySQL_Lexer::SEMICOLON_SYMBOL === $tokens[ $i ]->id ) {
				return $this->is_at_mysql_query_end( $tokens, $i ) ? $i : null;
			}
		}

		return null;
	}

	/**
	 * Find the position after a matching parenthesized token sequence.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Opening parenthesis position.
	 * @param int             $limit    Final token position, exclusive.
	 * @return int|null Position after the matching close parenthesis, or null.
	 */
	private function get_mysql_parenthesized_sequence_end( array $tokens, int $position, int $limit ): ?int {
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$depth = 0;
		for ( $i = $position; $i < $limit; $i++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $i ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== $tokens[ $i ]->id ) {
				continue;
			}

			--$depth;
			if ( 0 === $depth ) {
				return $i + 1;
			}

			if ( $depth < 0 ) {
				return null;
			}
		}

		return null;
	}

	/**
	 * Find a top-level MySQL token in a bounded token range.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $token_id Token ID to find.
	 * @param int             $start    First token position, inclusive.
	 * @param int             $end      Final token position, exclusive.
	 * @return int|null Token position, or null when not found.
	 */
	private function find_top_level_mysql_token( array $tokens, int $token_id, int $start, int $end ): ?int {
		$depth = 0;

		for ( $i = $start; $i < $end; $i++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $i ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $i ]->id ) {
				--$depth;
				if ( $depth < 0 ) {
					return null;
				}
				continue;
			}

			if ( 0 === $depth && $token_id === $tokens[ $i ]->id ) {
				return $i;
			}
		}

		return null;
	}

	/**
	 * Find the first top-level token matching any supplied token ID.
	 *
	 * @param WP_MySQL_Token[] $tokens    MySQL lexer token stream.
	 * @param int[]           $token_ids Token IDs to find.
	 * @param int             $start     First token position, inclusive.
	 * @param int             $end       Final token position, exclusive.
	 * @return int|null Token position, or null when not found.
	 */
	private function find_first_top_level_mysql_token( array $tokens, array $token_ids, int $start, int $end ): ?int {
		$lookup = array();
		foreach ( $token_ids as $token_id ) {
			$lookup[ $token_id ] = true;
		}

		$depth = 0;
		for ( $i = $start; $i < $end; $i++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $i ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $i ]->id ) {
				--$depth;
				if ( $depth < 0 ) {
					return null;
				}
				continue;
			}

			if ( 0 === $depth && isset( $lookup[ $tokens[ $i ]->id ] ) ) {
				return $i;
			}
		}

		return null;
	}

	/**
	 * Check whether a bounded token range contains any top-level token IDs.
	 *
	 * @param WP_MySQL_Token[] $tokens    MySQL lexer token stream.
	 * @param int             $start     First token position, inclusive.
	 * @param int             $end       Final token position, exclusive.
	 * @param int[]           $token_ids Token IDs to detect.
	 * @return bool Whether any token ID was found.
	 */
	private function contains_top_level_mysql_token( array $tokens, int $start, int $end, array $token_ids ): bool {
		foreach ( $token_ids as $token_id ) {
			if ( null !== $this->find_top_level_mysql_token( $tokens, $token_id, $start, $end ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether the token position is at the end of a single query.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Current token position.
	 * @return bool Whether only an optional semicolon and EOF remain.
	 */
	private function is_at_mysql_query_end( array $tokens, int $position ): bool {
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::SEMICOLON_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		return isset( $tokens[ $position ] ) && WP_MySQL_Lexer::EOF === $tokens[ $position ]->id;
	}

	/**
	 * Translate a MySQL token sequence to PostgreSQL SQL.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First token position, inclusive.
	 * @param int             $end    Final token position, exclusive.
	 * @return string PostgreSQL SQL fragment.
	 */
	private function translate_mysql_token_sequence_to_postgresql( array $tokens, int $start, int $end ): string {
		$sql               = '';
		$previous_token_id = null;

		for ( $i = $start; $i < $end; $i++ ) {
			$token               = $tokens[ $i ];
			$fragment_token_id   = $token->id;
			$translated_fragment = $this->translate_mysql_dual_table_reference_to_postgresql( $tokens, $i, $end );
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_index_hint_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_limit_offset_count_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_field_function_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_typed_cast_or_convert_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_regexp_operator_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_group_concat_function_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_rand_function_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_session_user_function_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_infix_interval_expression_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_date_arithmetic_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_nonparenthesized_timestamp_function_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_common_function_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_week_function_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_weekday_index_function_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_date_format_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_date_time_extract_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_convert_using_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_variable_reference_to_postgresql( $tokens, $i );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_select_row_locking_clause_to_empty_postgresql( $tokens, $i, $end );
			}

			$append_no_backslash_like_escape = false;
			if ( null !== $translated_fragment ) {
				$fragment          = $translated_fragment['sql'];
				$fragment_token_id = $translated_fragment['token_id'];
				$i                 = $translated_fragment['position'];
			} else {
				$fragment                        = $this->translate_mysql_token_to_postgresql(
					$token,
					$tokens[ $i + 1 ] ?? null
				);
				$append_no_backslash_like_escape = true;
			}

			if ( '' === $fragment ) {
				continue;
			}

			if ( $append_no_backslash_like_escape && $this->should_append_mysql_no_backslash_like_escape_sql( $tokens, $i, $end ) ) {
				$fragment .= $this->get_mysql_no_backslash_like_escape_sql();
			}

			if ( '' === $sql ) {
				$sql = $fragment;
			} elseif ( $this->should_join_mysql_tokens_without_space( $previous_token_id, $fragment_token_id ) ) {
				$sql .= $fragment;
			} else {
				$sql .= ' ' . $fragment;
			}

			$previous_token_id = $fragment_token_id;
		}

		return $sql;
	}

	/**
	 * Check whether a translated string literal is a LIKE pattern needing ESCAPE ''.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $position Current token position.
	 * @param int              $end Final token position, exclusive.
	 * @return bool Whether to append an implicit NO_BACKSLASH_ESCAPES clause.
	 */
	private function should_append_mysql_no_backslash_like_escape_sql( array $tokens, int $position, int $end ): bool {
		return '' !== $this->get_mysql_no_backslash_like_escape_sql()
			&& isset( $tokens[ $position - 1 ] )
			&& WP_MySQL_Lexer::LIKE_SYMBOL === $tokens[ $position - 1 ]->id
			&& isset( $tokens[ $position ] )
			&& $this->is_mysql_string_literal_token( $tokens[ $position ] )
			&& (
				! isset( $tokens[ $position + 1 ] )
				|| $position + 1 >= $end
				|| WP_MySQL_Lexer::ESCAPE_SYMBOL !== $tokens[ $position + 1 ]->id
			);
	}

	/**
	 * Translate MySQL's dummy DUAL table reference.
	 *
	 * MySQL accepts SELECT and INSERT ... SELECT statements with FROM DUAL as a
	 * one-row dummy table. PostgreSQL supports the same projections without a
	 * FROM clause, so erase only the exact unaliased FROM DUAL reference.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position FROM token position.
	 * @param int              $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_dual_table_reference_to_postgresql( array $tokens, int $position, int $end ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::FROM_SYMBOL !== $tokens[ $position ]->id
			|| WP_MySQL_Lexer::DUAL_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		if (
			isset( $tokens[ $position + 2 ] )
			&& $position + 2 < $end
			&& ! $this->is_mysql_dual_table_reference_boundary_token( $tokens[ $position + 2 ] )
		) {
			return null;
		}

		return array(
			'sql'      => '',
			'token_id' => WP_MySQL_Lexer::FROM_SYMBOL,
			'position' => $position + 1,
		);
	}

	/**
	 * Check whether a token can follow an erased FROM DUAL reference.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token starts a clause or closes the SELECT.
	 */
	private function is_mysql_dual_table_reference_boundary_token( WP_MySQL_Token $token ): bool {
		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::CLOSE_PAR_SYMBOL,
				WP_MySQL_Lexer::EOF,
				WP_MySQL_Lexer::GROUP_SYMBOL,
				WP_MySQL_Lexer::HAVING_SYMBOL,
				WP_MySQL_Lexer::LIMIT_SYMBOL,
				WP_MySQL_Lexer::ORDER_SYMBOL,
				WP_MySQL_Lexer::SEMICOLON_SYMBOL,
				WP_MySQL_Lexer::UNION_SYMBOL,
				WP_MySQL_Lexer::WHERE_SYMBOL,
			),
			true
		);
	}

	/**
	 * Erase supported MySQL SELECT row-locking clauses in nested translated ranges.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position First locking token position.
	 * @param int              $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when not a locking clause.
	 */
	private function translate_mysql_select_row_locking_clause_to_empty_postgresql( array $tokens, int $position, int $end ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| ! (
				WP_MySQL_Lexer::FOR_SYMBOL === $tokens[ $position ]->id
				|| WP_MySQL_Lexer::LOCK_SYMBOL === $tokens[ $position ]->id
			)
		) {
			return null;
		}

		$after_locking = $this->parse_supported_mysql_select_row_locking_clause( $tokens, $position, $end );
		if ( null === $after_locking ) {
			return null;
		}

		return array(
			'sql'      => '',
			'token_id' => $tokens[ $position ]->id,
			'position' => $after_locking - 1,
		);
	}

	/**
	 * Erase supported MySQL optimizer index hints.
	 *
	 * PostgreSQL has no equivalent for MySQL's USE/FORCE/IGNORE INDEX hints.
	 * Keep this bounded to the parsed hint clause so surrounding aliases, joins,
	 * predicates, grouping, ordering, and limits are still rendered normally.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Hint keyword token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_index_hint_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_index_hint_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		return array(
			'sql'      => '',
			'token_id' => $tokens[ $position ]->id,
			'position' => $bounds['end'] - 1,
		);
	}

	/**
	 * Get token bounds for a supported MySQL optimizer index hint.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Hint keyword token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{end: int}|null Hint bounds, or null when unsupported.
	 */
	private function get_mysql_index_hint_bounds( array $tokens, int $position, int $end ): ?array {
		if ( ! $this->is_mysql_index_hint_marker( $tokens, $position, $end ) ) {
			return null;
		}

		$hint_action = $tokens[ $position ]->id;
		$position   += 2;

		if ( isset( $tokens[ $position ] ) && $position < $end && WP_MySQL_Lexer::FOR_SYMBOL === $tokens[ $position ]->id ) {
			$position = $this->get_mysql_index_hint_scope_end( $tokens, $position, $end );
			if ( null === $position ) {
				return null;
			}
		}

		if ( ! isset( $tokens[ $position ] ) || $position >= $end || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
		if ( null === $after_close ) {
			return null;
		}

		$allow_empty_list = WP_MySQL_Lexer::USE_SYMBOL === $hint_action;
		if ( ! $this->is_mysql_index_hint_identifier_list( $tokens, $position + 1, $after_close - 1, $allow_empty_list ) ) {
			return null;
		}

		return array(
			'end' => $after_close,
		);
	}

	/**
	 * Check whether tokens at a position begin a MySQL optimizer index hint.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Current token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return bool Whether an index hint marker is present.
	 */
	private function is_mysql_index_hint_marker( array $tokens, int $position, int $end ): bool {
		return $position + 1 < $end
			&& $this->is_mysql_index_hint_action_token( $tokens[ $position ] ?? null )
			&& $this->is_mysql_index_hint_type_token( $tokens[ $position + 1 ] ?? null );
	}

	/**
	 * Check whether a token starts a MySQL optimizer index hint.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return bool Whether the token is USE, FORCE, or IGNORE.
	 */
	private function is_mysql_index_hint_action_token( ?WP_MySQL_Token $token ): bool {
		if ( null === $token ) {
			return false;
		}

		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::FORCE_SYMBOL,
				WP_MySQL_Lexer::IGNORE_SYMBOL,
				WP_MySQL_Lexer::USE_SYMBOL,
			),
			true
		);
	}

	/**
	 * Check whether a token names the hinted object type.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return bool Whether the token is INDEX or KEY.
	 */
	private function is_mysql_index_hint_type_token( ?WP_MySQL_Token $token ): bool {
		if ( null === $token ) {
			return false;
		}

		return WP_MySQL_Lexer::INDEX_SYMBOL === $token->id || WP_MySQL_Lexer::KEY_SYMBOL === $token->id;
	}

	/**
	 * Get the position after a supported MySQL optimizer index hint scope.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position FOR token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return int|null Position after scope tokens, or null when unsupported.
	 */
	private function get_mysql_index_hint_scope_end( array $tokens, int $position, int $end ): ?int {
		if ( ! isset( $tokens[ $position ], $tokens[ $position + 1 ] ) || $position + 1 >= $end ) {
			return null;
		}

		if ( WP_MySQL_Lexer::FOR_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		if ( WP_MySQL_Lexer::JOIN_SYMBOL === $tokens[ $position + 1 ]->id ) {
			return $position + 2;
		}

		if (
			isset( $tokens[ $position + 2 ] )
			&& $position + 2 < $end
			&& WP_MySQL_Lexer::BY_SYMBOL === $tokens[ $position + 2 ]->id
			&& (
				WP_MySQL_Lexer::GROUP_SYMBOL === $tokens[ $position + 1 ]->id
				|| WP_MySQL_Lexer::ORDER_SYMBOL === $tokens[ $position + 1 ]->id
			)
		) {
			return $position + 3;
		}

		return null;
	}

	/**
	 * Check whether a token range is a supported MySQL index-name list.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param int             $start       First list token position.
	 * @param int             $end         Final list token position, exclusive.
	 * @param bool            $allow_empty Whether an empty list is valid.
	 * @return bool Whether the token range is a supported index-name list.
	 */
	private function is_mysql_index_hint_identifier_list( array $tokens, int $start, int $end, bool $allow_empty ): bool {
		if ( $start === $end ) {
			return $allow_empty;
		}

		$expect_identifier = true;
		for ( $i = $start; $i < $end; $i++ ) {
			if ( $expect_identifier ) {
				if ( ! $this->is_mysql_index_hint_identifier_token( $tokens[ $i ] ?? null ) ) {
					return false;
				}

				$expect_identifier = false;
				continue;
			}

			if ( WP_MySQL_Lexer::COMMA_SYMBOL !== $tokens[ $i ]->id ) {
				return false;
			}

			$expect_identifier = true;
		}

		return ! $expect_identifier;
	}

	/**
	 * Check whether a token can name an index in a MySQL optimizer hint.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return bool Whether the token is a supported index identifier.
	 */
	private function is_mysql_index_hint_identifier_token( ?WP_MySQL_Token $token ): bool {
		if ( null === $token ) {
			return false;
		}

		return WP_MySQL_Lexer::PRIMARY_SYMBOL === $token->id
			|| null !== $this->get_mysql_identifier_token_value( $token );
	}

	/**
	 * Translate MySQL LIMIT offset,count syntax to PostgreSQL LIMIT count OFFSET offset.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position LIMIT token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_limit_offset_count_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_limit_offset_count_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		$sql = 'LIMIT ' . $tokens[ $bounds['count_position'] ]->get_bytes()
			. ' OFFSET ' . $tokens[ $bounds['offset_position'] ]->get_bytes();

		return array(
			'sql'      => $sql,
			'token_id' => WP_MySQL_Lexer::LIMIT_SYMBOL,
			'position' => $bounds['count_position'],
		);
	}

	/**
	 * Get token bounds for a MySQL LIMIT offset,count clause.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position LIMIT token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{offset_position: int, count_position: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_limit_offset_count_bounds( array $tokens, int $position, int $end ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ], $tokens[ $position + 3 ] )
			|| WP_MySQL_Lexer::LIMIT_SYMBOL !== $tokens[ $position ]->id
			|| WP_MySQL_Lexer::COMMA_SYMBOL !== $tokens[ $position + 2 ]->id
			|| $position + 4 !== $end
			|| ! $this->is_supported_simple_select_limit_number( $tokens[ $position + 1 ] )
			|| ! $this->is_supported_simple_select_limit_number( $tokens[ $position + 3 ] )
		) {
			return null;
		}

		return array(
			'offset_position' => $position + 1,
			'count_position'  => $position + 3,
		);
	}

	/**
	 * Translate MySQL GROUP_CONCAT([DISTINCT] expr [, expr ...] [ORDER BY ...] [SEPARATOR ...]).
	 *
	 * Multi-expression rows are concatenated before aggregation. DISTINCT stays
	 * intentionally single-expression so PostgreSQL does not silently change
	 * MySQL's de-duplication semantics for composite row values.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_group_concat_function_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_group_concat_function_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		$parsed = $this->parse_mysql_group_concat_arguments(
			$tokens,
			$bounds['arguments_start'],
			$bounds['arguments_end']
		);
		if ( null === $parsed ) {
			return null;
		}

		$expression_ranges = $parsed['expression_ranges'];
		if ( 1 === count( $expression_ranges ) ) {
			$range          = $expression_ranges[0];
			$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$range['start'],
				$range['end']
			);
		} else {
			$parts = array();
			foreach ( $expression_ranges as $range ) {
				if ( $range['start'] >= $range['end'] ) {
					return null;
				}

				$parts[] = sprintf(
					'CAST(%s AS text)',
					$this->translate_mysql_token_sequence_to_postgresql(
						$tokens,
						$range['start'],
						$range['end']
					)
				);
			}
			$expression_sql = implode( ' || ', $parts );
		}

		$separator_sql = null === $parsed['separator_start']
			? $this->connection->quote( ',' )
			: $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$parsed['separator_start'],
				$parsed['separator_end']
			);

		$order_sql = '';
		if ( null !== $parsed['order_start'] ) {
			$order_sql = $this->get_mysql_group_concat_order_by_sql(
				$tokens,
				$parsed['order_start'],
				$parsed['order_end'],
				$parsed['distinct'] ? $parsed['expression_ranges'][0] : null,
				$parsed['distinct'] ? $expression_sql : null
			);
			if ( null === $order_sql ) {
				return null;
			}
		}

		if ( ! $parsed['distinct'] ) {
			$aggregate_sql = sprintf(
				'STRING_AGG(CAST(%1$s AS text), CAST(%2$s AS text)%3$s)',
				$expression_sql,
				$separator_sql,
				$order_sql
			);
		} elseif ( 'sqlite' === $this->connection->get_driver_name() ) {
			if ( null !== $parsed['separator_start'] ) {
				return null;
			}
			$aggregate_sql = sprintf( 'GROUP_CONCAT(DISTINCT CAST(%s AS text))', $expression_sql );
		} else {
			$aggregate_sql = sprintf(
				'STRING_AGG(DISTINCT CAST(%1$s AS text), CAST(%2$s AS text)%3$s)',
				$expression_sql,
				$separator_sql,
				$order_sql
			);
		}

		return array(
			'sql'      => $this->get_mysql_group_concat_max_len_truncation_sql( $aggregate_sql ),
			'token_id' => WP_MySQL_Lexer::IDENTIFIER,
			'position' => $bounds['close'],
		);
	}

	/**
	 * Get token bounds for a GROUP_CONCAT() call.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{arguments_start: int, arguments_end: int, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_group_concat_function_bounds( array $tokens, int $position, int $end ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::GROUP_CONCAT_SYMBOL !== $tokens[ $position ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		return array(
			'arguments_start' => $position + 2,
			'arguments_end'   => $after_close - 1,
			'close'           => $after_close - 1,
		);
	}

	/**
	 * Parse the supported GROUP_CONCAT argument shape.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First argument token position.
	 * @param int             $end    Final argument token position, exclusive.
	 * @return array{distinct: bool, expression_ranges: array[], order_start: int|null, order_end: int, separator_start: int|null, separator_end: int}|null Parsed bounds.
	 */
	private function parse_mysql_group_concat_arguments( array $tokens, int $start, int $end ): ?array {
		if ( $start >= $end ) {
			return null;
		}

		$distinct         = false;
		$expression_start = $start;
		if ( WP_MySQL_Lexer::DISTINCT_SYMBOL === ( $tokens[ $expression_start ]->id ?? null ) ) {
			$distinct = true;
			++$expression_start;
		}
		if ( $expression_start >= $end ) {
			return null;
		}

		$separator_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::SEPARATOR_SYMBOL,
			$expression_start,
			$end
		);
		if (
			null !== $separator_position
			&& (
				$separator_position + 1 >= $end
				|| null !== $this->find_top_level_mysql_token(
					$tokens,
					WP_MySQL_Lexer::SEPARATOR_SYMBOL,
					$separator_position + 1,
					$end
				)
			)
		) {
			return null;
		}

		$before_separator_end = $separator_position ?? $end;
		$order_position       = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::ORDER_SYMBOL,
			$expression_start,
			$before_separator_end
		);
		if (
			null !== $order_position
			&& (
				! isset( $tokens[ $order_position + 1 ] )
				|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $order_position + 1 ]->id
				|| $order_position + 2 >= $before_separator_end
			)
		) {
			return null;
		}
		$expression_end = $order_position ?? $before_separator_end;
		if ( $expression_start >= $expression_end ) {
			return null;
		}

		$expression_arguments = $this->split_top_level_mysql_arguments( $tokens, $expression_start, $expression_end );
		if (
			null === $expression_arguments
			|| empty( $expression_arguments )
			|| ( $distinct && 1 !== count( $expression_arguments ) )
		) {
			return null;
		}
		if (
			$distinct
			&& null !== $separator_position
			&& ! $this->is_mysql_string_literal_range( $tokens, $separator_position + 1, $end )
		) {
			return null;
		}

		return array(
			'distinct'          => $distinct,
			'expression_ranges' => $expression_arguments,
			'order_start'       => null === $order_position ? null : $order_position + 2,
			'order_end'         => $before_separator_end,
			'separator_start'   => null === $separator_position ? null : $separator_position + 1,
			'separator_end'     => $end,
		);
	}

	/**
	 * Render ORDER BY items inside a supported GROUP_CONCAT().
	 *
	 * @param WP_MySQL_Token[] $tokens                        MySQL lexer token stream.
	 * @param int              $start                         First ORDER BY item token position.
	 * @param int              $end                           Final ORDER BY item token position, exclusive.
	 * @param array|null       $distinct_expression_range     DISTINCT expression range, if DISTINCT is present.
	 * @param string|null      $distinct_expression_sql       Translated DISTINCT expression SQL, if DISTINCT is present.
	 * @return string|null Aggregate ORDER BY SQL, or null when unsupported.
	 */
	private function get_mysql_group_concat_order_by_sql( array $tokens, int $start, int $end, ?array $distinct_expression_range = null, ?string $distinct_expression_sql = null ): ?string {
		$items = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if (
			null === $items
			|| empty( $items )
			|| ( null !== $distinct_expression_range && ( 1 !== count( $items ) || null === $distinct_expression_sql ) )
		) {
			return null;
		}

		$order_sql = array();
		foreach ( $items as $item ) {
			$item_start = $item['start'];
			$item_end   = $item['end'];
			$direction  = '';

			if ( isset( $tokens[ $item_end - 1 ] ) ) {
				if ( WP_MySQL_Lexer::DESC_SYMBOL === $tokens[ $item_end - 1 ]->id ) {
					$direction = ' DESC';
					--$item_end;
				} elseif ( WP_MySQL_Lexer::ASC_SYMBOL === $tokens[ $item_end - 1 ]->id ) {
					$direction = ' ASC';
					--$item_end;
				}
			}

			if ( $item_start >= $item_end ) {
				return null;
			}

			$item_sql = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $item_start, $item_end );
			if ( null !== $distinct_expression_range ) {
				return $this->translate_mysql_token_sequence_to_postgresql( $tokens, $distinct_expression_range['start'], $distinct_expression_range['end'] ) === $item_sql
					? sprintf( ' ORDER BY CAST(%s AS text)%s', $distinct_expression_sql, $direction )
					: null;
			}

			$order_sql[] = $item_sql . $direction;
		}

		return ' ORDER BY ' . implode( ', ', $order_sql );
	}

	/**
	 * Apply the current group_concat_max_len session value to GROUP_CONCAT SQL.
	 *
	 * PostgreSQL text cannot carry invalid UTF-8 byte prefixes, so PostgreSQL uses
	 * the longest valid UTF-8 prefix within the byte limit. The SQLite-backed test
	 * harness can preserve raw byte prefixes and uses byte-exact truncation.
	 *
	 * @param string $aggregate_sql Rendered STRING_AGG SQL.
	 * @return string Truncated aggregate SQL.
	 */
	private function get_mysql_group_concat_max_len_truncation_sql( string $aggregate_sql ): string {
		$value = $this->get_mysql_system_variable_value( 'group_concat_max_len' ) ?? '1024';
		$value = ltrim( $value, '0' );
		if ( '' === $value ) {
			$limit = 0;
		} else {
			$max   = (string) self::MYSQL_GROUP_CONCAT_MAX_LEN_SQL_LIMIT;
			$limit = strlen( $value ) > strlen( $max ) || ( strlen( $value ) === strlen( $max ) && strcmp( $value, $max ) > 0 )
				? self::MYSQL_GROUP_CONCAT_MAX_LEN_SQL_LIMIT
				: (int) $value;
		}

		if ( 'sqlite' === $this->connection->get_driver_name() ) {
			return sprintf(
				'CAST(SUBSTR(CAST(%1$s AS BLOB), 1, %2$d) AS TEXT)',
				$aggregate_sql,
				$limit
			);
		}

		if ( 'pgsql' === $this->connection->get_driver_name() ) {
			return $this->get_postgresql_mysql_utf8_safe_byte_prefix_sql( $aggregate_sql, $limit );
		}

		return sprintf( 'SUBSTR(%1$s, 1, %2$d)', $aggregate_sql, $limit );
	}

	/**
	 * Get PostgreSQL SQL for a valid UTF-8 prefix within a byte limit.
	 *
	 * @param string $expression_sql PostgreSQL text expression SQL.
	 * @param int    $limit          Maximum byte length.
	 * @return string PostgreSQL SQL.
	 */
	private function get_postgresql_mysql_utf8_safe_byte_prefix_sql( string $expression_sql, int $limit ): string {
		if ( 0 === $limit ) {
			return sprintf(
				'CASE WHEN %1$s IS NULL THEN NULL ELSE %2$s END',
				$expression_sql,
				$this->connection->quote( '' )
			);
		}

		$bytes_sql       = sprintf( "CONVERT_TO(CAST(%s AS text), 'UTF8')", $expression_sql );
		$safe_length_sql = (string) $limit;
		$next_byte_sql   = sprintf( 'GET_BYTE(%s, %d)', $bytes_sql, $limit );

		$branches = array(
			sprintf(
				'WHEN %s THEN %d',
				sprintf( '(%1$s < 128 OR %1$s >= 192)', $next_byte_sql ),
				$limit
			),
		);

		for ( $offset = 1; $offset <= 3; $offset++ ) {
			if ( $limit < $offset ) {
				break;
			}

			$byte_sql   = sprintf( 'GET_BYTE(%s, %d)', $bytes_sql, $limit - $offset );
			$branches[] = sprintf(
				'WHEN %s THEN %d',
				sprintf( '(%1$s < 128 OR %1$s >= 192)', $byte_sql ),
				$limit - $offset
			);
		}

		$safe_length_sql = 'CASE ' . implode( ' ', $branches ) . ' ELSE 0 END';

		return sprintf(
			"CASE WHEN %1\$s IS NULL THEN NULL WHEN OCTET_LENGTH(CAST(%1\$s AS text)) <= %2\$d THEN CAST(%1\$s AS text) ELSE CONVERT_FROM(SUBSTRING(%3\$s FROM 1 FOR %4\$s), 'UTF8') END",
			$expression_sql,
			$limit,
			$bytes_sql,
			$safe_length_sql
		);
	}

	/**
	 * Translate MySQL FIELD(expr, value, ...) to a PostgreSQL CASE expression.
	 *
	 * PostgreSQL does not coerce unknown text and integer values the same way
	 * MySQL FIELD() does. Cast both sides of each comparison to text to keep the
	 * WordPress ordering use-cases executable across mixed ID/name arguments.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_field_function_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_function_call_bounds( $tokens, $position, $end, 'field' );
		if ( null === $bounds ) {
			return null;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
		if ( null === $arguments || count( $arguments ) < 2 ) {
			return null;
		}

		$value_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$arguments[0]['start'],
			$arguments[0]['end']
		);

		$clauses = array(
			sprintf( 'WHEN %s IS NULL THEN 0', $value_sql ),
		);

		for ( $i = 1; $i < count( $arguments ); $i++ ) {
			$argument_sql = $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$arguments[ $i ]['start'],
				$arguments[ $i ]['end']
			);

			$clauses[] = sprintf(
				'WHEN CAST(%1$s AS text) = CAST(%2$s AS text) THEN %3$d',
				$value_sql,
				$argument_sql,
				$i
			);
		}

		return array(
			'sql'      => 'CASE ' . implode( ' ', $clauses ) . ' ELSE 0 END',
			'token_id' => WP_MySQL_Lexer::CASE_SYMBOL,
			'position' => $bounds['close'],
		);
	}

	/**
	 * Translate supported typed MySQL CAST/CONVERT expressions to PostgreSQL.
	 *
	 * CONVERT intentionally supports only the previously accepted typed forms.
	 * For example, CAST(... AS DATETIME) is supported, but CONVERT(..., DATETIME)
	 * remains unsupported and fails closed before backend execution.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position CAST/CONVERT token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_typed_cast_or_convert_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_typed_cast_or_convert_bounds(
			$tokens,
			$position,
			$end,
			array(
				'cast'    => array( 'integer', 'character', 'date_time', 'date', 'binary' ),
				'convert' => array( 'integer', 'character', 'binary', 'decimal', 'date' ),
			)
		);
		if ( null === $bounds ) {
			return null;
		}

		$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$bounds['expression_start'],
			$bounds['expression_end']
		);

		return array(
			'sql'      => $this->get_postgresql_mysql_typed_cast_or_convert_sql( $bounds['type'], $expression_sql ),
			'token_id' => WP_MySQL_Lexer::CAST_SYMBOL,
			'position' => $bounds['close'],
		);
	}

	/**
	 * Get PostgreSQL SQL for a supported typed MySQL CAST/CONVERT expression.
	 *
	 * @param string $type           Normalized MySQL cast/convert type.
	 * @param string $expression_sql PostgreSQL expression SQL.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_typed_cast_or_convert_sql( string $type, string $expression_sql ): string {
		if ( 'integer' === $type ) {
			return $this->get_postgresql_mysql_integer_cast_sql( $expression_sql );
		}

		if ( 'date_time' === $type ) {
			return $this->get_postgresql_zero_date_safe_timestamp_sql( $expression_sql );
		}

		if ( 'date' === $type ) {
			return $this->get_postgresql_mysql_date_sql( $expression_sql );
		}

		if ( 'decimal' === $type ) {
			return $this->get_postgresql_mysql_numeric_cast_sql( $expression_sql );
		}

		if ( in_array( $type, array( 'character', 'binary' ), true ) ) {
			return sprintf( 'CAST(%s AS text)', $expression_sql );
		}

		throw new InvalidArgumentException( 'Unsupported MySQL CAST/CONVERT type.' );
	}

	/**
	 * Get PostgreSQL SQL for MySQL-compatible integer text coercion.
	 *
	 * MySQL accepts text values when casting to SIGNED/UNSIGNED and coerces the
	 * leading integer prefix, or zero when no prefix exists. PostgreSQL bigint
	 * casts reject those values, so extract a safe prefix before casting.
	 *
	 * @param string $expression_sql PostgreSQL expression SQL.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_integer_cast_sql( string $expression_sql ): string {
		$expression_text_sql = sprintf( 'CAST(%s AS text)', $expression_sql );
		$integer_pattern     = $this->connection->quote( '^[[:space:]]*[+-]?[0-9]+' );

		return sprintf(
			'CASE WHEN %1$s IS NULL THEN NULL ELSE CAST(COALESCE(SUBSTRING(%1$s, %2$s), \'0\') AS bigint) END',
			$expression_text_sql,
			$integer_pattern
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL-compatible decimal text coercion.
	 *
	 * MySQL text values in numeric expression contexts use the leading numeric
	 * prefix, including decimal and exponent forms, or zero when no prefix exists.
	 *
	 * @param string $expression_sql PostgreSQL expression SQL.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_numeric_cast_sql( string $expression_sql ): string {
		$expression_text_sql = sprintf( 'CAST(%s AS text)', $expression_sql );
		$substring_sql       = array();
		$numeric_patterns    = array(
			'^[[:space:]]*[+-]?[0-9]+[.][0-9]*[eE][+-]?[0-9]+',
			'^[[:space:]]*[+-]?[.][0-9]+[eE][+-]?[0-9]+',
			'^[[:space:]]*[+-]?[0-9]+[eE][+-]?[0-9]+',
			'^[[:space:]]*[+-]?[0-9]+[.][0-9]*',
			'^[[:space:]]*[+-]?[.][0-9]+',
			'^[[:space:]]*[+-]?[0-9]+',
		);

		foreach ( $numeric_patterns as $pattern ) {
			$substring_sql[] = sprintf(
				'SUBSTRING(%1$s, %2$s)',
				$expression_text_sql,
				$this->connection->quote( $pattern )
			);
		}

		return sprintf(
			'CASE WHEN %1$s IS NULL THEN NULL ELSE CAST(COALESCE(%2$s, \'0\') AS numeric) END',
			$expression_text_sql,
			implode( ', ', $substring_sql )
		);
	}

	/**
	 * Get token bounds for a supported typed MySQL CAST expression.
	 *
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int             $position        CAST token position.
	 * @param int             $end             Final token position, exclusive.
	 * @param string[]        $supported_types Supported normalized type names.
	 * @return array{expression_start: int, expression_end: int, close: int, type: string}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_typed_cast_bounds( array $tokens, int $position, int $end, array $supported_types ): ?array {
		return $this->get_mysql_typed_cast_or_convert_bounds(
			$tokens,
			$position,
			$end,
			array(
				'cast' => $supported_types,
			)
		);
	}

	/**
	 * Get token bounds for a supported typed MySQL CONVERT expression.
	 *
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int             $position        CONVERT token position.
	 * @param int             $end             Final token position, exclusive.
	 * @param string[]        $supported_types Supported normalized type names.
	 * @return array{expression_start: int, expression_end: int, close: int, type: string}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_typed_convert_bounds( array $tokens, int $position, int $end, array $supported_types ): ?array {
		return $this->get_mysql_typed_cast_or_convert_bounds(
			$tokens,
			$position,
			$end,
			array(
				'convert' => $supported_types,
			)
		);
	}

	/**
	 * Get token bounds for a supported typed MySQL CAST/CONVERT expression.
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param int             $position                CAST/CONVERT token position.
	 * @param int             $end                     Final token position, exclusive.
	 * @param array           $supported_types_by_form Supported normalized types keyed by cast/convert form.
	 * @return array{expression_start: int, expression_end: int, close: int, type: string}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_typed_cast_or_convert_bounds( array $tokens, int $position, int $end, array $supported_types_by_form ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		if ( WP_MySQL_Lexer::CAST_SYMBOL === $tokens[ $position ]->id && isset( $supported_types_by_form['cast'] ) ) {
			$form               = 'cast';
			$separator_token_id = WP_MySQL_Lexer::AS_SYMBOL;
		} elseif ( WP_MySQL_Lexer::CONVERT_SYMBOL === $tokens[ $position ]->id && isset( $supported_types_by_form['convert'] ) ) {
			$form               = 'convert';
			$separator_token_id = WP_MySQL_Lexer::COMMA_SYMBOL;
		} else {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		$close_position     = $after_close - 1;
		$separator_position = $this->find_top_level_mysql_token(
			$tokens,
			$separator_token_id,
			$position + 2,
			$close_position
		);
		if ( null === $separator_position || $separator_position <= $position + 2 ) {
			return null;
		}

		$type = $this->get_mysql_cast_or_convert_type(
			$tokens,
			$separator_position + 1,
			$close_position
		);
		if (
			null === $type
			|| ! in_array( $type, $supported_types_by_form[ $form ], true )
		) {
			return null;
		}

		return array(
			'expression_start' => $position + 2,
			'expression_end'   => $separator_position,
			'close'            => $close_position,
			'type'             => $type,
		);
	}

	/**
	 * Get the normalized type for supported MySQL CAST/CONVERT type tokens.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First cast/convert type token.
	 * @param int             $end    Final cast/convert type token, exclusive.
	 * @return string|null Normalized type name, or null when unsupported.
	 */
	private function get_mysql_cast_or_convert_type( array $tokens, int $start, int $end ): ?string {
		if ( null !== $this->get_postgresql_integer_cast_type( $tokens, $start, $end ) ) {
			return 'integer';
		}

		if ( $this->is_mysql_character_cast_type( $tokens, $start, $end ) ) {
			return 'character';
		}

		if ( $this->is_mysql_date_time_cast_type( $tokens, $start, $end ) ) {
			return 'date_time';
		}

		if ( $this->is_mysql_date_cast_type( $tokens, $start, $end ) ) {
			return 'date';
		}

		if ( $this->is_mysql_binary_cast_type( $tokens, $start, $end ) ) {
			return 'binary';
		}

		if ( $this->is_mysql_decimal_cast_type( $tokens, $start, $end ) ) {
			return 'decimal';
		}

		return null;
	}

	/**
	 * Get the PostgreSQL type for supported MySQL integer cast type tokens.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First cast type token.
	 * @param int             $end    Final cast type token, exclusive.
	 * @return string|null PostgreSQL type SQL, or null when unsupported.
	 */
	private function get_postgresql_integer_cast_type( array $tokens, int $start, int $end ): ?string {
		if (
			! isset( $tokens[ $start ] )
			|| ! in_array(
				$tokens[ $start ]->id,
				array(
					WP_MySQL_Lexer::SIGNED_SYMBOL,
					WP_MySQL_Lexer::UNSIGNED_SYMBOL,
				),
				true
			)
		) {
			return null;
		}

		if ( $start + 1 === $end ) {
			return 'bigint';
		}

		if (
			$start + 2 === $end
			&& isset( $tokens[ $start + 1 ] )
			&& in_array(
				$tokens[ $start + 1 ]->id,
				array(
					WP_MySQL_Lexer::INT_SYMBOL,
					WP_MySQL_Lexer::INTEGER_SYMBOL,
				),
				true
			)
		) {
			return 'bigint';
		}

		return null;
	}

	/**
	 * Check whether a CAST/CONVERT type is MySQL CHAR.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First cast type token.
	 * @param int             $end    Final cast type token, exclusive.
	 * @return bool Whether the type is supported.
	 */
	private function is_mysql_character_cast_type( array $tokens, int $start, int $end ): bool {
		return $start + 1 === $end
			&& isset( $tokens[ $start ] )
			&& WP_MySQL_Lexer::CHAR_SYMBOL === $tokens[ $start ]->id;
	}

	/**
	 * Check whether a CAST/CONVERT type is MySQL DATETIME/TIMESTAMP.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First cast type token.
	 * @param int             $end    Final cast type token, exclusive.
	 * @return bool Whether the type is supported.
	 */
	private function is_mysql_date_time_cast_type( array $tokens, int $start, int $end ): bool {
		return $start + 1 === $end
			&& isset( $tokens[ $start ] )
			&& in_array(
				$tokens[ $start ]->id,
				array(
					WP_MySQL_Lexer::DATETIME_SYMBOL,
					WP_MySQL_Lexer::TIMESTAMP_SYMBOL,
				),
				true
			);
	}

	/**
	 * Check whether a CAST/CONVERT type is MySQL DATE.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First cast type token.
	 * @param int             $end    Final cast type token, exclusive.
	 * @return bool Whether the type is supported.
	 */
	private function is_mysql_date_cast_type( array $tokens, int $start, int $end ): bool {
		return $start + 1 === $end
			&& isset( $tokens[ $start ] )
			&& WP_MySQL_Lexer::DATE_SYMBOL === $tokens[ $start ]->id;
	}

	/**
	 * Check whether a CAST/CONVERT type is MySQL BINARY.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First cast type token.
	 * @param int             $end    Final cast type token, exclusive.
	 * @return bool Whether the type is supported.
	 */
	private function is_mysql_binary_cast_type( array $tokens, int $start, int $end ): bool {
		return $start + 1 === $end
			&& isset( $tokens[ $start ] )
			&& WP_MySQL_Lexer::BINARY_SYMBOL === $tokens[ $start ]->id;
	}

	/**
	 * Translate MySQL REGEXP/RLIKE operators to PostgreSQL regex operators.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Operator token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_regexp_operator_to_postgresql( array $tokens, int $position, int $end ): ?array {
		if ( ! isset( $tokens[ $position ] ) ) {
			return null;
		}

		$regexp_position = $position;
		$negated         = false;
		if ( WP_MySQL_Lexer::REGEXP_SYMBOL !== $tokens[ $position ]->id ) {
			if (
				! isset( $tokens[ $position + 1 ] )
				|| WP_MySQL_Lexer::NOT_SYMBOL !== $tokens[ $position ]->id
				|| WP_MySQL_Lexer::REGEXP_SYMBOL !== $tokens[ $position + 1 ]->id
			) {
				return null;
			}

			$regexp_position = $position + 1;
			$negated         = true;
		}

		if (
			isset( $tokens[ $regexp_position + 1 ] )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $regexp_position + 1 ]->id
		) {
			return null;
		}

		$is_binary = $this->is_mysql_regexp_binary_predicate( $tokens, $regexp_position + 1, $end );
		return array(
			'sql'      => $negated ? ( $is_binary ? '!~' : '!~*' ) : ( $is_binary ? '~' : '~*' ),
			'token_id' => WP_MySQL_Lexer::REGEXP_SYMBOL,
			'position' => $is_binary ? $regexp_position + 1 : $regexp_position,
		);
	}

	/**
	 * Check whether a REGEXP predicate starts with the BINARY modifier.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position First right-hand predicate token.
	 * @param int             $end      Final token position, exclusive.
	 * @return bool Whether the predicate uses REGEXP BINARY/RLIKE BINARY.
	 */
	private function is_mysql_regexp_binary_predicate( array $tokens, int $position, int $end ): bool {
		return $position < $end
			&& isset( $tokens[ $position ] )
			&& WP_MySQL_Lexer::BINARY_SYMBOL === $tokens[ $position ]->id;
	}

	/**
	 * Translate MySQL RAND() and RAND(seed) calls to PostgreSQL.
	 *
	 * PostgreSQL setseed() is session-stateful, so literal seeded calls are
	 * folded and dynamic seeded calls render the first value from SQLite's
	 * seeded MySQL-compatible LCG as a stateless SQL expression.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_rand_function_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_function_call_bounds( $tokens, $position, $end, 'rand' );
		if ( null === $bounds ) {
			return null;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
		if ( null === $arguments || count( $arguments ) > 1 ) {
			return null;
		}

		$sql = 'random()';
		if ( 1 === count( $arguments ) ) {
			$seed = $this->get_mysql_literal_rand_seed_value( $tokens, $arguments[0]['start'], $arguments[0]['end'] );
			if ( null !== $seed ) {
				$sql = $this->get_mysql_seeded_rand_literal_sql( $seed['value'] );
			} else {
				$seed_sql = $this->translate_mysql_token_sequence_to_postgresql(
					$tokens,
					$arguments[0]['start'],
					$arguments[0]['end']
				);
				$sql      = $this->get_postgresql_mysql_seeded_rand_sql( $seed_sql );
			}
		}

		return array(
			'sql'      => $sql,
			'token_id' => WP_MySQL_Lexer::IDENTIFIER,
			'position' => $bounds['close'],
		);
	}

	/**
	 * Check whether a range contains an unsupported MySQL RAND() form.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return bool Whether an unsupported RAND() call is present.
	 */
	private function contains_unsupported_mysql_rand_function( array $tokens, int $start, int $end ): bool {
		for ( $i = $start; $i < $end; $i++ ) {
			if ( null === $this->get_mysql_function_call_bounds( $tokens, $i, $end, 'rand' ) ) {
				continue;
			}

			if ( null === $this->translate_mysql_rand_function_to_postgresql( $tokens, $i, $end ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Get a literal MySQL RAND(seed) value using shared MySQL-compatible seed coercion.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First seed token.
	 * @param int              $end    Final seed token, exclusive.
	 * @return array{value: int}|null Seed value, or null when not a literal seed.
	 */
	private function get_mysql_literal_rand_seed_value( array $tokens, int $start, int $end ): ?array {
		if ( $start + 1 === $end && isset( $tokens[ $start ] ) && WP_MySQL_Lexer::NULL_SYMBOL === $tokens[ $start ]->id ) {
			return array( 'value' => 0 );
		}

		if ( $this->is_mysql_string_literal_range( $tokens, $start, $end ) ) {
			return array(
				'value' => (int) fmod( round( (float) $tokens[ $start ]->get_value(), 0, PHP_ROUND_HALF_EVEN ), 0x100000000 ),
			);
		}

		$literal = $this->parse_mysql_numeric_literal( $tokens, $start, $end );
		if ( null === $literal || $literal['start'] !== $start || $literal['end'] !== $end ) {
			return null;
		}

		return array(
			'value' => (int) fmod( round( (float) $this->get_mysql_token_sequence_bytes( $tokens, $start, $end ), 0, PHP_ROUND_HALF_EVEN ), 0x100000000 ),
		);
	}

	/**
	 * Get the first SQLite/MySQL-compatible LCG value for RAND(seed).
	 *
	 * @param int $seed MySQL-coerced seed value.
	 * @return string PostgreSQL numeric literal SQL.
	 */
	private function get_mysql_seeded_rand_literal_sql( int $seed ): string {
		$max_value = 0x3FFFFFFF;
		$seed_u32  = $seed & 0xFFFFFFFF;
		$seed1     = ( ( $seed_u32 * 0x10001 + 55555555 ) & 0xFFFFFFFF ) % $max_value;
		$seed2     = ( ( $seed_u32 * 0x10000001 ) & 0xFFFFFFFF ) % $max_value;
		$seed1     = ( $seed1 * 3 + $seed2 ) % $max_value;

		$literal = rtrim( rtrim( sprintf( '%.17F', (float) $seed1 / (float) $max_value ), '0' ), '.' );
		return sprintf( 'CAST(%s AS double precision)', $literal );
	}

	/**
	 * Get PostgreSQL SQL for the first MySQL-compatible seeded RAND() value.
	 *
	 * @param string $seed_sql PostgreSQL seed expression SQL.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_seeded_rand_sql( string $seed_sql ): string {
		$max_value        = '1073741823';
		$seed_numeric_sql = $this->get_postgresql_mysql_numeric_cast_sql( $seed_sql );
		$seed_sql         = sprintf(
			'(((CAST(ROUND(COALESCE(%s, 0)) AS bigint) %% 4294967296) + 4294967296) %% 4294967296)',
			$seed_numeric_sql
		);
		$seed1_sql        = sprintf( '((("__wp_pg_mysql_rand_seed"."seed" * 65537 + 55555555) %% %s))', $max_value );
		$seed2_sql        = sprintf( '((("__wp_pg_mysql_rand_seed"."seed" * 268435457) %% %s))', $max_value );
		$value_sql        = sprintf( '(((%s * 3 + %s) %% %s))', $seed1_sql, $seed2_sql, $max_value );

		return sprintf(
			'(SELECT CAST(%1$s AS double precision) / %2$s FROM (SELECT %3$s AS "seed") AS "__wp_pg_mysql_rand_seed")',
			$value_sql,
			$max_value,
			$seed_sql
		);
	}

	/**
	 * Translate MySQL session user runtime functions to a stable emulated user.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_session_user_function_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$function = $this->get_mysql_session_user_function_name( $tokens[ $position ] ?? null );
		if ( null === $function ) {
			return null;
		}

		if (
			isset( $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position + 1 ]->id
		) {
			$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $end );
			if ( null === $after_close || $position + 3 !== $after_close ) {
				return null;
			}

			return array(
				'sql'      => $this->connection->quote( self::MYSQL_SESSION_USER ),
				'token_id' => WP_MySQL_Lexer::SINGLE_QUOTED_TEXT,
				'position' => $after_close - 1,
			);
		}

		if ( 'current_user' !== $function ) {
			return null;
		}

		return array(
			'sql'      => $this->connection->quote( self::MYSQL_SESSION_USER ),
			'token_id' => WP_MySQL_Lexer::SINGLE_QUOTED_TEXT,
			'position' => $position,
		);
	}

	/**
	 * Get a normalized MySQL session user function name.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return string|null Function name, or null when unsupported.
	 */
	private function get_mysql_session_user_function_name( ?WP_MySQL_Token $token ): ?string {
		if ( null === $token ) {
			return null;
		}

		if ( WP_MySQL_Lexer::CURRENT_USER_SYMBOL === $token->id ) {
			return 'current_user';
		}

		if ( WP_MySQL_Lexer::USER_SYMBOL !== $token->id ) {
			return null;
		}

		$name = strtolower( $token->get_value() );
		return in_array( $name, array( 'user', 'session_user', 'system_user' ), true ) ? $name : null;
	}

	/**
	 * Translate MySQL temporal functions that allow no parentheses.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_nonparenthesized_timestamp_function_to_postgresql( array $tokens, int $position, int $end ): ?array {
		if ( ! isset( $tokens[ $position ] ) ) {
			return null;
		}

		if (
			isset( $tokens[ $position + 1 ] )
			&& $position + 1 < $end
			&& in_array( $tokens[ $position + 1 ]->id, array( WP_MySQL_Lexer::OPEN_PAR_SYMBOL, WP_MySQL_Lexer::DOT_SYMBOL ), true )
		) {
			return null;
		}

		$function_name = strtolower( $tokens[ $position ]->get_value() );
		if (
			! in_array( $function_name, array( 'current_date', 'current_time', 'current_timestamp', 'localtime', 'localtimestamp' ), true )
			|| (
				in_array( $function_name, array( 'current_timestamp', 'localtime', 'localtimestamp' ), true )
				&& WP_MySQL_Lexer::NOW_SYMBOL !== $tokens[ $position ]->id
			)
			|| (
				in_array( $function_name, array( 'current_date', 'current_time' ), true )
				&& WP_MySQL_Lexer::IDENTIFIER !== $tokens[ $position ]->id
			)
		) {
			return null;
		}

		if ( 'current_date' === $function_name ) {
			$function_name = 'curdate';
		} elseif ( 'current_time' === $function_name ) {
			$function_name = 'utc_time';
		}

		$sql = $this->get_postgresql_mysql_common_function_sql( $function_name, array() );
		if ( null === $sql ) {
			return null;
		}

		return $this->get_postgresql_mysql_expression_translation( $sql, WP_MySQL_Lexer::IDENTIFIER, $position );
	}

	/**
	 * Create translated expression replacement data.
	 *
	 * @param string $sql      PostgreSQL SQL.
	 * @param int    $token_id Replacement token ID.
	 * @param int    $position Final replaced token position.
	 * @return array{sql: string, token_id: int, position: int} Translation data.
	 */
	private function get_postgresql_mysql_expression_translation( string $sql, int $token_id, int $position ): array {
		return array(
			'sql'      => $sql,
			'token_id' => $token_id,
			'position' => $position,
		);
	}

	/**
	 * Translate common MySQL runtime functions to PostgreSQL expressions.
	 *
	 * This mirrors the broad MySQL compatibility function surface used by the
	 * SQLite backend. More complex or ambiguous forms intentionally remain
	 * unsupported so they fail visibly instead of changing semantics silently.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_common_function_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_common_function_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
		if ( null === $arguments ) {
			return null;
		}

		if ( 'substring' === $bounds['function'] ) {
			$arguments = $this->get_mysql_substring_function_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
			if ( null === $arguments ) {
				return null;
			}
		}

		if ( 'trim' === $bounds['function'] ) {
			$trim_bounds = $this->get_mysql_trim_function_bounds( $tokens, $position, $end );
			if ( null === $trim_bounds ) {
				return null;
			}

			$value_sql = $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$trim_bounds['argument_start'],
				$trim_bounds['argument_end']
			);

			$remove_sql = null;
			if ( null !== $trim_bounds['remove_start'] && null !== $trim_bounds['remove_end'] ) {
				$remove_sql = $this->translate_mysql_token_sequence_to_postgresql(
					$tokens,
					$trim_bounds['remove_start'],
					$trim_bounds['remove_end']
				);
			}

			return $this->get_postgresql_mysql_expression_translation(
				$this->get_postgresql_mysql_trim_sql( $trim_bounds['direction'], $value_sql, $trim_bounds['remove'], $remove_sql ),
				WP_MySQL_Lexer::IDENTIFIER,
				$trim_bounds['close']
			);
		}

		if ( 'timestampadd' === $bounds['function'] ) {
			return $this->translate_mysql_timestampadd_function_to_postgresql( $tokens, $arguments, $bounds['close'] );
		}

		if ( 'timestampdiff' === $bounds['function'] ) {
			return $this->translate_mysql_timestampdiff_function_to_postgresql( $tokens, $arguments, $bounds['close'] );
		}

		if (
			'from_unixtime' === $bounds['function']
			&& in_array( count( $arguments ), array( 1, 2 ), true )
			&& $this->is_mysql_null_literal_expression( $tokens, $arguments[0]['start'], $arguments[0]['end'] )
		) {
			return $this->get_postgresql_mysql_expression_translation( 'NULL', WP_MySQL_Lexer::IDENTIFIER, $bounds['close'] );
		}

		if (
			'last_insert_id' === $bounds['function']
			&& 1 === count( $arguments )
			&& $this->mysql_last_insert_id_assignment_translation_enabled
		) {
			$last_insert_id = $this->get_mysql_last_insert_id_assignment_literal_value( $tokens, $position, $bounds['close'] + 1 );
			if ( null === $last_insert_id ) {
				return null;
			}

			$this->mysql_last_insert_id_assignment_value = $last_insert_id;
			return $this->get_postgresql_mysql_expression_translation( (string) $last_insert_id, WP_MySQL_Lexer::IDENTIFIER, $bounds['close'] );
		}

		if (
			in_array( $bounds['function'], array( 'char_length', 'character_length', 'length' ), true )
			&& 1 === count( $arguments )
		) {
			$binary_length_sql = $this->get_postgresql_mysql_binary_argument_byte_length_sql(
				$tokens,
				$arguments[0]['start'],
				$arguments[0]['end']
			);
			if ( null !== $binary_length_sql ) {
				return $this->get_postgresql_mysql_expression_translation( $binary_length_sql, WP_MySQL_Lexer::IDENTIFIER, $bounds['close'] );
			}
		}

		if ( 'from_unixtime' === $bounds['function'] && 2 === count( $arguments ) ) {
			$format = $this->get_mysql_constant_string_expression_value(
				$tokens,
				$arguments[1]['start'],
				$arguments[1]['end']
			);
			if ( null !== $format ) {
				$sql = 'NULL';
				if ( ! $format['is_null'] ) {
					$timestamp_sql = $this->get_postgresql_mysql_from_unixtime_timestamp_sql(
						$this->translate_mysql_token_sequence_to_postgresql(
							$tokens,
							$arguments[0]['start'],
							$arguments[0]['end']
						)
					);
					$sql           = $this->get_postgresql_mysql_generic_date_format_sql( $format['value'], $timestamp_sql, false );
					if ( null === $sql ) {
						return null;
					}
				}

				return $this->get_postgresql_mysql_expression_translation( $sql, WP_MySQL_Lexer::IDENTIFIER, $bounds['close'] );
			}

			$timestamp_sql = $this->get_postgresql_mysql_from_unixtime_timestamp_sql(
				$this->translate_mysql_token_sequence_to_postgresql(
					$tokens,
					$arguments[0]['start'],
					$arguments[0]['end']
				)
			);
			$sql           = $this->get_postgresql_mysql_finite_date_format_choice_sql(
				$tokens,
				$arguments[1]['start'],
				$arguments[1]['end'],
				$timestamp_sql,
				true
			);
			if ( null !== $sql ) {
				return $this->get_postgresql_mysql_expression_translation( $sql, WP_MySQL_Lexer::CASE_SYMBOL, $bounds['close'] );
			}
		}

		if ( 'json_valid' === $bounds['function'] && 1 === count( $arguments ) ) {
			$json_value = $this->get_mysql_constant_string_expression_value(
				$tokens,
				$arguments[0]['start'],
				$arguments[0]['end']
			);
			if ( null !== $json_value ) {
				return $this->get_postgresql_mysql_expression_translation(
					$json_value['is_null'] ? 'NULL' : (string) self::get_mysql_json_valid_runtime_result( $json_value['value'] ),
					WP_MySQL_Lexer::IDENTIFIER,
					$bounds['close']
				);
			}
		}

		$argument_sql = array();
		foreach ( $arguments as $argument ) {
			$argument_sql[] = $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$argument['start'],
				$argument['end']
			);
		}

		if ( 'if' === $bounds['function'] && 3 === count( $argument_sql ) ) {
			$condition_sql = $this->is_mysql_boolean_condition_expression(
				$tokens,
				$arguments[0]['start'],
				$arguments[0]['end']
			)
				? '(' . $argument_sql[0] . ')'
				: $this->get_postgresql_mysql_truthy_expression_sql( $argument_sql[0] );

			return $this->get_postgresql_mysql_expression_translation(
				sprintf( 'CASE WHEN %s THEN %s ELSE %s END', $condition_sql, $argument_sql[1], $argument_sql[2] ),
				WP_MySQL_Lexer::CASE_SYMBOL,
				$bounds['close']
			);
		}

		if ( 'length' === $bounds['function'] && 1 === count( $arguments ) ) {
			$binary_length_sql = $this->get_postgresql_mysql_unhex_length_sql(
				$tokens,
				$arguments[0]['start'],
				$arguments[0]['end']
			);
			if ( null !== $binary_length_sql ) {
				return $this->get_postgresql_mysql_expression_translation( $binary_length_sql, WP_MySQL_Lexer::IDENTIFIER, $bounds['close'] );
			}
		}

		$sql = $this->get_postgresql_mysql_common_function_sql( $bounds['function'], $argument_sql );
		if ( null === $sql ) {
			return null;
		}

		return $this->get_postgresql_mysql_expression_translation( $sql, WP_MySQL_Lexer::IDENTIFIER, $bounds['close'] );
	}

	/**
	 * Get PostgreSQL SQL for MySQL LENGTH(UNHEX(...)).
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First argument token.
	 * @param int              $end    Final argument token, exclusive.
	 * @return string|null PostgreSQL byte-length SQL, or null when unsupported.
	 */
	private function get_postgresql_mysql_unhex_length_sql( array $tokens, int $start, int $end ): ?string {
		$bounds = $this->get_mysql_function_call_bounds( $tokens, $start, $end, 'unhex' );
		if ( null === $bounds || $bounds['close'] + 1 !== $end ) {
			return null;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
		if ( null === $arguments || 1 !== count( $arguments ) ) {
			return null;
		}

		$hex_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$arguments[0]['start'],
			$arguments[0]['end']
		);

		return sprintf( "OCTET_LENGTH(DECODE(CAST(%s AS text), 'hex'))", $hex_sql );
	}

	/**
	 * Get PostgreSQL SQL for LENGTH/CHAR_LENGTH of a MySQL binary expression.
	 *
	 * MySQL CHAR_LENGTH() counts bytes for binary strings. Keep the binary
	 * marker local to length functions so other expression contexts continue to
	 * use the existing text-compatible CAST behavior.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First argument token.
	 * @param int              $end    Final argument token, exclusive.
	 * @return string|null PostgreSQL byte-length SQL, or null when not binary.
	 */
	private function get_postgresql_mysql_binary_argument_byte_length_sql( array $tokens, int $start, int $end ): ?string {
		$hex_literal            = $this->get_mysql_text_hex_literal_value( $tokens, $start, $end );
		$hex_literal_length_sql = null === $hex_literal ? null : (string) strlen( $hex_literal );
		if ( null !== $hex_literal_length_sql ) {
			return $hex_literal_length_sql;
		}

		$unhex_length_sql = $this->get_postgresql_mysql_unhex_length_sql( $tokens, $start, $end );
		if ( null !== $unhex_length_sql ) {
			return $unhex_length_sql;
		}

		$from_base64_length_sql = $this->get_postgresql_mysql_from_base64_length_sql( $tokens, $start, $end );
		if ( null !== $from_base64_length_sql ) {
			return $from_base64_length_sql;
		}

		$binary_cast = $this->get_mysql_typed_cast_or_convert_bounds(
			$tokens,
			$start,
			$end,
			array(
				'cast'    => array( 'binary' ),
				'convert' => array( 'binary' ),
			)
		);
		if ( null !== $binary_cast && $binary_cast['close'] + 1 === $end ) {
			$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$binary_cast['expression_start'],
				$binary_cast['expression_end']
			);

			return $this->get_postgresql_mysql_text_byte_length_sql( $expression_sql );
		}

		if (
			$start + 1 < $end
			&& isset( $tokens[ $start ] )
			&& WP_MySQL_Lexer::BINARY_SYMBOL === $tokens[ $start ]->id
		) {
			$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$start + 1,
				$end
			);

			return $this->get_postgresql_mysql_text_byte_length_sql( $expression_sql );
		}

		return null;
	}

	/**
	 * Get PostgreSQL SQL for MySQL LENGTH/CHAR_LENGTH(FROM_BASE64(...)).
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First argument token.
	 * @param int              $end    Final argument token, exclusive.
	 * @return string|null PostgreSQL byte-length SQL, or null when unsupported.
	 */
	private function get_postgresql_mysql_from_base64_length_sql( array $tokens, int $start, int $end ): ?string {
		$bounds = $this->get_mysql_function_call_bounds( $tokens, $start, $end, 'from_base64' );
		if ( null === $bounds || $bounds['close'] + 1 !== $end ) {
			return null;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
		if ( null === $arguments || 1 !== count( $arguments ) ) {
			return null;
		}

		$base64_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$arguments[0]['start'],
			$arguments[0]['end']
		);

		return sprintf(
			'CASE WHEN %1$s THEN NULL ELSE OCTET_LENGTH(DECODE(CAST(%2$s AS text), \'base64\')) END',
			$this->get_postgresql_mysql_base64_invalid_condition_sql( $base64_sql ),
			$base64_sql
		);
	}

	/**
	 * Get token bounds for a supported common MySQL runtime function.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{function: string, arguments_start: int, arguments_end: int, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_common_function_bounds( array $tokens, int $position, int $end ): ?array {
		$function = $this->get_mysql_common_function_name( $tokens[ $position ] ?? null );
		if (
			null === $function
			|| ! isset( $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		return array(
			'function'        => $function,
			'arguments_start' => $position + 2,
			'arguments_end'   => $after_close - 1,
			'close'           => $after_close - 1,
		);
	}

	/**
	 * Get the normalized name for a supported common MySQL runtime function token.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return string|null Function name, or null when unsupported.
	 */
	private function get_mysql_common_function_name( ?WP_MySQL_Token $token ): ?string {
		if ( null === $token ) {
			return null;
		}

		$keyword_functions = array(
			WP_MySQL_Lexer::ASCII_SYMBOL             => 'ascii',
			WP_MySQL_Lexer::COALESCE_SYMBOL          => 'coalesce',
			WP_MySQL_Lexer::CURRENT_USER_SYMBOL      => 'current_user',
			WP_MySQL_Lexer::CURDATE_SYMBOL           => 'curdate',
			WP_MySQL_Lexer::CURTIME_SYMBOL           => 'utc_time',
			WP_MySQL_Lexer::CURRENT_DATE_SYMBOL      => 'curdate',
			WP_MySQL_Lexer::CURRENT_TIME_SYMBOL      => 'utc_time',
			WP_MySQL_Lexer::CURRENT_TIMESTAMP_SYMBOL => 'utc_timestamp',
			WP_MySQL_Lexer::DATABASE_SYMBOL          => 'database',
			WP_MySQL_Lexer::DATE_SYMBOL              => 'date',
			WP_MySQL_Lexer::IF_SYMBOL                => 'if',
			WP_MySQL_Lexer::LEFT_SYMBOL              => 'left',
			WP_MySQL_Lexer::MID_SYMBOL               => 'substring',
			WP_MySQL_Lexer::NOW_SYMBOL               => 'now',
			WP_MySQL_Lexer::REPLACE_SYMBOL           => 'replace',
			WP_MySQL_Lexer::REGEXP_SYMBOL            => 'regexp',
			WP_MySQL_Lexer::REPEAT_SYMBOL            => 'repeat',
			WP_MySQL_Lexer::REVERSE_SYMBOL           => 'reverse',
			WP_MySQL_Lexer::RIGHT_SYMBOL             => 'right',
			WP_MySQL_Lexer::ROW_COUNT_SYMBOL         => 'row_count',
			WP_MySQL_Lexer::SCHEMA_SYMBOL            => 'database',
			WP_MySQL_Lexer::SUBSTR_SYMBOL            => 'substring',
			WP_MySQL_Lexer::SUBSTRING_SYMBOL         => 'substring',
			WP_MySQL_Lexer::TRIM_SYMBOL              => 'trim',
			WP_MySQL_Lexer::UTC_DATE_SYMBOL          => 'utc_date',
			WP_MySQL_Lexer::UTC_TIME_SYMBOL          => 'utc_time',
			WP_MySQL_Lexer::UTC_TIMESTAMP_SYMBOL     => 'utc_timestamp',
		);
		if ( isset( $keyword_functions[ $token->id ] ) ) {
			return $keyword_functions[ $token->id ];
		}

		if ( WP_MySQL_Lexer::USER_SYMBOL === $token->id ) {
			$name = strtolower( $token->get_value() );
			return in_array( $name, array( 'user', 'session_user', 'system_user' ), true ) ? $name : null;
		}

		$name = $this->get_mysql_identifier_token_value( $token );
		if ( null === $name ) {
			return null;
		}

		$name    = strtolower( $name );
		$aliases = array_combine(
			explode( ' ', 'current_date current_time current_timestamp' ),
			explode( ' ', 'curdate utc_time utc_timestamp' )
		);
		if ( isset( $aliases[ $name ] ) ) {
			return $aliases[ $name ];
		}

		$supported = explode( ' ', 'ascii char_length character_length concat concat_ws connection_id curdate current_user database date dayname datediff elt find_in_set found_rows from_base64 from_unixtime get_lock greatest hex if ifnull inet_aton inet_ntoa instr isnull is_uuid json_valid lcase last_insert_id left least length locate log lower lpad localtime localtimestamp ltrim make_set md5 monthnum monthname now nullif release_lock replace regexp repeat reverse right rpad rtrim row_count schema session_user space substr substring system_user timestampadd timestampdiff to_base64 trim ucase unhex unix_timestamp upper utc_date utc_time utc_timestamp user version uuid' );

		return in_array( $name, $supported, true ) ? $name : null;
	}

	/**
	 * Check whether a range contains an unsupported known MySQL runtime function.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return bool Whether an unsupported known MySQL runtime function is present.
	 */
	private function contains_unsupported_mysql_common_function( array $tokens, int $start, int $end ): bool {
		for ( $i = $start; $i < $end; $i++ ) {
			if ( null === $this->get_mysql_common_function_bounds( $tokens, $i, $end ) ) {
				continue;
			}

			if ( null === $this->translate_mysql_common_function_to_postgresql( $tokens, $i, $end ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether a range contains an unsupported MySQL CONVERT() function.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First token position.
	 * @param int             $end    Final token position, exclusive.
	 * @return bool Whether an unsupported CONVERT() form is present.
	 */
	private function contains_unsupported_mysql_convert_function( array $tokens, int $start, int $end ): bool {
		for ( $i = $start; $i < $end; $i++ ) {
			if (
				! isset( $tokens[ $i ], $tokens[ $i + 1 ] )
				|| WP_MySQL_Lexer::CONVERT_SYMBOL !== $tokens[ $i ]->id
				|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $i + 1 ]->id
			) {
				continue;
			}

			if (
				null !== $this->get_mysql_convert_using_bounds( $tokens, $i, $end )
				|| null !== $this->get_mysql_typed_convert_bounds(
					$tokens,
					$i,
					$end,
					array( 'integer', 'character', 'binary', 'decimal', 'date' )
				)
			) {
				continue;
			}

			return true;
		}

		return false;
	}

	/**
	 * Check whether a query contains unsupported MySQL FULLTEXT search syntax.
	 *
	 * Metadata-only FULLTEXT indexes are supported for dbDelta compatibility,
	 * but MATCH (...) AGAINST (...) search semantics are not emulated.
	 *
	 * @param string $query SQL query.
	 * @return bool Whether unsupported FULLTEXT search syntax is present.
	 */
	private function contains_unsupported_mysql_fulltext_search_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) ) {
			return false;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return false;
		}

		for ( $i = 0; $i < $statement_end; $i++ ) {
			if (
				WP_MySQL_Lexer::MATCH_SYMBOL !== $tokens[ $i ]->id
				|| ! isset( $tokens[ $i + 1 ] )
				|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $i + 1 ]->id
			) {
				continue;
			}

			$after_match = $this->get_mysql_parenthesized_sequence_end( $tokens, $i + 1, $statement_end );
			if (
				null !== $after_match
				&& isset( $tokens[ $after_match ], $tokens[ $after_match + 1 ] )
				&& WP_MySQL_Lexer::AGAINST_SYMBOL === $tokens[ $after_match ]->id
				&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $after_match + 1 ]->id
			) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether a range contains an unsupported GROUP_CONCAT() form.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return bool Whether an unsupported GROUP_CONCAT() form is present.
	 */
	private function contains_unsupported_mysql_group_concat_function( array $tokens, int $start, int $end ): bool {
		for ( $i = $start; $i < $end; $i++ ) {
			if ( null === $this->get_mysql_group_concat_function_bounds( $tokens, $i, $end ) ) {
				continue;
			}

			if ( null === $this->translate_mysql_group_concat_function_to_postgresql( $tokens, $i, $end ) ) {
				return true;
			}
		}

		return false;
	}

	private function contains_unsupported_mysql_group_concat_function_query( string $query ): bool {
		return $this->contains_unsupported_mysql_range_scanner_query( $query, array( 'contains_unsupported_mysql_group_concat_function' ) );
	}

	/**
	 * Get PostgreSQL SQL testing whether a MySQL FROM_BASE64() input is invalid.
	 *
	 * @param string $argument_sql PostgreSQL argument SQL.
	 * @return string PostgreSQL condition SQL.
	 */
	private function get_postgresql_mysql_base64_invalid_condition_sql( string $argument_sql ): string {
		$argument_text_sql = sprintf( 'CAST(%s AS text)', $argument_sql );
		return sprintf(
			"%1\$s IS NULL OR %1\$s !~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$'",
			$argument_text_sql
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL LPAD()/RPAD().
	 *
	 * PostgreSQL raises when the fill string is empty. MySQL returns NULL for
	 * empty fill strings and negative target lengths, so guard before calling
	 * LPAD()/RPAD().
	 *
	 * @param string $function_name MySQL padding function name.
	 * @param string $value_sql     PostgreSQL value expression SQL.
	 * @param string $length_sql    PostgreSQL target length expression SQL.
	 * @param string $pad_sql       PostgreSQL padding expression SQL.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_pad_sql( string $function_name, string $value_sql, string $length_sql, string $pad_sql ): string {
		return sprintf(
			'CASE WHEN %1$s IS NULL OR %2$s IS NULL OR %3$s IS NULL OR CAST(%2$s AS integer) < 0 OR CAST(%3$s AS text) = \'\' THEN NULL ELSE %4$s(CAST(%1$s AS text), CAST(%2$s AS integer), CAST(%3$s AS text)) END',
			$value_sql,
			$length_sql,
			$pad_sql,
			strtoupper( $function_name )
		);
	}

	/**
	 * Get PostgreSQL SQL for a supported MySQL TRIM() form.
	 *
	 * @param string $direction MySQL trim direction: both, leading, or trailing.
	 * @param string $value_sql PostgreSQL value expression SQL.
	 * @param string|null $remove Literal string to remove, or null for dynamic.
	 * @param string|null $remove_sql PostgreSQL dynamic removal expression SQL.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_trim_sql( string $direction, string $value_sql, ?string $remove, ?string $remove_sql = null ): string {
		$value_text_sql = sprintf( 'CAST(%s AS text)', $value_sql );
		if ( null === $remove ) {
			if ( null === $remove_sql ) {
				return $value_text_sql;
			}

			return $this->get_postgresql_mysql_dynamic_trim_sql( $direction, $value_text_sql, sprintf( 'CAST(%s AS text)', $remove_sql ) );
		}

		if ( '' === $remove ) {
			return $value_text_sql;
		}

		if ( ' ' === $remove ) {
			$function = array(
				'both'     => 'BTRIM',
				'leading'  => 'LTRIM',
				'trailing' => 'RTRIM',
			)[ $direction ];

			return sprintf( "%s(%s, ' ')", $function, $value_text_sql );
		}

		$remove_pattern = (string) preg_replace( '/([\\\\.^$|?*+()[\]{}])/', '\\\\$1', $remove );
		if ( 'leading' === $direction ) {
			return sprintf( 'REGEXP_REPLACE(%s, %s, \'\')', $value_text_sql, $this->connection->quote( '^(' . $remove_pattern . ')+' ) );
		}

		if ( 'trailing' === $direction ) {
			return sprintf( 'REGEXP_REPLACE(%s, %s, \'\')', $value_text_sql, $this->connection->quote( '(' . $remove_pattern . ')+$' ) );
		}

		return sprintf(
			'REGEXP_REPLACE(REGEXP_REPLACE(%s, %s, \'\'), %s, \'\')',
			$value_text_sql,
			$this->connection->quote( '^(' . $remove_pattern . ')+' ),
			$this->connection->quote( '(' . $remove_pattern . ')+$' )
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL TRIM() with a dynamic removal expression.
	 *
	 * @param string $direction       MySQL trim direction: both, leading, or trailing.
	 * @param string $value_text_sql  PostgreSQL value expression cast to text.
	 * @param string $remove_text_sql PostgreSQL removal expression cast to text.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_dynamic_trim_sql( string $direction, string $value_text_sql, string $remove_text_sql ): string {
		$escaped_remove_sql = sprintf(
			"REGEXP_REPLACE(%s, %s, %s, 'g')",
			$remove_text_sql,
			$this->connection->quote( '([\\\\.^$|?*+()[\]{}])' ),
			$this->connection->quote( '\\\\\1' )
		);
		$leading_pattern    = sprintf( "( '^(' || %s || ')+' )", $escaped_remove_sql );
		$trailing_pattern   = sprintf( "( '(' || %s || ')+$' )", $escaped_remove_sql );

		if ( 'leading' === $direction ) {
			$trimmed_sql = sprintf( "REGEXP_REPLACE(%s, %s, '')", $value_text_sql, $leading_pattern );
		} elseif ( 'trailing' === $direction ) {
			$trimmed_sql = sprintf( "REGEXP_REPLACE(%s, %s, '')", $value_text_sql, $trailing_pattern );
		} else {
			$trimmed_sql = sprintf(
				"REGEXP_REPLACE(REGEXP_REPLACE(%s, %s, ''), %s, '')",
				$value_text_sql,
				$leading_pattern,
				$trailing_pattern
			);
		}

		return sprintf(
			'CASE WHEN %1$s IS NULL OR %2$s IS NULL THEN NULL WHEN %2$s = \'\' THEN %1$s ELSE %3$s END',
			$value_text_sql,
			$remove_text_sql,
			$trimmed_sql
		);
	}

	/**
	 * Render PostgreSQL SQL for a supported common MySQL runtime function.
	 *
	 * @param string   $function_name Lowercase MySQL function name.
	 * @param string[] $argument_sql Translated PostgreSQL arguments.
	 * @return string|null PostgreSQL SQL, or null when unsupported.
	 */
	private function get_postgresql_mysql_common_function_sql( string $function_name, array $argument_sql ): ?string {
		$count = count( $argument_sql );

		$templates = array(
			1 => array(
				'char_length'      => 'CHAR_LENGTH(CAST(%s AS text))',
				'character_length' => 'CHAR_LENGTH(CAST(%s AS text))',
				'hex'              => "UPPER(ENCODE(CONVERT_TO(CAST(%s AS text), 'UTF8'), 'hex'))",
				'isnull'           => 'CASE WHEN %s IS NULL THEN 1 ELSE 0 END',
				'lcase'            => 'LOWER(CAST(%s AS text))',
				'lower'            => 'LOWER(CAST(%s AS text))',
				'ltrim'            => "LTRIM(CAST(%s AS text), ' ')",
				'md5'              => 'MD5(CAST(%s AS text))',
				'reverse'          => 'REVERSE(CAST(%s AS text))',
				'rtrim'            => "RTRIM(CAST(%s AS text), ' ')",
				'space'            => "CASE WHEN %1\$s IS NULL THEN NULL ELSE REPEAT(' ', GREATEST(CAST(%1\$s AS integer), 0)) END",
				'to_base64'        => "ENCODE(CONVERT_TO(CAST(%s AS text), 'UTF8'), 'base64')",
				'trim'             => "BTRIM(CAST(%s AS text), ' ')",
				'ucase'            => 'UPPER(CAST(%s AS text))',
				'unhex'            => "CONVERT_FROM(DECODE(CAST(%s AS text), 'hex'), 'UTF8')",
				'upper'            => 'UPPER(CAST(%s AS text))',
			),
			2 => array(
				'ifnull' => 'COALESCE(%s, %s)',
				'instr'  => 'STRPOS(CAST(%s AS text), CAST(%s AS text))',
				'left'   => 'LEFT(CAST(%s AS text), CAST(%s AS integer))',
				'nullif' => 'NULLIF(%s, %s)',
				'repeat' => 'CASE WHEN %1$s IS NULL OR %2$s IS NULL THEN NULL ELSE REPEAT(CAST(%1$s AS text), GREATEST(CAST(%2$s AS integer), 0)) END',
				'right'  => 'RIGHT(CAST(%s AS text), CAST(%s AS integer))',
			),
			3 => array(
				'replace' => 'REPLACE(CAST(%s AS text), CAST(%s AS text), CAST(%s AS text))',
			),
		);
		if ( isset( $templates[ $count ][ $function_name ] ) ) {
			return vsprintf( $templates[ $count ][ $function_name ], $argument_sql );
		}

		$array_method_specs = array(
			'concat_ws' => array( 2, null, 'get_postgresql_mysql_concat_ws_sql' ),
			'elt'       => array( 2, null, 'get_postgresql_mysql_elt_sql' ),
			'log'       => array( 1, 2, 'get_postgresql_mysql_log_sql' ),
			'make_set'  => array( 2, null, 'get_postgresql_mysql_make_set_sql' ),
			'substr'    => array( 2, 3, 'get_postgresql_mysql_substring_sql' ),
			'substring' => array( 2, 3, 'get_postgresql_mysql_substring_sql' ),
		);
		if ( isset( $array_method_specs[ $function_name ] ) ) {
			list( $min_args, $max_args, $method ) = $array_method_specs[ $function_name ];
			return $count >= $min_args && ( null === $max_args || $count <= $max_args ) ? $this->$method( $argument_sql ) : null;
		}

		$single_arg_method_specs = array(
			'date'       => 'get_postgresql_mysql_date_sql',
			'json_valid' => 'get_postgresql_mysql_json_valid_sql',
			'length'     => 'get_postgresql_mysql_text_byte_length_sql',
		);
		if ( isset( $single_arg_method_specs[ $function_name ] ) ) {
			$method = $single_arg_method_specs[ $function_name ];
			return 1 === $count ? $this->$method( $argument_sql[0] ) : null;
		}

		$zero_arg_sql = array(
			'connection_id' => (string) self::MYSQL_CONNECTION_ID,
			'database'      => $this->connection->quote( $this->db_name ),
			'found_rows'    => (string) $this->last_found_rows,
			'row_count'     => (string) $this->last_row_count,
			'schema'        => $this->connection->quote( $this->db_name ),
			'uuid'          => "LOWER(REGEXP_REPLACE(MD5(CAST(CLOCK_TIMESTAMP() AS text) || CAST(RANDOM() AS text) || CAST(PG_BACKEND_PID() AS text)), '^(.{8})(.{4}).(.{3}).(.{3})(.{12})$', '\\1-\\2-4\\3-8\\4-\\5'))",
			'version'       => $this->connection->quote( $this->get_mysql_version_string() ),
		);
		if ( isset( $zero_arg_sql[ $function_name ] ) ) {
			return 0 === $count ? $zero_arg_sql[ $function_name ] : null;
		}

		if ( in_array( $function_name, array( 'current_user', 'session_user', 'system_user', 'user' ), true ) ) {
			return 0 === $count ? $this->connection->quote( self::MYSQL_SESSION_USER ) : null;
		}

		if ( 'get_lock' === $function_name || 'release_lock' === $function_name ) {
			return ( 'get_lock' === $function_name ? 2 : 1 ) === $count ? '1' : null;
		}

		switch ( $function_name ) {
			case 'ascii':
				if ( 1 !== $count ) {
					return null;
				}

				$text_sql           = sprintf( 'CAST(%s AS text)', $argument_sql[0] );
				$prefix_chars       = preg_match_all( '/./us', self::MYSQL_TEXT_ENCODING_PREFIX );
				$prefix_length      = false === $prefix_chars ? strlen( self::MYSQL_TEXT_ENCODING_PREFIX ) : $prefix_chars;
				$prefix_sql         = $this->connection->get_pdo()->quote( self::MYSQL_TEXT_ENCODING_PREFIX );
				$payload_sql        = sprintf( 'SUBSTR(%s, %d)', $text_sql, $prefix_length + 1 );
				$separator_sql      = sprintf( "STRPOS(%s, ':')", $payload_sql );
				$length_sql         = sprintf( 'SUBSTR(%s, 1, GREATEST(%s - 1, 0))', $payload_sql, $separator_sql );
				$after_length_sql   = sprintf( 'SUBSTR(%s, GREATEST(%s + 1, 1))', $payload_sql, $separator_sql );
				$hash_separator_sql = sprintf( "STRPOS(%s, ':')", $after_length_sql );
				$hash_sql           = sprintf( 'SUBSTR(%s, 1, GREATEST(%s - 1, 0))', $after_length_sql, $hash_separator_sql );
				$hex_sql            = sprintf( 'SUBSTR(%s, GREATEST(%s + 1, 1))', $after_length_sql, $hash_separator_sql );
				$envelope_sql       = sprintf(
					"SUBSTR(%1\$s, 1, %2\$d) = %3\$s AND %4\$s > 1 AND %5\$s > 1 AND TRANSLATE(%6\$s, '0123456789', '') = '' AND (%6\$s = '0' OR SUBSTR(%6\$s, 1, 1) <> '0') AND %7\$s ~ '^[0-9a-f]{64}$' AND MOD(CHAR_LENGTH(%8\$s), 2) = 0 AND %8\$s ~ '^[0-9a-f]*$' AND (%6\$s = '0' OR CHAR_LENGTH(%8\$s) >= 2)",
					$text_sql,
					$prefix_length,
					$prefix_sql,
					$separator_sql,
					$hash_separator_sql,
					$length_sql,
					$hash_sql,
					$hex_sql
				);

				return sprintf(
					"CASE WHEN %1\$s IS NULL THEN NULL WHEN %2\$s THEN CASE WHEN CAST(%3\$s AS bigint) = 0 THEN 0 ELSE GET_BYTE(DECODE(SUBSTR(%4\$s, 1, 2), 'hex'), 0) END WHEN %1\$s = '' THEN 0 ELSE GET_BYTE(CONVERT_TO(%1\$s, 'UTF8'), 0) END",
					$text_sql,
					$envelope_sql,
					$length_sql,
					$hex_sql
				);

			case 'concat':
				if ( 0 === $count ) {
					return null;
				}

				return '(' . implode(
					' || ',
					array_map(
						static function ( string $sql ): string {
							return sprintf( 'CAST(%s AS text)', $sql );
						},
						$argument_sql
					)
				) . ')';

			case 'find_in_set':
				return 2 === $count ? $this->get_postgresql_mysql_find_in_set_sql( $argument_sql[0], $argument_sql[1] ) : null;

			case 'curdate':
			case 'utc_date':
				return 0 === $count ? "TO_CHAR(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD')" : null;

			case 'utc_time':
				$fsp = $this->get_mysql_temporal_function_fractional_seconds_precision( $argument_sql );
				if ( null === $fsp ) {
					return null;
				}
				if ( 0 === $fsp ) {
					return "TO_CHAR(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'HH24:MI:SS')";
				}

				return sprintf(
					"LEFT(TO_CHAR(CURRENT_TIMESTAMP(%1\$d) AT TIME ZONE 'UTC', 'HH24:MI:SS.US'), %2\$d)",
					$fsp,
					9 + $fsp
				);

			case 'current_timestamp':
			case 'localtime':
			case 'localtimestamp':
			case 'now':
			case 'utc_timestamp':
				$fsp = $this->get_mysql_temporal_function_fractional_seconds_precision( $argument_sql );
				return null === $fsp ? null : $this->get_postgresql_mysql_current_timestamp_sql( $fsp );

			case 'lpad':
			case 'rpad':
				return 3 === $count ? $this->get_postgresql_mysql_pad_sql( $function_name, $argument_sql[0], $argument_sql[1], $argument_sql[2] ) : null;

			case 'is_uuid':
				if ( 1 !== $count ) {
					return null;
				}

				$argument_text_sql = sprintf( 'CAST(%s AS text)', $argument_sql[0] );
				return sprintf(
					'CASE WHEN %1$s IS NULL THEN NULL WHEN %1$s ~* %2$s THEN 1 ELSE 0 END',
					$argument_text_sql,
					$this->connection->quote( '^(?:[0-9a-f]{32}|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|\{[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\})$' )
				);

			case 'last_insert_id':
				if ( 0 !== $count ) {
					return null;
				}

				$last_insert_id = null !== $this->mysql_last_insert_id_assignment_value
					? $this->mysql_last_insert_id_assignment_value
					: $this->get_insert_id();
				return is_numeric( $last_insert_id ) ? (string) (int) $last_insert_id : '0';

			case 'coalesce':
				return $count > 0 ? sprintf( 'COALESCE(%s)', implode( ', ', $argument_sql ) ) : null;

			case 'if':
				return null;

			case 'least':
			case 'greatest':
				if ( $count < 2 ) {
					return null;
				}

				return sprintf(
					'CASE WHEN %1$s THEN NULL ELSE %2$s(%3$s) END',
					implode(
						' OR ',
						array_map(
							static function ( string $sql ): string {
								return sprintf( '%s IS NULL', $sql );
							},
							$argument_sql
						)
					),
					strtoupper( $function_name ),
					implode( ', ', $argument_sql )
				);

			case 'from_base64':
				return 1 === $count
					? sprintf(
						'CASE WHEN %1$s THEN NULL ELSE CONVERT_FROM(DECODE(CAST(%2$s AS text), \'base64\'), \'UTF8\') END',
						$this->get_postgresql_mysql_base64_invalid_condition_sql( $argument_sql[0] ),
						$argument_sql[0]
					)
					: null;

			case 'inet_aton':
				if ( 1 !== $count ) {
					return null;
				}

				$ip = sprintf( 'CAST(%s AS text)', $argument_sql[0] );
				return sprintf(
					'CASE WHEN %1$s IS NULL THEN NULL ELSE ((CAST(SPLIT_PART(%1$s, \'.\', 1) AS bigint) << 24) + (CAST(SPLIT_PART(%1$s, \'.\', 2) AS bigint) << 16) + (CAST(SPLIT_PART(%1$s, \'.\', 3) AS bigint) << 8) + CAST(SPLIT_PART(%1$s, \'.\', 4) AS bigint)) END',
					$ip
				);

			case 'inet_ntoa':
				if ( 1 !== $count ) {
					return null;
				}

				$number = sprintf( 'CAST(%s AS bigint)', $argument_sql[0] );
				return sprintf(
					'CASE WHEN %1$s IS NULL THEN NULL ELSE (((%1$s >> 24) & 255)::text || \'.\' || ((%1$s >> 16) & 255)::text || \'.\' || ((%1$s >> 8) & 255)::text || \'.\' || (%1$s & 255)::text) END',
					$number
				);

			case 'datediff':
				if ( 2 !== $count ) {
					return null;
				}

				return sprintf(
					'CAST((CAST(%1$s AS date) - CAST(%2$s AS date)) AS integer)',
					$this->get_postgresql_zero_date_safe_timestamp_sql( $argument_sql[0] ),
					$this->get_postgresql_zero_date_safe_timestamp_sql( $argument_sql[1] )
				);

			case 'locate':
				if ( 2 === $count ) {
					return sprintf( 'STRPOS(CAST(%2$s AS text), CAST(%1$s AS text))', $argument_sql[0], $argument_sql[1] );
				}
				if ( 3 === $count ) {
					return $this->get_postgresql_mysql_locate_with_position_sql( $argument_sql[0], $argument_sql[1], $argument_sql[2] );
				}
				return null;

			case 'dayname':
				return 1 === $count
					? $this->get_postgresql_mysql_temporal_name_sql(
						'DOW',
						$argument_sql[0],
						array(
							0 => 'Sunday',
							1 => 'Monday',
							2 => 'Tuesday',
							3 => 'Wednesday',
							4 => 'Thursday',
							5 => 'Friday',
							6 => 'Saturday',
						)
					)
					: null;

			case 'monthname':
				return 1 === $count
					? $this->get_postgresql_mysql_temporal_name_sql(
						'MONTH',
						$argument_sql[0],
						array(
							1  => 'January',
							2  => 'February',
							3  => 'March',
							4  => 'April',
							5  => 'May',
							6  => 'June',
							7  => 'July',
							8  => 'August',
							9  => 'September',
							10 => 'October',
							11 => 'November',
							12 => 'December',
						)
					)
					: null;

			case 'regexp':
				if ( 2 !== $count ) {
					return null;
				}

				$pattern = sprintf( 'CAST(%s AS text)', $argument_sql[0] );
				$value   = sprintf( 'CAST(%s AS text)', $argument_sql[1] );
				return sprintf(
					'CASE WHEN %1$s IS NULL OR %2$s IS NULL THEN NULL WHEN %2$s ~* %1$s THEN 1 ELSE 0 END',
					$pattern,
					$value
				);

			case 'from_unixtime':
				if ( 1 === $count ) {
					$unix_double_sql = sprintf( 'CAST(%s AS double precision)', $argument_sql[0] );
					$timestamp_sql   = $this->get_postgresql_mysql_from_unixtime_timestamp_sql( $argument_sql[0] );

					return sprintf(
						"CASE WHEN %1\$s IS NULL THEN NULL WHEN %1\$s = FLOOR(%1\$s) THEN TO_CHAR(%2\$s, 'YYYY-MM-DD HH24:MI:SS') ELSE TO_CHAR(%2\$s, 'YYYY-MM-DD HH24:MI:SS.US') END",
						$unix_double_sql,
						$timestamp_sql
					);
				}
				if ( 2 === $count ) {
					$timestamp_sql = $this->get_postgresql_mysql_from_unixtime_timestamp_sql( $argument_sql[0] );
					$format        = $this->get_mysql_sql_string_literal_value( $argument_sql[1] );
					if ( null !== $format ) {
						return $this->get_postgresql_mysql_generic_date_format_sql(
							$format,
							$timestamp_sql,
							false
						);
					}

					return $this->get_postgresql_mysql_dynamic_date_format_sql(
						$argument_sql[1],
						$timestamp_sql
					);
				}
				return null;

			case 'monthnum':
				return 1 === $count ? $this->get_postgresql_zero_date_safe_extract_sql( 'MONTH', $argument_sql[0] ) : null;

			case 'unix_timestamp':
				if ( 0 === $count ) {
					return 'CAST(FLOOR(EXTRACT(EPOCH FROM CURRENT_TIMESTAMP)) AS bigint)';
				}
				if ( 1 === $count ) {
					return sprintf( 'CAST(FLOOR(EXTRACT(EPOCH FROM %s)) AS bigint)', $this->get_postgresql_zero_date_safe_timestamp_sql( $argument_sql[0] ) );
				}
				return null;

		}

		return null;
	}

	/**
	 * Get PostgreSQL SQL for an English MySQL temporal name function.
	 *
	 * @param string        $unit           PostgreSQL EXTRACT unit.
	 * @param string        $expression_sql PostgreSQL expression SQL.
	 * @param array<int,string> $names      Extracted integer value to MySQL name.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_temporal_name_sql( string $unit, string $expression_sql, array $names ): string {
		$expression_text_sql = sprintf( 'CAST(%s AS text)', $expression_sql );
		$timestamp_sql       = $this->get_postgresql_zero_date_safe_timestamp_sql( $expression_sql );
		$branches            = array();

		foreach ( $names as $value => $name ) {
			$branches[] = sprintf(
				'WHEN %d THEN %s',
				$value,
				$this->connection->quote( $name )
			);
		}

		return sprintf(
			'CASE WHEN %1$s OR %2$s THEN NULL ELSE CASE CAST(EXTRACT(%3$s FROM %4$s) AS integer) %5$s END END',
			$this->get_postgresql_empty_temporal_condition_sql( $expression_text_sql ),
			$this->get_postgresql_zero_date_condition_sql( $expression_text_sql ),
			$unit,
			$timestamp_sql,
			implode( ' ', $branches )
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL JSON_VALID().
	 *
	 * PostgreSQL can validate dynamic JSON text with pg_input_is_valid() without
	 * raising a cast error. SQLite-backed tests keep using the runtime helper for
	 * dynamic values, while constant values can be folded before execution.
	 *
	 * @param string $argument_sql PostgreSQL argument SQL.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_json_valid_sql( string $argument_sql ): string {
		if ( 'NULL' === strtoupper( trim( $argument_sql ) ) ) {
			return 'NULL';
		}

		$literal_value = $this->get_mysql_sql_string_literal_value( $argument_sql );
		if ( null !== $literal_value ) {
			return (string) self::get_mysql_json_valid_runtime_result( $literal_value );
		}

		if ( 1 === preg_match( '/^-?(?:0|[1-9][0-9]*)(?:[.][0-9]+)?(?:[eE][+-]?[0-9]+)?$/', trim( $argument_sql ) ) ) {
			return (string) self::get_mysql_json_valid_runtime_result( trim( $argument_sql ) );
		}

		if ( 'pgsql' === $this->connection->get_driver_name() ) {
			return sprintf(
				'CASE WHEN %1$s IS NULL THEN NULL WHEN pg_input_is_valid(CAST(%1$s AS text), %2$s) THEN 1 ELSE 0 END',
				$argument_sql,
				$this->connection->quote( 'json' )
			);
		}

		return sprintf( 'CASE WHEN %1$s IS NULL THEN NULL ELSE json_valid(CAST(%1$s AS text)) END', $argument_sql );
	}

	/**
	 * Get PostgreSQL timestamp SQL for MySQL FROM_UNIXTIME() in the session time zone.
	 *
	 * @param string $unix_timestamp_sql PostgreSQL Unix timestamp expression SQL.
	 * @return string PostgreSQL timestamp SQL.
	 */
	private function get_postgresql_mysql_from_unixtime_timestamp_sql( string $unix_timestamp_sql ): string {
		$timestamp_sql = sprintf( "TO_TIMESTAMP(CAST(%s AS double precision)) AT TIME ZONE 'UTC'", $unix_timestamp_sql );
		$time_zone     = $this->get_mysql_system_variable_value( 'time_zone' );
		$offset        = $this->get_mysql_time_zone_offset_minutes( null === $time_zone ? 'SYSTEM' : $time_zone );

		if ( null === $offset || 0 === $offset ) {
			return $timestamp_sql;
		}

		return sprintf(
			'(%s + INTERVAL %s)',
			$timestamp_sql,
			$this->connection->quote( $offset . ' minutes' )
		);
	}

	/**
	 * Get a numeric minute offset from a MySQL time_zone value.
	 *
	 * @param string $time_zone MySQL time_zone value.
	 * @return int|null Offset minutes, or null for UTC/SYSTEM/unsupported named zones.
	 */
	private function get_mysql_time_zone_offset_minutes( string $time_zone ): ?int {
		$time_zone = trim( $time_zone, "'\"` \t\n\r\0\x0B" );
		if ( '' === $time_zone || 0 === strcasecmp( $time_zone, 'SYSTEM' ) || 0 === strcasecmp( $time_zone, 'UTC' ) ) {
			return 0;
		}

		if ( 1 !== preg_match( '/\A([+-])([0-9]{2}):([0-9]{2})\z/', $time_zone, $matches ) ) {
			return null;
		}

		$offset = ( (int) $matches[2] * 60 ) + (int) $matches[3];
		return '-' === $matches[1] ? -$offset : $offset;
	}

	/**
	 * Ensure runtime helper functions referenced by a translated query exist.
	 *
	 * @param string $query PostgreSQL query.
	 */
	private function ensure_postgresql_runtime_helpers_for_query( string $query ): void {
		if ( $this->should_use_postgresql_catalog_metadata() ) {
			foreach ( array_keys( self::MYSQL_TEXT_DOMAIN_TYPES ) as $domain_name ) {
				if ( false === strpos( $query, $domain_name ) ) {
					continue;
				}

				$this->connection->query(
					sprintf(
						'DO $wp_mysql_text_domain$
BEGIN
	CREATE DOMAIN %s AS text;
EXCEPTION WHEN duplicate_object THEN
	NULL;
END;
$wp_mysql_text_domain$',
						$this->connection->quote_identifier( $domain_name )
					)
				);
			}
		}

		$this->ensure_postgresql_mysql_domains( 'binary', $this->get_postgresql_mysql_binary_domain_definitions_for_query( $query ) );
		$this->ensure_postgresql_mysql_domains( 'integer', $this->get_postgresql_mysql_integer_domain_definitions_for_query( $query ) );
		$this->ensure_postgresql_mysql_domains( 'numeric', $this->get_postgresql_mysql_numeric_domain_definitions_for_query( $query ) );
	}

	/**
	 * Get MySQL binary/blob domain definitions referenced by a PostgreSQL query.
	 *
	 * @param string $query PostgreSQL query.
	 * @return array<string,string> Domain name to PostgreSQL base type.
	 */
	private function get_postgresql_mysql_binary_domain_definitions_for_query( string $query ): array {
		$match_count = preg_match_all( '/\b__wp_mysql_(?:(?:var)?binary(?:_[0-9]+)?|tinyblob|blob|mediumblob|longblob)\b/', $query, $matches );
		if ( false === $match_count || 0 === $match_count ) {
			return array();
		}

		$domain_definitions = array();
		foreach ( $matches[0] as $domain_name ) {
			$domain_definitions[ $domain_name ] = 'bytea';
		}

		return $domain_definitions;
	}

	/**
	 * Ensure PostgreSQL domains that preserve MySQL type shapes exist.
	 *
	 * @param string               $kind               Domain kind for the DO block label.
	 * @param array<string,string> $domain_definitions Domain name to PostgreSQL base type.
	 */
	private function ensure_postgresql_mysql_domains( string $kind, array $domain_definitions ): void {
		if ( ! $this->should_use_postgresql_catalog_metadata() ) {
			return;
		}

		foreach ( $domain_definitions as $domain_name => $base_type ) {
			$this->connection->query(
				sprintf(
					'DO $wp_mysql_%1$s_domain$
BEGIN
	CREATE DOMAIN %2$s AS %3$s;
EXCEPTION WHEN duplicate_object THEN
	NULL;
END;
$wp_mysql_%1$s_domain$',
					$kind,
					$this->connection->quote_identifier( $domain_name ),
					$base_type
				)
			);
		}
	}

	/**
	 * Get MySQL integer domain definitions referenced by a PostgreSQL query.
	 *
	 * @param string $query PostgreSQL query.
	 * @return array<string,string> Domain name to PostgreSQL base type.
	 */
	private function get_postgresql_mysql_integer_domain_definitions_for_query( string $query ): array {
		$match_count = preg_match_all( '/\b__wp_mysql_(bit|bool|boolean|tinyint|smallint|mediumint|int|int1|int2|int3|int4|int8|bigint)(?:_([0-9]+))?(_unsigned)?\b/', $query, $matches, PREG_SET_ORDER );
		if ( false === $match_count || 0 === $match_count ) {
			return array();
		}

		$domain_definitions = array();
		foreach ( $matches as $match ) {
			$type = $match[1];
			if ( ! isset( self::MYSQL_INTEGER_DOMAIN_BASE_TYPES[ $type ] ) ) {
				continue;
			}

			$domain_definitions[ $match[0] ] = self::MYSQL_INTEGER_DOMAIN_BASE_TYPES[ $type ];
		}

		return $domain_definitions;
	}

	/**
	 * Get MySQL numeric alias domain definitions referenced by a PostgreSQL query.
	 *
	 * @param string $query PostgreSQL query.
	 * @return array<string,string> Domain name to PostgreSQL base type.
	 */
	private function get_postgresql_mysql_numeric_domain_definitions_for_query( string $query ): array {
		$match_count = preg_match_all( '/\b__wp_mysql_(dec|fixed|float|double|real|numeric)(?:_([0-9]+)(?:_([0-9]+))?)?\b/', $query, $matches, PREG_SET_ORDER );
		if ( false === $match_count || 0 === $match_count ) {
			return array();
		}

		$domain_definitions = array();
		foreach ( $matches as $match ) {
			$type      = $match[1];
			$precision = $match[2] ?? '';
			$scale     = $match[3] ?? '';

			if ( '' !== $precision ) {
				$base_type = 'numeric(' . (int) $precision . ( '' === $scale ? '' : ',' . (int) $scale ) . ')';
			} elseif ( in_array( $type, array( 'float', 'double', 'real' ), true ) ) {
				$base_type = 'double precision';
			} else {
				$base_type = 'numeric';
			}

			$domain_definitions[ $match[0] ] = $base_type;
		}

		return $domain_definitions;
	}

	/**
	 * Get the MySQL-compatible JSON_VALID() result for a runtime value.
	 *
	 * @param mixed $value Runtime value.
	 * @return int|null MySQL-compatible JSON_VALID() result.
	 */
	private static function get_mysql_json_valid_runtime_result( $value ): ?int {
		if ( null === $value ) {
			return null;
		}

		json_decode( (string) $value );
		return JSON_ERROR_NONE === json_last_error() ? 1 : 0;
	}

	/**
	 * Get a bounded MySQL fractional seconds precision from translated function arguments.
	 *
	 * @param string[] $argument_sql Translated PostgreSQL arguments.
	 * @return int|null Precision, or null when unsupported.
	 */
	private function get_mysql_temporal_function_fractional_seconds_precision( array $argument_sql ): ?int {
		if ( 0 === count( $argument_sql ) ) {
			return 0;
		}

		if ( 1 !== count( $argument_sql ) ) {
			return null;
		}

		$sql = trim( $argument_sql[0] );
		return 1 === preg_match( '/^[0-6]$/', $sql ) ? (int) $sql : null;
	}

	/**
	 * Get a bounded MySQL fractional seconds precision from a token.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return int|null Precision, or null when unsupported.
	 */
	private function get_mysql_fractional_seconds_precision_token_value( ?WP_MySQL_Token $token ): ?int {
		if ( null === $token || WP_MySQL_Lexer::INT_NUMBER !== $token->id ) {
			return null;
		}

		$value = $token->get_value();
		return 1 === preg_match( '/^[0-6]$/', $value ) ? (int) $value : null;
	}

	/**
	 * Format the emulated MySQL current timestamp value with optional fractional seconds.
	 *
	 * @param int $fsp Fractional seconds precision, 0 through 6.
	 * @return string PostgreSQL SQL.
	 */
	private function get_postgresql_mysql_current_timestamp_sql( int $fsp ): string {
		if ( 0 === $fsp ) {
			return "TO_CHAR(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')";
		}

		return sprintf(
			"LEFT(TO_CHAR(CURRENT_TIMESTAMP(%1\$d) AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'), %2\$d)",
			$fsp,
			20 + $fsp
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL DATE(expr), preserving zero-date text values.
	 *
	 * @param string $expression_sql Translated expression SQL.
	 * @return string PostgreSQL SQL.
	 */
	private function get_postgresql_mysql_date_sql( string $expression_sql ): string {
		$expression_text_sql = sprintf( 'CAST(%s AS text)', $expression_sql );

		return sprintf(
			"CASE WHEN %1\$s THEN NULL WHEN %2\$s THEN SUBSTRING(%3\$s FROM 1 FOR 10) ELSE TO_CHAR(%4\$s, 'YYYY-MM-DD') END",
			$this->get_postgresql_empty_temporal_condition_sql( $expression_text_sql ),
			$this->get_postgresql_zero_date_condition_sql( $expression_text_sql ),
			$expression_text_sql,
			$this->get_postgresql_zero_date_safe_timestamp_sql( $expression_sql )
		);
	}

	/**
	 * Get argument bounds for supported MySQL SUBSTRING/SUBSTR/MID forms.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First argument token.
	 * @param int              $end    Final argument token, exclusive.
	 * @return array<int, array{start: int, end: int}>|null Argument bounds, or null when unsupported.
	 */
	private function get_mysql_substring_function_arguments( array $tokens, int $start, int $end ): ?array {
		$arguments = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null !== $arguments && ( 2 === count( $arguments ) || 3 === count( $arguments ) ) ) {
			return $arguments;
		}

		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, $start, $end );
		if ( null === $from_position || $from_position <= $start || $from_position + 1 >= $end ) {
			return null;
		}

		$for_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FOR_SYMBOL, $from_position + 1, $end );
		if ( null === $for_position ) {
			return array(
				array(
					'start' => $start,
					'end'   => $from_position,
				),
				array(
					'start' => $from_position + 1,
					'end'   => $end,
				),
			);
		}

		if ( $for_position <= $from_position + 1 || $for_position + 1 >= $end ) {
			return null;
		}

		return array(
			array(
				'start' => $start,
				'end'   => $from_position,
			),
			array(
				'start' => $from_position + 1,
				'end'   => $for_position,
			),
			array(
				'start' => $for_position + 1,
				'end'   => $end,
			),
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL byte-oriented LENGTH(text).
	 *
	 * PostgreSQL-safe text envelopes carry the original MySQL byte length in
	 * their prefix. Use that length before falling back to UTF-8 byte counting.
	 *
	 * @param string $argument_sql Translated argument SQL.
	 * @return string PostgreSQL byte-length SQL.
	 */
	private function get_postgresql_mysql_text_byte_length_sql( string $argument_sql ): string {
		$text_sql      = sprintf( 'CAST(%s AS text)', $argument_sql );
		$prefix_chars  = preg_match_all( '/./us', self::MYSQL_TEXT_ENCODING_PREFIX );
		$prefix_length = false === $prefix_chars ? strlen( self::MYSQL_TEXT_ENCODING_PREFIX ) : $prefix_chars;
		$prefix_sql    = $this->connection->get_pdo()->quote( self::MYSQL_TEXT_ENCODING_PREFIX );
		$payload_sql   = sprintf( 'SUBSTR(%s, %d)', $text_sql, $prefix_length + 1 );
		$separator_sql = sprintf( "STRPOS(%s, ':')", $payload_sql );
		$length_sql    = sprintf( 'SUBSTR(%s, 1, %s - 1)', $payload_sql, $separator_sql );

		return sprintf(
			"CASE WHEN SUBSTR(%1\$s, 1, %2\$d) = %3\$s AND %4\$s > 1 AND TRANSLATE(%5\$s, '0123456789', '') = '' AND (%5\$s = '0' OR SUBSTR(%5\$s, 1, 1) <> '0') THEN CAST(%5\$s AS bigint) ELSE OCTET_LENGTH(CONVERT_TO(%1\$s, 'UTF8')) END",
			$text_sql,
			$prefix_length,
			$prefix_sql,
			$separator_sql,
			$length_sql
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL CONCAT_WS(separator, value, ...).
	 *
	 * MySQL skips NULL values after the separator, keeps empty strings, and
	 * returns NULL only when the separator itself is NULL.
	 *
	 * @param string[] $argument_sql Translated PostgreSQL arguments.
	 * @return string PostgreSQL SQL.
	 */
	private function get_postgresql_mysql_concat_ws_sql( array $argument_sql ): string {
		$separator_sql  = $argument_sql[0];
		$value_sql      = array_slice( $argument_sql, 1 );
		$fragments      = array();
		$seen_value_sql = array();

		foreach ( $value_sql as $index => $sql ) {
			if ( $index > 0 ) {
				$fragments[] = sprintf(
					'CASE WHEN (%1$s) AND %2$s IS NOT NULL THEN CAST(%3$s AS text) ELSE \'\' END',
					implode( ' OR ', $seen_value_sql ),
					$sql,
					$separator_sql
				);
			}

			$fragments[]      = sprintf( 'COALESCE(CAST(%s AS text), \'\')', $sql );
			$seen_value_sql[] = sprintf( '%s IS NOT NULL', $sql );
		}

		return sprintf(
			'CASE WHEN %1$s IS NULL THEN NULL ELSE (%2$s) END',
			$separator_sql,
			implode( ' || ', $fragments )
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL ELT(index, value, ...).
	 *
	 * MySQL coerces the index argument to an integer and returns the indexed
	 * string argument, or NULL when the index is NULL or out of range.
	 *
	 * @param string[] $argument_sql Translated PostgreSQL arguments.
	 * @return string PostgreSQL SQL.
	 */
	private function get_postgresql_mysql_elt_sql( array $argument_sql ): string {
		$index_sql = $this->get_postgresql_mysql_integer_cast_sql( $argument_sql[0] );
		$branches  = array(
			sprintf( 'WHEN %s IS NULL THEN NULL', $index_sql ),
		);

		for ( $i = 1; $i < count( $argument_sql ); $i++ ) {
			$branches[] = sprintf(
				'WHEN %1$s = %2$d THEN CAST(%3$s AS text)',
				$index_sql,
				$i,
				$argument_sql[ $i ]
			);
		}

		return 'CASE ' . implode( ' ', $branches ) . ' ELSE NULL END';
	}

	/**
	 * Get PostgreSQL SQL for MySQL FIND_IN_SET(str, strlist).
	 *
	 * MySQL returns NULL for NULL arguments, 0 when the needle contains a comma,
	 * and otherwise the one-based position in the comma-separated list.
	 *
	 * @param string $needle_sql PostgreSQL needle expression SQL.
	 * @param string $list_sql   PostgreSQL comma-separated list expression SQL.
	 * @return string PostgreSQL SQL.
	 */
	private function get_postgresql_mysql_find_in_set_sql( string $needle_sql, string $list_sql ): string {
		$needle_text_sql = sprintf( 'CAST(%s AS text)', $needle_sql );
		$list_text_sql   = sprintf( 'CAST(%s AS text)', $list_sql );

		return sprintf(
			"CASE WHEN %1\$s IS NULL OR %2\$s IS NULL THEN NULL WHEN STRPOS(%1\$s, ',') > 0 THEN 0 ELSE COALESCE(ARRAY_POSITION(STRING_TO_ARRAY(%2\$s, ','), %1\$s), 0) END",
			$needle_text_sql,
			$list_text_sql
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL MAKE_SET(bits, str1, str2, ...).
	 *
	 * PostgreSQL bigint bitwise operators are signed, so support the practical
	 * MySQL-compatible bit range that fits in a positive bigint mask.
	 *
	 * @param string[] $argument_sql Translated PostgreSQL arguments.
	 * @return string|null PostgreSQL SQL, or null when unsupported.
	 */
	private function get_postgresql_mysql_make_set_sql( array $argument_sql ): ?string {
		if ( count( $argument_sql ) > 64 ) {
			return null;
		}

		$mask_sql   = $this->get_postgresql_mysql_integer_cast_sql( $argument_sql[0] );
		$values_sql = array();

		for ( $i = 1; $i < count( $argument_sql ); $i++ ) {
			$bit_sql      = (string) ( 1 << ( $i - 1 ) );
			$values_sql[] = sprintf(
				'CASE WHEN (%1$s & %2$s) <> 0 THEN CAST(%3$s AS text) ELSE NULL END',
				$mask_sql,
				$bit_sql,
				$argument_sql[ $i ]
			);
		}

		return sprintf(
			'CASE WHEN %1$s IS NULL THEN NULL ELSE CONCAT_WS(\',\', %2$s) END',
			$mask_sql,
			implode( ', ', $values_sql )
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL LOG() forms.
	 *
	 * @param string[] $argument_sql Translated PostgreSQL arguments.
	 * @return string|null PostgreSQL SQL, or null when unsupported.
	 */
	private function get_postgresql_mysql_log_sql( array $argument_sql ): ?string {
		if ( 1 === count( $argument_sql ) ) {
			$value = sprintf( 'CAST(%s AS double precision)', $argument_sql[0] );

			return sprintf(
				'CASE WHEN %1$s IS NULL OR %1$s <= 0 THEN NULL ELSE LN(%1$s) END',
				$value
			);
		}

		if ( 2 === count( $argument_sql ) ) {
			$base  = sprintf( 'CAST(%s AS double precision)', $argument_sql[0] );
			$value = sprintf( 'CAST(%s AS double precision)', $argument_sql[1] );

			return sprintf(
				'CASE WHEN %1$s IS NULL OR %2$s IS NULL OR %1$s <= 1 OR %2$s <= 0 THEN NULL ELSE LN(%2$s) / LN(%1$s) END',
				$base,
				$value
			);
		}

		return null;
	}

	/**
	 * Get PostgreSQL SQL for MySQL SUBSTRING/SUBSTR/MID() forms.
	 *
	 * @param string[] $argument_sql Translated PostgreSQL arguments.
	 * @return string|null PostgreSQL SQL, or null when unsupported.
	 */
	private function get_postgresql_mysql_substring_sql( array $argument_sql ): ?string {
		if ( 2 !== count( $argument_sql ) && 3 !== count( $argument_sql ) ) {
			return null;
		}

		$value    = sprintf( 'CAST(%s AS text)', $argument_sql[0] );
		$position = sprintf( 'CAST(%s AS integer)', $argument_sql[1] );
		$start    = sprintf(
			'CASE WHEN %1$s > 0 THEN %1$s WHEN %1$s < 0 THEN CHAR_LENGTH(%2$s) + %1$s + 1 ELSE 0 END',
			$position,
			$value
		);

		if ( 2 === count( $argument_sql ) ) {
			return sprintf(
				'CASE WHEN %1$s IS NULL OR %2$s IS NULL THEN NULL WHEN %2$s = 0 OR (%3$s < 1) THEN \'\' ELSE SUBSTRING(%1$s FROM %3$s) END',
				$value,
				$position,
				$start
			);
		}

		$length = sprintf( 'CAST(%s AS integer)', $argument_sql[2] );

		return sprintf(
			'CASE WHEN %1$s IS NULL OR %2$s IS NULL OR %3$s IS NULL THEN NULL WHEN %2$s = 0 OR %3$s < 1 OR (%4$s < 1) THEN \'\' ELSE SUBSTRING(%1$s FROM %4$s FOR %3$s) END',
			$value,
			$position,
			$length,
			$start
		);
	}

	/**
	 * Decode a simple SQL string literal rendered from a MySQL string token.
	 *
	 * @param string $sql SQL fragment.
	 * @return string|null Literal value, or null when the fragment is not a string literal.
	 */
	private function get_mysql_sql_string_literal_value( string $sql ): ?string {
		if ( strlen( $sql ) < 2 || "'" !== $sql[0] || "'" !== substr( $sql, -1 ) ) {
			return null;
		}

		return str_replace( "''", "'", substr( $sql, 1, -1 ) );
	}

	/**
	 * Get PostgreSQL SQL for MySQL truthiness in IF(condition, truthy, falsy).
	 *
	 * @param string $expression_sql PostgreSQL expression SQL.
	 * @return string PostgreSQL boolean SQL.
	 */
	private function get_postgresql_mysql_truthy_expression_sql( string $expression_sql ): string {
		return sprintf( 'COALESCE(%s <> 0, false)', $this->get_postgresql_mysql_numeric_cast_sql( $expression_sql ) );
	}

	/**
	 * Check whether a MySQL expression range is visibly a boolean predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First expression token.
	 * @param int              $end    Final expression token, exclusive.
	 * @return bool Whether the range contains predicate syntax.
	 */
	private function is_mysql_boolean_condition_expression( array $tokens, int $start, int $end ): bool {
		$depth = 0;
		for ( $i = $start; $i < $end; $i++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $i ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $i ]->id ) {
				--$depth;
				continue;
			}

			if ( 0 !== $depth ) {
				continue;
			}

			if (
				in_array(
					$tokens[ $i ]->id,
					array(
						WP_MySQL_Lexer::BETWEEN_SYMBOL,
						WP_MySQL_Lexer::EQUAL_OPERATOR,
						WP_MySQL_Lexer::GREATER_OR_EQUAL_OPERATOR,
						WP_MySQL_Lexer::GREATER_THAN_OPERATOR,
						WP_MySQL_Lexer::IN_SYMBOL,
						WP_MySQL_Lexer::IS_SYMBOL,
						WP_MySQL_Lexer::LESS_OR_EQUAL_OPERATOR,
						WP_MySQL_Lexer::LESS_THAN_OPERATOR,
						WP_MySQL_Lexer::LIKE_SYMBOL,
						WP_MySQL_Lexer::LOGICAL_AND_OPERATOR,
						WP_MySQL_Lexer::LOGICAL_OR_OPERATOR,
						WP_MySQL_Lexer::NOT_EQUAL_OPERATOR,
						WP_MySQL_Lexer::NULL_SAFE_EQUAL_OPERATOR,
						WP_MySQL_Lexer::REGEXP_SYMBOL,
					),
					true
				)
			) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Get PostgreSQL SQL for MySQL LOCATE(substr, str, pos).
	 *
	 * @param string $needle_sql   Needle SQL.
	 * @param string $haystack_sql Haystack SQL.
	 * @param string $position_sql One-based start position SQL.
	 * @return string PostgreSQL SQL.
	 */
	private function get_postgresql_mysql_locate_with_position_sql( string $needle_sql, string $haystack_sql, string $position_sql ): string {
		$needle   = sprintf( 'CAST(%s AS text)', $needle_sql );
		$haystack = sprintf( 'CAST(%s AS text)', $haystack_sql );
		$position = sprintf( 'CAST(%s AS integer)', $position_sql );
		$offset   = sprintf( 'STRPOS(SUBSTRING(%s FROM %s), %s)', $haystack, $position, $needle );

		return sprintf(
			'CASE WHEN %1$s IS NULL OR %2$s IS NULL OR %3$s IS NULL THEN NULL WHEN %3$s < 1 THEN 0 WHEN %4$s = 0 THEN 0 ELSE %4$s + %3$s - 1 END',
			$needle,
			$haystack,
			$position,
			$offset
		);
	}

	/**
	 * Get token bounds for a MySQL identifier function call.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int             $position      Function token position.
	 * @param int             $end           Final token position, exclusive.
	 * @param string          $function_name Lowercase function name to match.
	 * @return array{arguments_start: int, arguments_end: int, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_function_call_bounds( array $tokens, int $position, int $end, string $function_name ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::IDENTIFIER !== $tokens[ $position ]->id
			|| strtolower( $tokens[ $position ]->get_value() ) !== $function_name
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		return array(
			'arguments_start' => $position + 2,
			'arguments_end'   => $after_close - 1,
			'close'           => $after_close - 1,
		);
	}

	/**
	 * Split a bounded token range into top-level comma-separated arguments.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First argument token position.
	 * @param int             $end    Final argument token position, exclusive.
	 * @return array<int, array{start: int, end: int}>|null Argument bounds, or null when malformed.
	 */
	private function split_top_level_mysql_arguments( array $tokens, int $start, int $end ): ?array {
		if ( $start === $end ) {
			return array();
		}

		$arguments      = array();
		$argument_start = $start;
		$depth          = 0;

		for ( $i = $start; $i < $end; $i++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $i ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $i ]->id ) {
				--$depth;
				if ( $depth < 0 ) {
					return null;
				}
				continue;
			}

			if ( 0 === $depth && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $i ]->id ) {
				if ( $argument_start === $i ) {
					return null;
				}

				$arguments[]    = array(
					'start' => $argument_start,
					'end'   => $i,
				);
				$argument_start = $i + 1;
			}
		}

		if ( 0 !== $depth || $argument_start === $end ) {
			return null;
		}

		$arguments[] = array(
			'start' => $argument_start,
			'end'   => $end,
		);

		return $arguments;
	}

	/**
	 * Translate MySQL DATE_ADD(expr, INTERVAL value unit) and date arithmetic aliases.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_date_arithmetic_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_date_arithmetic_function_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		return $this->get_postgresql_mysql_date_arithmetic_translation( $tokens, $bounds, $tokens[ $position ]->id );
	}

	/**
	 * Translate MySQL expr +/- INTERVAL value unit date arithmetic.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position First expression token.
	 * @param int              $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_infix_interval_expression_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_infix_interval_expression_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		return $this->get_postgresql_mysql_date_arithmetic_translation( $tokens, $bounds, $tokens[ $position ]->id );
	}

	/**
	 * Render PostgreSQL SQL for parsed MySQL date arithmetic bounds.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param array            $bounds   Date arithmetic bounds.
	 * @param int              $token_id Replacement token ID.
	 * @return array{sql: string, token_id: int, position: int} Translation data.
	 */
	private function get_postgresql_mysql_date_arithmetic_translation( array $tokens, array $bounds, int $token_id ): array {
		$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$bounds['expression_start'],
			$bounds['expression_end']
		);
		$value_sql      = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$bounds['interval_value_start'],
			$bounds['interval_value_end']
		);
		$interval_sql   = $bounds['interval_sql'] ?? $this->get_postgresql_mysql_interval_sql( $value_sql, $bounds['interval_unit'] );

		return $this->get_postgresql_mysql_expression_translation(
			sprintf(
				'(%1$s %2$s %3$s)',
				$this->get_postgresql_zero_date_safe_timestamp_sql( $expression_sql ),
				$bounds['operator'],
				$interval_sql
			),
			$token_id,
			$bounds['close']
		);
	}

	/**
	 * Get token bounds for a supported MySQL infix interval expression.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position First expression token.
	 * @param int              $end      Final token position, exclusive.
	 * @return array{operator: string, expression_start: int, expression_end: int, interval_value_start: int, interval_value_end: int, interval_unit: string, interval_sql?: string, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_infix_interval_expression_bounds( array $tokens, int $position, int $end ): ?array {
		if (
			isset( $tokens[ $position ] )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
		) {
			$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
			if ( null === $after_close ) {
				return null;
			}

			if ( $after_close === $end ) {
				$inner = $this->get_mysql_infix_interval_expression_bounds( $tokens, $position + 1, $after_close - 1 );
				if ( null === $inner || $inner['close'] !== $after_close - 2 ) {
					return null;
				}

				$inner['close'] = $after_close - 1;
				return $inner;
			}
		}

		$expression = $this->get_mysql_infix_interval_left_expression_bounds( $tokens, $position, $end );
		if ( null === $expression ) {
			return null;
		}

		$operator_position = $expression['end'];
		if (
			! isset( $tokens[ $operator_position ] )
			|| ! in_array( $tokens[ $operator_position ]->id, array( WP_MySQL_Lexer::PLUS_OPERATOR, WP_MySQL_Lexer::MINUS_OPERATOR ), true )
		) {
			return null;
		}

		$interval = $this->get_mysql_interval_argument_bounds( $tokens, $operator_position + 1, $end );
		if ( null === $interval ) {
			return null;
		}

		$bounds = array(
			'operator'             => WP_MySQL_Lexer::MINUS_OPERATOR === $tokens[ $operator_position ]->id ? '-' : '+',
			'expression_start'     => $expression['start'],
			'expression_end'       => $expression['end'],
			'interval_value_start' => $interval['value_start'],
			'interval_value_end'   => $interval['value_end'],
			'interval_unit'        => $interval['unit'],
			'close'                => $end - 1,
		);

		if ( isset( $interval['sql'] ) ) {
			$bounds['interval_sql'] = $interval['sql'];
		}

		return $bounds;
	}

	/**
	 * Get the left expression bounds for a supported MySQL infix interval expression.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position First expression token.
	 * @param int              $end      Final token position, exclusive.
	 * @return array{start: int, end: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_infix_interval_left_expression_bounds( array $tokens, int $position, int $end ): ?array {
		if ( $position >= $end || ! isset( $tokens[ $position ] ) ) {
			return null;
		}

		if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
			if ( null === $after_close ) {
				return null;
			}

			$inner = $this->get_mysql_infix_interval_left_expression_bounds( $tokens, $position + 1, $after_close - 1 );
			if ( null !== $inner && $inner['start'] === $position + 1 && $inner['end'] === $after_close - 1 ) {
				return array(
					'start' => $position,
					'end'   => $after_close,
				);
			}
		}

		if ( WP_MySQL_Lexer::CASE_SYMBOL === $tokens[ $position ]->id ) {
			$case_end = $this->get_mysql_case_expression_end( $tokens, $position, $end );
			if ( null !== $case_end ) {
				return array(
					'start' => $position,
					'end'   => $case_end,
				);
			}
		}

		$common_function = $this->get_mysql_common_function_bounds( $tokens, $position, $end );
		if ( null !== $common_function ) {
			return array(
				'start' => $position,
				'end'   => $common_function['close'] + 1,
			);
		}

		if ( null !== $this->translate_mysql_nonparenthesized_timestamp_function_to_postgresql( $tokens, $position, $end ) ) {
			return array(
				'start' => $position,
				'end'   => $position + 1,
			);
		}

		return null;
	}

	/**
	 * Get the end position for a complete CASE expression.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position CASE token position.
	 * @param int              $end      Final token position, exclusive.
	 * @return int|null End position, exclusive, or null when unsupported.
	 */
	private function get_mysql_case_expression_end( array $tokens, int $position, int $end ): ?int {
		if (
			$position >= $end
			|| ! isset( $tokens[ $position ] )
			|| WP_MySQL_Lexer::CASE_SYMBOL !== $tokens[ $position ]->id
		) {
			return null;
		}

		$case_depth  = 0;
		$paren_depth = 0;
		for ( $i = $position + 1; $i < $end; $i++ ) {
			$token_id = $tokens[ $i ]->id;

			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $token_id ) {
				++$paren_depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $token_id ) {
				--$paren_depth;
				if ( $paren_depth < 0 ) {
					return null;
				}
				continue;
			}

			if ( 0 !== $paren_depth ) {
				continue;
			}

			if ( WP_MySQL_Lexer::CASE_SYMBOL === $token_id ) {
				++$case_depth;
				continue;
			}

			if ( WP_MySQL_Lexer::END_SYMBOL !== $token_id ) {
				continue;
			}

			if ( $case_depth > 0 ) {
				--$case_depth;
				continue;
			}

			return null === $this->get_mysql_case_expression_result_ranges( $tokens, $position, $i + 1 )
				? null
				: $i + 1;
		}

		return null;
	}

	/**
	 * Check whether a range contains an unsupported MySQL date arithmetic call.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return bool Whether an unsupported date arithmetic call is present.
	 */
	private function contains_unsupported_mysql_date_arithmetic_function( array $tokens, int $start, int $end ): bool {
		for ( $i = $start; $i < $end; $i++ ) {
			if (
				! isset( $tokens[ $i ], $tokens[ $i + 1 ] )
				|| ! in_array(
					$tokens[ $i ]->id,
					array(
						WP_MySQL_Lexer::ADDDATE_SYMBOL,
						WP_MySQL_Lexer::DATE_ADD_SYMBOL,
						WP_MySQL_Lexer::DATE_SUB_SYMBOL,
						WP_MySQL_Lexer::SUBDATE_SYMBOL,
					),
					true
				)
				|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $i + 1 ]->id
			) {
				continue;
			}

			$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $i + 1, $end );
			if ( null === $after_close || null === $this->get_mysql_date_arithmetic_function_bounds( $tokens, $i, $end ) ) {
				return true;
			}
		}

		return false;
	}

	private function contains_unsupported_mysql_date_arithmetic_function_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) ) {
			return false;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		$end           = null === $statement_end ? count( $tokens ) : $statement_end;

		return $this->contains_unsupported_mysql_date_arithmetic_function( $tokens, 0, $end )
			|| $this->contains_unsupported_mysql_translated_common_function( $tokens, 0, $end, 'timestampadd', 'translate_mysql_timestampadd_function_to_postgresql' )
			|| $this->contains_unsupported_mysql_translated_common_function( $tokens, 0, $end, 'timestampdiff', 'translate_mysql_timestampdiff_function_to_postgresql' );
	}

	/**
	 * Check whether a range contains an unsupported translated MySQL common function call.
	 *
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int              $start           First token position.
	 * @param int              $end             Final token position, exclusive.
	 * @param string           $function_name   Lowercase MySQL function name.
	 * @param string           $translator_name Private translator method name.
	 * @return bool Whether an unsupported call is present.
	 */
	private function contains_unsupported_mysql_translated_common_function( array $tokens, int $start, int $end, string $function_name, string $translator_name ): bool {
		for ( $i = $start; $i < $end; $i++ ) {
			if (
				$function_name !== $this->get_mysql_common_function_name( $tokens[ $i ] ?? null )
				|| ! isset( $tokens[ $i + 1 ] )
				|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $i + 1 ]->id
			) {
				continue;
			}

			$bounds = $this->get_mysql_common_function_bounds( $tokens, $i, $end );
			if ( null === $bounds ) {
				return true;
			}

			$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
			if ( null === $arguments || null === $this->$translator_name( $tokens, $arguments, $bounds['close'] ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Get token bounds for a supported MySQL date arithmetic expression.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{operator: string, expression_start: int, expression_end: int, interval_value_start: int, interval_value_end: int, interval_unit: string, interval_sql?: string, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_date_arithmetic_function_bounds( array $tokens, int $position, int $end ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| ! in_array(
				$tokens[ $position ]->id,
				array(
					WP_MySQL_Lexer::ADDDATE_SYMBOL,
					WP_MySQL_Lexer::DATE_ADD_SYMBOL,
					WP_MySQL_Lexer::DATE_SUB_SYMBOL,
					WP_MySQL_Lexer::SUBDATE_SYMBOL,
				),
				true
			)
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $position + 2, $after_close - 1 );
		if ( null === $arguments || 2 !== count( $arguments ) ) {
			return null;
		}

		$interval = $this->get_mysql_interval_argument_bounds( $tokens, $arguments[1]['start'], $arguments[1]['end'] );
		if (
			null === $interval
			&& in_array( $tokens[ $position ]->id, array( WP_MySQL_Lexer::ADDDATE_SYMBOL, WP_MySQL_Lexer::SUBDATE_SYMBOL ), true )
		) {
			$interval = array(
				'value_start' => $arguments[1]['start'],
				'value_end'   => $arguments[1]['end'],
				'unit'        => 'day',
			);
		}
		if ( null === $interval ) {
			return null;
		}

		$bounds = array(
			'operator'             => in_array( $tokens[ $position ]->id, array( WP_MySQL_Lexer::DATE_SUB_SYMBOL, WP_MySQL_Lexer::SUBDATE_SYMBOL ), true ) ? '-' : '+',
			'expression_start'     => $arguments[0]['start'],
			'expression_end'       => $arguments[0]['end'],
			'interval_value_start' => $interval['value_start'],
			'interval_value_end'   => $interval['value_end'],
			'interval_unit'        => $interval['unit'],
			'close'                => $after_close - 1,
		);

		if ( isset( $interval['sql'] ) ) {
			$bounds['interval_sql'] = $interval['sql'];
		}

		return $bounds;
	}

	/**
	 * Get token bounds for a supported MySQL INTERVAL value unit argument.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First interval token position.
	 * @param int             $end    Final interval token position, exclusive.
	 * @return array{value_start: int, value_end: int, unit: string, sql?: string}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_interval_argument_bounds( array $tokens, int $start, int $end ): ?array {
		if (
			$start + 3 > $end
			|| ! isset( $tokens[ $start ], $tokens[ $end - 1 ] )
			|| WP_MySQL_Lexer::INTERVAL_SYMBOL !== $tokens[ $start ]->id
		) {
			return null;
		}

		$unit_token = $tokens[ $end - 1 ];
		$unit       = $this->get_postgresql_simple_interval_unit( $unit_token );
		if ( null !== $unit ) {
			return array(
				'value_start' => $start + 1,
				'value_end'   => $end - 1,
				'unit'        => $unit,
			);
		}

		$part_units = $this->get_mysql_composite_interval_part_units( $unit_token );
		if ( null === $part_units ) {
			return null;
		}

		$sql = $this->get_postgresql_mysql_composite_interval_literal_sql( $tokens, $start + 1, $end - 1, $part_units );
		if ( null === $sql ) {
			return null;
		}

		return array(
			'value_start' => $start + 1,
			'value_end'   => $end - 1,
			'unit'        => 'composite',
			'sql'         => $sql,
		);
	}

	/**
	 * Get a PostgreSQL interval unit for supported simple MySQL interval units.
	 *
	 * @param WP_MySQL_Token $token MySQL interval unit token.
	 * @return string|null PostgreSQL interval unit, or null when unsupported.
	 */
	private function get_postgresql_simple_interval_unit( WP_MySQL_Token $token ): ?string {
		$units = array(
			WP_MySQL_Lexer::MICROSECOND_SYMBOL => 'microsecond',
			WP_MySQL_Lexer::SECOND_SYMBOL      => 'second',
			WP_MySQL_Lexer::MINUTE_SYMBOL      => 'minute',
			WP_MySQL_Lexer::HOUR_SYMBOL        => 'hour',
			WP_MySQL_Lexer::DAY_SYMBOL         => 'day',
			WP_MySQL_Lexer::WEEK_SYMBOL        => 'week',
			WP_MySQL_Lexer::MONTH_SYMBOL       => 'month',
			WP_MySQL_Lexer::QUARTER_SYMBOL     => '3 months',
			WP_MySQL_Lexer::YEAR_SYMBOL        => 'year',
		);

		return $units[ $token->id ] ?? null;
	}

	/**
	 * Get component units for supported composite MySQL interval units.
	 *
	 * @param WP_MySQL_Token $token MySQL interval unit token.
	 * @return string[]|null Ordered PostgreSQL component units, or null when unsupported.
	 */
	private function get_mysql_composite_interval_part_units( WP_MySQL_Token $token ): ?array {
		$units = array(
			WP_MySQL_Lexer::SECOND_MICROSECOND_SYMBOL => array( 'second', 'microsecond' ),
			WP_MySQL_Lexer::MINUTE_SECOND_SYMBOL      => array( 'minute', 'second' ),
			WP_MySQL_Lexer::MINUTE_MICROSECOND_SYMBOL => array( 'minute', 'second', 'microsecond' ),
			WP_MySQL_Lexer::HOUR_MINUTE_SYMBOL        => array( 'hour', 'minute' ),
			WP_MySQL_Lexer::HOUR_SECOND_SYMBOL        => array( 'hour', 'minute', 'second' ),
			WP_MySQL_Lexer::HOUR_MICROSECOND_SYMBOL   => array( 'hour', 'minute', 'second', 'microsecond' ),
			WP_MySQL_Lexer::DAY_HOUR_SYMBOL           => array( 'day', 'hour' ),
			WP_MySQL_Lexer::DAY_MINUTE_SYMBOL         => array( 'day', 'hour', 'minute' ),
			WP_MySQL_Lexer::DAY_SECOND_SYMBOL         => array( 'day', 'hour', 'minute', 'second' ),
			WP_MySQL_Lexer::DAY_MICROSECOND_SYMBOL    => array( 'day', 'hour', 'minute', 'second', 'microsecond' ),
			WP_MySQL_Lexer::YEAR_MONTH_SYMBOL         => array( 'year', 'month' ),
		);

		return $units[ $token->id ] ?? null;
	}

	/**
	 * Get PostgreSQL SQL for a safe literal MySQL composite interval.
	 *
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $start      First interval value token position.
	 * @param int              $end        Final interval value token position, exclusive.
	 * @param string[]         $part_units Ordered PostgreSQL component units.
	 * @return string|null PostgreSQL interval SQL, or null when unsupported.
	 */
	private function get_postgresql_mysql_composite_interval_literal_sql( array $tokens, int $start, int $end, array $part_units ): ?string {
		if ( $start >= $end || ! isset( $tokens[ $start ] ) ) {
			return null;
		}

		$value = $this->get_mysql_composite_interval_literal_value( $tokens, $start, $end );
		if ( null === $value ) {
			return null;
		}

		if ( $value['is_null'] ) {
			return 'CAST(NULL AS interval)';
		}

		$components = $this->parse_mysql_composite_interval_literal_components( $value['value'], $part_units );
		if ( null === $components ) {
			return null;
		}

		return $this->get_postgresql_mysql_composite_interval_components_sql( $components );
	}

	/**
	 * Get a simple literal value for a MySQL composite interval.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First interval value token position.
	 * @param int              $end    Final interval value token position, exclusive.
	 * @return array{value: string, is_null: bool}|null Literal interval value, or null when unsupported.
	 */
	private function get_mysql_composite_interval_literal_value( array $tokens, int $start, int $end ): ?array {
		if ( $start + 1 === $end ) {
			if ( WP_MySQL_Lexer::NULL_SYMBOL === $tokens[ $start ]->id ) {
				return array(
					'value'   => '',
					'is_null' => true,
				);
			}

			if ( $this->is_mysql_quoted_text_token( $tokens[ $start ] ) ) {
				return array(
					'value'   => $tokens[ $start ]->get_value(),
					'is_null' => false,
				);
			}

			if ( $this->is_mysql_unsigned_numeric_token( $tokens[ $start ] ) ) {
				return array(
					'value'   => $tokens[ $start ]->get_value(),
					'is_null' => false,
				);
			}
		}

		if (
			$start + 2 === $end
			&& isset( $tokens[ $start + 1 ] )
			&& (
				WP_MySQL_Lexer::MINUS_OPERATOR === $tokens[ $start ]->id
				|| WP_MySQL_Lexer::PLUS_OPERATOR === $tokens[ $start ]->id
			)
			&& $this->is_mysql_unsigned_numeric_token( $tokens[ $start + 1 ] )
		) {
			return array(
				'value'   => $tokens[ $start ]->get_bytes() . $tokens[ $start + 1 ]->get_value(),
				'is_null' => false,
			);
		}

		return null;
	}

	/**
	 * Check whether a token is a simple unsigned numeric literal.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is a simple numeric literal.
	 */
	private function is_mysql_unsigned_numeric_token( WP_MySQL_Token $token ): bool {
		if ( $this->is_mysql_unsigned_integer_token( $token ) ) {
			return true;
		}

		if (
			in_array(
				$token->id,
				array(
					WP_MySQL_Lexer::DECIMAL_NUMBER,
				),
				true
			)
		) {
			return 1 === preg_match( '/^[0-9]+[.][0-9]+$/', $token->get_value() );
		}

		return false;
	}

	/**
	 * Parse a full or right-aligned MySQL composite interval literal.
	 *
	 * @param string   $value      MySQL interval literal value.
	 * @param string[] $part_units Ordered PostgreSQL component units.
	 * @return array<int,array{value: string, unit: string}>|null Parsed components, or null when unsupported.
	 */
	private function parse_mysql_composite_interval_literal_components( string $value, array $part_units ): ?array {
		$part_count = count( $part_units );
		$value      = trim( $value );
		if ( '' === $value ) {
			return null;
		}

		$sign = '';
		if ( '-' === $value[0] || '+' === $value[0] ) {
			$sign  = '-' === $value[0] ? '-' : '';
			$value = trim( substr( $value, 1 ) );
		}

		if ( '' === $value || 1 !== preg_match( '/^[0-9]+(?:[^0-9]+[0-9]+)*$/', $value ) ) {
			return null;
		}

		$parts = preg_split( '/[^0-9]+/', $value );
		if ( false === $parts || empty( $parts ) || count( $parts ) > $part_count ) {
			return null;
		}

		$units      = array_slice( $part_units, $part_count - count( $parts ) );
		$components = array();
		foreach ( $parts as $index => $part ) {
			$unit            = $units[ $index ];
			$component_value = 'microsecond' === $unit ? str_pad( $part, 6, '0' ) : $part;

			$components[] = array(
				'value' => $sign . $component_value,
				'unit'  => $unit,
			);
		}

		return $components;
	}

	/**
	 * Get PostgreSQL SQL for parsed MySQL composite interval components.
	 *
	 * @param array<int,array{value: string, unit: string}> $components Parsed interval components.
	 * @return string PostgreSQL interval SQL.
	 */
	private function get_postgresql_mysql_composite_interval_components_sql( array $components ): string {
		$parts = array();
		foreach ( $components as $component ) {
			$parts[] = sprintf(
				'(CAST(%1$s AS double precision) * INTERVAL %2$s)',
				$this->connection->quote( $component['value'] ),
				$this->connection->quote( '1 ' . $component['unit'] )
			);
		}

		return '(' . implode( ' + ', $parts ) . ')';
	}

	/**
	 * Get PostgreSQL SQL for a MySQL-compatible interval expression.
	 *
	 * @param string $value_sql PostgreSQL interval value SQL.
	 * @param string $unit      Normalized interval unit.
	 * @return string PostgreSQL interval SQL.
	 */
	private function get_postgresql_mysql_interval_sql( string $value_sql, string $unit ): string {
		$interval_unit  = '3 months' === $unit ? $unit : '1 ' . $unit;
		$value_cast_sql = 'second' === $unit
			? $this->get_postgresql_mysql_numeric_cast_sql( $value_sql )
			: $this->get_postgresql_mysql_integer_cast_sql( $value_sql );

		return sprintf(
			'(%1$s * INTERVAL %2$s)',
			sprintf( 'CAST(%s AS double precision)', $value_cast_sql ),
			$this->connection->quote( $interval_unit )
		);
	}

	/**
	 * Translate MySQL TIMESTAMPADD(unit, interval, datetime_expr) to PostgreSQL.
	 *
	 * @param WP_MySQL_Token[]                            $tokens    MySQL lexer token stream.
	 * @param array<int,array{start:int,end:int}>         $arguments Function argument bounds.
	 * @param int                                         $close     Closing parenthesis token position.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_timestampadd_function_to_postgresql( array $tokens, array $arguments, int $close ): ?array {
		if ( 3 !== count( $arguments ) ) {
			return null;
		}

		$interval = $this->get_mysql_timestampadd_interval(
			$tokens,
			$arguments[0]['start'],
			$arguments[0]['end'],
			$arguments[1]['start'],
			$arguments[1]['end']
		);
		if ( null === $interval ) {
			return null;
		}

		$interval_sql = $interval['sql'] ?? null;
		if ( null === $interval_sql ) {
			$value_sql    = $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$arguments[1]['start'],
				$arguments[1]['end']
			);
			$interval_sql = $this->get_postgresql_mysql_interval_sql( $value_sql, $interval['unit'] );
		}

		$datetime_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$arguments[2]['start'],
			$arguments[2]['end']
		);

		return $this->get_postgresql_mysql_expression_translation(
			sprintf(
				'(%1$s + %2$s)',
				$this->get_postgresql_zero_date_safe_timestamp_sql( $datetime_sql ),
				$interval_sql
			),
			WP_MySQL_Lexer::IDENTIFIER,
			$close
		);
	}

	/**
	 * Translate MySQL TIMESTAMPDIFF(unit, datetime_expr1, datetime_expr2) to PostgreSQL.
	 *
	 * @param WP_MySQL_Token[]                    $tokens    MySQL lexer token stream.
	 * @param array<int,array{start:int,end:int}> $arguments Function argument bounds.
	 * @param int                                 $close     Closing parenthesis token position.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_timestampdiff_function_to_postgresql( array $tokens, array $arguments, int $close ): ?array {
		if ( 3 !== count( $arguments ) ) {
			return null;
		}

		$unit = $this->get_mysql_timestampdiff_unit(
			$tokens,
			$arguments[0]['start'],
			$arguments[0]['end']
		);
		if ( null === $unit ) {
			return null;
		}

		$start_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$arguments[1]['start'],
			$arguments[1]['end']
		);
		$end_sql   = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$arguments[2]['start'],
			$arguments[2]['end']
		);

		return $this->get_postgresql_mysql_expression_translation(
			$this->get_postgresql_mysql_timestampdiff_sql( $unit, $start_sql, $end_sql ),
			WP_MySQL_Lexer::IDENTIFIER,
			$close
		);
	}

	/**
	 * Get supported TIMESTAMPDIFF unit data.
	 *
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $unit_start First unit token.
	 * @param int              $unit_end   Final unit token, exclusive.
	 * @return string|null Normalized TIMESTAMPDIFF unit, or null when unsupported.
	 */
	private function get_mysql_timestampdiff_unit( array $tokens, int $unit_start, int $unit_end ): ?string {
		if ( $unit_start + 1 !== $unit_end || ! isset( $tokens[ $unit_start ] ) ) {
			return null;
		}

		$units = array(
			WP_MySQL_Lexer::MICROSECOND_SYMBOL => 'microsecond',
			WP_MySQL_Lexer::SECOND_SYMBOL      => 'second',
			WP_MySQL_Lexer::MINUTE_SYMBOL      => 'minute',
			WP_MySQL_Lexer::HOUR_SYMBOL        => 'hour',
			WP_MySQL_Lexer::DAY_SYMBOL         => 'day',
			WP_MySQL_Lexer::WEEK_SYMBOL        => 'week',
			WP_MySQL_Lexer::MONTH_SYMBOL       => 'month',
			WP_MySQL_Lexer::QUARTER_SYMBOL     => 'quarter',
			WP_MySQL_Lexer::YEAR_SYMBOL        => 'year',
		);

		return $units[ $tokens[ $unit_start ]->id ] ?? null;
	}

	/**
	 * Get PostgreSQL SQL for a MySQL TIMESTAMPDIFF() expression.
	 *
	 * @param string $unit      Normalized TIMESTAMPDIFF unit.
	 * @param string $start_sql Translated start datetime SQL.
	 * @param string $end_sql   Translated end datetime SQL.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_timestampdiff_sql( string $unit, string $start_sql, string $end_sql ): string {
		$start_timestamp_sql = $this->get_postgresql_zero_date_safe_timestamp_sql( $start_sql );
		$end_timestamp_sql   = $this->get_postgresql_zero_date_safe_timestamp_sql( $end_sql );

		if ( 'microsecond' === $unit ) {
			return sprintf(
				'CAST(TRUNC(EXTRACT(EPOCH FROM (%2$s - %1$s)) * 1000000) AS bigint)',
				$start_timestamp_sql,
				$end_timestamp_sql
			);
		}

		$seconds_per_unit = array_combine( explode( ' ', 'second minute hour day week' ), array( 1, 60, 3600, 86400, 604800 ) );
		if ( isset( $seconds_per_unit[ $unit ] ) ) {
			return sprintf(
				'CAST(TRUNC(EXTRACT(EPOCH FROM (%2$s - %1$s)) / %3$d) AS bigint)',
				$start_timestamp_sql,
				$end_timestamp_sql,
				$seconds_per_unit[ $unit ]
			);
		}

		$month_sql = $this->get_postgresql_mysql_timestampdiff_month_sql( $start_timestamp_sql, $end_timestamp_sql );
		if ( 'month' === $unit ) {
			return $month_sql;
		}

		if ( 'quarter' === $unit ) {
			return sprintf( 'CAST(TRUNC((%s)::numeric / 3) AS bigint)', $month_sql );
		}

		return sprintf( 'CAST(TRUNC((%s)::numeric / 12) AS bigint)', $month_sql );
	}

	/**
	 * Get PostgreSQL SQL for MySQL TIMESTAMPDIFF(MONTH, ...).
	 *
	 * @param string $start_timestamp_sql Zero-date-safe start timestamp SQL.
	 * @param string $end_timestamp_sql   Zero-date-safe end timestamp SQL.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_timestampdiff_month_sql( string $start_timestamp_sql, string $end_timestamp_sql ): string {
		$month_delta_sql     = sprintf(
			'((CAST(EXTRACT(YEAR FROM %2$s) AS integer) * 12 + CAST(EXTRACT(MONTH FROM %2$s) AS integer)) - (CAST(EXTRACT(YEAR FROM %1$s) AS integer) * 12 + CAST(EXTRACT(MONTH FROM %1$s) AS integer)))',
			$start_timestamp_sql,
			$end_timestamp_sql
		);
		$start_remainder_sql = sprintf( "TO_CHAR(%s, 'DD HH24:MI:SS.US')", $start_timestamp_sql );
		$end_remainder_sql   = sprintf( "TO_CHAR(%s, 'DD HH24:MI:SS.US')", $end_timestamp_sql );

		return sprintf(
			'CAST(CASE WHEN %1$s IS NULL OR %2$s IS NULL THEN NULL WHEN %2$s >= %1$s THEN (%3$s - CASE WHEN %4$s < %5$s THEN 1 ELSE 0 END) ELSE (%3$s + CASE WHEN %4$s > %5$s THEN 1 ELSE 0 END) END AS bigint)',
			$start_timestamp_sql,
			$end_timestamp_sql,
			$month_delta_sql,
			$end_remainder_sql,
			$start_remainder_sql
		);
	}

	/**
	 * Get supported TIMESTAMPADD interval data from the unit and value arguments.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param int              $unit_start  First unit token.
	 * @param int              $unit_end    Final unit token, exclusive.
	 * @param int              $value_start First interval value token.
	 * @param int              $value_end   Final interval value token, exclusive.
	 * @return array{unit: string, sql?: string}|null Interval data, or null when unsupported.
	 */
	private function get_mysql_timestampadd_interval( array $tokens, int $unit_start, int $unit_end, int $value_start, int $value_end ): ?array {
		if ( $unit_start + 1 !== $unit_end || ! isset( $tokens[ $unit_start ] ) ) {
			return null;
		}

		$unit = $this->get_postgresql_simple_interval_unit( $tokens[ $unit_start ] );
		if ( null !== $unit ) {
			return array(
				'unit' => $unit,
			);
		}

		$part_units = $this->get_mysql_composite_interval_part_units( $tokens[ $unit_start ] );
		if ( null === $part_units ) {
			return null;
		}

		$sql = $this->get_postgresql_mysql_composite_interval_literal_sql( $tokens, $value_start, $value_end, $part_units );
		if ( null === $sql ) {
			return null;
		}

		return array(
			'unit' => 'composite',
			'sql'  => $sql,
		);
	}

	/**
	 * Translate supported MySQL WEEK() calls to PostgreSQL.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_week_function_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_week_function_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$bounds['expression_start'],
			$bounds['expression_end']
		);

		return $this->get_postgresql_mysql_expression_translation(
			$this->get_postgresql_mysql_week_sql( $expression_sql, $bounds['mode'] ),
			WP_MySQL_Lexer::CASE_SYMBOL,
			$bounds['close']
		);
	}

	/**
	 * Get token bounds for supported MySQL WEEK() calls.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{expression_start: int, expression_end: int, mode: int, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_week_function_bounds( array $tokens, int $position, int $end ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$is_weekofyear = false;
		if ( WP_MySQL_Lexer::WEEK_SYMBOL !== $tokens[ $position ]->id ) {
			$function_name = $this->get_mysql_identifier_token_value( $tokens[ $position ] );
			if ( null === $function_name || 0 !== strcasecmp( $function_name, 'weekofyear' ) ) {
				return null;
			}

			$is_weekofyear = true;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $position + 2, $after_close - 1 );
		if ( null === $arguments || ! in_array( count( $arguments ), array( 1, 2 ), true ) ) {
			return null;
		}

		if ( $is_weekofyear && 1 !== count( $arguments ) ) {
			return null;
		}

		$mode = $is_weekofyear ? 3 : 0;
		if ( 2 === count( $arguments ) ) {
			$mode = $this->get_mysql_supported_week_mode_argument( $tokens, $arguments[1]['start'], $arguments[1]['end'] );
			if ( null === $mode ) {
				return null;
			}
		}

		return array(
			'expression_start' => $arguments[0]['start'],
			'expression_end'   => $arguments[0]['end'],
			'mode'             => $mode,
			'close'            => $after_close - 1,
		);
	}

	/**
	 * Check whether a range contains an unsupported MySQL WEEK() call.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return bool Whether an unsupported WEEK() call is present.
	 */
	private function contains_unsupported_mysql_week_function( array $tokens, int $start, int $end ): bool {
		for ( $i = $start; $i < $end; $i++ ) {
			if (
				! isset( $tokens[ $i ], $tokens[ $i + 1 ] )
				|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $i + 1 ]->id
			) {
				continue;
			}

			if ( WP_MySQL_Lexer::WEEK_SYMBOL !== $tokens[ $i ]->id ) {
				$function_name = $this->get_mysql_identifier_token_value( $tokens[ $i ] );
				if ( null === $function_name || 0 !== strcasecmp( $function_name, 'weekofyear' ) ) {
					continue;
				}
			}

			$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $i + 1, $end );
			if ( null === $after_close || null === $this->get_mysql_week_function_bounds( $tokens, $i, $end ) ) {
				return true;
			}
		}

		return false;
	}

	private function contains_unsupported_mysql_week_function_query( string $query ): bool {
		return $this->contains_unsupported_mysql_range_scanner_query( $query, array( 'contains_unsupported_mysql_week_function' ) );
	}

	/**
	 * Get a supported MySQL WEEK() mode argument.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First mode token.
	 * @param int             $end    Final mode token, exclusive.
	 * @return int|null Supported mode, or null when unsupported.
	 */
	private function get_mysql_supported_week_mode_argument( array $tokens, int $start, int $end ): ?int {
		if (
			$start + 1 !== $end
			|| ! isset( $tokens[ $start ] )
			|| WP_MySQL_Lexer::INT_NUMBER !== $tokens[ $start ]->id
		) {
			return null;
		}

		$mode = $tokens[ $start ]->get_value();
		if ( ! in_array( $mode, array( '0', '1', '2', '3', '4', '5', '6', '7' ), true ) ) {
			return null;
		}

		return (int) $mode;
	}

	/**
	 * Get PostgreSQL SQL for a supported MySQL WEEK() mode.
	 *
	 * @param string $expression_sql PostgreSQL expression SQL.
	 * @param int    $mode           MySQL WEEK() mode.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_week_sql( string $expression_sql, int $mode ): string {
		$timestamp_sql = $this->get_postgresql_zero_date_safe_timestamp_sql( $expression_sql );
		$mode_methods  = array(
			0 => 'get_postgresql_mysql_sunday_week_mode_zero_sql',
			1 => 'get_postgresql_mysql_week_mode_one_timestamp_sql',
			2 => 'get_postgresql_mysql_sunday_week_mode_two_sql',
			4 => 'get_postgresql_mysql_sunday_week_mode_four_sql',
			5 => 'get_postgresql_mysql_monday_week_mode_five_sql',
			6 => 'get_postgresql_mysql_sunday_week_mode_six_sql',
			7 => 'get_postgresql_mysql_monday_week_mode_seven_sql',
		);
		if ( isset( $mode_methods[ $mode ] ) ) {
			return $this->{$mode_methods[ $mode ]}( $timestamp_sql );
		}

		if ( 3 === $mode ) {
			return sprintf(
				'CAST(TO_CHAR(%s, %s) AS integer)',
				$timestamp_sql,
				$this->connection->quote( 'IW' )
			);
		}

		throw new InvalidArgumentException( 'Unsupported MySQL WEEK() mode.' );
	}

	/**
	 * Get PostgreSQL SQL for MySQL WEEK(timestamp, 1).
	 *
	 * @param string $timestamp_sql PostgreSQL timestamp expression.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_week_mode_one_timestamp_sql( string $timestamp_sql ): string {
		$week_start_sql       = sprintf( "DATE_TRUNC('week', %s)", $timestamp_sql );
		$year_start_sql       = sprintf( "DATE_TRUNC('year', %s)", $timestamp_sql );
		$first_week_start_sql = sprintf(
			"(CASE WHEN EXTRACT(ISODOW FROM %1\$s) <= 4 THEN DATE_TRUNC('week', %1\$s) ELSE DATE_TRUNC('week', %1\$s) + INTERVAL '1 week' END)",
			$year_start_sql
		);

		return $this->get_postgresql_mysql_zero_based_week_index_sql( $timestamp_sql, $week_start_sql, $first_week_start_sql );
	}

	/**
	 * Translate MySQL DAYOFWEEK(expr) and WEEKDAY(expr) calls to PostgreSQL.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_weekday_index_function_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_weekday_index_function_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$bounds['expression_start'],
			$bounds['expression_end']
		);
		$timestamp_sql  = $this->get_postgresql_zero_date_safe_timestamp_sql( $expression_sql );
		$sql            = 'dayofweek' === $bounds['function']
			? sprintf( 'CAST(EXTRACT(DOW FROM %s) AS integer) + 1', $timestamp_sql )
			: sprintf( 'CAST(EXTRACT(ISODOW FROM %s) AS integer) - 1', $timestamp_sql );

		return $this->get_postgresql_mysql_expression_translation( $sql, WP_MySQL_Lexer::CAST_SYMBOL, $bounds['close'] );
	}

	/**
	 * Get token bounds for supported MySQL weekday index functions.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{function: string, expression_start: int, expression_end: int, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_weekday_index_function_bounds( array $tokens, int $position, int $end ): ?array {
		$function_name = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $function_name ) {
			return null;
		}

		$function_name = strtolower( $function_name );
		if ( 'dayofweek' !== $function_name && 'weekday' !== $function_name ) {
			return null;
		}

		$bounds = $this->get_mysql_function_call_bounds( $tokens, $position, $end, $function_name );
		if ( null === $bounds ) {
			return null;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
		if ( null === $arguments || 1 !== count( $arguments ) ) {
			return null;
		}

		return array(
			'function'         => $function_name,
			'expression_start' => $arguments[0]['start'],
			'expression_end'   => $arguments[0]['end'],
			'close'            => $bounds['close'],
		);
	}

	/**
	 * Translate supported MySQL DATE_FORMAT(expr, format) calls to PostgreSQL.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_date_format_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_date_format_call_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$bounds['expression_start'],
			$bounds['expression_end']
		);
		if ( $this->is_mysql_null_literal_expression( $tokens, $bounds['expression_start'], $bounds['expression_end'] ) ) {
			$sql = 'NULL';
		} elseif ( null !== $bounds['format'] ) {
			$sql = $this->get_postgresql_mysql_date_format_sql( $bounds['format'], $expression_sql );
		} elseif ( $bounds['format_is_null'] ) {
			$sql = 'NULL';
		} else {
			$sql = $this->get_postgresql_mysql_finite_date_format_choice_sql(
				$tokens,
				$bounds['format_start'],
				$bounds['format_end'],
				$expression_sql,
				false
			);
			if ( null === $sql ) {
				$format_sql = $this->translate_mysql_token_sequence_to_postgresql(
					$tokens,
					$bounds['format_start'],
					$bounds['format_end']
				);
				$sql        = $this->get_postgresql_mysql_dynamic_date_format_sql( $format_sql, $expression_sql );
			}
		}
		if ( null === $sql ) {
			return null;
		}

		return $this->get_postgresql_mysql_expression_translation( $sql, WP_MySQL_Lexer::CASE_SYMBOL, $bounds['close'] );
	}

	/**
	 * Get PostgreSQL SQL for runtime choices between finite DATE_FORMAT() masks.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $start         First format expression token.
	 * @param int              $end           Final format expression token, exclusive.
	 * @param string           $expression_sql PostgreSQL timestamp/date expression SQL.
	 * @param bool             $force_string  Whether to force formatted string semantics.
	 * @return string|null PostgreSQL SQL, or null when the format is not a finite choice.
	 */
	private function get_postgresql_mysql_finite_date_format_choice_sql( array $tokens, int $start, int $end, string $expression_sql, bool $force_string ): ?string {
		$if_sql = $this->get_postgresql_mysql_finite_date_format_if_choice_sql(
			$tokens,
			$start,
			$end,
			$expression_sql,
			$force_string
		);
		if ( null !== $if_sql ) {
			return $if_sql;
		}

		$searched_case = $this->get_mysql_case_expression_branches( $tokens, $start, $end, false );
		if ( null !== $searched_case ) {
			return $this->get_postgresql_mysql_finite_date_format_case_choice_sql( $tokens, $searched_case, $expression_sql, $force_string );
		}

		$simple_case = $this->get_mysql_case_expression_branches( $tokens, $start, $end, true );
		if ( null === $simple_case ) {
			return null;
		}

		return $this->get_postgresql_mysql_finite_date_format_case_choice_sql( $tokens, $simple_case, $expression_sql, $force_string );
	}

	/**
	 * Get PostgreSQL SQL for IF() choices between finite DATE_FORMAT() masks.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $start         First format expression token.
	 * @param int              $end           Final format expression token, exclusive.
	 * @param string           $expression_sql PostgreSQL timestamp/date expression SQL.
	 * @param bool             $force_string  Whether to force formatted string semantics.
	 * @return string|null PostgreSQL SQL, or null when the format is not a finite IF() choice.
	 */
	private function get_postgresql_mysql_finite_date_format_if_choice_sql( array $tokens, int $start, int $end, string $expression_sql, bool $force_string ): ?string {
		$bounds = $this->get_mysql_common_function_bounds( $tokens, $start, $end );
		if ( null === $bounds || $bounds['close'] + 1 !== $end || 'if' !== $bounds['function'] ) {
			return null;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
		if ( null === $arguments || 3 !== count( $arguments ) ) {
			return null;
		}

		$truthy_sql = $this->get_postgresql_mysql_date_format_constant_branch_sql(
			$tokens,
			$arguments[1]['start'],
			$arguments[1]['end'],
			$expression_sql,
			$force_string
		);
		$falsy_sql  = $this->get_postgresql_mysql_date_format_constant_branch_sql(
			$tokens,
			$arguments[2]['start'],
			$arguments[2]['end'],
			$expression_sql,
			$force_string
		);
		if ( null === $truthy_sql || null === $falsy_sql ) {
			return null;
		}

		$condition_argument_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$arguments[0]['start'],
			$arguments[0]['end']
		);
		$condition_sql          = $this->is_mysql_boolean_condition_expression(
			$tokens,
			$arguments[0]['start'],
			$arguments[0]['end']
		)
			? '(' . $condition_argument_sql . ')'
			: $this->get_postgresql_mysql_truthy_expression_sql( $condition_argument_sql );

		return sprintf( 'CASE WHEN %s THEN %s ELSE %s END', $condition_sql, $truthy_sql, $falsy_sql );
	}

	/**
	 * Get PostgreSQL SQL for CASE choices between finite DATE_FORMAT() masks.
	 *
	 * @param WP_MySQL_Token[]                                                                                     $tokens          MySQL lexer token stream.
	 * @param array{value_start?:int,value_end?:int,branches:array<int,array<string,int>>,else:array{start:int,end:int}|null} $case_ranges CASE branch ranges.
	 * @param string                                                                                               $expression_sql  PostgreSQL timestamp/date expression SQL.
	 * @param bool                                                                                                 $force_string    Whether to force formatted string semantics.
	 * @return string|null PostgreSQL SQL, or null when a result branch is not a fixed mask or NULL.
	 */
	private function get_postgresql_mysql_finite_date_format_case_choice_sql( array $tokens, array $case_ranges, string $expression_sql, bool $force_string ): ?string {
		$value_sql = isset( $case_ranges['value_start'], $case_ranges['value_end'] )
			? $this->translate_mysql_token_sequence_to_postgresql( $tokens, $case_ranges['value_start'], $case_ranges['value_end'] )
			: null;
		$parts     = array( 'CASE' );
		foreach ( $case_ranges['branches'] as $branch ) {
			$branch_sql = $this->get_postgresql_mysql_date_format_constant_branch_sql(
				$tokens,
				$branch['result_start'],
				$branch['result_end'],
				$expression_sql,
				$force_string
			);
			if ( null === $branch_sql ) {
				return null;
			}

			if ( null === $value_sql ) {
				$condition_argument_sql = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $branch['condition_start'], $branch['condition_end'] );
				$condition_sql          = $this->is_mysql_boolean_condition_expression( $tokens, $branch['condition_start'], $branch['condition_end'] )
					? '(' . $condition_argument_sql . ')'
					: $this->get_postgresql_mysql_truthy_expression_sql( $condition_argument_sql );
			} else {
				$condition_sql = sprintf(
					'(%s = %s)',
					$value_sql,
					$this->translate_mysql_token_sequence_to_postgresql( $tokens, $branch['compare_start'], $branch['compare_end'] )
				);
			}

			$parts[] = sprintf( 'WHEN %s THEN %s', $condition_sql, $branch_sql );
		}

		$else_sql = 'NULL';
		if ( null !== $case_ranges['else'] ) {
			$else_sql = $this->get_postgresql_mysql_date_format_constant_branch_sql(
				$tokens,
				$case_ranges['else']['start'],
				$case_ranges['else']['end'],
				$expression_sql,
				$force_string
			);
			if ( null === $else_sql ) {
				return null;
			}
		}

		$parts[] = 'ELSE ' . $else_sql;
		$parts[] = 'END';

		return implode( ' ', $parts );
	}

	/**
	 * Get CASE branch ranges.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param int              $start       CASE token position.
	 * @param int              $end         Final CASE expression token position, exclusive.
	 * @param bool             $simple_case Whether to parse a simple CASE expression.
	 * @return array{value_start?:int,value_end?:int,branches:array<int,array<string,int>>,else:array{start:int,end:int}|null}|null Branch ranges, or null when unsupported.
	 */
	private function get_mysql_case_expression_branches( array $tokens, int $start, int $end, bool $simple_case ): ?array {
		if (
			$start + ( $simple_case ? 4 : 3 ) >= $end
			|| ! isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $end - 1 ] )
			|| WP_MySQL_Lexer::CASE_SYMBOL !== $tokens[ $start ]->id
			|| ( $simple_case && WP_MySQL_Lexer::WHEN_SYMBOL === $tokens[ $start + 1 ]->id )
			|| ( ! $simple_case && WP_MySQL_Lexer::WHEN_SYMBOL !== $tokens[ $start + 1 ]->id )
			|| WP_MySQL_Lexer::END_SYMBOL !== $tokens[ $end - 1 ]->id
			|| $this->get_mysql_case_expression_end( $tokens, $start, $end ) !== $end
		) {
			return null;
		}

		$branches                = array();
		$case_depth              = 0;
		$paren_depth             = 0;
		$value_start             = $start + 1;
		$value_end               = null;
		$test_start              = null;
		$test_end                = null;
		$result_start            = null;
		$else_start              = null;
		$finalize_current_branch = function ( int $position ) use ( &$branches, &$test_start, &$test_end, &$result_start, $simple_case ): bool {
			if (
				null === $test_start
				|| null === $test_end
				|| null === $result_start
				|| $test_start >= $test_end
				|| $result_start >= $position
			) {
				return false;
			}

			$branches[]   = array(
				( $simple_case ? 'compare_start' : 'condition_start' ) => $test_start,
				( $simple_case ? 'compare_end' : 'condition_end' ) => $test_end,
				'result_start' => $result_start,
				'result_end'   => $position,
			);
			$test_start   = null;
			$test_end     = null;
			$result_start = null;

			return true;
		};

		for ( $i = $start + 1; $i < $end; $i++ ) {
			$token_id = $tokens[ $i ]->id;

			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $token_id ) {
				++$paren_depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $token_id ) {
				--$paren_depth;
				if ( $paren_depth < 0 ) {
					return null;
				}
				continue;
			}

			if ( 0 !== $paren_depth ) {
				continue;
			}

			if ( WP_MySQL_Lexer::CASE_SYMBOL === $token_id ) {
				++$case_depth;
				continue;
			}

			if ( WP_MySQL_Lexer::END_SYMBOL === $token_id && $case_depth > 0 ) {
				--$case_depth;
				continue;
			}

			if ( 0 !== $case_depth ) {
				continue;
			}

			if ( WP_MySQL_Lexer::WHEN_SYMBOL === $token_id ) {
				if ( null !== $else_start ) {
					return null;
				}
				if ( $simple_case && null === $value_end ) {
					if ( $value_start >= $i ) {
						return null;
					}
					$value_end = $i;
				} elseif ( null !== $result_start && ! $finalize_current_branch( $i ) ) {
					return null;
				}
				if ( null !== $test_start || null !== $test_end ) {
					return null;
				}

				$test_start = $i + 1;
				continue;
			}

			if ( WP_MySQL_Lexer::THEN_SYMBOL === $token_id ) {
				if (
					( $simple_case && null === $value_end )
					|| null === $test_start
					|| null !== $test_end
					|| null !== $result_start
					|| null !== $else_start
					|| $test_start >= $i
				) {
					return null;
				}

				$test_end     = $i;
				$result_start = $i + 1;
				continue;
			}

			if ( WP_MySQL_Lexer::ELSE_SYMBOL === $token_id ) {
				if ( null !== $else_start || null === $result_start || ! $finalize_current_branch( $i ) ) {
					return null;
				}

				$else_start = $i + 1;
				continue;
			}

			if ( WP_MySQL_Lexer::END_SYMBOL === $token_id ) {
				if ( $i !== $end - 1 || ( $simple_case && null === $value_end ) ) {
					return null;
				}
				if ( null !== $result_start && ! $finalize_current_branch( $i ) ) {
					return null;
				}
				if ( null !== $test_start || null !== $test_end || empty( $branches ) ) {
					return null;
				}
				if ( null !== $else_start && $else_start >= $i ) {
					return null;
				}

				$case_ranges = array(
					'branches' => $branches,
					'else'     => null === $else_start ? null : array(
						'start' => $else_start,
						'end'   => $i,
					),
				);
				if ( $simple_case ) {
					$case_ranges['value_start'] = $value_start;
					$case_ranges['value_end']   = $value_end;
				}

				return $case_ranges;
			}
		}

		return null;
	}

	/**
	 * Get PostgreSQL SQL for one fixed DATE_FORMAT() branch.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $start         First branch token.
	 * @param int              $end           Final branch token, exclusive.
	 * @param string           $expression_sql PostgreSQL timestamp/date expression SQL.
	 * @param bool             $force_string  Whether to force formatted string semantics.
	 * @return string|null PostgreSQL SQL, or null when the branch is not a fixed mask or NULL.
	 */
	private function get_postgresql_mysql_date_format_constant_branch_sql( array $tokens, int $start, int $end, string $expression_sql, bool $force_string ): ?string {
		$format = $this->get_mysql_constant_string_expression_value( $tokens, $start, $end );
		if ( null === $format ) {
			return null;
		}

		if ( $format['is_null'] ) {
			return 'NULL';
		}

		return $force_string
			? $this->get_postgresql_mysql_generic_date_format_sql( $format['value'], $expression_sql, false )
			: $this->get_postgresql_mysql_date_format_sql( $format['value'], $expression_sql );
	}

	/**
	 * Check whether a range contains an unsupported MySQL DATE_FORMAT() form.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return bool Whether an unsupported DATE_FORMAT() call is present.
	 */
	private function contains_unsupported_mysql_date_format_function( array $tokens, int $start, int $end ): bool {
		for ( $i = $start; $i < $end; $i++ ) {
			if ( null === $this->get_mysql_function_call_bounds( $tokens, $i, $end, 'date_format' ) ) {
				continue;
			}

			if ( null === $this->get_mysql_date_format_call_bounds( $tokens, $i, $end ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check a query with one or more unsupported-construct range scanners.
	 *
	 * @param string   $query         SQL query.
	 * @param string[] $scanner_names Private scanner method names.
	 * @return bool Whether any scanner reports an unsupported construct.
	 */
	private function contains_unsupported_mysql_range_scanner_query( string $query, array $scanner_names ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) ) {
			return false;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		$end           = null === $statement_end ? count( $tokens ) : $statement_end;
		foreach ( $scanner_names as $scanner_name ) {
			if ( $this->$scanner_name( $tokens, 0, $end ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Get token bounds for supported MySQL DATE_FORMAT(expr, format) calls.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{format: string, expression_start: int, expression_end: int, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_date_format_bounds( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_date_format_call_bounds( $tokens, $position, $end );
		if ( null === $bounds || null === $bounds['format'] ) {
			return null;
		}

		return $bounds;
	}

	/**
	 * Get token bounds for MySQL DATE_FORMAT(expr, format) calls.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{format: string|null, format_is_null: bool, expression_start: int, expression_end: int, format_start: int, format_end: int, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_date_format_call_bounds( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_function_call_bounds( $tokens, $position, $end, 'date_format' );
		if ( null === $bounds ) {
			return null;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
		if ( null === $arguments || 2 !== count( $arguments ) ) {
			return null;
		}

		$format_constant = $this->get_mysql_constant_string_expression_value(
			$tokens,
			$arguments[1]['start'],
			$arguments[1]['end']
		);
		$format          = null !== $format_constant && ! $format_constant['is_null'] ? $format_constant['value'] : null;

		return array(
			'format'           => $format,
			'format_is_null'   => null !== $format_constant && $format_constant['is_null'],
			'expression_start' => $arguments[0]['start'],
			'expression_end'   => $arguments[0]['end'],
			'format_start'     => $arguments[1]['start'],
			'format_end'       => $arguments[1]['end'],
			'close'            => $bounds['close'],
		);
	}

	/**
	 * Get PostgreSQL SQL for a supported MySQL DATE_FORMAT() format.
	 *
	 * @param string $format         MySQL DATE_FORMAT format.
	 * @param string $expression_sql PostgreSQL expression SQL.
	 * @return string|null PostgreSQL expression SQL, or null when unsupported.
	 */
	private function get_postgresql_mysql_date_format_sql( string $format, string $expression_sql ): ?string {
		$numeric_formats = array(
			'%H.%i'   => array( "SUBSTRING(%1\$s FROM 12 FOR 2) || '.' || SUBSTRING(%1\$s FROM 15 FOR 2)", 'TO_CHAR(%1$s, %2$s)', 'HH24.MI' ),
			'%H.%i%s' => array( "SUBSTRING(%1\$s FROM 12 FOR 2) || '.' || SUBSTRING(%1\$s FROM 15 FOR 2) || SUBSTRING(%1\$s FROM 18 FOR 2)", 'TO_CHAR(%1$s, %2$s)', 'HH24.MISS' ),
			'0.%i%s'  => array( "'0.' || SUBSTRING(%1\$s FROM 15 FOR 2) || SUBSTRING(%1\$s FROM 18 FOR 2)", "'0.' || TO_CHAR(%1\$s, %2\$s)", 'MISS' ),
		);
		if ( isset( $numeric_formats[ $format ] ) ) {
			$numeric_format       = $numeric_formats[ $format ];
			$expression_text_sql  = sprintf( 'CAST(%s AS text)', $expression_sql );
			$zero_date_condition  = $this->get_postgresql_zero_date_condition_sql( $expression_text_sql );
			$date_time_pattern    = "'^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T][0-9]{2}:[0-9]{2}:[0-9]{2}'";
			$zero_date_format_sql = sprintf(
				'CASE WHEN %1$s ~ %2$s THEN CAST(%3$s AS double precision) ELSE 0 END',
				$expression_text_sql,
				$date_time_pattern,
				sprintf( $numeric_format[0], $expression_text_sql )
			);

			return sprintf(
				'CASE WHEN %1$s THEN %2$s ELSE CAST(%3$s AS double precision) END',
				$zero_date_condition,
				$zero_date_format_sql,
				sprintf(
					$numeric_format[1],
					$this->get_postgresql_zero_date_safe_timestamp_sql( $expression_sql ),
					$this->connection->quote( $numeric_format[2] )
				)
			);
		}

		if ( '%Y-%m-%d' === $format ) {
			$expression_text_sql = sprintf( 'CAST(%s AS text)', $expression_sql );

			return sprintf(
				'CASE WHEN %1$s THEN NULL WHEN %2$s THEN SUBSTRING(%3$s FROM 1 FOR 10) ELSE TO_CHAR(%4$s, %5$s) END',
				$this->get_postgresql_empty_temporal_condition_sql( $expression_text_sql ),
				$this->get_postgresql_zero_date_condition_sql( $expression_text_sql ),
				$expression_text_sql,
				$this->get_postgresql_zero_date_safe_timestamp_sql( $expression_sql ),
				$this->connection->quote( 'YYYY-MM-DD' )
			);
		}

		return $this->get_postgresql_mysql_generic_date_format_sql( $format, $expression_sql );
	}

	/**
	 * Get PostgreSQL SQL for general MySQL DATE_FORMAT() format strings.
	 *
	 * @param string $format                   MySQL DATE_FORMAT format.
	 * @param string $expression_sql           PostgreSQL expression SQL.
	 * @param bool   $preserve_zero_date_parts Whether to derive numeric/time parts from zero-ish dates.
	 * @return string|null PostgreSQL expression SQL, or null when unsupported.
	 */
	private function get_postgresql_mysql_generic_date_format_sql( string $format, string $expression_sql, bool $preserve_zero_date_parts = true ): ?string {
		$timestamp_sql        = $this->get_postgresql_zero_date_safe_timestamp_sql( $expression_sql );
		$expression_text_sql  = sprintf( 'CAST(%s AS text)', $expression_sql );
		$empty_date_condition = $this->get_postgresql_empty_temporal_condition_sql( $expression_text_sql );
		$zero_date_condition  = $this->get_postgresql_zero_date_condition_sql( $expression_text_sql );
		$zero_date_format_sql = $this->get_postgresql_mysql_zero_date_format_sql( $format, $expression_text_sql );
		$formatted_sql        = $this->get_postgresql_mysql_date_format_fragments_sql(
			$format,
			function ( string $specifier ) use ( $timestamp_sql ): ?string {
				return $this->get_postgresql_mysql_date_format_specifier_sql( $specifier, $timestamp_sql );
			}
		);
		if ( ! $preserve_zero_date_parts ) {
			return sprintf(
				'CASE WHEN %1$s IS NULL OR %2$s OR %3$s THEN NULL ELSE %4$s END',
				$expression_text_sql,
				$empty_date_condition,
				$zero_date_condition,
				$formatted_sql
			);
		}

		return sprintf(
			'CASE WHEN %1$s IS NULL OR %2$s THEN NULL WHEN %3$s THEN %4$s ELSE %5$s END',
			$expression_text_sql,
			$empty_date_condition,
			$zero_date_condition,
			$zero_date_format_sql,
			$formatted_sql
		);
	}

	/**
	 * Get PostgreSQL SQL for DATE_FORMAT() against a zero or partial-zero date string.
	 *
	 * MySQL can format numeric month/day ranges that include zero, but specifiers
	 * that need a real calendar date still return NULL for incomplete dates.
	 *
	 * @param string $format              MySQL DATE_FORMAT format.
	 * @param string $expression_text_sql PostgreSQL expression cast to text.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_zero_date_format_sql( string $format, string $expression_text_sql ): string {
		$sql = $this->get_postgresql_mysql_date_format_fragments_sql(
			$format,
			function ( string $specifier ) use ( $expression_text_sql ): ?string {
				return $this->get_postgresql_mysql_zero_date_format_specifier_sql( $specifier, $expression_text_sql );
			},
			true
		);

		return null === $sql ? 'NULL' : $sql;
	}

	/**
	 * Render fixed DATE_FORMAT() fragments with a specifier renderer.
	 *
	 * @param string   $format                         MySQL DATE_FORMAT format.
	 * @param callable $specifier_callback             Specifier renderer.
	 * @param bool     $null_on_known_unrenderable     Whether known specifiers that require a full date should return NULL.
	 * @return string|null Fragment SQL, or null when zero-date formatting must return NULL.
	 */
	private function get_postgresql_mysql_date_format_fragments_sql( string $format, callable $specifier_callback, bool $null_on_known_unrenderable = false ): ?string {
		$fragments = array();
		$literal   = '';
		$length    = strlen( $format );

		for ( $i = 0; $i < $length; $i++ ) {
			if ( '%' !== $format[ $i ] ) {
				$literal .= $format[ $i ];
				continue;
			}

			if ( $i + 1 >= $length ) {
				$literal .= '%';
				continue;
			}

			if ( '' !== $literal ) {
				$fragments[] = $this->connection->quote( $literal );
				$literal     = '';
			}

			$fragment = $specifier_callback( $format[ ++$i ] );
			if ( null === $fragment ) {
				if ( $null_on_known_unrenderable && $this->is_postgresql_mysql_date_format_known_specifier( $format[ $i ] ) ) {
					return null;
				}

				$literal .= $format[ $i ];
				continue;
			}

			$fragments[] = $fragment;
		}

		if ( '' !== $literal ) {
			$fragments[] = $this->connection->quote( $literal );
		}

		return empty( $fragments ) ? "''" : implode( ' || ', $fragments );
	}

	/**
	 * Check whether a DATE_FORMAT() specifier is known to MySQL.
	 *
	 * @param string $specifier MySQL DATE_FORMAT specifier without the leading percent.
	 * @return bool Whether the specifier has emulated meaning.
	 */
	private function is_postgresql_mysql_date_format_known_specifier( string $specifier ): bool {
		return '%' === $specifier
			|| 'D' === $specifier
			|| 'w' === $specifier
			|| null !== $this->get_postgresql_mysql_date_format_week_specifier_sql( $specifier, 'NULL' )
			|| isset( $this->get_postgresql_mysql_date_format_to_char_formats()[ $specifier ] );
	}

	/**
	 * Get PostgreSQL SQL for one DATE_FORMAT() specifier on a zero-ish date.
	 *
	 * @param string $specifier           MySQL DATE_FORMAT specifier without the leading percent.
	 * @param string $expression_text_sql PostgreSQL expression cast to text.
	 * @return string|null PostgreSQL SQL fragment, or null when a real calendar date is required.
	 */
	private function get_postgresql_mysql_zero_date_format_specifier_sql( string $specifier, string $expression_text_sql ): ?string {
		foreach ( array_chunk( array( 'Y', 1, 4, 'y', 3, 2, 'm', 6, 2, 'd', 9, 2 ), 3 ) as $range ) {
			if ( $range[0] === $specifier ) {
				return sprintf( 'SUBSTRING(%s FROM %d FOR %d)', $expression_text_sql, $range[1], $range[2] );
			}
		}

		foreach ( array_chunk( array( 'c', 6, 2, 'e', 9, 2 ), 3 ) as $range ) {
			if ( $range[0] === $specifier ) {
				return sprintf( 'CAST(CAST(SUBSTRING(%s FROM %d FOR %d) AS integer) AS text)', $expression_text_sql, $range[1], $range[2] );
			}
		}

		foreach ( array_chunk( array( 'H', 12, 'i', 15, 'S', 18, 's', 18 ), 2 ) as $range ) {
			if ( $range[0] === $specifier ) {
				return $this->get_postgresql_mysql_zero_date_time_part_sql( $expression_text_sql, $range[1], 2 );
			}
		}

		if ( '%' === $specifier ) {
			return $this->connection->quote( '%' );
		}

		if ( 'D' === $specifier ) {
			return $this->get_postgresql_mysql_day_with_suffix_sql( sprintf( 'CAST(SUBSTRING(%s FROM 9 FOR 2) AS integer)', $expression_text_sql ) );
		}

		$hour_12_sql = $this->get_postgresql_mysql_zero_date_hour_12_sql( $expression_text_sql );
		if ( 'h' === $specifier || 'I' === $specifier ) {
			return sprintf( "LPAD(CAST(%s AS text), 2, '0')", $hour_12_sql );
		}

		if ( 'k' === $specifier ) {
			return sprintf( 'CAST(CAST(%s AS integer) AS text)', $this->get_postgresql_mysql_zero_date_time_part_sql( $expression_text_sql, 12, 2 ) );
		}

		if ( 'l' === $specifier ) {
			return sprintf( 'CAST(%s AS text)', $hour_12_sql );
		}

		if ( 'T' === $specifier || 'r' === $specifier ) {
			$time_sql = sprintf(
				"%1\$s || ':' || %2\$s || ':' || %3\$s",
				'T' === $specifier ? $this->get_postgresql_mysql_zero_date_time_part_sql( $expression_text_sql, 12, 2 ) : sprintf( "LPAD(CAST(%s AS text), 2, '0')", $hour_12_sql ),
				$this->get_postgresql_mysql_zero_date_time_part_sql( $expression_text_sql, 15, 2 ),
				$this->get_postgresql_mysql_zero_date_time_part_sql( $expression_text_sql, 18, 2 )
			);
			return 'T' === $specifier ? $time_sql : sprintf( "%s || ' ' || %s", $time_sql, $this->get_postgresql_mysql_zero_date_meridiem_sql( $expression_text_sql ) );
		}

		if ( 'p' === $specifier ) {
			return $this->get_postgresql_mysql_zero_date_meridiem_sql( $expression_text_sql );
		}

		if ( 'f' === $specifier ) {
			return $this->get_postgresql_mysql_zero_date_microsecond_sql( $expression_text_sql );
		}

		return null;
	}

	/**
	 * Get a time component from a zero-ish date string, defaulting to 00.
	 *
	 * @param string $expression_text_sql PostgreSQL expression cast to text.
	 * @param int    $start               One-based substring start.
	 * @param int    $length              Substring length.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_zero_date_time_part_sql( string $expression_text_sql, int $start, int $length ): string {
		return sprintf(
			"CASE WHEN %1\$s ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T][0-9]{2}:[0-9]{2}:[0-9]{2}' THEN SUBSTRING(%1\$s FROM %2\$d FOR %3\$d) ELSE '00' END",
			$expression_text_sql,
			$start,
			$length
		);
	}

	/**
	 * Get a 12-hour clock hour from a zero-ish date string.
	 *
	 * @param string $expression_text_sql PostgreSQL expression cast to text.
	 * @return string PostgreSQL integer expression SQL.
	 */
	private function get_postgresql_mysql_zero_date_hour_12_sql( string $expression_text_sql ): string {
		return sprintf(
			'MOD(CAST(%s AS integer) + 11, 12) + 1',
			$this->get_postgresql_mysql_zero_date_time_part_sql( $expression_text_sql, 12, 2 )
		);
	}

	/**
	 * Get an AM/PM marker from a zero-ish date string.
	 *
	 * @param string $expression_text_sql PostgreSQL expression cast to text.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_zero_date_meridiem_sql( string $expression_text_sql ): string {
		return sprintf(
			"CASE WHEN CAST(%s AS integer) < 12 THEN 'AM' ELSE 'PM' END",
			$this->get_postgresql_mysql_zero_date_time_part_sql( $expression_text_sql, 12, 2 )
		);
	}

	/**
	 * Get the microsecond component from a zero-ish date string.
	 *
	 * @param string $expression_text_sql PostgreSQL expression cast to text.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_zero_date_microsecond_sql( string $expression_text_sql ): string {
		return sprintf(
			"CASE WHEN %1\$s ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T][0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]+' THEN LEFT(RPAD(SUBSTRING(%1\$s FROM '[.]([0-9]+)'), 6, '0'), 6) ELSE '000000' END",
			$expression_text_sql
		);
	}

	/**
	 * Get PostgreSQL SQL for a MySQL DATE_FORMAT() call with a runtime format expression.
	 *
	 * @param string $format_sql     PostgreSQL SQL for the MySQL format expression.
	 * @param string $expression_sql PostgreSQL SQL for the value to format.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_dynamic_date_format_sql( string $format_sql, string $expression_sql ): string {
		$timestamp_sql        = $this->get_postgresql_zero_date_safe_timestamp_sql( $expression_sql );
		$expression_text_sql  = sprintf( 'CAST(%s AS text)', $expression_sql );
		$format_text_sql      = sprintf( 'CAST(%s AS text)', $format_sql );
		$empty_date_condition = $this->get_postgresql_empty_temporal_condition_sql( $expression_text_sql );
		$zero_date_condition  = $this->get_postgresql_zero_date_condition_sql( $expression_text_sql );

		$character_sql           = sprintf(
			'SUBSTRING(%s FROM "__wp_pg_mysql_date_format"."position" FOR 1)',
			$format_text_sql
		);
		$specifier_sql           = sprintf(
			'SUBSTRING(%s FROM "__wp_pg_mysql_date_format"."position" + 1 FOR 1)',
			$format_text_sql
		);
		$percent_sql             = $this->connection->quote( '%' );
		$next_position_sql       = sprintf(
			'CASE WHEN %1$s = %2$s AND "__wp_pg_mysql_date_format"."position" < CHAR_LENGTH(%3$s) THEN "__wp_pg_mysql_date_format"."position" + 2 ELSE "__wp_pg_mysql_date_format"."position" + 1 END',
			$character_sql,
			$percent_sql,
			$format_text_sql
		);
		$fragment_sql            = sprintf(
			'CASE WHEN %1$s <> %2$s THEN %1$s WHEN "__wp_pg_mysql_date_format"."position" >= CHAR_LENGTH(%3$s) THEN %2$s ELSE %4$s END',
			$character_sql,
			$percent_sql,
			$format_text_sql,
			$this->get_postgresql_mysql_dynamic_date_format_specifier_case_sql( $specifier_sql, $timestamp_sql )
		);
		$zero_date_fragment_sql  = sprintf(
			'CASE WHEN %1$s <> %2$s THEN %1$s WHEN "__wp_pg_mysql_date_format"."position" >= CHAR_LENGTH(%3$s) THEN %2$s ELSE %4$s END',
			$character_sql,
			$percent_sql,
			$format_text_sql,
			$this->get_postgresql_mysql_dynamic_zero_date_format_specifier_case_sql( $specifier_sql, $expression_text_sql )
		);
		$formatter_sql           = sprintf(
			'(WITH RECURSIVE "__wp_pg_mysql_date_format"("position", "formatted") AS (SELECT 1, CAST(\'\' AS text) UNION ALL SELECT %1$s, "formatted" || %2$s FROM "__wp_pg_mysql_date_format" WHERE "position" <= CHAR_LENGTH(%3$s)) SELECT "formatted" FROM "__wp_pg_mysql_date_format" ORDER BY "position" DESC LIMIT 1)',
			$next_position_sql,
			$fragment_sql,
			$format_text_sql
		);
		$zero_date_formatter_sql = sprintf(
			'(WITH RECURSIVE "__wp_pg_mysql_date_format"("position", "formatted") AS (SELECT 1, CAST(\'\' AS text) UNION ALL SELECT %1$s, "formatted" || %2$s FROM "__wp_pg_mysql_date_format" WHERE "position" <= CHAR_LENGTH(%3$s)) SELECT "formatted" FROM "__wp_pg_mysql_date_format" ORDER BY "position" DESC LIMIT 1)',
			$next_position_sql,
			$zero_date_fragment_sql,
			$format_text_sql
		);

		return sprintf(
			'CASE WHEN %1$s IS NULL OR %2$s IS NULL OR %3$s THEN NULL WHEN %4$s THEN %5$s ELSE %6$s END',
			$expression_text_sql,
			$format_text_sql,
			$empty_date_condition,
			$zero_date_condition,
			$zero_date_formatter_sql,
			$formatter_sql
		);
	}

	/**
	 * Get PostgreSQL CASE SQL for a runtime MySQL DATE_FORMAT() specifier on a zero-ish date.
	 *
	 * @param string $specifier_sql        PostgreSQL SQL for the format specifier character.
	 * @param string $expression_text_sql PostgreSQL expression cast to text.
	 * @return string PostgreSQL CASE expression SQL.
	 */
	private function get_postgresql_mysql_dynamic_zero_date_format_specifier_case_sql( string $specifier_sql, string $expression_text_sql ): string {
		$cases                     = array();
		$zero_date_part_specifiers = array( '%', 'Y', 'y', 'm', 'c', 'd', 'e', 'D', 'H', 'k', 'h', 'I', 'l', 'i', 'S', 's', 'T', 'r', 'p', 'f' );
		foreach ( $zero_date_part_specifiers as $specifier ) {
			$cases[] = sprintf(
				'WHEN %s THEN %s',
				$this->connection->quote( $specifier ),
				$this->get_postgresql_mysql_zero_date_format_specifier_sql( $specifier, $expression_text_sql )
			);
		}

		$null_specifiers = array_unique(
			array_merge(
				array_keys( $this->get_postgresql_mysql_date_format_to_char_formats() ),
				array( 'w', 'U', 'u', 'V', 'v', 'X', 'x' )
			)
		);
		foreach ( $null_specifiers as $specifier ) {
			if ( null !== $this->get_postgresql_mysql_zero_date_format_specifier_sql( $specifier, $expression_text_sql ) ) {
				continue;
			}

			$cases[] = sprintf(
				'WHEN %s THEN NULL',
				$this->connection->quote( $specifier )
			);
		}

			return sprintf(
				'CASE %1$s %2$s ELSE %1$s END',
				$specifier_sql,
				implode( ' ', $cases )
			);
	}

	/**
	 * Get PostgreSQL CASE SQL for a runtime MySQL DATE_FORMAT() specifier.
	 *
	 * @param string $specifier_sql PostgreSQL SQL for the format specifier character.
	 * @param string $timestamp_sql PostgreSQL timestamp expression.
	 * @return string PostgreSQL CASE expression SQL.
	 */
	private function get_postgresql_mysql_dynamic_date_format_specifier_case_sql( string $specifier_sql, string $timestamp_sql ): string {
		$cases = array();
		foreach ( $this->get_postgresql_mysql_date_format_to_char_formats() as $specifier => $format ) {
			$cases[] = sprintf(
				'WHEN %s THEN TO_CHAR(%s, %s)',
				$this->connection->quote( $specifier ),
				$timestamp_sql,
				$this->connection->quote( $format )
			);
		}

		$cases[] = sprintf(
			'WHEN %s THEN %s',
			$this->connection->quote( '%' ),
			$this->connection->quote( '%' )
		);
		$cases[] = sprintf(
			'WHEN %s THEN %s',
			$this->connection->quote( 'D' ),
			$this->get_postgresql_mysql_day_with_suffix_sql(
				sprintf( 'CAST(EXTRACT(DAY FROM %s) AS integer)', $timestamp_sql )
			)
		);
		$cases[] = sprintf(
			'WHEN %s THEN CAST(CAST(EXTRACT(DOW FROM %s) AS integer) AS text)',
			$this->connection->quote( 'w' ),
			$timestamp_sql
		);
		foreach ( array( 'U', 'u', 'V', 'v', 'X', 'x' ) as $week_specifier ) {
			$cases[] = sprintf(
				'WHEN %s THEN %s',
				$this->connection->quote( $week_specifier ),
				$this->get_postgresql_mysql_date_format_week_specifier_sql( $week_specifier, $timestamp_sql )
			);
		}

			return sprintf(
				'CASE %1$s %2$s ELSE %1$s END',
				$specifier_sql,
				implode( ' ', $cases )
			);
	}

	/**
	 * Get PostgreSQL SQL for one MySQL DATE_FORMAT() specifier.
	 *
	 * @param string $specifier    MySQL DATE_FORMAT specifier without the leading percent.
	 * @param string $timestamp_sql PostgreSQL timestamp expression.
	 * @return string|null PostgreSQL SQL fragment, or null when the specifier is unknown.
	 */
	private function get_postgresql_mysql_date_format_specifier_sql( string $specifier, string $timestamp_sql ): ?string {
		$to_char_formats = $this->get_postgresql_mysql_date_format_to_char_formats();

		if ( '%' === $specifier ) {
			return $this->connection->quote( '%' );
		}

		if ( 'D' === $specifier ) {
			return $this->get_postgresql_mysql_day_with_suffix_sql(
				sprintf( 'CAST(EXTRACT(DAY FROM %s) AS integer)', $timestamp_sql )
			);
		}

		if ( 'w' === $specifier ) {
			return sprintf( 'CAST(CAST(EXTRACT(DOW FROM %s) AS integer) AS text)', $timestamp_sql );
		}

		$week_sql = $this->get_postgresql_mysql_date_format_week_specifier_sql( $specifier, $timestamp_sql );
		if ( null !== $week_sql ) {
			return $week_sql;
		}

		if ( isset( $to_char_formats[ $specifier ] ) ) {
			return sprintf(
				'TO_CHAR(%s, %s)',
				$timestamp_sql,
				$this->connection->quote( $to_char_formats[ $specifier ] )
			);
		}

		return null;
	}

	/**
	 * Get PostgreSQL TO_CHAR format strings keyed by MySQL DATE_FORMAT() specifier.
	 *
	 * @return array<string, string> PostgreSQL TO_CHAR formats.
	 */
	private function get_postgresql_mysql_date_format_to_char_formats(): array {
		return array_combine(
			str_split( 'abcdefHhIijklMmprSsTWYy' ),
			explode( '|', 'Dy|Mon|FMMM|DD|FMDD|US|HH24|HH12|HH12|MI|DDD|FMHH24|FMHH12|FMMonth|MM|AM|HH12:MI:SS AM|SS|SS|HH24:MI:SS|FMDay|YYYY|YY' )
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL DATE_FORMAT() week/year specifiers.
	 *
	 * @param string $specifier    MySQL DATE_FORMAT specifier without the leading percent.
	 * @param string $timestamp_sql PostgreSQL timestamp expression.
	 * @return string|null PostgreSQL SQL fragment, or null when the specifier is not a week specifier.
	 */
	private function get_postgresql_mysql_date_format_week_specifier_sql( string $specifier, string $timestamp_sql ): ?string {
		$zero_padded_week_methods = array(
			'U' => 'get_postgresql_mysql_sunday_week_mode_zero_sql',
			'u' => 'get_postgresql_mysql_week_mode_one_timestamp_sql',
			'V' => 'get_postgresql_mysql_sunday_week_mode_two_sql',
		);
		if ( isset( $zero_padded_week_methods[ $specifier ] ) ) {
			return sprintf(
				"LPAD(CAST(%s AS text), 2, '0')",
				$this->{$zero_padded_week_methods[ $specifier ]}( $timestamp_sql )
			);
		}

		$to_char_formats = array(
			'v' => 'IW',
			'x' => 'IYYY',
		);
		if ( isset( $to_char_formats[ $specifier ] ) ) {
			return sprintf(
				'TO_CHAR(%s, %s)',
				$timestamp_sql,
				$this->connection->quote( $to_char_formats[ $specifier ] )
			);
		}

		if ( 'X' === $specifier ) {
			$week_start_sql       = $this->get_postgresql_mysql_sunday_week_start_sql( $timestamp_sql );
			$year_start_sql       = sprintf( "DATE_TRUNC('year', %s)", $timestamp_sql );
			$first_week_start_sql = $this->get_postgresql_mysql_first_sunday_of_year_sql( $year_start_sql );

			return sprintf(
				"CASE WHEN %1\$s IS NULL THEN NULL WHEN %2\$s < %3\$s THEN TO_CHAR(%4\$s - INTERVAL '1 year', 'YYYY') ELSE TO_CHAR(%4\$s, 'YYYY') END",
				$timestamp_sql,
				$week_start_sql,
				$first_week_start_sql,
				$year_start_sql
			);
		}

		return null;
	}

	/**
	 * Get PostgreSQL SQL for MySQL WEEK(expr, 0).
	 *
	 * Mode 0 is Sunday-first, returns 0-53, and week 1 starts at the first
	 * Sunday in the calendar year.
	 *
	 * @param string $timestamp_sql PostgreSQL timestamp expression.
	 * @return string PostgreSQL integer expression.
	 */
	private function get_postgresql_mysql_sunday_week_mode_zero_sql( string $timestamp_sql ): string {
		$week_start_sql       = $this->get_postgresql_mysql_sunday_week_start_sql( $timestamp_sql );
		$year_start_sql       = sprintf( "DATE_TRUNC('year', %s)", $timestamp_sql );
		$first_week_start_sql = $this->get_postgresql_mysql_first_sunday_of_year_sql( $year_start_sql );

		return $this->get_postgresql_mysql_zero_based_week_index_sql( $timestamp_sql, $week_start_sql, $first_week_start_sql );
	}

	/**
	 * Get PostgreSQL SQL for MySQL WEEK(expr, 2).
	 *
	 * Mode 2 is Sunday-first, returns 1-53, and uses the previous week-year
	 * for dates before the first Sunday in the calendar year.
	 *
	 * @param string $timestamp_sql PostgreSQL timestamp expression.
	 * @return string PostgreSQL integer expression.
	 */
	private function get_postgresql_mysql_sunday_week_mode_two_sql( string $timestamp_sql ): string {
		$week_start_sql          = $this->get_postgresql_mysql_sunday_week_start_sql( $timestamp_sql );
		$year_start_sql          = sprintf( "DATE_TRUNC('year', %s)", $timestamp_sql );
		$first_week_start_sql    = $this->get_postgresql_mysql_first_sunday_of_year_sql( $year_start_sql );
		$previous_year_start_sql = sprintf( "(%s - INTERVAL '1 year')", $year_start_sql );
		$previous_first_week_sql = $this->get_postgresql_mysql_first_sunday_of_year_sql( $previous_year_start_sql );

		return sprintf(
			'CASE WHEN %1$s IS NULL THEN NULL WHEN %2$s < %3$s THEN CAST(FLOOR(EXTRACT(EPOCH FROM (%2$s - %4$s)) / 604800) AS integer) + 1 ELSE CAST(FLOOR(EXTRACT(EPOCH FROM (%2$s - %3$s)) / 604800) AS integer) + 1 END',
			$timestamp_sql,
			$week_start_sql,
			$first_week_start_sql,
			$previous_first_week_sql
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL WEEK(expr, 4).
	 *
	 * Mode 4 is Sunday-first, returns 0-53, and week 1 has four or more
	 * days in the calendar year.
	 *
	 * @param string $timestamp_sql PostgreSQL timestamp expression.
	 * @return string PostgreSQL integer expression.
	 */
	private function get_postgresql_mysql_sunday_week_mode_four_sql( string $timestamp_sql ): string {
		$week_start_sql       = $this->get_postgresql_mysql_sunday_week_start_sql( $timestamp_sql );
		$year_start_sql       = sprintf( "DATE_TRUNC('year', %s)", $timestamp_sql );
		$first_week_start_sql = $this->get_postgresql_mysql_first_sunday_four_day_week_of_year_sql( $year_start_sql );

		return $this->get_postgresql_mysql_zero_based_week_index_sql( $timestamp_sql, $week_start_sql, $first_week_start_sql );
	}

	/**
	 * Get PostgreSQL SQL for MySQL WEEK(expr, 5).
	 *
	 * Mode 5 is Monday-first, returns 0-53, and week 1 starts with the
	 * first Monday in the calendar year.
	 *
	 * @param string $timestamp_sql PostgreSQL timestamp expression.
	 * @return string PostgreSQL integer expression.
	 */
	private function get_postgresql_mysql_monday_week_mode_five_sql( string $timestamp_sql ): string {
		$week_start_sql       = sprintf( "DATE_TRUNC('week', %s)", $timestamp_sql );
		$year_start_sql       = sprintf( "DATE_TRUNC('year', %s)", $timestamp_sql );
		$first_week_start_sql = $this->get_postgresql_mysql_first_monday_of_year_sql( $year_start_sql );

		return $this->get_postgresql_mysql_zero_based_week_index_sql( $timestamp_sql, $week_start_sql, $first_week_start_sql );
	}

	/**
	 * Get PostgreSQL SQL for MySQL week modes that return 0 before the first week.
	 *
	 * @param string $timestamp_sql        PostgreSQL timestamp expression.
	 * @param string $week_start_sql       PostgreSQL week-start expression.
	 * @param string $first_week_start_sql PostgreSQL first-week-start expression.
	 * @return string PostgreSQL integer expression.
	 */
	private function get_postgresql_mysql_zero_based_week_index_sql( string $timestamp_sql, string $week_start_sql, string $first_week_start_sql ): string {
		return sprintf(
			'CASE WHEN %1$s IS NULL THEN NULL WHEN %2$s < %3$s THEN 0 ELSE CAST(FLOOR(EXTRACT(EPOCH FROM (%2$s - %3$s)) / 604800) AS integer) + 1 END',
			$timestamp_sql,
			$week_start_sql,
			$first_week_start_sql
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL WEEK(expr, 6).
	 *
	 * Mode 6 is Sunday-first, returns 1-53, and week 1 has four or more
	 * days in the week-year.
	 *
	 * @param string $timestamp_sql PostgreSQL timestamp expression.
	 * @return string PostgreSQL integer expression.
	 */
	private function get_postgresql_mysql_sunday_week_mode_six_sql( string $timestamp_sql ): string {
		$week_start_sql          = $this->get_postgresql_mysql_sunday_week_start_sql( $timestamp_sql );
		$year_start_sql          = sprintf( "DATE_TRUNC('year', %s)", $timestamp_sql );
		$first_week_start_sql    = $this->get_postgresql_mysql_first_sunday_four_day_week_of_year_sql( $year_start_sql );
		$previous_year_start_sql = sprintf( "(%s - INTERVAL '1 year')", $year_start_sql );
		$next_year_start_sql     = sprintf( "(%s + INTERVAL '1 year')", $year_start_sql );
		$previous_first_week_sql = $this->get_postgresql_mysql_first_sunday_four_day_week_of_year_sql( $previous_year_start_sql );
		$next_first_week_sql     = $this->get_postgresql_mysql_first_sunday_four_day_week_of_year_sql( $next_year_start_sql );

		return sprintf(
			'CASE WHEN %1$s IS NULL THEN NULL WHEN %2$s >= %5$s THEN 1 WHEN %2$s < %3$s THEN CAST(FLOOR(EXTRACT(EPOCH FROM (%2$s - %4$s)) / 604800) AS integer) + 1 ELSE CAST(FLOOR(EXTRACT(EPOCH FROM (%2$s - %3$s)) / 604800) AS integer) + 1 END',
			$timestamp_sql,
			$week_start_sql,
			$first_week_start_sql,
			$previous_first_week_sql,
			$next_first_week_sql
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL WEEK(expr, 7).
	 *
	 * Mode 7 is Monday-first, returns 1-53, and week 1 starts with the
	 * first Monday in the calendar year.
	 *
	 * @param string $timestamp_sql PostgreSQL timestamp expression.
	 * @return string PostgreSQL integer expression.
	 */
	private function get_postgresql_mysql_monday_week_mode_seven_sql( string $timestamp_sql ): string {
		$week_start_sql          = sprintf( "DATE_TRUNC('week', %s)", $timestamp_sql );
		$year_start_sql          = sprintf( "DATE_TRUNC('year', %s)", $timestamp_sql );
		$first_week_start_sql    = $this->get_postgresql_mysql_first_monday_of_year_sql( $year_start_sql );
		$previous_year_start_sql = sprintf( "(%s - INTERVAL '1 year')", $year_start_sql );
		$previous_first_week_sql = $this->get_postgresql_mysql_first_monday_of_year_sql( $previous_year_start_sql );

		return sprintf(
			'CASE WHEN %1$s IS NULL THEN NULL WHEN %2$s < %3$s THEN CAST(FLOOR(EXTRACT(EPOCH FROM (%2$s - %4$s)) / 604800) AS integer) + 1 ELSE CAST(FLOOR(EXTRACT(EPOCH FROM (%2$s - %3$s)) / 604800) AS integer) + 1 END',
			$timestamp_sql,
			$week_start_sql,
			$first_week_start_sql,
			$previous_first_week_sql
		);
	}

	/**
	 * Get PostgreSQL SQL for the Sunday-start week containing a timestamp.
	 *
	 * @param string $timestamp_sql PostgreSQL timestamp expression.
	 * @return string PostgreSQL timestamp expression.
	 */
	private function get_postgresql_mysql_sunday_week_start_sql( string $timestamp_sql ): string {
		return sprintf(
			"(DATE_TRUNC('day', %1\$s) - (CAST(EXTRACT(DOW FROM %1\$s) AS integer) * INTERVAL '1 day'))",
			$timestamp_sql
		);
	}

	/**
	 * Get PostgreSQL SQL for the first Sunday in a year.
	 *
	 * @param string $year_start_sql PostgreSQL timestamp expression for January 1.
	 * @return string PostgreSQL timestamp expression.
	 */
	private function get_postgresql_mysql_first_sunday_of_year_sql( string $year_start_sql ): string {
		return sprintf(
			"(%1\$s + (MOD(7 - CAST(EXTRACT(DOW FROM %1\$s) AS integer), 7) * INTERVAL '1 day'))",
			$year_start_sql
		);
	}

	/**
	 * Get PostgreSQL SQL for the first Sunday-start week with four days in a year.
	 *
	 * @param string $year_start_sql PostgreSQL timestamp expression for January 1.
	 * @return string PostgreSQL timestamp expression.
	 */
	private function get_postgresql_mysql_first_sunday_four_day_week_of_year_sql( string $year_start_sql ): string {
		$week_start_sql = $this->get_postgresql_mysql_sunday_week_start_sql( $year_start_sql );

		return sprintf(
			"(CASE WHEN EXTRACT(DOW FROM %1\$s) <= 3 THEN %2\$s ELSE %2\$s + INTERVAL '1 week' END)",
			$year_start_sql,
			$week_start_sql
		);
	}

	/**
	 * Get PostgreSQL SQL for the first Monday in a year.
	 *
	 * @param string $year_start_sql PostgreSQL timestamp expression for January 1.
	 * @return string PostgreSQL timestamp expression.
	 */
	private function get_postgresql_mysql_first_monday_of_year_sql( string $year_start_sql ): string {
		return sprintf(
			"(%1\$s + (MOD(8 - CAST(EXTRACT(ISODOW FROM %1\$s) AS integer), 7) * INTERVAL '1 day'))",
			$year_start_sql
		);
	}

	/**
	 * Get PostgreSQL SQL for a MySQL ordinal day value.
	 *
	 * @param string $day_sql PostgreSQL integer day expression.
	 * @return string PostgreSQL SQL fragment.
	 */
	private function get_postgresql_mysql_day_with_suffix_sql( string $day_sql ): string {
		return sprintf(
			'CAST(%1$s AS text) || CASE WHEN %1$s %% 100 BETWEEN 11 AND 13 THEN \'th\' WHEN %1$s %% 10 = 1 THEN \'st\' WHEN %1$s %% 10 = 2 THEN \'nd\' WHEN %1$s %% 10 = 3 THEN \'rd\' ELSE \'th\' END',
			$day_sql
		);
	}

	/**
	 * Translate supported MySQL date/time extract functions to PostgreSQL.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_date_time_extract_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_extract_function_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$bounds['expression_start'],
			$bounds['expression_end']
		);

		return $this->get_postgresql_mysql_expression_translation(
			$this->get_postgresql_zero_date_safe_extract_sql( $bounds['unit'], $expression_sql ),
			$tokens[ $position ]->id,
			$bounds['close']
		);
	}

	/**
	 * Get PostgreSQL SQL for a MySQL date/time extract that preserves MySQL zero-date behavior.
	 *
	 * PostgreSQL rejects MySQL zero-ish dates such as 0000-00-00 during timestamp
	 * casts. Detect those text-backed values first and extract the requested
	 * numeric part directly from the text; keep valid dates on PostgreSQL's
	 * timestamp EXTRACT path.
	 *
	 * @param string $unit           PostgreSQL EXTRACT unit.
	 * @param string $expression_sql PostgreSQL expression SQL.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_zero_date_safe_extract_sql( string $unit, string $expression_sql ): string {
		$expression_text_sql  = sprintf( 'CAST(%s AS text)', $expression_sql );
		$empty_date_condition = $this->get_postgresql_empty_temporal_condition_sql( $expression_text_sql );
		$zero_date_condition  = $this->get_postgresql_zero_date_condition_sql( $expression_text_sql );

		if ( 'MICROSECOND' === $unit ) {
			return sprintf(
				"CASE WHEN %1\$s THEN NULL WHEN %2\$s THEN CAST(%3\$s AS integer) ELSE CAST(TO_CHAR(%4\$s, 'US') AS integer) END",
				$empty_date_condition,
				$zero_date_condition,
				$this->get_postgresql_mysql_zero_date_microsecond_sql( $expression_text_sql ),
				$this->get_postgresql_zero_date_safe_timestamp_sql( $expression_sql )
			);
		}

		return sprintf(
			'CASE WHEN %1$s THEN NULL WHEN %2$s THEN %3$s ELSE CAST(EXTRACT(%4$s FROM %5$s) AS integer) END',
			$empty_date_condition,
			$zero_date_condition,
			$this->get_postgresql_zero_date_extract_part_sql( $unit, $expression_text_sql ),
			$unit,
			$this->get_postgresql_zero_date_safe_timestamp_sql( $expression_sql )
		);
	}

	/**
	 * Get PostgreSQL SQL that casts a MySQL date/time expression without casting zero dates.
	 *
	 * @param string $expression_sql PostgreSQL expression SQL.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_zero_date_safe_timestamp_sql( string $expression_sql ): string {
		$expression_text_sql = sprintf( 'CAST(%s AS text)', $expression_sql );

		return sprintf(
			'CAST(CASE WHEN %1$s OR %2$s THEN NULL ELSE %3$s END AS timestamp)',
			$this->get_postgresql_empty_temporal_condition_sql( $expression_text_sql ),
			$this->get_postgresql_zero_date_condition_sql( $expression_text_sql ),
			$expression_text_sql
		);
	}

	/**
	 * Get a condition that detects MySQL empty temporal strings.
	 *
	 * @param string $expression_text_sql PostgreSQL expression cast to text.
	 * @return string PostgreSQL condition SQL.
	 */
	private function get_postgresql_empty_temporal_condition_sql( string $expression_text_sql ): string {
		return sprintf( "%s = ''", $expression_text_sql );
	}

	/**
	 * Get a condition that detects MySQL zero or partial-zero date strings.
	 *
	 * @param string $expression_text_sql PostgreSQL expression cast to text.
	 * @return string PostgreSQL condition SQL.
	 */
	private function get_postgresql_zero_date_condition_sql( string $expression_text_sql ): string {
		$date_text_pattern = "'^[0-9]{4}-[0-9]{2}-[0-9]{2}'";

		return sprintf(
			'%1$s ~ %2$s AND (SUBSTRING(%1$s FROM 1 FOR 4) = \'0000\' OR SUBSTRING(%1$s FROM 6 FOR 2) = \'00\' OR SUBSTRING(%1$s FROM 9 FOR 2) = \'00\')',
			$expression_text_sql,
			$date_text_pattern
		);
	}

	/**
	 * Get PostgreSQL SQL that extracts one part from a zero-ish MySQL date string.
	 *
	 * @param string $unit                PostgreSQL EXTRACT unit.
	 * @param string $expression_text_sql PostgreSQL expression cast to text.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_zero_date_extract_part_sql( string $unit, string $expression_text_sql ): string {
		$date_time_text_pattern = "'^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T][0-9]{2}:[0-9]{2}:[0-9]{2}'";

		if ( 'DOY' === $unit ) {
			return 'NULL';
		}

		$date_part_starts = array(
			'YEAR'  => array( 1, 4 ),
			'MONTH' => array( 6, 2 ),
			'DAY'   => array( 9, 2 ),
		);
		if ( isset( $date_part_starts[ $unit ] ) ) {
			return sprintf( 'CAST(SUBSTRING(%s FROM %d FOR %d) AS integer)', $expression_text_sql, $date_part_starts[ $unit ][0], $date_part_starts[ $unit ][1] );
		}

		if ( 'QUARTER' === $unit ) {
			return sprintf( 'CAST(FLOOR((CAST(SUBSTRING(%s FROM 6 FOR 2) AS integer) + 2) / 3.0) AS integer)', $expression_text_sql );
		}

		$time_part_starts = array(
			'HOUR'   => 12,
			'MINUTE' => 15,
			'SECOND' => 18,
		);
		if ( ! isset( $time_part_starts[ $unit ] ) ) {
			return sprintf( 'CAST(EXTRACT(%s FROM CAST(%s AS timestamp)) AS integer)', $unit, $expression_text_sql );
		}

		return sprintf(
			'CASE WHEN %1$s ~ %2$s THEN CAST(SUBSTRING(%1$s FROM %3$d FOR 2) AS integer) ELSE 0 END',
			$expression_text_sql,
			$date_time_text_pattern,
			$time_part_starts[ $unit ]
		);
	}

	/**
	 * Get token bounds for supported MySQL date/time extract forms.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{unit: string, expression_start: int, expression_end: int, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_extract_function_bounds( array $tokens, int $position, int $end ): ?array {
		if ( ! isset( $tokens[ $position ], $tokens[ $position + 1 ] ) ) {
			return null;
		}

		if ( WP_MySQL_Lexer::EXTRACT_SYMBOL === $tokens[ $position ]->id ) {
			return $this->get_mysql_extract_keyword_bounds( $tokens, $position, $end );
		}

		return $this->get_mysql_date_time_function_bounds( $tokens, $position, $end );
	}

	/**
	 * Get token bounds for EXTRACT(unit FROM expr).
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position EXTRACT token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{unit: string, expression_start: int, expression_end: int, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_extract_keyword_bounds( array $tokens, int $position, int $end ): ?array {
		if (
			! isset( $tokens[ $position + 3 ] )
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
			|| WP_MySQL_Lexer::FROM_SYMBOL !== $tokens[ $position + 3 ]->id
		) {
			return null;
		}

		$unit = $this->get_mysql_date_time_extract_unit( $tokens[ $position + 2 ] );
		if ( null === $unit ) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $end );
		if ( null === $after_close || $position + 4 >= $after_close - 1 ) {
			return null;
		}

		return array(
			'unit'             => $unit,
			'expression_start' => $position + 4,
			'expression_end'   => $after_close - 1,
			'close'            => $after_close - 1,
		);
	}

	/**
	 * Get token bounds for YEAR(expr), MONTH(expr), DAY(expr), and similar calls.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{unit: string, expression_start: int, expression_end: int, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_date_time_function_bounds( array $tokens, int $position, int $end ): ?array {
		$unit = $this->get_mysql_date_time_extract_unit( $tokens[ $position ] );
		if (
			null === $unit
			|| ! isset( $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		$close_position = $after_close - 1;
		if (
			$position + 2 >= $close_position
			|| null !== $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::COMMA_SYMBOL,
				$position + 2,
				$close_position
			)
		) {
			return null;
		}

		return array(
			'unit'             => $unit,
			'expression_start' => $position + 2,
			'expression_end'   => $close_position,
			'close'            => $close_position,
		);
	}

	/**
	 * Get the PostgreSQL EXTRACT unit for a MySQL date/time token.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return string|null PostgreSQL EXTRACT unit, or null when unsupported.
	 */
	private function get_mysql_date_time_extract_unit( WP_MySQL_Token $token ): ?string {
		$units = array(
			WP_MySQL_Lexer::YEAR_SYMBOL        => 'YEAR',
			WP_MySQL_Lexer::MONTH_SYMBOL       => 'MONTH',
			WP_MySQL_Lexer::QUARTER_SYMBOL     => 'QUARTER',
			WP_MySQL_Lexer::DAY_SYMBOL         => 'DAY',
			WP_MySQL_Lexer::DAYOFMONTH_SYMBOL  => 'DAY',
			WP_MySQL_Lexer::HOUR_SYMBOL        => 'HOUR',
			WP_MySQL_Lexer::MINUTE_SYMBOL      => 'MINUTE',
			WP_MySQL_Lexer::SECOND_SYMBOL      => 'SECOND',
			WP_MySQL_Lexer::MICROSECOND_SYMBOL => 'MICROSECOND',
		);
		if ( isset( $units[ $token->id ] ) ) {
			return $units[ $token->id ];
		}

		$name = $this->get_mysql_identifier_token_value( $token );
		if ( null !== $name && 0 === strcasecmp( $name, 'dayofyear' ) ) {
			return 'DOY';
		}

		return null;
	}

	/**
	 * Translate a MySQL CONVERT(expr USING charset) expression to PostgreSQL.
	 *
	 * PostgreSQL text is already stored in the database encoding, so the MySQL
	 * character-set conversion is represented by the inner expression. A directly
	 * attached MySQL COLLATE clause is dropped because PostgreSQL does not have
	 * MySQL collation names.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position CONVERT token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_convert_using_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_convert_using_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		$final_position = $bounds['close'];
		if (
			isset( $tokens[ $final_position + 1 ], $tokens[ $final_position + 2 ] )
			&& $final_position + 2 < $end
			&& WP_MySQL_Lexer::COLLATE_SYMBOL === $tokens[ $final_position + 1 ]->id
			&& null !== $this->get_mysql_identifier_token_value( $tokens[ $final_position + 2 ] )
		) {
			$final_position += 2;
		}

		$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$bounds['expression_start'],
			$bounds['expression_end']
		);

		return array(
			'sql'      => '(' . $expression_sql . ')',
			'token_id' => $tokens[ $bounds['expression_start'] ]->id,
			'position' => $final_position,
		);
	}

	/**
	 * Get token bounds for a supported MySQL CONVERT(expr USING charset) expression.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position CONVERT token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{expression_start: int, expression_end: int, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_convert_using_bounds( array $tokens, int $position, int $end ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::CONVERT_SYMBOL !== $tokens[ $position ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		$close_position = $after_close - 1;
		$using_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::USING_SYMBOL,
			$position + 2,
			$close_position
		);
		if (
			null === $using_position
			|| $using_position <= $position + 2
			|| $using_position + 2 !== $close_position
			|| ! $this->is_mysql_charset_token( $tokens[ $using_position + 1 ] ?? null )
		) {
			return null;
		}

		return array(
			'expression_start' => $position + 2,
			'expression_end'   => $using_position,
			'close'            => $close_position,
		);
	}

	/**
	 * Translate a single MySQL token to a PostgreSQL fragment.
	 *
	 * @param WP_MySQL_Token      $token      MySQL token.
	 * @param WP_MySQL_Token|null $next_token Next MySQL token, if known.
	 * @return string PostgreSQL SQL fragment.
	 */
	private function translate_mysql_token_to_postgresql( WP_MySQL_Token $token, ?WP_MySQL_Token $next_token = null ): string {
		if (
			WP_MySQL_Lexer::IDENTIFIER === $token->id
			&& $this->should_quote_bare_mysql_identifier( $token->get_value() )
			&& ( null === $next_token || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $next_token->id )
		) {
			return $this->connection->quote_identifier( $token->get_value() );
		}

		if ( WP_MySQL_Lexer::BACK_TICK_QUOTED_ID === $token->id ) {
			return $this->connection->quote_identifier( $token->get_value() );
		}

		if ( WP_MySQL_Lexer::SINGLE_QUOTED_TEXT === $token->id || WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $token->id ) {
			return $this->connection->quote( $token->get_value() );
		}

		if ( WP_MySQL_Lexer::LOGICAL_OR_OPERATOR === $token->id ) {
			return 'OR';
		}

		if ( WP_MySQL_Lexer::LOGICAL_AND_OPERATOR === $token->id ) {
			return 'AND';
		}

		return $token->get_bytes();
	}

	/**
	 * Translate a MySQL identifier token to a PostgreSQL identifier fragment.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return string PostgreSQL identifier fragment.
	 */
	private function translate_mysql_identifier_token_to_postgresql( ?WP_MySQL_Token $token ): string {
		if ( null === $token ) {
			return '';
		}

		return $this->translate_mysql_token_to_postgresql( $token );
	}

	/**
	 * Check whether two translated tokens should be joined without a space.
	 *
	 * @param int|null $previous_token_id Previous token ID.
	 * @param int      $token_id          Current token ID.
	 * @return bool Whether no separator should be added.
	 */
	private function should_join_mysql_tokens_without_space( ?int $previous_token_id, int $token_id ): bool {
		return in_array(
			$token_id,
			array(
				WP_MySQL_Lexer::CLOSE_PAR_SYMBOL,
				WP_MySQL_Lexer::COMMA_SYMBOL,
				WP_MySQL_Lexer::DOT_SYMBOL,
				WP_MySQL_Lexer::SEMICOLON_SYMBOL,
			),
			true
		) || in_array(
			$previous_token_id,
			array(
				WP_MySQL_Lexer::DOT_SYMBOL,
				WP_MySQL_Lexer::OPEN_PAR_SYMBOL,
			),
			true
		);
	}

	/**
	 * Get a MySQL identifier token value.
	 *
	 * @param WP_MySQL_Token|null $token               MySQL token.
	 * @param bool                $allow_double_quoted Whether to accept double-quoted text as an identifier.
	 * @return string|null Identifier value, or null when the token is unsupported.
	 */
	private function get_mysql_identifier_token_value( ?WP_MySQL_Token $token, bool $allow_double_quoted = false ): ?string {
		if ( null === $token ) {
			return null;
		}

		if ( WP_MySQL_Lexer::IDENTIFIER === $token->id || WP_MySQL_Lexer::BACK_TICK_QUOTED_ID === $token->id ) {
			return $token->get_value();
		}

		if ( $allow_double_quoted && WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $token->id ) {
			return $token->get_value();
		}

		return null;
	}

	/**
	 * Get an identifier token value in DML column contexts.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return string|null Identifier value, or null when unsupported.
	 */
	private function get_mysql_dml_identifier_token_value( ?WP_MySQL_Token $token ): ?string {
		$identifier = $this->get_mysql_identifier_token_value( $token );
		if ( null !== $identifier ) {
			return $identifier;
		}

		if (
			null !== $token
			&& in_array(
				$token->id,
				array(
					WP_MySQL_Lexer::COMMENT_SYMBOL,
					WP_MySQL_Lexer::STATUS_SYMBOL,
					WP_MySQL_Lexer::TIMESTAMP_SYMBOL,
					WP_MySQL_Lexer::VALUE_SYMBOL,
				),
				true
			)
		) {
			return $token->get_value();
		}

		return null;
	}

	/**
	 * Check whether a token is an identifier-like token with the expected value.
	 *
	 * Some MySQL information_schema column names, such as TABLE_NAME, are lexed
	 * as keyword tokens. Treat them like identifiers only in explicit catalog
	 * translator contexts.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @param string              $value Expected identifier value.
	 * @return bool Whether the token has the expected identifier-like value.
	 */
	private function is_mysql_identifier_like_token_value( ?WP_MySQL_Token $token, string $value ): bool {
		if ( null === $token ) {
			return false;
		}

		$identifier = $this->get_mysql_identifier_token_value( $token );
		if ( null === $identifier && WP_MySQL_Lexer::TABLE_NAME_SYMBOL === $token->id ) {
			$identifier = $token->get_value();
		}

		return null !== $identifier && strtolower( $identifier ) === strtolower( $value );
	}

	/**
	 * Check whether a token's semantic value matches a keyword or identifier.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @param string              $value Expected value.
	 * @return bool Whether the token value matches.
	 */
	private function is_mysql_token_value( ?WP_MySQL_Token $token, string $value ): bool {
		if ( null === $token ) {
			return false;
		}

		return strtolower( $token->get_value() ) === strtolower( $value );
	}

	/**
	 * Check whether a token can represent a MySQL character set name.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return bool Whether the token is a supported charset token.
	 */
	private function is_mysql_charset_token( ?WP_MySQL_Token $token ): bool {
		if ( null === $token ) {
			return false;
		}

		return null !== $this->get_mysql_identifier_token_value( $token )
			|| in_array(
				$token->id,
				array(
					WP_MySQL_Lexer::ASCII_SYMBOL,
					WP_MySQL_Lexer::BINARY_SYMBOL,
					WP_MySQL_Lexer::DEFAULT_SYMBOL,
					WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT,
					WP_MySQL_Lexer::SINGLE_QUOTED_TEXT,
				),
				true
			);
	}

	/**
	 * Get a MySQL charset/collation token value.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return string Token value.
	 */
	private function get_mysql_charset_token_value( WP_MySQL_Token $token ): string {
		if ( WP_MySQL_Lexer::DEFAULT_SYMBOL === $token->id ) {
			return 'default';
		}

		return $token->get_value();
	}

	/**
	 * Check whether a bare MySQL identifier needs PostgreSQL quoting.
	 *
	 * @param string $identifier Identifier token value.
	 * @return bool Whether the bare identifier must be quoted.
	 */
	private function should_quote_bare_mysql_identifier( string $identifier ): bool {
		return strtolower( $identifier ) !== $identifier;
	}

	/**
	 * Check whether a token range needs the compatibility rewrite.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return bool Whether any token needs PostgreSQL compatibility rewriting.
	 */
	private function needs_mysql_compatible_rewrite( array $tokens, int $start, int $end ): bool {
		for ( $i = $start; $i < $end; $i++ ) {
			$token = $tokens[ $i ];
			if ( WP_MySQL_Lexer::BACK_TICK_QUOTED_ID === $token->id ) {
				return true;
			}

			if ( WP_MySQL_Lexer::SINGLE_QUOTED_TEXT === $token->id ) {
				return true;
			}

			if ( WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $token->id ) {
				return true;
			}

			if ( WP_MySQL_Lexer::LOGICAL_OR_OPERATOR === $token->id || WP_MySQL_Lexer::LOGICAL_AND_OPERATOR === $token->id ) {
				return true;
			}

			if (
				WP_MySQL_Lexer::AT_TEXT_SUFFIX === $token->id
				|| WP_MySQL_Lexer::AT_AT_SIGN_SYMBOL === $token->id
			) {
				return true;
			}

			if ( null !== $this->get_mysql_convert_using_bounds( $tokens, $i, $end ) ) {
				return true;
			}

			if ( null !== $this->translate_mysql_dual_table_reference_to_postgresql( $tokens, $i, $end ) ) {
				return true;
			}

			if ( null !== $this->get_mysql_index_hint_bounds( $tokens, $i, $end ) ) {
				return true;
			}

			if ( null !== $this->get_mysql_function_call_bounds( $tokens, $i, $end, 'field' ) ) {
				return true;
			}

			if (
				null !== $this->get_mysql_typed_cast_or_convert_bounds(
					$tokens,
					$i,
					$end,
					array(
						'cast'    => array( 'integer', 'date_time', 'date', 'binary' ),
						'convert' => array( 'integer', 'character', 'binary', 'decimal', 'date' ),
					)
				)
			) {
				return true;
			}

			if ( null !== $this->translate_mysql_regexp_operator_to_postgresql( $tokens, $i, $end ) ) {
				return true;
			}

			if ( null !== $this->translate_mysql_group_concat_function_to_postgresql( $tokens, $i, $end ) ) {
				return true;
			}

			if ( null !== $this->get_mysql_function_call_bounds( $tokens, $i, $end, 'rand' ) ) {
				return true;
			}

			if ( null !== $this->translate_mysql_session_user_function_to_postgresql( $tokens, $i, $end ) ) {
				return true;
			}

			if ( null !== $this->translate_mysql_nonparenthesized_timestamp_function_to_postgresql( $tokens, $i, $end ) ) {
				return true;
			}

			if ( null !== $this->translate_mysql_common_function_to_postgresql( $tokens, $i, $end ) ) {
				return true;
			}

			if ( null !== $this->get_mysql_date_arithmetic_function_bounds( $tokens, $i, $end ) ) {
				return true;
			}

			if ( null !== $this->get_mysql_week_function_bounds( $tokens, $i, $end ) ) {
				return true;
			}

			if ( null !== $this->get_mysql_weekday_index_function_bounds( $tokens, $i, $end ) ) {
				return true;
			}

			if ( null !== $this->get_mysql_date_format_call_bounds( $tokens, $i, $end ) ) {
				return true;
			}

			if ( null !== $this->get_mysql_limit_offset_count_bounds( $tokens, $i, $end ) ) {
				return true;
			}

			if ( null !== $this->get_mysql_extract_function_bounds( $tokens, $i, $end ) ) {
				return true;
			}

			if (
				WP_MySQL_Lexer::IDENTIFIER === $token->id
				&& $this->should_quote_bare_mysql_identifier( $token->get_value() )
				&& ( ! isset( $tokens[ $i + 1 ] ) || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $i + 1 ]->id )
			) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether a query still contains raw MySQL optimizer index hint syntax.
	 *
	 * @param string $query SQL query.
	 * @return bool Whether raw MySQL index hint syntax remains.
	 */
	private function contains_mysql_index_hint_syntax( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		for ( $i = 0; isset( $tokens[ $i ] ) && WP_MySQL_Lexer::EOF !== $tokens[ $i ]->id; $i++ ) {
			if ( $this->is_mysql_index_hint_marker( $tokens, $i, count( $tokens ) ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether a query is a supported MySQL CREATE TABLE statement.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the query should be translated before execution.
	 */
	private function is_create_table_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );

		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::CREATE_SYMBOL !== $tokens[0]->id ) {
			return false;
		}

		$position = 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::TEMPORARY_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		$table_name_position = $position + 1;

		return isset( $tokens[ $position ] )
			&& WP_MySQL_Lexer::TABLE_SYMBOL === $tokens[ $position ]->id
			&& (
				$this->has_mysql_create_table_marker( $tokens )
				|| $this->is_mysql_create_table_qualified_target( $tokens, $table_name_position )
			);
	}

	/**
	 * Parse the target of a supported CREATE TABLE statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{schema: string, table: string, temporary: bool}|null Parsed target, or null.
	 */
	private function get_mysql_create_table_target( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		$prefix = $this->get_mysql_create_table_prefix( $tokens );
		if ( null === $prefix ) {
			return null;
		}

		$position     = $prefix['position'];
		$is_temporary = $prefix['temporary'];

		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position, true );
		if ( null === $table_reference || ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position ]->id ) ) {
			throw new InvalidArgumentException( 'Unsupported CREATE TABLE statement.' );
		}

		return array(
			'schema'    => $this->get_mysql_create_table_select_backend_schema( $table_reference, $is_temporary ),
			'table'     => $table_reference['table'],
			'temporary' => $is_temporary,
		);
	}

	/**
	 * Check whether CREATE TABLE IF NOT EXISTS targets an existing table.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the statement should be a MySQL-compatible no-op.
	 */
	private function mysql_create_table_if_not_exists_target_exists( string $query ): bool {
		$target = $this->get_mysql_create_table_if_not_exists_target( $query );
		if ( null === $target ) {
			return false;
		}

		return $this->mysql_create_table_target_exists( $target['schema'], $target['table'], $target['temporary'] );
	}

	/**
	 * Parse the target of a CREATE TABLE IF NOT EXISTS statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{schema: string, table: string, temporary: bool}|null Parsed target, or null when this is not IF NOT EXISTS.
	 */
	private function get_mysql_create_table_if_not_exists_target( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		$prefix = $this->get_mysql_create_table_prefix( $tokens );
		if ( null === $prefix || ! $prefix['if_not_exists'] ) {
			return null;
		}

		$position        = $prefix['position'];
		$is_temporary    = $prefix['temporary'];
		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position, true );
		if ( null === $table_reference || $this->is_at_mysql_query_end( $tokens, $position ) ) {
			return null;
		}

		return array(
			'schema'    => $this->get_mysql_create_table_select_backend_schema( $table_reference, $is_temporary ),
			'table'     => $table_reference['table'],
			'temporary' => $is_temporary,
		);
	}

	/**
	 * Check whether a CREATE TABLE target already exists in the backend.
	 *
	 * @param string $schema_name  Backend schema name.
	 * @param string $table_name   Table name.
	 * @param bool   $is_temporary Whether the target is temporary.
	 * @return bool Whether the target exists.
	 */
	private function mysql_create_table_target_exists( string $schema_name, string $table_name, bool $is_temporary ): bool {
		if ( $is_temporary ) {
			return null !== $this->get_active_temporary_table_schema( $table_name );
		}

		if ( 'sqlite' === $this->connection->get_driver_name() ) {
			return $this->sqlite_table_administration_table_exists( $schema_name, $table_name );
		}

		$stmt = $this->connection->query(
			'SELECT 1
			FROM pg_catalog.pg_class c
			INNER JOIN pg_catalog.pg_namespace n
				ON n.oid = c.relnamespace
			WHERE n.nspname = ?
				AND c.relname = ?
				AND c.relkind IN (\'r\', \'p\')
			LIMIT 1',
			array( $schema_name, $table_name )
		);

		return false !== $stmt->fetchColumn();
	}

	/**
	 * Check whether a CREATE TABLE statement uses a qualified table target.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Table-name position.
	 * @return bool Whether the table target is qualified.
	 */
	private function is_mysql_create_table_qualified_target( array $tokens, int $position ): bool {
		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
			&& WP_MySQL_Lexer::IF_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $position + 1 ]->id
			&& WP_MySQL_Lexer::EXISTS_SYMBOL === $tokens[ $position + 2 ]->id
		) {
			$position += 3;
		}

		return null !== $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null )
			&& isset( $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position + 1 ]->id
			&& null !== $this->get_mysql_identifier_token_value( $tokens[ $position + 2 ] ?? null );
	}

	/**
	 * Check whether a CREATE TABLE query creates a temporary table.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the query is CREATE TEMPORARY TABLE.
	 */
	private function is_temporary_create_table_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );

		return isset( $tokens[0], $tokens[1], $tokens[2] )
			&& WP_MySQL_Lexer::CREATE_SYMBOL === $tokens[0]->id
			&& WP_MySQL_Lexer::TEMPORARY_SYMBOL === $tokens[1]->id
			&& WP_MySQL_Lexer::TABLE_SYMBOL === $tokens[2]->id;
	}

	/**
	 * Check whether a CREATE TABLE query contains MySQL install-schema syntax.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @return bool Whether the query should use the install DDL translator.
	 */
	private function has_mysql_create_table_marker( array $tokens ): bool {
		foreach ( $tokens as $position => $token ) {
			if ( $this->is_mysql_create_table_charset_set_marker( $tokens, $position ) ) {
				return true;
			}

			if ( $this->is_mysql_create_table_secondary_index_marker( $tokens, $position ) ) {
				return true;
			}

			if ( $this->is_mysql_create_table_foreign_key_marker( $tokens, $position ) ) {
				return true;
			}

			if ( $this->is_mysql_create_table_primary_key_index_option_marker( $tokens, $position ) ) {
				return true;
			}

			if (
				WP_MySQL_Lexer::ON_SYMBOL === $token->id
				&& isset( $tokens[ $position + 1 ] )
				&& WP_MySQL_Lexer::UPDATE_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				return true;
			}

			if (
				in_array(
					$token->id,
					array(
						WP_MySQL_Lexer::AUTO_INCREMENT_SYMBOL,
						WP_MySQL_Lexer::AUTOEXTEND_SIZE_SYMBOL,
						WP_MySQL_Lexer::AVG_ROW_LENGTH_SYMBOL,
						WP_MySQL_Lexer::BACK_TICK_QUOTED_ID,
						WP_MySQL_Lexer::BINARY_SYMBOL,
						WP_MySQL_Lexer::BIT_SYMBOL,
						WP_MySQL_Lexer::BLOB_SYMBOL,
						WP_MySQL_Lexer::BOOLEAN_SYMBOL,
						WP_MySQL_Lexer::BOOL_SYMBOL,
						WP_MySQL_Lexer::CHARSET_SYMBOL,
						WP_MySQL_Lexer::CHECK_SYMBOL,
						WP_MySQL_Lexer::CHECKSUM_SYMBOL,
						WP_MySQL_Lexer::COLLATE_SYMBOL,
						WP_MySQL_Lexer::COMMENT_SYMBOL,
						WP_MySQL_Lexer::COMPRESSION_SYMBOL,
						WP_MySQL_Lexer::CONNECTION_SYMBOL,
						WP_MySQL_Lexer::DATE_SYMBOL,
						WP_MySQL_Lexer::DATETIME_SYMBOL,
						WP_MySQL_Lexer::DEC_SYMBOL,
						WP_MySQL_Lexer::DELAY_KEY_WRITE_SYMBOL,
						WP_MySQL_Lexer::DIRECTORY_SYMBOL,
						WP_MySQL_Lexer::ENCRYPTION_SYMBOL,
						WP_MySQL_Lexer::ENFORCED_SYMBOL,
						WP_MySQL_Lexer::ENGINE_SYMBOL,
						WP_MySQL_Lexer::ENGINE_ATTRIBUTE_SYMBOL,
						WP_MySQL_Lexer::FIXED_SYMBOL,
						WP_MySQL_Lexer::FULLTEXT_SYMBOL,
						WP_MySQL_Lexer::INSERT_METHOD_SYMBOL,
						WP_MySQL_Lexer::JSON_SYMBOL,
						WP_MySQL_Lexer::KEY_BLOCK_SIZE_SYMBOL,
						WP_MySQL_Lexer::LONGBLOB_SYMBOL,
						WP_MySQL_Lexer::LONG_SYMBOL,
						WP_MySQL_Lexer::MEDIUMBLOB_SYMBOL,
						WP_MySQL_Lexer::MAX_ROWS_SYMBOL,
						WP_MySQL_Lexer::MIN_ROWS_SYMBOL,
						WP_MySQL_Lexer::PACK_KEYS_SYMBOL,
						WP_MySQL_Lexer::PASSWORD_SYMBOL,
						WP_MySQL_Lexer::REAL_SYMBOL,
						WP_MySQL_Lexer::ROW_FORMAT_SYMBOL,
						WP_MySQL_Lexer::SECONDARY_ENGINE_SYMBOL,
						WP_MySQL_Lexer::SECONDARY_ENGINE_ATTRIBUTE_SYMBOL,
						WP_MySQL_Lexer::SPATIAL_SYMBOL,
						WP_MySQL_Lexer::STATS_AUTO_RECALC_SYMBOL,
						WP_MySQL_Lexer::STATS_PERSISTENT_SYMBOL,
						WP_MySQL_Lexer::STATS_SAMPLE_PAGES_SYMBOL,
						WP_MySQL_Lexer::TABLESPACE_SYMBOL,
						WP_MySQL_Lexer::TIME_SYMBOL,
						WP_MySQL_Lexer::TIMESTAMP_SYMBOL,
						WP_MySQL_Lexer::TINYBLOB_SYMBOL,
						WP_MySQL_Lexer::UNSIGNED_SYMBOL,
						WP_MySQL_Lexer::UNION_SYMBOL,
						WP_MySQL_Lexer::VARBINARY_SYMBOL,
						WP_MySQL_Lexer::YEAR_SYMBOL,
					),
					true
				)
				) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether a CREATE TABLE token introduces a FOREIGN KEY definition.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position.
	 * @return bool Whether the tokens are a FOREIGN KEY marker.
	 */
	private function is_mysql_create_table_foreign_key_marker( array $tokens, int $position ): bool {
		return isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::FOREIGN_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::KEY_SYMBOL === $tokens[ $position + 1 ]->id;
	}

	/**
	 * Check whether a CREATE TABLE token introduces a MySQL secondary index definition.
	 *
	 * PostgreSQL-compatible PRIMARY KEY clauses can fall through to the backend
	 * parser, but MySQL KEY/INDEX table elements must use the DDL translator even
	 * when the statement has no other MySQL-only markers.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position.
	 * @return bool Whether the token is a secondary KEY/INDEX marker.
	 */
	private function is_mysql_create_table_secondary_index_marker( array $tokens, int $position ): bool {
		if (
			! isset( $tokens[ $position ] )
			|| ! in_array( $tokens[ $position ]->id, array( WP_MySQL_Lexer::KEY_SYMBOL, WP_MySQL_Lexer::INDEX_SYMBOL ), true )
		) {
			return false;
		}

		$previous_token = $tokens[ $position - 1 ] ?? null;
		return null === $previous_token
			|| ! in_array( $previous_token->id, array( WP_MySQL_Lexer::PRIMARY_SYMBOL, WP_MySQL_Lexer::FOREIGN_SYMBOL ), true );
	}

	/**
	 * Check whether a CREATE TABLE PRIMARY KEY clause uses MySQL index options.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position.
	 * @return bool Whether the token is a PRIMARY KEY option marker.
	 */
	private function is_mysql_create_table_primary_key_index_option_marker( array $tokens, int $position ): bool {
		return isset( $tokens[ $position ], $tokens[ $position - 1 ], $tokens[ $position - 2 ] )
			&& WP_MySQL_Lexer::USING_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::KEY_SYMBOL === $tokens[ $position - 1 ]->id
			&& WP_MySQL_Lexer::PRIMARY_SYMBOL === $tokens[ $position - 2 ]->id;
	}

	/**
	 * Check whether tokens at a position form CHAR SET or CHARACTER SET.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position.
	 * @return bool Whether this is a MySQL charset marker.
	 */
	private function is_mysql_create_table_charset_set_marker( array $tokens, int $position ): bool {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::SET_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return false;
		}

		if ( WP_MySQL_Lexer::CHARACTER_SYMBOL === $tokens[ $position ]->id ) {
			return true;
		}

		return WP_MySQL_Lexer::CHAR_SYMBOL === $tokens[ $position ]->id
			&& in_array( strtolower( $tokens[ $position ]->get_bytes() ), array( 'char', 'character' ), true );
	}

	/**
	 * Get a simple MySQL variable SELECT query.
	 *
	 * @param string $query MySQL query.
	 * @return array{columns: string[], row: array<string, string|null>}|null Parsed variable query, or null when not applicable.
	 */
	private function get_mysql_variable_select_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id
			|| (
				WP_MySQL_Lexer::AT_TEXT_SUFFIX !== $tokens[1]->id
				&& WP_MySQL_Lexer::AT_AT_SIGN_SYMBOL !== $tokens[1]->id
			)
		) {
			return null;
		}

		$position = 1;
		$columns  = array();
		$row      = array();

		while ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::EOF !== $tokens[ $position ]->id ) {
			$variable = $this->parse_mysql_select_variable_reference( $tokens, $position );
			if ( null === $variable ) {
				throw new InvalidArgumentException( 'Unsupported MySQL variable SELECT statement.' );
			}

			$column = $variable['display'];
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $position ]->id ) {
				$alias = $this->get_mysql_projection_alias_token_value( $tokens[ $position + 1 ] ?? null );
				if ( null === $alias ) {
					throw new InvalidArgumentException( 'Unsupported MySQL variable SELECT statement.' );
				}

				$column    = $alias;
				$position += 2;
			} else {
				$implicit_alias = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
				if ( null !== $implicit_alias ) {
					$column = $implicit_alias;
					++$position;
				}
			}

			$columns[]      = $column;
			$row[ $column ] = $variable['value'];

			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				if (
					! isset( $tokens[ $position ] )
					|| (
						WP_MySQL_Lexer::AT_TEXT_SUFFIX !== $tokens[ $position ]->id
						&& WP_MySQL_Lexer::AT_AT_SIGN_SYMBOL !== $tokens[ $position ]->id
					)
				) {
					if ( isset( $tokens[ $position ] ) && ! $this->is_mysql_variable_select_fallback_boundary_token( $tokens[ $position ] ) ) {
						return null;
					}

					throw new InvalidArgumentException( 'Unsupported MySQL variable SELECT statement.' );
				}

				continue;
			}

			break;
		}

		if ( ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
			if ( isset( $tokens[ $position ] ) && $this->is_mysql_variable_select_fallback_boundary_token( $tokens[ $position ] ) ) {
				return null;
			}

			throw new InvalidArgumentException( 'Unsupported MySQL variable SELECT statement.' );
		}

		return array(
			'columns' => $columns,
			'row'     => $row,
		);
	}

	/**
	 * Check whether a token can start a clause handled by the general SELECT translator.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the simple variable SELECT path should defer.
	 */
	private function is_mysql_variable_select_fallback_boundary_token( WP_MySQL_Token $token ): bool {
		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::FROM_SYMBOL,
				WP_MySQL_Lexer::GROUP_SYMBOL,
				WP_MySQL_Lexer::HAVING_SYMBOL,
				WP_MySQL_Lexer::LIMIT_SYMBOL,
				WP_MySQL_Lexer::ORDER_SYMBOL,
				WP_MySQL_Lexer::UNION_SYMBOL,
				WP_MySQL_Lexer::WHERE_SYMBOL,
			),
			true
		);
	}

	/**
	 * Parse a variable reference in a simple SELECT list.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 * @return array{display: string, value: string|null}|null Variable result descriptor.
	 */
	private function parse_mysql_select_variable_reference( array $tokens, int &$position ): ?array {
		if ( ! isset( $tokens[ $position ] ) ) {
			return null;
		}

		if ( WP_MySQL_Lexer::AT_TEXT_SUFFIX === $tokens[ $position ]->id ) {
			$display = $tokens[ $position ]->get_value();
			++$position;

			return array(
				'display' => $display,
				'value'   => $this->get_mysql_user_variable_value( $this->normalize_mysql_user_variable_name( $display ) ),
			);
		}

		if ( WP_MySQL_Lexer::AT_AT_SIGN_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$display = null;
		$scope   = null;
		$name    = $this->parse_mysql_system_variable_reference( $tokens, $position, $display, $scope );
		if ( null === $name || null === $display ) {
			return null;
		}

		$value = $this->get_mysql_system_variable_value( $name, $scope );
		if ( null === $value ) {
			throw new InvalidArgumentException( 'Unsupported MySQL system variable.' );
		}

		return array(
			'display' => $display,
			'value'   => $value,
		);
	}

	/**
	 * Get the result column name from a supported SELECT DATABASE() query.
	 *
	 * @param string $query MySQL query.
	 * @return string|null Result column name, or null when unsupported.
	 */
	private function get_mysql_database_function_select_column( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1], $tokens[2], $tokens[3] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::DATABASE_SYMBOL !== $tokens[1]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[2]->id
			|| WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== $tokens[3]->id
			|| ! $this->is_at_mysql_query_end( $tokens, 4 )
		) {
			return null;
		}

		return $tokens[1]->get_value() . '()';
	}

	/**
	 * Get the result column name for a MySQL FOUND_ROWS() query.
	 *
	 * @param string $query MySQL query.
	 * @return string|null Result column name, or null when the query is not SELECT FOUND_ROWS().
	 */
	private function get_found_rows_query_column_name( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1], $tokens[2], $tokens[3] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::IDENTIFIER !== $tokens[1]->id
			|| 'found_rows' !== strtolower( $tokens[1]->get_value() )
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[2]->id
			|| WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== $tokens[3]->id
		) {
			return null;
		}

		if ( $this->is_at_mysql_query_end( $tokens, 4 ) ) {
			return 'FOUND_ROWS()';
		}

		if (
			isset( $tokens[4], $tokens[5] )
			&& WP_MySQL_Lexer::AS_SYMBOL === $tokens[4]->id
			&& null !== $this->get_mysql_identifier_token_value( $tokens[5] )
			&& $this->is_at_mysql_query_end( $tokens, 6 )
		) {
			return $this->get_mysql_identifier_token_value( $tokens[5] );
		}

		if (
			isset( $tokens[4] )
			&& null !== $this->get_mysql_identifier_token_value( $tokens[4] )
			&& $this->is_at_mysql_query_end( $tokens, 5 )
		) {
			return $this->get_mysql_identifier_token_value( $tokens[4] );
		}

		return null;
	}

	/**
	 * Read the backend server version without requiring a PostgreSQL-only query.
	 *
	 * @return string
	 */
	private function read_server_version(): string {
		try {
			$version = $this->connection->get_pdo()->getAttribute( PDO::ATTR_SERVER_VERSION );
			if ( false !== $version && null !== $version ) {
				return (string) $version;
			}
		} catch ( Throwable $e ) {
			return 'PostgreSQL';
		}

		return 'PostgreSQL';
	}

	/**
	 * Normalize PDO column metadata into the MySQLi-shaped fields wpdb expects.
	 *
	 * @param PDOStatement $stmt           The statement to inspect.
	 * @param array        $excluded_names Column names hidden from callers.
	 * @return array
	 */
	private function normalize_column_meta( PDOStatement $stmt, array $excluded_names = array() ): array {
		$meta = array();
		for ( $i = 0; $i < $stmt->columnCount(); $i++ ) {
			$column_meta = $stmt->getColumnMeta( $i );
			if ( ! is_array( $column_meta ) ) {
				$column_meta = array();
			}
			$normalized_column_meta = $this->normalize_single_column_meta( $column_meta );
			if ( isset( $excluded_names[ $normalized_column_meta['name'] ] ) ) {
				continue;
			}

			$meta[] = $normalized_column_meta;
		}
		return $meta;
	}

	/**
	 * Normalize metadata for one column.
	 *
	 * @param array $column_meta Raw PDO column metadata.
	 * @return array
	 */
	private function normalize_single_column_meta( array $column_meta ): array {
		$name        = isset( $column_meta['name'] ) ? (string) $column_meta['name'] : '';
		$table       = isset( $column_meta['table'] ) ? (string) $column_meta['table'] : '';
		$native_type = isset( $column_meta['native_type'] ) ? strtolower( (string) $column_meta['native_type'] ) : '';
		$type        = $this->map_native_type( $native_type );
		$length      = isset( $column_meta['len'] ) ? (int) $column_meta['len'] : 0;
		$precision   = isset( $column_meta['precision'] ) ? (int) $column_meta['precision'] : 0;

		return array(
			'native_type'      => $type['native_type'],
			'pdo_type'         => $type['pdo_type'],
			'flags'            => isset( $column_meta['flags'] ) && is_array( $column_meta['flags'] ) ? $column_meta['flags'] : array(),
			'table'            => $table,
			'name'             => $name,
			'len'              => $length,
			'precision'        => $precision,
			'mysqli:orgname'   => $name,
			'mysqli:orgtable'  => $table,
			'mysqli:db'        => $this->db_name,
			'mysqli:charsetnr' => $type['charsetnr'],
			'mysqli:flags'     => 0,
			'mysqli:type'      => $type['mysqli_type'],
		);
	}

	/**
	 * Map PostgreSQL native type names to conservative MySQL/PDO metadata.
	 *
	 * @param string $native_type Lowercase PDO native type.
	 * @return array
	 */
	private function map_native_type( string $native_type ): array {
		static $map = null;
		if ( null === $map ) {
			$map = array();
			foreach (
				array(
					array( array( 'int2', 'smallint' ), 'SHORT', PDO::PARAM_INT, 2, 63 ),
					array( array( 'int4', 'integer' ), 'LONG', PDO::PARAM_INT, 3, 63 ),
					array( array( 'int8', 'bigint' ), 'LONGLONG', PDO::PARAM_INT, 8, 63 ),
					array( array( 'bytea', 'blob' ), 'BLOB', PDO::PARAM_LOB, 252, 63 ),
					array( array( 'bool', 'boolean' ), 'TINY', PDO::PARAM_BOOL, 1, 63 ),
					array( array( 'numeric', 'decimal' ), 'NEWDECIMAL', PDO::PARAM_STR, 246, 63 ),
					array( array( 'float4' ), 'FLOAT', PDO::PARAM_STR, 4, 63 ),
					array( array( 'float8' ), 'DOUBLE', PDO::PARAM_STR, 5, 63 ),
					array( array( 'date' ), 'DATE', PDO::PARAM_STR, 10, 63 ),
					array( array( 'time' ), 'TIME', PDO::PARAM_STR, 11, 63 ),
					array( array( 'timestamp', 'timestamptz', 'datetime' ), 'DATETIME', PDO::PARAM_STR, 12, 63 ),
				) as $type
			) {
				foreach ( $type[0] as $alias ) {
					$map[ $alias ] = array(
						'native_type' => $type[1],
						'pdo_type'    => $type[2],
						'mysqli_type' => $type[3],
						'charsetnr'   => $type[4],
					);
				}
			}
		}

		return $map[ $native_type ] ?? array(
			'native_type' => 'VAR_STRING',
			'pdo_type'    => PDO::PARAM_STR,
			'mysqli_type' => 253,
			'charsetnr'   => 255,
		);
	}
}
